(window.__qhadithX=window.__qhadithX||{})[2]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 787","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-787","x":"The above mentioned tradition has been reported by ibn abbas through a different chain of narrators to the same effect. This version adds:\n\nThe apostle of Allah (ﷺ) died, but he did not mention to us that surah al baraah ins a part of al-anfal. Abu Dawood said: Al-sha’bl, Abu Malik, Qatadah, and Thabit b. ‘Umarah said: The prophet( may peace be upon him) did not write\"In the name of Allah, the compassionate, the merciful\" until Surah al-naml was revealed. This is the meaning of what they said. Further, this is a mursal traditional(omitting the name of the companion)","ar":"حَدَّثَنَا زِيَادُ بْنُ أَيُّوبَ، حَدَّثَنَا مَرْوَانُ، - يَعْنِي ابْنَ مُعَاوِيَةَ - أَخْبَرَنَا عَوْفٌ الأَعْرَابِيُّ، عَنْ يَزِيدَ الْفَارِسِيِّ، حَدَّثَنَا ابْنُ عَبَّاسٍ، بِمَعْنَاهُ قَالَ فِيهِ فَقُبِضَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَلَمْ يُبَيِّنْ لَنَا أَنَّهَا مِنْهَا ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ الشَّعْبِيُّ وَأَبُو مَالِكٍ وَقَتَادَةُ وَثَابِتُ بْنُ عُمَارَةَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمْ يَكْتُبْ ‏{‏ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏}‏ حَتَّى نَزَلَتْ سُورَةُ النَّمْلِ هَذَا مَعْنَاهُ ‏.‏","v":[]}],"15":[{"c":"Sahih Muslim","r":"Hadith 227c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-227c","x":"Humran reported when 'Uthman performed ablution he said:\n\nBy Allah, I am narrating to you a hadith had there not been this verse in the Book of Allah. I would not have narrated it to you. Verily I heard the Messenger of Allah (ﷺ) say: Not a person is there who performed ablution, and did it well, then offered prayer, but his sins (which he committed) were not pardoned between the prayer that he offered and the next one. 'Urwa said: The verse is this:\" Those who suppress the clear proofs and the guidance which We have sent down\"... to His words:\" the Cursers\" (ii. 15).","ar":"وَحَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا أَبِي، عَنْ صَالِحٍ، قَالَ ابْنُ شِهَابٍ وَلَكِنْ عُرْوَةُ يُحَدِّثُ عَنْ حُمْرَانَ، أَنَّهُ قَالَ فَلَمَّا تَوَضَّأَ عُثْمَانُ قَالَ وَاللَّهِ لأُحَدِّثَنَّكُمْ حَدِيثًا وَاللَّهِ لَوْلاَ آيَةٌ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمُوهُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\"‏ لاَ يَتَوَضَّأُ رَجُلٌ فَيُحْسِنُ وُضُوءَهُ ثُمَّ يُصَلِّي الصَّلاَةَ إِلاَّ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلاَةِ الَّتِي تَلِيهَا ‏\"‏ ‏.‏ قَالَ عُرْوَةُ الآيَةُ ‏{‏ إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى‏}‏ إِلَى قَوْلِهِ ‏{‏ اللاَّعِنُونَ‏}‏","v":[]}],"20":[{"c":"Muwatta Malik","r":"Book 2, Hadith 110","u":"https://quranx.com/Hadith/Malik/In-Book/Book-2/Hadith-110","x":"Yahya related to me from Malik from Nafi that Abdullah ibn Umar, if he wished to sleep or eat while junub, would wash his face, and his arms to the elbows, and wipe his head. Then he would eat or sleep. 2.20 The Repetition of the Prayer by a Person in a State of Major Ritual Impurity, his Doing Ghusl, when He has Prayed without Remembering it, and his Washing his Garments.","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ إِذَا أَرَادَ أَنْ يَنَامَ، أَوْ يَطْعَمَ وَهُوَ جُنُبٌ غَسَلَ وَجْهَهُ وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ وَمَسَحَ بِرَأْسِهِ ثُمَّ طَعِمَ أَوْ نَامَ ‏.‏","v":[]}],"42":[{"c":"Sahih Bukhari","r":"Hadith 2692","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2692","x":"Narrated Um Kulthum bint `Uqba:\n\nThat she heard Allah's Messenger (ﷺ) saying, \"He who makes peace between the people by inventing good information or saying good things, is not a liar.\"","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحٍ، عَنِ ابْنِ شِهَابٍ، أَنَّ حُمَيْدَ بْنَ عَبْدِ الرَّحْمَنِ، أَخْبَرَهُ أَنَّ أُمَّهُ أُمَّ كُلْثُومٍ بِنْتَ عُقْبَةَ أَخْبَرَتْهُ أَنَّهَا، سَمِعَتْ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\n\n\"‏ لَيْسَ الْكَذَّابُ الَّذِي يُصْلِحُ بَيْنَ النَّاسِ، فَيَنْمِي خَيْرًا، أَوْ يَقُولُ خَيْرًا ‏\"\n\n‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 3, Book 15, Hadith 1432","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-3/Book-15/Hadith-1432","x":"'Umar bin Al-Khattab said:\n\n\"Verily Allah sent Muhammad (ﷺ) with the truth, and he revealed the Book to him. Among what was revealed to him was the Ayah of stoning. So the Messenger of Allah (ﷺ) stoned, and we stoned after him. I fear that time will pass over the people such that someone will say 'We do not see stoning in the Book of Allah.' They will be misguided by leaving an obligation which Allah revealed. Indeed stoning is the retribution for the adulterer if he was married and the evidence has been established, or due to pregnancy, or confession.\"","ar":"حَدَّثَنَا سَلَمَةُ بْنُ شَبِيبٍ، وَإِسْحَاقُ بْنُ مَنْصُورٍ، وَالْحَسَنُ بْنُ عَلِيٍّ الْخَلاَّلُ، وَغَيْرُ، وَاحِدٍ، قَالُوا حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنِ الزُّهْرِيِّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ، عَنِ ابْنِ عَبَّاسٍ، عَنْ عُمَرَ بْنِ الْخَطَّابِ، قَالَ إِنَّ اللَّهَ بَعَثَ مُحَمَّدًا صلى الله عليه وسلم بِالْحَقِّ وَأَنْزَلَ عَلَيْهِ الْكِتَابَ فَكَانَ فِيمَا أَنْزَلَ عَلَيْهِ آيَةُ الرَّجْمِ فَرَجَمَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَرَجَمْنَا بَعْدَهُ وَإِنِّي خَائِفٌ أَنْ يَطُولَ بِالنَّاسِ زَمَانٌ فَيَقُولَ قَائِلٌ لاَ نَجِدُ الرَّجْمَ فِي كِتَابِ اللَّهِ فَيَضِلُّوا بِتَرْكِ فَرِيضَةٍ أَنْزَلَهَا اللَّهُ أَلاَ وَإِنَّ الرَّجْمَ حَقٌّ عَلَى مَنْ زَنَى إِذَا أَحْصَنَ وَقَامَتِ الْبَيِّنَةُ أَوْ كَانَ حَبَلٌ أَوِ اعْتِرَافٌ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَرُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ.‏","v":[]}],"51":[{"c":"Sunan an-Nasa'i","r":"Volume 4, Book 25, Hadith 3139","u":"https://quranx.com/Hadith/Nasai/DarusSalam/Volume-4/Book-25/Hadith-3139","x":"It was narrated from Abu Hurairah, that one of the people of Ash-Sham said to him:\n\n\"O Shaikh, tell me of a Hadith that you heard from the Messenger of Allah (ﷺ).\" (He said: \"Yes; I heard the Messenger of Allah (ﷺ)) say: 'The first of people for whom judgment will be passed on the Day of Resurrection are three. A man who was martyred. He will be brought and Allah will remind him of His blessings and he will acknowledge them. He will say: What did you do with them? He will say: I fought for Your sake until I was martyred. He will say: You are lying. You fought so that it would be said that so-and-so is brave, and it was said. Then He will order that he be dragged on his face and thrown into the Fire. And (the second will be) a man who acquired knowledge and taught others,and read Qur'an. He will be brought, and Allah will remind him of His blessings, and he will acknowledge them. He will say: What did you do with them? He will say: I acquired knowledge and taught others, and read the Qur'an for Your sake. He will say: You are lying. You acquired knowledge so that it would be said that you were a scholar; and you read Qur'an so that it would be said that you were a reciter, and it was said. Then He will order that he be dragged on his face and thrown into the Fire. And (the third will be) a man whom Allah made rich and gave him all kinds of wealth. He will be brought and Allah will remind him of His blessings, and he will acknowledge them. he will say: What did you do with them? He will say: I did not leave any way that You like wealth to be spent - Abu 'Abdur-Rahman (An-Nasa'i) said: I did not understand \"what You like\" as I wanted to [1] - \"but I spent it.\" He will say: \"You are lying. You spent it so that it would be said that he was generous, and it was said.\" Then he will order that he be dragged on his face and thrown into the Fire.'\" [1] That is, he did not hear or understand what came after it as well as he wanted to, but it was similar to what follows regarding the spending. Similar was stated by Shaikh 'Abdur-Rahman Al-punjani in his notes on the text, according to Al-Funjani in his commentary At-Ta'iqat As-Salafiyyah (2:51)","ar":"أَخْبَرَنَا مُحَمَّدُ بْنُ عَبْدِ الأَعْلَى، قَالَ حَدَّثَنَا خَالِدٌ، قَالَ حَدَّثَنَا ابْنُ جُرَيْجٍ، قَالَ حَدَّثَنَا يُونُسُ بْنُ يُوسُفَ، عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، قَالَ تَفَرَّقَ النَّاسُ عَنْ أَبِي هُرَيْرَةَ، فَقَالَ لَهُ قَائِلٌ مِنْ أَهْلِ الشَّامِ أَيُّهَا الشَّيْخُ حَدِّثْنِي حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\"‏ أَوَّلُ النَّاسِ يُقْضَى لَهُمْ يَوْمَ الْقِيَامَةِ ثَلاَثَةٌ رَجُلٌ اسْتُشْهِدَ فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا قَالَ فَمَا عَمِلْتَ فِيهَا قَالَ قَاتَلْتُ فِيكَ حَتَّى اسْتُشْهِدْتُ ‏.‏ قَالَ كَذَبْتَ وَلَكِنَّكَ قَاتَلْتَ لِيُقَالَ فُلاَنٌ جَرِيءٌ فَقَدْ قِيلَ ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ وَرَجُلٌ تَعَلَّمَ الْعِلْمَ وَعَلَّمَهُ وَقَرَأَ الْقُرْآنَ فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا قَالَ فَمَا عَمِلْتَ فِيهَا قَالَ تَعَلَّمْتُ الْعِلْمَ وَعَلَّمْتُهُ وَقَرَأْتُ فِيكَ الْقُرْآنَ ‏.‏ قَالَ كَذَبْتَ وَلَكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ عَالِمٌ وَقَرَأْتَ الْقُرْآنَ لِيُقَالَ قَارِئٌ فَقَدْ قِيلَ ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ وَرَجُلٌ وَسَّعَ اللَّهُ عَلَيْهِ وَأَعْطَاهُ مِنْ أَصْنَافِ الْمَالِ كُلِّهِ فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا فَقَالَ مَا عَمِلْتَ فِيهَا قَالَ مَا تَرَكْتُ مِنْ سَبِيلٍ تُحِبُّ ‏\"‏ ‏.‏ قَالَ أَبُو عَبْدِ الرَّحْمَنِ وَلَمْ أَفْهَمْ تُحِبُّ كَمَا أَرَدْتُ ‏\"‏ أَنْ يُنْفَقَ فِيهَا إِلاَّ أَنْفَقْتُ فِيهَا لَكَ ‏.‏ قَالَ كَذَبْتَ وَلَكِنْ لِيُقَالَ إِنَّهُ جَوَادٌ فَقَدْ قِيلَ ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ فَأُلْقِيَ فِي النَّارِ ‏\"‏ ‏.‏","v":[]}],"58":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2956","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2956","x":"Narrated Abu Hurairah:\n\nthat the Messenger of Allah (ﷺ) said, regarding Allah's saying: Enter the gate in prostration (2:58): \"They entered dragging their behinds\" meaning they distorted it, and with this chain, from the Prophet (ﷺ): But those who did wrong changed the word from that which had been told to them for another (2:59) - \"They said: Habbah (a seed) in Sha'irah (in barely).\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنْ هَمَّامِ بْنِ مُنَبِّهٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي قَوْلِهِ ‏:‏ ‏(‏ادْخُلُوا الْبَابَ سُجَّدًا ‏)‏ قَالَ ‏\"‏ دَخَلُوا مُتَزَحِّفِينَ عَلَى أَوْرَاكِهِمْ ‏\"‏ ‏.‏ وَبِهَذَا الإِسْنَادِ عَنِ النَّبِيِّ صلى الله عليه وسلمَ ‏:‏ ‏(‏فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلاً غَيْرَ الَّذِي قِيلَ لَهُمْ ‏)‏ قَالَ ‏\"‏ قَالُوا حَبَّةٌ فِي شَعْرَةٍ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"59":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2956","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2956","x":"Narrated Abu Hurairah:\n\nthat the Messenger of Allah (ﷺ) said, regarding Allah's saying: Enter the gate in prostration (2:58): \"They entered dragging their behinds\" meaning they distorted it, and with this chain, from the Prophet (ﷺ): But those who did wrong changed the word from that which had been told to them for another (2:59) - \"They said: Habbah (a seed) in Sha'irah (in barely).\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنْ هَمَّامِ بْنِ مُنَبِّهٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي قَوْلِهِ ‏:‏ ‏(‏ادْخُلُوا الْبَابَ سُجَّدًا ‏)‏ قَالَ ‏\"‏ دَخَلُوا مُتَزَحِّفِينَ عَلَى أَوْرَاكِهِمْ ‏\"‏ ‏.‏ وَبِهَذَا الإِسْنَادِ عَنِ النَّبِيِّ صلى الله عليه وسلمَ ‏:‏ ‏(‏فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلاً غَيْرَ الَّذِي قِيلَ لَهُمْ ‏)‏ قَالَ ‏\"‏ قَالُوا حَبَّةٌ فِي شَعْرَةٍ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"97":[{"c":"Sahih Bukhari","r":"Hadith 4480","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4480","x":"Narrated Anas:\n\n`Abdullah bin Salam heard the news of the arrival of Allah's Messenger (ﷺ) (at Medina) while he was on a farm collecting its fruits. So he came to the Prophet (ﷺ) and said, \"I will ask you about three things which nobody knows unless he be a prophet. Firstly, what is the first portent of the Hour? What is the first meal of the people of Paradise? And what makes a baby look like its father or mother?'. The Prophet (ﷺ) said, \"Just now Gabriel has informed me about that.\" `Abdullah said, \"Gabriel?\" The Prophet (ﷺ) said, \"Yes.\" `Abdullah said, \"He, among the angels is the enemy of the Jews.\" On that the Prophet (ﷺ) recited this Holy Verse:-- \"Whoever is an enemy to Gabriel (let him die in his fury!) for he has brought it (i.e. Qur'an) down to your heart by Allah's permission.\" (2.97) Then he added, \"As for the first portent of the Hour, it will be a fire that will collect the people from the East to West. And as for the first meal of the people of Paradise, it will be the caudite (i.e. extra) lobe of the fish liver. And if a man's discharge proceeded that of the woman, then the child resembles the father, and if the woman's discharge proceeded that of the man, then the child resembles the mother.\" On hearing that, `Abdullah said, \"I testify that None has the right to be worshipped but Allah, and that you are the Messenger of Allah, O, Allah's Messenger (ﷺ); the Jews are liars, and if they should come to know that I have embraced Islam, they would accuse me of being a liar.\" In the meantime some Jews came (to the Prophet) and he asked them, \"What is `Abdullah's status amongst you?\" They replied, \"He is the best amongst us, and he is our chief and the son of our chief.\" The Prophet (ﷺ) said, \"What would you think if `Abdullah bin Salam embraced Islam?\" They replied, \"May Allah protect him from this!\" Then `Abdullah came out and said, \"I testify that None has the right to be worshipped but Allah and that Muhammad is the Messenger of Allah.\" The Jews then said, \"Abdullah is the worst of us and the son of the worst of us,\" and disparaged him. On that `Abdullah said, \"O Allah's Messenger (ﷺ)! This is what I was afraid of!\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُنِيرٍ، سَمِعَ عَبْدَ اللَّهِ بْنَ بَكْرٍ، حَدَّثَنَا حُمَيْدٌ، عَنْ أَنَسٍ، قَالَ سَمِعَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ، بِقُدُومِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَهْوَ فِي أَرْضٍ يَخْتَرِفُ، فَأَتَى النَّبِيَّ صلى الله عليه وسلم فَقَالَ إِنِّي سَائِلُكَ عَنْ ثَلاَثٍ لاَ يَعْلَمُهُنَّ إِلاَّ نَبِيٌّ فَمَا أَوَّلُ أَشْرَاطِ السَّاعَةِ وَمَا أَوَّلُ طَعَامِ أَهْلِ الْجَنَّةِ وَمَا يَنْزِعُ الْوَلَدُ إِلَى أَبِيهِ أَوْ إِلَى أُمِّهِ قَالَ ‏\"‏ أَخْبَرَنِي بِهِنَّ جِبْرِيلُ آنِفًا ‏\"‏‏.‏ قَالَ جِبْرِيلُ قَالَ ‏\"‏ نَعَمْ ‏\"‏‏.‏ قَالَ ذَاكَ عَدُوُّ الْيَهُودِ مِنَ الْمَلاَئِكَةِ‏.‏ فَقَرَأَ هَذِهِ الآيَةَ ‏{‏مَنْ كَانَ عَدُوًّا لِجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَى قَلْبِكَ‏}‏ أَمَّا أَوَّلُ أَشْرَاطِ السَّاعَةِ فَنَارٌ تَحْشُرُ النَّاسَ مِنَ الْمَشْرِقِ إِلَى الْمَغْرِبِ، وَأَمَّا أَوَّلُ طَعَامِ أَهْلِ الْجَنَّةِ فَزِيَادَةُ كَبِدِ حُوتٍ، وَإِذَا سَبَقَ مَاءُ الرَّجُلِ مَاءَ الْمَرْأَةِ نَزَعَ الْوَلَدَ، وَإِذَا سَبَقَ مَاءُ الْمَرْأَةِ نَزَعَتْ ‏\"‏‏.‏ قَالَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ‏.‏ يَا رَسُولَ اللَّهِ إِنَّ الْيَهُودَ قَوْمٌ بُهُتٌ، وَإِنَّهُمْ إِنْ يَعْلَمُوا بِإِسْلاَمِي قَبْلَ أَنْ تَسْأَلَهُمْ يَبْهَتُونِي‏.‏ فَجَاءَتِ الْيَهُودُ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ أَىُّ رَجُلٍ عَبْدُ اللَّهِ فِيكُمْ ‏\"‏‏.‏ قَالُوا خَيْرُنَا وَابْنُ خَيْرِنَا، وَسَيِّدُنَا وَابْنُ سَيِّدِنَا‏.‏ قَالَ ‏\"‏ أَرَأَيْتُمْ إِنْ أَسْلَمَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ ‏\"‏‏.‏ فَقَالُوا أَعَاذَهُ اللَّهُ مِنْ ذَلِكَ‏.‏ فَخَرَجَ عَبْدُ اللَّهِ فَقَالَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ‏.‏ فَقَالُوا شَرُّنَا وَابْنُ شَرِّنَا‏.‏ وَانْتَقَصُوهُ‏.‏ قَالَ فَهَذَا الَّذِي كُنْتُ أَخَافُ يَا رَسُولَ اللَّهِ‏.‏","v":[]}],"102":[{"c":"Sahih Bukhari","r":"Hadith 2766","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2766","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"Avoid the seven great destructive sins.\" The people enquire, \"O Allah's Messenger (ﷺ)! What are they? \"He said, \"To join others in worship along with Allah, to practice sorcery, to kill the life which Allah has forbidden except for a just cause, (according to Islamic law), to eat up Riba (usury), to eat up an orphan's wealth, to give back to the enemy and fleeing from the battlefield at the time of fighting, and to accuse, chaste women, who never even think of anything touching chastity and are good believers.","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنِي سُلَيْمَانُ بْنُ بِلاَلٍ، عَنْ ثَوْرِ بْنِ زَيْدٍ الْمَدَنِيِّ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ ‏\"‏‏.‏ قَالُوا يَا رَسُولَ اللَّهِ، وَمَا هُنَّ قَالَ ‏\"‏ الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ ‏\"‏‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 43, Hadith 1594","u":"https://quranx.com/Hadith/Malik/In-Book/Book-43/Hadith-1594","x":"Yahya related to me from Malik from Muhammad ibn Abd ar-Rahman ibn Sad ibn Zurara that he had heard that Hafsa, the wife of the Prophet, may Allah bless him and grant him peace, killed one of her slave-girls who had used sorcery against her. She was a mudabbara. Hafsa gave the order, and she was killed. Malik said, \"The sorcerer is the one who uses sorcery for himself and no one else uses that for him. It is like the one about whom Allah, the Blessed, the Exalted, said in His Book, 'They know the one who devotes himself to it will have no share in the Next World.' (Sura 2 ayat 102) I think that that person is killed if he does that himself.\"","ar":"وَحَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ، أَنَّهُ بَلَغَهُ أَنَّ حَفْصَةَ، زَوْجَ النَّبِيِّ صلى الله عليه وسلم قَتَلَتْ جَارِيَةً لَهَا سَحَرَتْهَا وَقَدْ كَانَتْ دَبَّرَتْهَا فَأَمَرَتْ بِهَا فَقُتِلَتْ ‏.‏ قَالَ مَالِكٌ السَّاحِرُ الَّذِي يَعْمَلُ السِّحْرَ وَلَمْ يَعْمَلْ ذَلِكَ لَهُ غَيْرُهُ هُوَ مَثَلُ الَّذِي قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى فِي كِتَابِهِ ‏{‏وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الآخِرَةِ مِنْ خَلاَقٍ‏}‏ فَأَرَى أَنْ يُقْتَلَ ذَلِكَ إِذَا عَمِلَ ذَلِكَ هُوَ نَفْسُهُ ‏.‏","v":[]}],"106":[{"c":"Sahih Bukhari","r":"Hadith 4481","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4481","x":"Narrated Ibn `Abbas:\n\n`Umar said, \"Our best Qur'an reciter is Ubai and our best judge is `Ali; and in spite of this, we leave some of the statements of Ubai because Ubai says, 'I do not leave anything that I have heard from Allah's Messenger (ﷺ) while Allah: \"Whatever verse (Revelations) do We abrogate or cause to be forgotten but We bring a better one or similar to it.\" (2.106)","ar":"حَدَّثَنَا عَمْرُو بْنُ عَلِيٍّ، حَدَّثَنَا يَحْيَى، حَدَّثَنَا سُفْيَانُ، عَنْ حَبِيبٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ عُمَرُ ـ رضى الله عنه ـ أَقْرَؤُنَا أُبَىٌّ، وَأَقْضَانَا عَلِيٌّ، وَإِنَّا لَنَدَعُ مِنْ قَوْلِ أُبَىٍّ، وَذَاكَ أَنَّ أُبَيًّا يَقُولُ لاَ أَدَعُ شَيْئًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم وَقَدْ قَالَ اللَّهُ تَعَالَى ‏{‏مَا نَنْسَخْ مِنْ آيَةٍ أَوْ نَنْسَأْهَا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5005","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5005","x":"Narrated Ibn Abbas:\n\nUmar said, Ubayy was the best of us in the recitation (of the Qur'an) yet we leave some of what he recites. Ubayy says, \"I have taken it from the mouth of Allah's Messenger (ﷺ) and I will not leave it for anything.\" But Allah said \"None of Our Revelations do We abrogate or cause to be forgotten but We substitute something better or similar.\" (Quran 2:106)","ar":"حَدَّثَنَا صَدَقَةُ بْنُ الْفَضْلِ، أَخْبَرَنَا يَحْيَى، عَنْ سُفْيَانَ، عَنْ حَبِيبِ بْنِ أَبِي ثَابِتٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ عُمَرُ أُبَىٌّ أَقْرَؤُنَا وَإِنَّا لَنَدَعُ مِنْ لَحَنِ أُبَىٍّ، وَأُبَىٌّ يَقُولُ أَخَذْتُهُ مِنْ فِي رَسُولِ اللَّهِ صلى الله عليه وسلم فَلاَ أَتْرُكُهُ لِشَىْءٍ قَالَ اللَّهُ تَعَالَى ‏{‏مَا نَنْسَخْ مِنْ آيَةٍ أَوْ نَنْسَأْهَا نَأْتِ بِخَيْرٍ مِنْهَا أَوْ مِثْلِهَا‏}‏","v":[]}],"109":[{"c":"Sahih Bukhari","r":"Hadith 4566","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4566","x":"Narrated Usama bin Zaid:\n\nAllah's Messenger (ﷺ) rode a donkey, equipped with a thick cloth-covering made in Fadak and was riding behind him. He was going to pay visit to Sa`d bin Ubada in Banu Al-Harith bin Al-Khazraj; and this incident happened before the battle of Badr. The Prophet (ﷺ) passed by a gathering in which `Abdullah bin Ubai bin Salul was present, and that was before `Abdullah bin Ubai embraced Islam. Behold in that gathering there were people of different religions: there were Muslims, pagans, idol-worshippers and Jews, and in that gathering `Abdullah bin Rawaha was also present. When a cloud of dust raised by the donkey reached that gathering, `Abdullah bin Ubai covered his nose with his garment and then said, \"Do not cover us with dust.\" Then Allah's Messenger (ﷺ) greeted them and stopped and dismounted and invited them to Allah (i.e. to embrace Islam) and recited to them the Holy Qur'an. On that, `Abdullah bin Ubai bin Saluil said, \"O man ! There is nothing better than that what you say. If it is the truth, then do not trouble us with it in our gatherings. Return to your mount (or residence) and if somebody comes to you, relate (your tales) to him.\" On that `Abdullah bin Rawaha said, \"Yes, O Allah's Apostle! Bring it (i.e. what you want to say) to us in our gathering, for we love that.\" So the Muslims, the pagans and the Jews started abusing one another till they were on the point of fighting with one another. The Prophet (ﷺ) kept on quietening them till they became quiet, whereupon the Prophet rode his animal (mount) and proceeded till he entered upon Sa`d bin Ubada. The Prophet (ﷺ) said to Sa`d, \"Did you not hear what 'Abu Hub-b said?\" He meant `Abdullah bin Ubai. \"He said so-andso.\" On that Sa`d bin Ubada said, \"O Allah's Messenger (ﷺ)! Excuse and forgive him, for by Him Who revealed the Book to you, Allah brought the Truth which was sent to you at the time when the people of this town (i.e. Medina) had decided unanimously to crown him and tie a turban on his head (electing him as chief). But when Allah opposed that (decision) through the Truth which Allah gave to you, he (i.e. `Abdullah bin Ubai) was grieved with jealously. and that caused him to do what you have seen.\" So Allah's Messenger (ﷺ) excused him, for the Prophet (ﷺ) and his companions used to forgive the pagans and the people of Scripture as Allah had ordered them, and they used to put up with their mischief with patience. Allah said: \"And you shall certainly hear much that will grieve you from those who received the Scripture before you and from the pagans........'(3.186) And Allah also said:--\"Many of the people of the Scripture wish if they could turn you away as disbelievers after you have believed, from selfish envy..\" (2.109) So the Prophet (ﷺ) used to stick to the principle of forgiveness for them as long as Allah ordered him to do so till Allah permitted fighting them. So when Allah's Messenger (ﷺ) fought the battle of Badr and Allah killed the nobles of Quraish infidels through him, Ibn Ubai bin Salul and the pagans and idolaters who were with him, said, \"This matter (i.e. Islam) has appeared (i.e. became victorious).\" So they gave the pledge of allegiance (for embracing Islam) to Allah's Messenger (ﷺ) and became Muslims.","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّ أُسَامَةَ بْنَ زَيْدٍ ـ رضى الله عنهما ـ أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم رَكِبَ عَلَى حِمَارٍ عَلَى قَطِيفَةٍ فَدَكِيَّةٍ، وَأَرْدَفَ أُسَامَةَ بْنَ زَيْدٍ وَرَاءَهُ، يَعُودُ سَعْدَ بْنَ عُبَادَةَ فِي بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ قَبْلَ وَقْعَةِ بَدْرٍ ـ قَالَ ـ حَتَّى مَرَّ بِمَجْلِسٍ فِيهِ عَبْدُ اللَّهِ بْنُ أُبَىٍّ، ابْنُ سَلُولَ، وَذَلِكَ قَبْلَ أَنْ يُسْلِمَ عَبْدُ اللَّهِ بْنُ أُبَىٍّ فَإِذَا فِي الْمَجْلِسِ أَخْلاَطٌ مِنَ الْمُسْلِمِينَ وَالْمُشْرِكِينَ عَبَدَةِ الأَوْثَانِ وَالْيَهُودِ وَالْمُسْلِمِينَ، وَفِي الْمَجْلِسِ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ، فَلَمَّا غَشِيَتِ الْمَجْلِسَ عَجَاجَةُ الدَّابَّةِ خَمَّرَ عَبْدُ اللَّهِ بْنُ أُبَىٍّ أَنْفَهُ بِرِدَائِهِ، ثُمَّ قَالَ لاَ تُغَبِّرُوا عَلَيْنَا‏.‏ فَسَلَّمَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَيْهِمْ ثُمَّ وَقَفَ فَنَزَلَ فَدَعَاهُمْ إِلَى اللَّهِ، وَقَرَأَ عَلَيْهِمُ الْقُرْآنَ، فَقَالَ عَبْدُ اللَّهِ بْنُ أُبَىٍّ ابْنُ سَلُولَ أَيُّهَا الْمَرْءُ، إِنَّهُ لاَ أَحْسَنَ مِمَّا تَقُولُ، إِنْ كَانَ حَقًّا، فَلاَ تُؤْذِينَا بِهِ فِي مَجْلِسِنَا، ارْجِعْ إِلَى رَحْلِكَ، فَمَنْ جَاءَكَ فَاقْصُصْ عَلَيْهِ‏.‏ فَقَالَ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ بَلَى يَا رَسُولَ اللَّهِ، فَاغْشَنَا بِهِ فِي مَجَالِسِنَا، فَإِنَّا نُحِبُّ ذَلِكَ‏.‏ فَاسْتَبَّ الْمُسْلِمُونَ وَالْمُشْرِكُونَ وَالْيَهُودُ حَتَّى كَادُوا يَتَثَاوَرُونَ، فَلَمْ يَزَلِ النَّبِيُّ صلى الله عليه وسلم يُخَفِّضُهُمْ حَتَّى سَكَنُوا، ثُمَّ رَكِبَ النَّبِيُّ صلى الله عليه وسلم دَابَّتَهُ فَسَارَ حَتَّى دَخَلَ عَلَى سَعْدِ بْنِ عُبَادَةَ، فَقَالَ لَهُ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ يَا سَعْدُ أَلَمْ تَسْمَعْ مَا قَالَ أَبُو حُبَابٍ ‏\"‏‏.‏ يُرِيدُ عَبْدَ اللَّهِ بْنَ أُبَىٍّ ‏\"‏ قَالَ كَذَا وَكَذَا ‏\"‏‏.‏ قَالَ سَعْدُ بْنُ عُبَادَةَ يَا رَسُولَ اللَّهِ، اعْفُ عَنْهُ وَاصْفَحْ عَنْهُ، فَوَالَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ، لَقَدْ جَاءَ اللَّهُ بِالْحَقِّ الَّذِي أَنْزَلَ عَلَيْكَ، لَقَدِ اصْطَلَحَ أَهْلُ هَذِهِ الْبُحَيْرَةِ عَلَى أَنْ يُتَوِّجُوهُ فَيُعَصِّبُونَهُ بِالْعِصَابَةِ، فَلَمَّا أَبَى اللَّهُ ذَلِكَ بِالْحَقِّ الَّذِي أَعْطَاكَ اللَّهُ شَرِقَ بِذَلِكَ، فَذَلِكَ فَعَلَ بِهِ ما رَأَيْتَ‏.‏ فَعَفَا عَنْهُ رَسُولُ اللَّهِ صلى الله عليه وسلم وَكَانَ النَّبِيُّ صلى الله عليه وسلم وَأَصْحَابُهُ يَعْفُونَ عَنِ الْمُشْرِكِينَ وَأَهْلِ الْكِتَابِ كَمَا أَمَرَهُمُ اللَّهُ، وَيَصْبِرُونَ عَلَى الأَذَى قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَمِنَ الَّذِينَ أَشْرَكُوا أَذًى كَثِيرًا ‏}‏ الآيَةَ، وَقَالَ اللَّهُ ‏{‏وَدَّ كَثِيرٌ مِنْ أَهْلِ الْكِتَابِ لَوْ يَرُدُّونَكُمْ مِنْ بَعْدِ إِيمَانِكُمْ كُفَّارًا حَسَدًا مِنْ عِنْدِ أَنْفُسِهِمْ‏}‏ إِلَى آخِرِ الآيَةِ، وَكَانَ النَّبِيُّ صلى الله عليه وسلم يَتَأَوَّلُ الْعَفْوَ مَا أَمَرَهُ اللَّهُ بِهِ، حَتَّى أَذِنَ اللَّهُ فِيهِمْ، فَلَمَّا غَزَا رَسُولُ اللَّهِ صلى الله عليه وسلم بَدْرًا، فَقَتَلَ اللَّهُ بِهِ صَنَادِيدَ كُفَّارِ قُرَيْشٍ قَالَ ابْنُ أُبَىٍّ ابْنُ سَلُولَ، وَمَنْ مَعَهُ مِنَ الْمُشْرِكِينَ، وَعَبَدَةِ الأَوْثَانِ هَذَا أَمْرٌ قَدْ تَوَجَّهَ‏.‏ فَبَايَعُوا الرَّسُولَ صلى الله عليه وسلم عَلَى الإِسْلاَمِ فَأَسْلَمُوا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6207","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6207","x":"Narrated Usama bin Zaid:\n\nThat Allah's Messenger (ﷺ) rode over a donkey covered with a Fadakiya (velvet sheet) and Usama was riding behind him. He was visiting Sa`d bin 'Ubada (who was sick) in the dwelling place of Bani Al-Harith bin Al-Khazraj and this incident happened before the battle of Badr. They proceeded till they passed by a gathering in which `Abdullah bin Ubai bin Salul was present., and that was before `Abdullah bin Ubat embraced Islam. In that gathering there were Muslims, pagan idolators and Jews, and among the Muslims there was `Abdullah bin Rawaha. When a cloud of dust raised by (the movement of ) the animal covered that gathering, `Abdullah bin Ubai covered his nose with his garment and said, \"Do not cover us with dust.\" Allah's Messenger (ﷺ) greeted them, stopped, dismounted and invited them to Allah (i.e. to embrace Islam) and recited to them the Holy Qur'an. On that `Abdullah bin Ubai bin Salul said to him, \"O man! There is nothing better than what you say, if it is the truth. So do not trouble us with it in our gatherings, but if somebody comes to you, you can preach to him.\" On that `Abdullah bin Rawaha said \"Yes, O Allah's Messenger (ﷺ)! Call on us in our gathering, for we love that.\" So the Muslims, the pagans and the Jews started abusing one another till they were about to fight with one another. Allah's Messenger (ﷺ) kept on quietening them till all of them became quiet, and then Allah's Messenger (ﷺ) rode his animal and proceeded till he entered upon Sa`d bin 'Ubada. Allah's Messenger (ﷺ) said, \"O Sa`d! Didn't you hear what Abu Habab said?\" (meaning `Abdullah bin Unbar). \"He said so-and-so.\" Sa`d bin Ubada said, \"O Allah's Messenger (ﷺ)! Let my father be sacrificed for you ! Excuse and forgive him for, by Him Who revealed to you the Book, Allah sent the Truth which was revealed to you at the time when the people of this town had decided to crown him (`Abdullah bin Ubai) as their ruler. So when Allah had prevented that with the Truth He had given you, he was choked by that, and that caused him to behave in such an impolite manner which you had noticed.\" So Allah's Messenger (ﷺ) excused him. (It was the custom of) Allah's Messenger (ﷺ) and his companions to excuse the pagans and the people of the scripture (Christians and Jews) as Allah ordered them, and they used to be patient when annoyed (by them). Allah said: 'You shall certainly hear much that will grieve you from those who received the Scripture before you.....and from the pagans (3.186) He also said: 'Many of the people of the scripture wish that if they could turn you away as disbelievers after you have believed..... (2.109) So Allah's Messenger (ﷺ) used to apply what Allah had ordered him by excusing them till he was allowed to fight against them. When Allah's Messenger (ﷺ) had fought the battle of Badr and Allah killed whomever He killed among the chiefs of the infidels and the nobles of Quraish, and Allah's Messenger (ﷺ) and his companions had returned with victory and booty, bringing with them some of the chiefs of the infidels and the nobles of the Quraish as captives. `Abdullah bin Ubai bin Salul and the pagan idolators who were with him, said, \"This matter (Islam) has now brought out its face (triumphed), so give Allah's Messenger (ﷺ) the pledge of allegiance (for embracing Islam.)\". Then they became Muslims.","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي أَخِي، عَنْ سُلَيْمَانَ، عَنْ مُحَمَّدِ بْنِ أَبِي عَتِيقٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، أَنَّ أُسَامَةَ بْنَ زَيْدٍ ـ رضى الله عنهما ـ أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم رَكِبَ عَلَى حِمَارٍ عَلَيْهِ قَطِيفَةٌ فَدَكِيَّةٌ وَأُسَامَةُ وَرَاءَهُ، يَعُودُ سَعْدَ بْنَ عُبَادَةَ فِي بَنِي حَارِثِ بْنِ الْخَزْرَجِ قَبْلَ وَقْعَةِ بَدْرٍ، فَسَارَا حَتَّى مَرَّا بِمَجْلِسٍ فِيهِ عَبْدُ اللَّهِ بْنُ أُبَىٍّ ابْنُ سَلُولَ، وَذَلِكَ قَبْلَ أَنْ يُسْلِمَ عَبْدُ اللَّهِ بْنُ أُبَىٍّ، فَإِذَا فِي الْمَجْلِسِ أَخْلاَطٌ مِنَ الْمُسْلِمِينَ وَالْمُشْرِكِينَ عَبَدَةِ الأَوْثَانِ وَالْيَهُودِ، وَفِي الْمُسْلِمِينَ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ، فَلَمَّا غَشِيَتِ الْمَجْلِسَ عَجَاجَةُ الدَّابَّةِ خَمَّرَ ابْنُ أُبَىٍّ أَنْفَهُ بِرِدَائِهِ وَقَالَ لاَ تُغَبِّرُوا عَلَيْنَا‏.‏ فَسَلَّمَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَيْهِمْ، ثُمَّ وَقَفَ فَنَزَلَ فَدَعَاهُمْ إِلَى اللَّهِ وَقَرَأَ عَلَيْهِمُ الْقُرْآنَ، فَقَالَ لَهُ عَبْدُ اللَّهِ بْنُ أُبَىٍّ ابْنُ سَلُولَ أَيُّهَا الْمَرْءُ لاَ أَحْسَنَ مِمَّا تَقُولُ إِنْ كَانَ حَقًّا، فَلاَ تُؤْذِنَا بِهِ فِي مَجَالِسِنَا، فَمَنْ جَاءَكَ فَاقْصُصْ عَلَيْهِ‏.‏ قَالَ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ بَلَى يَا رَسُولَ اللَّهِ فَاغْشَنَا فِي مَجَالِسِنَا فَإِنَّا نُحِبُّ ذَلِكَ‏.‏ فَاسْتَبَّ الْمُسْلِمُونَ وَالْمُشْرِكُونَ وَالْيَهُودُ حَتَّى كَادُوا يَتَثَاوَرُونَ فَلَمْ يَزَلْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَخْفِضُهُمْ حَتَّى سَكَتُوا، ثُمَّ رَكِبَ رَسُولُ اللَّهِ صلى الله عليه وسلم دَابَّتَهُ فَسَارَ حَتَّى دَخَلَ عَلَى سَعْدِ بْنِ عُبَادَةَ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَىْ سَعْدُ أَلَمْ تَسْمَعْ مَا قَالَ أَبُو حُبَابٍ ـ يُرِيدُ عَبْدَ اللَّهِ بْنَ أُبَىٍّ ـ قَالَ كَذَا وَكَذَا ‏\"‏‏.‏ فَقَالَ سَعْدُ بْنُ عُبَادَةَ أَىْ رَسُولَ اللَّهِ بِأَبِي أَنْتَ، اعْفُ عَنْهُ وَاصْفَحْ، فَوَالَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ لَقَدْ جَاءَ اللَّهُ بِالْحَقِّ الَّذِي أَنْزَلَ عَلَيْكَ، وَلَقَدِ اصْطَلَحَ أَهْلُ هَذِهِ الْبَحْرَةِ عَلَى أَنْ يُتَوِّجُوهُ وَيُعَصِّبُوهُ بِالْعِصَابَةِ، فَلَمَّا رَدَّ اللَّهُ ذَلِكَ بِالْحَقِّ الَّذِي أَعْطَاكَ شَرِقَ بِذَلِكَ فَذَلِكَ فَعَلَ بِهِ مَا رَأَيْتَ‏.‏ فَعَفَا عَنْهُ رَسُولُ اللَّهِ صلى الله عليه وسلم وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَصْحَابُهُ يَعْفُونَ عَنِ الْمُشْرِكِينَ وَأَهْلِ الْكِتَابِ كَمَا أَمَرَهُمُ اللَّهُ، وَيَصْبِرُونَ عَلَى الأَذَى، قَالَ اللَّهُ تَعَالَى ‏{‏وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ‏}‏ الآيَةَ، وَقَالَ ‏{‏وَدَّ كَثِيرٌ مِنْ أَهْلِ الْكِتَابِ‏}‏ فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَتَأَوَّلُ فِي الْعَفْوِ عَنْهُمْ مَا أَمَرَهُ اللَّهُ بِهِ حَتَّى أَذِنَ لَهُ فِيهِمْ، فَلَمَّا غَزَا رَسُولُ اللَّهِ صلى الله عليه وسلم بَدْرًا، فَقَتَلَ اللَّهُ بِهَا مَنْ قَتَلَ مِنْ صَنَادِيدِ الْكُفَّارِ، وَسَادَةِ قُرَيْشٍ، فَقَفَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَصْحَابُهُ مَنْصُورِينَ غَانِمِينَ مَعَهُمْ أُسَارَى مِنْ صَنَادِيدِ الْكُفَّارِ وَسَادَةِ قُرَيْشٍ قَالَ ابْنُ أُبَىٍّ ابْنُ سَلُولَ، وَمَنْ مَعَهُ مِنَ الْمُشْرِكِينَ عَبَدَةِ الأَوْثَانِ هَذَا أَمْرٌ قَدْ تَوَجَّهَ فَبَايِعُوا رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى الإِسْلاَمِ فَأَسْلَمُوا‏.‏","v":[]}],"115":[{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1020","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1020","x":"It was narrated from ‘Abdullah bin ‘Amir bin Rabi’ah that his father said:\n\n\"We were with the Messenger of Allah (ﷺ) on a journey, and the sky was overcast so it was difficult for us to determine the Qiblah. So we performed prayer, and we marked the location.* Later, when the sun reappeared, we realized that we had prayed facing a direction other than the Qiblah. We mentioned that to the Prophet (ﷺ), then the Words were revealed: ‘So wherever you turn there is the Face of Allah.’\" [2:115]","ar":"حَدَّثَنَا يَحْيَى بْنُ حَكِيمٍ، حَدَّثَنَا أَبُو دَاوُدَ، حَدَّثَنَا أَشْعَثُ بْنُ سَعِيدٍ أَبُو الرَّبِيعِ السَّمَّانُ، عَنْ عَاصِمِ بْنِ عُبَيْدِ اللَّهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ رَبِيعَةَ، عَنْ أَبِيهِ، قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فِي سَفَرٍ فَتَغَيَّمَتِ السَّمَاءُ وَأَشْكَلَتْ عَلَيْنَا الْقِبْلَةُ فَصَلَّيْنَا وَأَعْلَمْنَا فَلَمَّا طَلَعَتِ الشَّمْسُ إِذَا نَحْنُ قَدْ صَلَّيْنَا لِغَيْرِ الْقِبْلَةِ فَذَكَرْنَا ذَلِكَ لِلنَّبِيِّ ـ صلى الله عليه وسلم ـ فَأَنْزَلَ اللَّهُ ‏{فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ}‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 700c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-700c","x":"Ibn 'Umar reported that the Messenger of Allah (ﷺ) used to say prayer on his camel while coming from Mecca to Medina, in whatever direction his face had turned; and its was (in this context) that this verse was revealed:\n\n\" So whether you turn thither is Allah's face\" (ii. 115).","ar":"وَحَدَّثَنِي عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ عَبْدِ الْمَلِكِ بْنِ أَبِي سُلَيْمَانَ، قَالَ حَدَّثَنَا سَعِيدُ بْنُ جُبَيْرٍ، عَنِ ابْنِ عُمَرَ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي وَهُوَ مُقْبِلٌ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ عَلَى رَاحِلَتِهِ حَيْثُ كَانَ وَجْهُهُ - قَالَ - وَفِيهِ نَزَلَتْ ‏{‏ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 1, Book 2, Hadith 345","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-1/Book-2/Hadith-345","x":"Abdullah bin Amir bin Rabi'ah narrated from his father who said:\n\n\"We were with the Prophet on a journey on a very dark night and we did not know the direction of the Qiblah. So each man among us prayed in his own direction. In the morning when we mentioned that to the Prophet, then the following was revealed: So where ever you turn, there is the Face of Allah.\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا أَشْعَثُ بْنُ سَعِيدٍ السَّمَّانُ، عَنْ عَاصِمِ بْنِ عُبَيْدِ اللَّهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ رَبِيعَةَ، عَنْ أَبِيهِ، قَالَ كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم فِي سَفَرٍ فِي لَيْلَةٍ مُظْلِمَةٍ فَلَمْ نَدْرِ أَيْنَ الْقِبْلَةُ فَصَلَّى كُلُّ رَجُلٍ مِنَّا عَلَى حِيَالِهِ فَلَمَّا أَصْبَحْنَا ذَكَرْنَا ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَنَزَلَ‏:‏ ‏(‏فَأَيْنَمَا تُولُّوا فَثَمَّ وَجْهُ الله‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ لَيْسَ إِسْنَادُهُ بِذَاكَ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ أَشْعَثَ السَّمَّانِ ‏.‏ وَأَشْعَثُ بْنُ سَعِيدٍ أَبُو الرَّبِيعِ السَّمَّانُ يُضَعَّفُ فِي الْحَدِيثِ ‏.‏ وَقَدْ ذَهَبَ أَكْثَرُ أَهْلِ الْعِلْمِ إِلَى هَذَا ‏.‏ قَالُوا إِذَا صَلَّى فِي الْغَيْمِ لِغَيْرِ الْقِبْلَةِ ثُمَّ اسْتَبَانَ لَهُ بَعْدَ مَا صَلَّى أَنَّهُ صَلَّى لِغَيْرِ الْقِبْلَةِ فَإِنَّ صَلاَتَهُ جَائِزَةٌ ‏.‏ وَبِهِ يَقُولُ سُفْيَانُ الثَّوْرِيُّ وَابْنُ الْمُبَارَكِ وَأَحْمَدُ وَإِسْحَاقُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2957","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2957","x":"Narrated 'Abdullah bin 'Amir bin Rabi'ah:\n\nfrom his father who said: \"We were with the Messenger of Allah (ﷺ) on a journey on a very dark night and we did not know where the Qiblah was. So each man among us prayed in his own direction. In the morning when we mentioned that to the Messenger of Allah (ﷺ), then the following was revealed: \"So wherever you turn, there is the Face of Allah. (2:115)\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا أَشْعَثُ السَّمَّانُ، عَنْ عَاصِمِ بْنِ عُبَيْدِ اللَّهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ رَبِيعَةَ، عَنْ أَبِيهِ، قَالَ كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم فِي سَفَرِهِ فِي لَيْلَةٍ مُظْلِمَةٍ فَلَمْ نَدْرِ أَيْنَ الْقِبْلَةُ فَصَلَّى كُلُّ رَجُلٍ مِنَّا عَلَى حِيَالِهِ فَلَمَّا أَصْبَحْنَا ذَكَرْنَا ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَنَزَلَتْ ‏:‏ ‏(‏أَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ أَشْعَثَ السَّمَّانِ أَبِي الرَّبِيعِ عَنْ عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏.‏ وَأَشْعَثُ يُضَعَّفُ فِي الْحَدِيثِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2958","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2958","x":"Narrated Ibn 'Umar:\n\n\"The Messenger of Allah (ﷺ) would perform voluntary Salat upon his mount facing whichever direction he was headed, while he was coming from Makkah to Al-Madinah.\" Then Ibn 'Umar recited: To Allah belong both the east and the west. (2:115)\" And Ibn 'Umar said: \"It was about this that the Ayah was revealed.\" [Abu Eisa said:] This Hadith is Hasan Sahih. It has been reported from Qatadah that he said about this Ayah: To Allah belong both the east and the west, so wherever you turn, there is the Face of Allah. [Qatadah said:] \"It is abrogated, it was abrogated by [His saying]: So turn your face in the direction of Al-Masjid Al-Haram. Meaning: facing it.\" And it has been reported that Mujãhid said about this Ayah: \"So wherever you turn, there is the Face of Allah\": \"So there is the direction of Allah.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا يَزِيدُ بْنُ هَارُونَ، أَخْبَرَنَا عَبْدُ الْمَلِكِ بْنُ أَبِي سُلَيْمَانَ، قَالَ سَمِعْتُ سَعِيدَ بْنَ جُبَيْرٍ، يُحَدِّثُ عَنِ ابْنِ عُمَرَ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم يُصَلِّي عَلَى رَاحِلَتِهِ تَطَوُّعًا حَيْثُمَا تَوَجَّهَتْ بِهِ وَهُوَ جَاءٍ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ ثُمَّ قَرَأَ ابْنُ عُمَرَ هَذِهِ الآيَةَ ‏:‏ ‏(‏وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ ‏)‏ الآيَةَ ‏.‏ قَالَ ابْنُ عُمَرَ فَفِي هَذَا أُنْزِلَتْ هَذِهِ الآيَةُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَيُرْوَى عَنْ قَتَادَةَ، أَنَّهُ قَالَ فِي هَذِهِ الآيَةِِ ‏:‏ ‏(‏)ولله الْمَشْرِقُ وَالْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ ‏)‏ قَالَ قَتَادَةُ هِيَ مَنْسُوخَةٌ نَسَخَهَا قَوْلُهُ ‏:‏ ‏(‏فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ ‏)‏ أَىْ تِلْقَاءَهُ ‏.‏ حَدَّثَنَا بِذَلِكَ مُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الشَّوَارِبِ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ عَنْ سَعِيدٍ عَنْ قَتَادَةَ ‏.‏ وَيُرْوَى عَنْ مُجَاهِدٍ، فِي هَذِهِ الآيَةِ ‏:‏ ‏(‏أَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ ‏)‏ قَالَ فَثَمَّ قِبْلَةُ اللَّهِ ‏.‏ حَدَّثَنَا بِذَلِكَ أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلاَءِ حَدَّثَنَا وَكِيعٌ عَنِ النَّضْرِ بْنِ عَرَبِيٍّ عَنْ مُجَاهِدٍ بِهَذَا ‏.‏","v":[]}],"119":[{"c":"Sunan Abu Dawud","r":"Hadith 1260","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1260","x":"Narrated Abu Hurairah:\n\nThat he heard the Prophet (ﷺ) recite in both rak'ahs of the dawn: \"Say: We believe in Allah, and in the revelation given to us\" (3:84). This is in the first rak'ah. In the second rak'ah he recited this verse: \"Our Lord, we have believed in what You have sent down, and we follow the Messenger, so write us down among those who bear witness.\" or he recited: \"Surely, we have sent you with the truth as a bringer of glad tidings, and a warner. And you will not be asked about the inhabitants of the Blazing Fire\" (2:119). Al-Darawardi doubted (which of the verse he recited).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ بْنِ سُفْيَانَ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنِ مُحَمَّدٍ، عَنْ عُثْمَانَ بْنِ عُمَرَ، - يَعْنِي ابْنَ مُوسَى - عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقْرَأُ فِي رَكْعَتَىِ الْفَجْرِ ‏{‏ قُلْ آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ عَلَيْنَا ‏}‏ فِي الرَّكْعَةِ الأُولَى وَفِي الرَّكْعَةِ الأُخْرَى بِهَذِهِ الآيَةِ ‏{‏ رَبَّنَا آمَنَّا بِمَا أَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ ‏}‏ أَوْ ‏{‏ إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا وَلاَ تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ ‏}‏ شَكَّ الدَّرَاوَرْدِيُّ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 1265","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1265","x":"Narrated 'Abd Allah b. Sarjas:\n\nA man came while the Prophet (ﷺ) was leading the people in the dawn prayer. He prayed the two rak'ahs and then joined the congregational prayer led by the Prophet (ﷺ). When he finished the prayer, the Prophet (ﷺ) said: So-and-so, which was your real prayer, the one you prayed alone or the one offered with us ?","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ عَاصِمٍ، عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ، قَالَ جَاءَ رَجُلٌ وَالنَّبِيُّ صلى الله عليه وسلم يُصَلِّي الصُّبْحَ فَصَلَّى الرَّكْعَتَيْنِ ثُمَّ دَخَلَ مَعَ النَّبِيِّ صلى الله عليه وسلم فِي الصَّلاَةِ فَلَمَّا انْصَرَفَ قَالَ ‏\n\n\"‏ يَا فُلاَنُ أَيَّتُهُمَا صَلاَتُكَ الَّتِي صَلَّيْتَ وَحْدَكَ أَوِ الَّتِي صَلَّيْتَ مَعَنَا ‏\"\n\n‏ ‏.‏","v":[]}],"125":[{"c":"Sunan Abu Dawud","r":"Hadith 1914","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1914","x":"Narrated Abdullah ibn Umar:\n\nWhen al-Hajjaj killed Ibn Zubayr, he sent a message to Ibn Umar asking him: At which moment the Messenger of Allah (ﷺ) used to proceed (to Arafat) this day? He replied: When it happens so, we shall proceed. When Ibn Umar intended to proceed, the people said: The sun did not decline. He (Ibn Umar) asked: Did it decline? They replied: It did not decline. When they said that the sun had declined, he proceeded.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا نَافِعُ بْنُ عُمَرَ، عَنْ سَعِيدِ بْنِ حَسَّانَ، عَنِ ابْنِ عُمَرَ، قَالَ لَمَّا أَنْ قَتَلَ الْحَجَّاجُ ابْنَ الزُّبَيْرِ، أَرْسَلَ إِلَى ابْنِ عُمَرَ أَيَّةُ سَاعَةٍ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَرُوحُ فِي هَذَا الْيَوْمِ قَالَ إِذَا كَانَ ذَلِكَ رُحْنَا ‏.‏ فَلَمَّا أَرَادَ ابْنُ عُمَرَ أَنْ يَرُوحَ قَالُوا لَمْ تَزِغِ الشَّمْسُ ‏.‏ قَالَ أَزَاغَتْ قَالُوا لَمْ تَزِغْ - أَوْ زَاغَتْ - قَالَ فَلَمَّا قَالُوا قَدْ زَاغَتِ ‏.‏ ارْتَحَلَ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 3980","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3980","x":"Narrated Ubayy b. Ka'b:\n\n\"Say, in the bounty of Allah, and in His mercy- in that let you rejoice.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، عَنْ أَسْلَمَ الْمِنْقَرِيِّ، عَنْ عَبْدِ اللَّهِ، عَنْ أَبِيهِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى، قَالَ قَالَ أُبَىُّ بْنُ كَعْبٍ ‏{‏ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْتَفْرَحُوا ‏}‏ ‏.‏ قَالَ أَبُو دَاوُدَ بِالتَّاءِ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 402","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-402","x":"Narrated `Umar (bin Al-Khattab):\n\nMy Lord agreed with me in three things: -1. I said, \"O Allah's Messenger (ﷺ), I wish we took the station of Abraham as our praying place (for some of our prayers). So came the Divine Inspiration: And take you (people) the station of Abraham as a place of prayer (for some of your prayers e.g. two rak`at of Tawaf of Ka`ba)\". (2.125) -2. And as regards the (verse of) the veiling of the women, I said, 'O Allah's Messenger (ﷺ)! I wish you ordered your wives to cover themselves from the men because good and bad ones talk to them.' So the verse of the veiling of the women was revealed. -3. Once the wives of the Prophet (ﷺ) made a united front against the Prophet (ﷺ) and I said to them, 'It may be if he (the Prophet) divorced you, (all) that his Lord (Allah) will give him instead of you wives better than you.' So this verse (the same as I had said) was revealed.\" (66.5).","ar":"حَدَّثَنَا عَمْرُو بْنُ عَوْنٍ، قَالَ حَدَّثَنَا هُشَيْمٌ، عَنْ حُمَيْدٍ، عَنْ أَنَسٍ، قَالَ قَالَ عُمَرُ وَافَقْتُ رَبِّي فِي ثَلاَثٍ، فَقُلْتُ يَا رَسُولَ اللَّهِ لَوِ اتَّخَذْنَا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى فَنَزَلَتْ ‏{‏وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى‏}‏ وَآيَةُ الْحِجَابِ قُلْتُ يَا رَسُولَ اللَّهِ، لَوْ أَمَرْتَ نِسَاءَكَ أَنْ يَحْتَجِبْنَ، فَإِنَّهُ يُكَلِّمُهُنَّ الْبَرُّ وَالْفَاجِرُ‏.‏ فَنَزَلَتْ آيَةُ الْحِجَابِ، وَاجْتَمَعَ نِسَاءُ النَّبِيِّ صلى الله عليه وسلم فِي الْغَيْرَةِ عَلَيْهِ فَقُلْتُ لَهُنَّ عَسَى رَبُّهُ إِنْ طَلَّقَكُنَّ أَنْ يُبَدِّلَهُ أَزْوَاجًا خَيْرًا مِنْكُنَّ‏.‏ فَنَزَلَتْ هَذِهِ الآيَةُ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1008","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1008","x":"It was narrated that Jabir said:\n\n\"When the Messenger of Allah (ﷺ) finished Tawaf around the House (the Ka’bah), he came to Maqam of Ibrahim (the Station of Ibrahim). ‘Umar said: ‘O Messenger of Allah, this is the Station of our father Ibrahim about which Allah said: \"And take you (people) the Maqam of Ibrahim as a place of prayer.’\" [2:125]","ar":"حَدَّثَنَا الْعَبَّاسُ بْنُ عُثْمَانَ الدِّمَشْقِيُّ، حَدَّثَنَا الْوَلِيدُ بْنُ مُسْلِمٍ، حَدَّثَنَا مَالِكُ بْنُ أَنَسٍ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ جَابِرٍ، أَنَّهُ قَالَ لَمَّا فَرَغَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ مِنْ طَوَافِ الْبَيْتِ أَتَى مَقَامَ إِبْرَاهِيمَ فَقَالَ عُمَرُ يَا رَسُولَ اللَّهِ هَذَا مَقَامُ أَبِينَا إِبْرَاهِيمَ الَّذِي قَالَ اللَّهُ ‏{وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى }‏ ‏.‏ قَالَ الْوَلِيدُ فَقُلْتُ لِمَالِكٍ أَهَكَذَا قَرَأَ ‏{وَاتَّخِذُوا}‏ قَالَ نَعَمْ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1009","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1009","x":"It was narrated that Anas bin Malik told that ‘Umar said:\n\n\"I said: ‘O Messenger of Allah (ﷺ), why do you not take the Maqam of Ibrahim as a place of prayer?’ Then the following was revealed: ‘And take you (people) the Maqam of Ibrahim as a place of prayer.’\" [2:125]","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ، حَدَّثَنَا هُشَيْمٌ، عَنْ حُمَيْدٍ الطَّوِيلِ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ عُمَرُ قُلْتُ يَا رَسُولَ اللَّهِ لَوِ اتَّخَذْتَ مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى فَنَزَلَتْ ‏{وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى}‏ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 25, Hadith 2960","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-25/Hadith-2960","x":"It was narrated that Jabir said:\n\n\"When Allah’s Messenger (ﷺ) finished circumambulating the House, he came to Maqam Ibrahim. ‘Umar said: ‘O Messenger of Allah, this is the Maqam of our father Ibrahim, about which Allah says, \"And take you (people) the Maqam (place) of Ibrahim as a place of prayer.’\" [2:125]","ar":"حَدَّثَنَا الْعَبَّاسُ بْنُ عُثْمَانَ الدِّمَشْقِيُّ، حَدَّثَنَا الْوَلِيدُ بْنُ مُسْلِمٍ، عَنْ مَالِكِ بْنِ أَنَسٍ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ جَابِرٍ، أَنَّهُ قَالَ لَمَّا فَرَغَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ مِنْ طَوَافِ الْبَيْتِ أَتَى مَقَامَ إِبْرَاهِيمَ فَقَالَ عُمَرُ يَا رَسُولَ اللَّهِ هَذَا مَقَامُ أَبِينَا إِبْرَاهِيمَ الَّذِي قَالَ اللَّهُ سُبْحَانَهُ ‏{وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى}‏ ‏.‏ قَالَ الْوَلِيدُ فَقُلْتُ لِمَالِكٍ هَكَذَا قَرَأَهَا ‏{وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى}‏ قَالَ نَعَمْ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 25, Hadith 3074","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-25/Hadith-3074","x":"Ja’far bin Muhammad narrated that his father said:\n\n\"We entered upon Jabir bin ‘Abdullah, and when we reached him he asked about the people (i.e., what their names were, etc.). When he reached me, I said: ‘I am Muhammad bin ‘Ali bin Husain.’ He stretched forth his hand towards my head, and undid my top button, then undid my lower button. Then he placed his hand on my chest, and I was a young boy at that time. Then he said: ‘Welcome to you, ask whatever you want.’ So I asked him, and he was blind. The time for prayer came, so he stood up, wrapping himself in a woven cloth. Every time he put it on his shoulders, its edges came up, because it was too small. And his cloak was beside him on a hook. He led us in prayer, then he said: ‘Tell us about the Hajj of the Messenger of Allah (ﷺ).’ He held up his hands, showing nine (fingers), and said: ‘The Messenger of Allah (ﷺ) stayed for nine years without performing Hajj, then it was announced to the people in the tenth year that the Messenger of Allah (ﷺ) was going for Hajj. So many people came to Al-Madinah, all of them seeking to follow the Messenger of Allah (ﷺ) and do what he did. He set out and we set out with him, and we came to Dhul-Hulaifah where Asma’ bint ‘Umais gave birth to Muhammad bin Abu Bakr. She sent word to the Messenger of Allah (ﷺ) asking what she should do. He said: \"Perform Ghusl, fasten a cloth around your waist and enter Ihram.\" The Messenger of Allah (ﷺ) prayed in the mosque, then he rode Qaswa’ (his she-camel) until, when his she-camel arose with him upon Baida’,’ Jabir said: ‘As far as I could see, I saw people riding and walking in front of him, and I saw the same to his right and left, and behind him, and the Messenger of Allah (ﷺ) was among us and Qur’an was being revealed to him, and he understood its meaning. Whatever he did, we did too. Then he began the Talbiyah of monotheism: \"Labbaika Allahumma labbaik, labbaika la sharika laka labbaik. Innal-hamda wan-ni’mata laka wal-mulk, la sharika laka (Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Verily all praise and blessings are Yours, and all sovereignty, You have no partner).\" And the people repeated his words. And the Messenger of Allah (ﷺ) approved of that. And the Messenger of Allah (ﷺ) continued to recite the Talbiyah.’ Jabir said: ‘We did not intend (to do) anything but Hajj. We were not aware of ‘Umrah. Then when we reached the House with him, he touched the Corner, and walked quickly (Ramal) for three circuits and walked (normally) for four. Then he stood at the place of Ibrahim and said: \"And take you (people) the place of Ibrahim as a place of prayer.\" [2:125] He stood with the place between him and the House. My father used to say:* \"And I do not think that he mentioned it other than from the Prophet (ﷺ): ‘That he used to recite in those two Rak’ah (at the place of Ibrahim): \"Say: ‘O you disbelievers!’\" [Al-Kafirun (109)] and \"Say: ‘He is Allah, (the) One.’\" [Al-Ikhlas (112)] \"Then he went back to the House and touched the Corner, then he went out through the gate to Safa. When he drew near to Safa he recited: \"Verily, Safa and Marwah are among the symbols of Allah,\" [2:158] (and said:) \"We will start with that with which Allah started.\" So he started with Safa and climbed it until he could see the House, then proclaimed the greatness of Allah (by saying: Allahu Akbar) and said Tahlil (La ilaha illallah) and praised Him (saying Al-Hamdulillah), and he said: \"La ilaha illallah wahdahu la sharika lahu, lahul-mulku, wa lahul-hamdu, yuhyi wa yumit wa huwa ‘ala kulli shai’in Qadir. La ilaha illallah wahdahu, La sharika lahu anjaza wa’dahu, wa nasara ‘abduhu, wa hazamal-Ahzaba wahdahu (None has the right to be worshiped but Allah alone, with no partner or associate; His is the dominion, all praise is due to Him, He gives life and causes death and He is able to do all things. None has the right to be worshiped but Allah alone; He has no partner or associate, He fulfilled His promise, granted victory to His slave, and defeated the Confederates alone).\" And he said that three times, supplication in between. Then he headed towards Marwah walking normally until, when he started to go downhill, he walked quickly (Ramal) in the bottom of the valley. When he started to go uphill, he walked normally, until he reached Marwah, and he did atop Marwah what he had done atop Safa. At the end of his Sa’y, atop Marwah he said: \"If I had known before what I have come to know now, I would not have garlanded the sacrificial animal, and I would have made it ‘Umrah. Whoever among you does not have a sacrificial animal with him, let him exit Ihram and make it ‘Umrah.\" So all the people exited Ihram and cut their hair, except the Prophet (ﷺ) and those who had sacrificial animals with them. Suraqah bin Malik bin Ju’shum stood up and said: \"O Messenger of Allah! Is this for this year only, or forever and ever?\" The Messenger of Allah (ﷺ) interlaced his fingers and said: \"‘Umrah is included in Hajj like this,\" twice. \"No, it is forever and ever.\" ‘Ali brought the camels of the Prophet (ﷺ), and he found that Fatimah was one of those who had exited Ihram. She had put on a dyed garment and used kohl. ‘Ali disliked this action on her part, but she said: \"My father told me to do this.\" ‘Ali used to say in Iraq: \"So I went to the Messenger of Allah (ﷺ), feeling upset with Fatimah because of what she had done, to ask the Messenger of Allah (ﷺ) about what she had said that he said, and that I had disliked that. He said: ‘She spoke the truth, she spoke the truth. What did you say when you began your Hajj?’\" He said: \"I said: ‘O Allah, I begin the Talbiyah for that for which your Messenger (ﷺ) begins the Talbiyah.’ (He said:) ‘And I have the sacrificial animal with me, so do not exit Ihram.’ He said: \"The total number of sacrificial animals that ‘Ali had brought from Yemen and that the Prophet (ﷺ) brought from Al-Madinah were one hundred. Then all the people exited Ihram and cut their hair, apart from the Prophet (ﷺ) and those who had sacrificial animals with them. When the day of Tarwiyah came (the 8th of Dhul-Hijjah), they headed for Mina and began the Talbiyah for Hajj. The Messenger of Allah (ﷺ) rode. He prayed Zuhr, ‘Asr, Maghrib, ‘Isha’ and Fajr at Mina. Then he stayed for a short while until the sun rose, and he ordered that a tent of goat hair be pitched for him in Namirah. Then the Messenger of Allah (ﷺ) set out, and the Quraish were certain that he was going to stay at Al-Mash’ar Haram or at Al-Muzdalifah, as Quraish used to do during the Ignorance days. But the Messenger of Allah (ﷺ) continued until he came to ‘Arafat, where he found that the tent had been pitched for him in Namirah, and he stopped there. Then when the sun had passed its zenith, he called for Qaswa’ and she was saddled for him. He rode until he came to the bottom of the valley, and he addressed the people and said: ‘Your blood and your wealth are sacred to you, as sacred as this day of yours, in this month of yours, in this land of yours. Every matter of Ignorance days is abolished, beneath these two feet of mine. The blood feuds of the Ignorance days are abolished, and the first blood feud of Rabi’ah bin Harith, who was nursed among Banu Sa’d and killed by Hudhail. The usuries of Ignorance days are abolished, and the first usury (that I abolish) is our usury, the usury due to ‘Abbas bin ‘Abdul-Muttalib. It is all abolished. Fear Allah with regard to women, for you have taken them as a trust from Allah, and intimacy with them has become permissible to you through Allah’s Word. Your rights over them are that they should not allow anyone whom you dislike to sit on your bedding.** If they do that, then hit them, but in a manner that does not cause injury or leave a mark. Their rights over you are that you should provide for them and clothe them in a reasonable manner. I have left behind you something which, if you adhere to it, you will never go astray: the Book of Allah. You will be asked about me. What will you say?’ They said: ‘We bear witness that you have conveyed (the message) and fulfilled (your duty) and offered sincere advice.’ He gestured with his forefinger towards the sky and then towards the people, (and said:) ‘O Allah, bear witness, O Allah bear witness,’ three times. Then Bilal called the Adhan, then the Iqamah, and he prayed Zuhr. Then he made Iqamah and prayed ‘Asr, and he did not offer any prayer between them. Then the Messenger of Allah (ﷺ) rode until he came to the place of standing, and he made his she-camel face Sakharat*** with the path in the sand in front of him, and he faced the Qiblah, then he remained standing until the sun had set and the afterglow had lessened somewhat, when the disk of the sun disappeared. Then he seated Usamah bin Zaid behind him and the Messenger of Allah (ﷺ) set out. He pulled Qaswa’s reins tight until her head was touching the saddle, and he gestured with his right hand: ‘O people, calmly, calmly!’ Every time he came to a hill, he released the reins a little so that she could climb. Then he came to Muzdalifah where he prayed Maghrib and ‘Isha’ with one Adhan and two Iqamah, offering no prayer in between. Then the Messenger of Allah (ﷺ) lay down until dawn came, and he prayed Fajr, when he saw that morning had come, with one Adhan and one Iqamah. Then he rode Qaswa’ until he came to Al-Mash’ar Al-Haram. He climbed it and praised Allah and proclaimed His greatness and that He is the only One worthy of worship. Then he remained standing until it had become quite bright, then he moved on before the sun rose. He seated Fadl bin ‘Abbas behind him, who was a man with lovely hair, white and handsome. When the Messenger of Allah (ﷺ) moved on, he passed some women riding camels. Fadl started to look at them, so the Messenger of Allah (ﷺ) put his hand on the other side. Fadl turned his face to the other side to look. When he came to Muhassir, he sped up a little. Then he followed the middle road that brings you out to the biggest Pillar, until he reached the Pillar that is by the tree. He threw seven pebbles, saying the Takbir with each throw, pebbles suitable for Khadhf (i.e., the size of a chickpea) throwing from the bottom of the valley. Then he went to the place of slaughter, and slaughtered sixty-three camels with his own hand. Then he handed it over to ‘Ali who slaughtered the rest, and he gave him a share in his sacrificial animal. Then he ordered that a piece from each camel be brought; (the pieces) were put in a pot and cooked, and they (the Prophet (ﷺ) and ‘Ali) ate from the meat and drank from the soup. Then the Messenger of Allah (ﷺ) hastened to the House, and prayed Zuhr in Makkah. He came to Banu ‘Abdul-Muttalib, who were providing water to the pilgrims at Zamzam, and said: ‘Draw me some water, O Banu ‘Abdul-Muttalib. Were it not that the people would overwhelm you, I would have drawn water with you.’ So they drew up a bucket for him and he drank from it.’\" * It appears that the speaker is Ja’far bin Muhammad who is narrating from his father, from Jabir. **And they say that the meaning if ‘your furniture’ or, ‘your special place’ in which case the objective is to say that the wife is not to admit anyone in the house whom the husband would be displeased with. ***Sakharat plural of Sakhrah rock or boulder. Nawawi said: \"They are the rocks that lay at the base of the Mount of Mercy, and it is the mount in the middle of ‘Arafat.\"","ar":"حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا حَاتِمُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا جَعْفَرُ بْنُ مُحَمَّدٍ، عَنْ أَبِيهِ، قَالَ دَخَلْنَا عَلَى جَابِرِ بْنِ عَبْدِ اللَّهِ فَلَمَّا انْتَهَيْنَا إِلَيْهِ سَأَلَ عَنِ الْقَوْمِ، حَتَّى انْتَهَى إِلَىَّ فَقُلْتُ أَنَا مُحَمَّدُ بْنُ عَلِيِّ بْنِ الْحُسَيْنِ، ‏.‏ فَأَهْوَى بِيَدِهِ إِلَى رَأْسِي فَحَلَّ زِرِّي الأَعْلَى ثُمَّ حَلَّ زِرِّي الأَسْفَلَ ثُمَّ وَضَعَ كَفَّهُ بَيْنَ ثَدْيَىَّ وَأَنَا يَوْمَئِذٍ غُلاَمٌ شَابٌّ فَقَالَ مَرْحَبًا بِكَ سَلْ عَمَّا شِئْتَ ‏.‏ فَسَأَلْتُهُ وَهُوَ أَعْمَى فَجَاءَ وَقْتُ الصَّلاَةِ فَقَامَ فِي نِسَاجَةٍ مُلْتَحِفًا بِهَا كُلَّمَا وَضَعَهَا عَلَى مَنْكِبَيْهِ رَجَعَ طَرَفَاهَا إِلَيْهِ مِنْ صِغَرِهَا وَرِدَاؤُهُ إِلَى جَانِبِهِ عَلَى الْمِشْجَبِ فَصَلَّى بِنَا فَقُلْتُ أَخْبِرْنَا عَنْ حَجَّةِ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ ‏.‏ فَقَالَ بِيَدِهِ فَعَقَدَ تِسْعًا وَقَالَ إِنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ مَكَثَ تِسْعَ سِنِينَ لَمْ يَحُجَّ فَأَذَّنَ فِي النَّاسِ فِي الْعَاشِرَةِ أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ حَاجٌّ فَقَدِمَ الْمَدِينَةَ بَشَرٌ كَثِيرٌ كُلُّهُمْ يَلْتَمِسُ أَنْ يَأْتَمَّ بِرَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ وَيَعْمَلَ بِمِثْلِ عَمَلِهِ فَخَرَجَ وَخَرَجْنَا مَعَهُ فَأَتَيْنَا ذَا الْحُلَيْفَةِ فَوَلَدَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ مُحَمَّدَ بْنَ أَبِي بَكْرٍ فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ كَيْفَ أَصْنَعُ قَالَ ‏\"‏ اغْتَسِلِي وَاسْتَثْفِرِي بِثَوْبٍ وَأَحْرِمِي ‏\"‏ ‏.‏ فَصَلَّى رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ فِي الْمَسْجِدِ ثُمَّ رَكِبَ الْقَصْوَاءَ ‏.‏ حَتَّى إِذَا اسْتَوَتْ بِهِ نَاقَتُهُ عَلَى الْبَيْدَاءِ - قَالَ جَابِرٌ نَظَرْتُ إِلَى مَدِّ بَصَرِي مِنْ بَيْنِ يَدَيْهِ بَيْنَ رَاكِبٍ وَمَاشٍ وَعَنْ يَمِينِهِ مِثْلُ ذَلِكَ وَعَنْ يَسَارِهِ مِثْلُ ذَلِكَ وَمِنْ خَلْفِهِ مِثْلُ ذَلِكَ وَرَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ بَيْنَ أَظْهُرِنَا وَعَلَيْهِ يَنْزِلُ الْقُرْآنُ وَهُوَ يَعْرِفُ تَأْوِيلَهُ مَا عَمِلَ مِنْ شَىْءٍ عَمِلْنَا بِهِ فَأَهَلَّ بِالتَّوْحِيدِ ‏\"‏ لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لاَ شَرِيكَ لَكَ ‏\"‏ ‏.‏ وَأَهَلَّ النَّاسُ بِهَذَا الَّذِي يُهِلُّونَ بِهِ فَلَمْ يَرُدَّ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ عَلَيْهِمْ شَيْئًا مِنْهُ وَلَزِمَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ تَلْبِيَتَهُ ‏.‏ قَالَ جَابِرٌ لَسْنَا نَنْوِي إِلاَّ الْحَجَّ لَسْنَا نَعْرِفُ الْعُمْرَةَ حَتَّى إِذَا أَتَيْنَا الْبَيْتَ مَعَهُ اسْتَلَمَ الرُّكْنَ فَرَمَلَ ثَلاَثًا وَمَشَى أَرْبَعًا ثُمَّ قَامَ إِلَى مَقَامِ إِبْرَاهِيمَ فَقَالَ ‏\"‏ ‏{وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى}‏ ‏\"‏ ‏.‏ فَجَعَلَ الْمَقَامَ بَيْنَهُ وَبَيْنَ الْبَيْتِ فَكَانَ أَبِي يَقُولُ - وَلاَ أَعْلَمُهُ إِلاَّ ذَكَرَهُ عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ - إِنَّهُ كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ ‏{قُلْ يَا أَيُّهَا الْكَافِرُونَ}‏ وَ ‏{قُلْ هُوَ اللَّهُ أَحَدٌ }‏ ‏.‏ ثُمَّ رَجَعَ إِلَى الْبَيْتِ فَاسْتَلَمَ الرُّكْنَ ثُمَّ خَرَجَ مِنَ الْبَابِ إِلَى الصَّفَا حَتَّى إِذَا دَنَا مِنَ الصَّفَا قَرَأَ ‏\"‏ ‏{إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ ‏)‏ ‏.‏ نَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ ‏\"‏ ‏.‏ فَبَدَأَ بِالصَّفَا ‏.‏ فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ فَكَبَّرَ اللَّهَ وَهَلَّلَهُ وَحَمِدَهُ وَقَالَ ‏\"‏ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ ‏\"‏ ‏.‏ ثُمَّ دَعَا بَيْنَ ذَلِكَ وَقَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ ثُمَّ نَزَلَ إِلَى الْمَرْوَةِ فَمَشَى حَتَّى إِذَا انْصَبَّتْ قَدَمَاهُ رَمَلَ فِي بَطْنِ الْوَادِي حَتَّى إِذَا صَعِدَتَا - يَعْنِي قَدَمَاهُ - مَشَى حَتَّى أَتَى الْمَرْوَةَ فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا فَلَمَّا كَانَ آخِرُ طَوَافِهِ عَلَى الْمَرْوَةِ ‏.‏ قَالَ ‏\"‏ لَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ لَمْ أَسُقِ الْهَدْىَ وَجَعَلْتُهَا عُمْرَةً فَمَنْ كَانَ مِنْكُمْ لَيْسَ مَعَهُ هَدْىٌ فَلْيَحْلِلْ وَلْيَجْعَلْهَا عُمْرَةً ‏\"‏ ‏.‏ فَحَلَّ النَّاسُ كُلُّهُمْ وَقَصَّرُوا إِلاَّ النَّبِيَّ ـ صلى الله عليه وسلم ـ وَمَنْ كَانَ مَعَهُ الْهَدْىُ فَقَامَ سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ فَقَالَ يَا رَسُولَ اللَّهِ أَلِعَامِنَا هَذَا أَمْ لأَبَدِ الأَبَدِ قَالَ فَشَبَّكَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ أَصَابِعَهُ فِي الأُخْرَى وَقَالَ ‏\"‏ دَخَلَتِ الْعُمْرَةُ فِي الْحَجِّ هَكَذَا - مَرَّتَيْنِ - لاَ بَلْ لأَبَدِ الأَبَدِ ‏\"‏ ‏.‏ قَالَ وَقَدِمَ عَلِيٌّ بِبُدْنٍ إِلَى النَّبِيِّ ـ صلى الله عليه وسلم ـ ‏.‏ فَوَجَدَ فَاطِمَةَ مِمَّنْ حَلَّ وَلَبِسَتْ ثِيابًا صَبِيغًا وَاكْتَحَلَتْ فَأَنْكَرَ ذَلِكَ عَلَيْهَا عَلِيٌّ فَقَالَتْ أَمَرَنِي أَبِي بِهَذَا ‏.‏ فَكَانَ عَلِيٌّ يَقُولُ بِالْعِرَاقِ فَذَهَبْتُ إِلَى رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ مُحَرِّشًا عَلَى فَاطِمَةَ فِي الَّذِي صَنَعَتْهُ مُسْتَفْتِيًا رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ فِي الَّذِي ذَكَرَتْ عَنْهُ وَأَنْكَرْتُ ذَلِكَ عَلَيْهَا ‏.‏ فَقَالَ ‏\"‏ صَدَقَتْ صَدَقَتْ مَاذَا قُلْتَ حِينَ فَرَضْتَ الْحَجَّ ‏\"‏ ‏.‏ قَالَ قُلْتُ اللَّهُمَّ إِنِّي أُهِلُّ بِمَا أَهَلَّ بِهِ رَسُولُكَ ـ صلى الله عليه وسلم ـ ‏.‏ قَالَ ‏\"‏ فَإِنَّ مَعِيَ الْهَدْىَ فَلاَ تَحِلُّ ‏\"‏ ‏.‏ قَالَ فَكَانَ جَمَاعَةُ الْهَدْىِ الَّذِي جَاءَ بِهِ عَلِيٌّ مِنَ الْيَمَنِ وَالَّذِي أَتَى بِهِ النَّبِيُّ ـ صلى الله عليه وسلم ـ مِنَ الْمَدِينَةِ مِائَةً ثُمَّ حَلَّ النَّاسُ كُلُّهُمْ وَقَصَّرُوا إِلاَّ النَّبِيَّ ـ صلى الله عليه وسلم ـ وَمَنْ كَانَ مَعَهُ هَدْىٌ فَلَمَّا كَانَ يَوْمُ التَّرْوِيَةِ وَتَوَجَّهُوا إِلَى مِنًى أَهَلُّوا بِالْحَجِّ ‏.‏ فَرَكِبَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ فَصَلَّى بِمِنًى الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ وَالصُّبْحَ ثُمَّ مَكَثَ قَلِيلاً حَتَّى طَلَعَتِ الشَّمْسُ وَأَمَرَ بِقُبَّةٍ مِنْ شَعَرٍ فَضُرِبَتْ لَهُ بِنَمِرَةَ فَسَارَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ لاَ تَشُكُّ قُرَيْشٌ إِلاَّ أَنَّهُ وَاقِفٌ عِنْدَ الْمَشْعَرِ الْحَرَامِ أَوِ الْمُزْدَلِفَةِ كَمَا كَانَتْ قُرَيْشٌ تَصْنَعُ فِي الْجَاهِلِيَّةِ فَأَجَازَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ حَتَّى أَتَى عَرَفَةَ فَوَجَدَ الْقُبَّةَ قَدْ ضُرِبَتْ لَهُ بِنَمِرَةَ فَنَزَلَ بِهَا حَتَّى إِذَا زَاغَتِ الشَّمْسُ أَمَرَ بِالْقَصْوَاءِ فَرُحِلَتْ لَهُ فَرَكِبَ حَتَّى أَتَى بَطْنَ الْوَادِي فَخَطَبَ النَّاسَ فَقَالَ ‏\"‏ إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا أَلاَ وَإِنَّ كُلَّ شَىْءٍ مِنْ أَمْرِ الْجَاهِلِيَّةِ مَوْضُوعٌ تَحْتَ قَدَمَىَّ هَاتَيْنِ وَدِمَاءُ الْجَاهِلِيَّةِ مَوْضُوعَةٌ وَأَوَّلُ دَمٍ أَضَعُهُ دَمُ رَبِيعَةَ بْنِ الْحَارِثِ - كَانَ مُسْتَرْضِعًا فِي بَنِي سَعْدٍ فَقَتَلَتْهُ هُذَيْلٌ - وَرِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ وَأَوَّلُ رِبًا أَضَعُهُ رِبَانَا رِبَا الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ فَإِنَّهُ مَوْضُوعٌ كُلُّهُ فَاتَّقُوا اللَّهَ فِي النِّسَاءِ فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانَةِ اللَّهِ وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ وَإِنَّ لَكُمْ عَلَيْهِنَّ أَنْ لاَ يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ وَلَهُنَّ عَلَيْكُمْ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ وَقَدْ تَرَكْتُ فِيكُمْ مَا لَمْ تَضِلُّوا إِنِ اعْتَصَمْتُمْ بِهِ كِتَابَ اللَّهِ وَأَنْتُمْ مَسْئُولُونَ عَنِّي فَمَا أَنْتُمْ قَائِلُونَ ‏\"‏ ‏.‏ قَالُوا نَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ وَأَدَّيْتَ وَنَصَحْتَ ‏.‏ فَقَالَ بِإِصْبَعِهِ السَّبَّابَةِ إِلَى السَّمَاءِ وَيَنْكُبُهَا إِلَى النَّاسِ ‏\"‏ اللَّهُمَّ اشْهَدِ اللَّهُمَّ اشْهَدْ ‏\"‏ ‏.‏ ثَلاَثَ مَرَّاتٍ ثُمَّ أَذَّنَ بِلاَلٌ ثُمَّ أَقَامَ فَصَلَّى الظُّهْرَ ثُمَّ أَقَامَ فَصَلَّى الْعَصْرَ وَلَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا ثُمَّ رَكِبَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ حَتَّى أَتَى الْمَوْقِفَ فَجَعَلَ بَطْنَ نَاقَتِهِ إِلَى الصَّخَرَاتِ وَجَعَلَ حَبْلَ الْمُشَاةِ بَيْنَ يَدَيْهِ وَاسْتَقْبَلَ الْقِبْلَةَ فَلَمْ يَزَلْ وَاقِفًا حَتَّى غَرَبَتِ الشَّمْسُ وَذَهَبَتِ الصُّفْرَةُ قَلِيلاً حَتَّى غَابَ الْقُرْصُ وَأَرْدَفَ أُسَامَةَ بْنَ زَيْدٍ خَلْفَهُ فَدَفَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ وَقَدْ شَنَقَ الْقَصْوَاءَ بِالزِّمَامِ حَتَّى إِنَّ رَأْسَهَا لَيُصِيبُ مَوْرِكَ رَحْلِهِ وَيَقُولُ بِيَدِهِ الْيُمْنَى ‏\"‏ أَيُّهَا النَّاسُ السَّكِينَةَ السَّكِينَةَ ‏\"‏ ‏.‏ كُلَّمَا أَتَى حَبْلاً مِنَ الْحِبَالِ أَرْخَى لَهَا قَلِيلاً حَتَّى تَصْعَدَ ثُمَّ أَتَى الْمُزْدَلِفَةَ فَصَلَّى بِهَا الْمَغْرِبَ وَالْعِشَاءَ بِأَذَانٍ وَاحِدٍ وَإِقَامَتَيْنِ وَلَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا ثُمَّ اضْطَجَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ حَتَّى طَلَعَ الْفَجْرُ فَصَلَّى الْفَجْرَ حِينَ تَبَيَّنَ لَهُ الصُّبْحُ بِأَذَانٍ وَإِقَامَةٍ ثُمَّ رَكِبَ الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَرَقِيَ عَلَيْهِ فَحَمِدَ اللَّهَ وَكَبَّرَهُ وَهَلَّلَهُ فَلَمْ يَزَلْ وَاقِفًا حَتَّى أَسْفَرَ جِدًّا ثُمَّ دَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ وَأَرْدَفَ الْفَضْلَ بْنَ الْعَبَّاسِ وَكَانَ رَجُلاً حَسَنَ الشَّعَرِ أَبْيَضَ وَسِيمًا فَلَمَّا دَفَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ مَرَّ الظُّعُنُ يَجْرِينَ فَطَفِقَ الْفَضْلُ يَنْظُرُ إِلَيْهِنَّ فَوَضَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ يَدَهُ مِنَ الشِّقِّ الآخَرِ فَصَرَفَ الْفَضْلُ وَجْهَهُ مِنَ الشِّقِّ الآخَرِ يَنْظُرُ حَتَّى أَتَى مُحَسِّرًا حَرَّكَ قَلِيلاً ثُمَّ سَلَكَ الطَّرِيقَ الْوُسْطَى الَّتِي تُخْرِجُكَ إِلَى الْجَمْرَةِ الْكُبْرَى حَتَّى أَتَى الْجَمْرَةَ الَّتِي عِنْدَ الشَّجَرَةِ فَرَمَى بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ مِنْهَا مِثْلِ حَصَى الْخَذْفِ وَرَمَى مِنْ بَطْنِ الْوَادِي ثُمَّ انْصَرَفَ إِلَى الْمَنْحَرِ فَنَحَرَ ثَلاَثًا وَسِتِّينَ بَدَنَةً بِيَدِهِ وَأَعْطَى عَلِيًّا فَنَحَرَ مَا غَبَرَ وَأَشْرَكَهُ فِي هَدْيِهِ ثُمَّ أَمَرَ مِنْ كُلِّ بَدَنَةٍ بِبَضْعَةٍ فَجُعِلَتْ فِي قِدْرٍ فَطُبِخَتْ فَأَكَلاَ مِنْ لَحْمِهَا وَشَرِبَا مِنْ مَرَقِهَا ثُمَّ أَفَاضَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ إِلَى الْبَيْتِ فَصَلَّى بِمَكَّةَ الظُّهْرَ فَأَتَى بَنِي عَبْدِ الْمُطَّلِبِ وَهُمْ يَسْقُونَ عَلَى زَمْزَمَ فَقَالَ ‏\"‏ انْزِعُوا بَنِي عَبْدِ الْمُطَّلِبِ لَوْلاَ أَنْ يَغْلِبَكُمُ النَّاسُ عَلَى سِقَايَتِكُمْ لَنَزَعْتُ مَعَكُمْ ‏\"‏ ‏.‏ فَنَاوَلُوهُ دَلْوًا فَشَرِبَ مِنْهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2959","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2959","x":"Narrated Anas:\n\nthat 'Umar bin Al-Khattab said: \"O Messenger of Allah (ﷺ)! I wish that we could perform Salat behind the Maqam: So the following was revealed: And take you the Maqam of Ibrahim as a place of Salat. (2:125).\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا الْحَجَّاجُ بْنُ مِنْهَالٍ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ حُمَيْدٍ، عَنْ أَنَسٍ، أَنَّ عُمَرَ، قَالَ يَا رَسُولَ اللَّهِ لَوْ صَلَّيْنَا خَلْفَ الْمَقَامِ فَنَزَلَتْ ‏:‏ ‏(‏وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2960","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2960","x":"Narrated Anas:\n\nthat 'Umar bin Al-Khattab [may Allah be pleased with him] said: \"I said: 'O Messenger of Allah (ﷺ)! I wish that you could perform Salat behind the Maqam of Ibrahim.' So the following was revealed: And take you the Maqam of Ibrahim as a place of Salat.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا حُمَيْدٌ الطَّوِيلُ، عَنْ أَنَسٍ، قَالَ قَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قُلْتُ لِرَسُولِ اللَّهِ صلى الله عليه وسلم لَوِ اتَّخَذْتَ مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى فَنَزَلَتْ ‏:‏ ‏(‏وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَفِي الْبَابِ عَنِ ابْنِ عُمَرَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2967","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2967","x":"Narrated Jabir bin 'Abdullah:\n\n\"When the Messenger of Allah (ﷺ) arrived in Makkah, performing Tawaf around the House seven times, I heard him reciting: And take the Maqam of Ibrahim as a place of prayer (2:125). So he performed Salat behind the Maqam, then he came to the (Black) Stone, then he said: 'We begin with what Allah began with.' So he began at As-Safa and recited: Indeed As-Safa and Al-Marwah are among the Symbols of Allah (2:158).\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم حِينَ قَدِمَ مَكَّةَ طَافَ بِالْبَيْتِ سَبْعًا فَقَرَأَ ‏:‏ ‏(‏وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى ‏)‏ فَصَلَّى خَلْفَ الْمَقَامِ ثُمَّ أَتَى الْحَجَرَ فَاسْتَلَمَهُ ثُمَّ قَالَ ‏\"‏ نَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ ‏\"‏ ‏.‏ وَقَرَأَ ‏:‏ ‏(‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"127":[{"c":"Sahih Bukhari","r":"Hadith 3364","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3364","x":"Narrated Ibn `Abbas:\n\nThe first lady to use a girdle was the mother of Ishmael. She used a girdle so that she might hide her tracks from Sarah. Abraham brought her and her son Ishmael while she was suckling him, to a place near the Ka`ba under a tree on the spot of Zamzam, at the highest place in the mosque. During those days there was nobody in Mecca, nor was there any water So he made them sit over there and placed near them a leather bag containing some dates, and a small water-skin containing some water, and set out homeward. Ishmael's mother followed him saying, \"O Abraham! Where are you going, leaving us in this valley where there is no person whose company we may enjoy, nor is there anything (to enjoy)?\" She repeated that to him many times, but he did not look back at her Then she asked him, \"Has Allah ordered you to do so?\" He said, \"Yes.\" She said, \"Then He will not neglect us,\" and returned while Abraham proceeded onwards, and on reaching the Thaniya where they could not see him, he faced the Ka`ba, and raising both hands, invoked Allah saying the following prayers: 'O our Lord! I have made some of my offspring dwell in a valley without cultivation, by Your Sacred House (Ka`ba at Mecca) in order, O our Lord, that they may offer prayer perfectly. So fill some hearts among men with love towards them, and (O Allah) provide them with fruits, so that they may give thanks.' (14.37) Ishmael's mother went on suckling Ishmael and drinking from the water (she had). When the water in the water-skin had all been used up, she became thirsty and her child also became thirsty. She started looking at him (i.e. Ishmael) tossing in agony; She left him, for she could not endure looking at him, and found that the mountain of Safa was the nearest mountain to her on that land. She stood on it and started looking at the valley keenly so that she might see somebody, but she could not see anybody. Then she descended from Safa and when she reached the valley, she tucked up her robe and ran in the valley like a person in distress and trouble, till she crossed the valley and reached the Marwa mountain where she stood and started looking, expecting to see somebody, but she could not see anybody. She repeated that (running between Safa and Marwa) seven times.\" The Prophet (ﷺ) said, \"This is the source of the tradition of the walking of people between them (i.e. Safa and Marwa). When she reached the Marwa (for the last time) she heard a voice and she asked herself to be quiet and listened attentively. She heard the voice again and said, 'O, (whoever you may be)! You have made me hear your voice; have you got something to help me?\" And behold! She saw an angel at the place of Zamzam, digging the earth with his heel (or his wing), till water flowed from that place. She started to make something like a basin around it, using her hand in this way, and started filling her water-skin with water with her hands, and the water was flowing out after she had scooped some of it.\" The Prophet (ﷺ) added, \"May Allah bestow Mercy on Ishmael's mother! Had she let the Zamzam (flow without trying to control it) (or had she not scooped from that water) (to fill her water-skin), Zamzam would have been a stream flowing on the surface of the earth.\" The Prophet (ﷺ) further added, \"Then she drank (water) and suckled her child. The angel said to her, 'Don't be afraid of being neglected, for this is the House of Allah which will be built by this boy and his father, and Allah never neglects His people.' The House (i.e. Ka`ba) at that time was on a high place resembling a hillock, and when torrents came, they flowed to its right and left. She lived in that way till some people from the tribe of Jurhum or a family from Jurhum passed by her and her child, as they (i.e. the Jurhum people) were coming through the way of Kada'. They landed in the lower part of Mecca where they saw a bird that had the habit of flying around water and not leaving it. They said, 'This bird must be flying around water, though we know that there is no water in this valley.' They sent one or two messengers who discovered the source of water, and returned to inform them of the water. So, they all came (towards the water).\" The Prophet (ﷺ) added, \"Ishmael's mother was sitting near the water. They asked her, 'Do you allow us to stay with you?\" She replied, 'Yes, but you will have no right to possess the water.' They agreed to that.\" The Prophet (ﷺ) further said, \"Ishmael's mother was pleased with the whole situation as she used to love to enjoy the company of the people. So, they settled there, and later on they sent for their families who came and settled with them so that some families became permanent residents there. The child (i.e. Ishmael) grew up and learnt Arabic from them and (his virtues) caused them to love and admire him as he grew up, and when he reached the age of puberty they made him marry a woman from amongst them. After Ishmael's mother had died, Abraham came after Ishmael's marriage in order to see his family that he had left before, but he did not find Ishmael there. When he asked Ishmael's wife about him, she replied, 'He has gone in search of our livelihood.' Then he asked her about their way of living and their condition, and she replied, 'We are living in misery; we are living in hardship and destitution,' complaining to him. He said, 'When your husband returns, convey my salutation to him and tell him to change the threshold of the gate (of his house).' When Ishmael came, he seemed to have felt something unusual, so he asked his wife, 'Has anyone visited you?' She replied, 'Yes, an old man of so-and-so description came and asked me about you and I informed him, and he asked about our state of living, and I told him that we were living in a hardship and poverty.' On that Ishmael said, 'Did he advise you anything?' She replied, 'Yes, he told me to convey his salutation to you and to tell you to change the threshold of your gate.' Ishmael said, 'It was my father, and he has ordered me to divorce you. Go back to your family.' So, Ishmael divorced her and married another woman from amongst them (i.e. Jurhum). Then Abraham stayed away from them for a period as long as Allah wished and called on them again but did not find Ishmael. So he came to Ishmael's wife and asked her about Ishmael. She said, 'He has gone in search of our livelihood.' Abraham asked her, 'How are you getting on?' asking her about their sustenance and living. She replied, 'We are prosperous and well-off (i.e. we have everything in abundance).' Then she thanked Allah' Abraham said, 'What kind of food do you eat?' She said. 'Meat.' He said, 'What do you drink?' She said, 'Water.\" He said, \"O Allah! Bless their meat and water.\" The Prophet added, \"At that time they did not have grain, and if they had grain, he would have also invoked Allah to bless it.\" The Prophet (ﷺ) added, \"If somebody has only these two things as his sustenance, his health and disposition will be badly affected, unless he lives in Mecca.\" The Prophet (ﷺ) added,\" Then Abraham said Ishmael's wife, \"When your husband comes, give my regards to him and tell him that he should keep firm the threshold of his gate.' When Ishmael came back, he asked his wife, 'Did anyone call on you?' She replied, 'Yes, a good-looking old man came to me,' so she praised him and added. 'He asked about you, and I informed him, and he asked about our livelihood and I told him that we were in a good condition.' Ishmael asked her, 'Did he give you any piece of advice?' She said, 'Yes, he told me to give his regards to you and ordered that you should keep firm the threshold of your gate.' On that Ishmael said, 'It was my father, and you are the threshold (of the gate). He has ordered me to keep you with me.' Then Abraham stayed away from them for a period as long as Allah wished, and called on them afterwards. He saw Ishmael under a tree near Zamzam, sharpening his arrows. When he saw Abraham, he rose up to welcome him (and they greeted each other as a father does with his son or a son does with his father). Abraham said, 'O Ishmael! Allah has given me an order.' Ishmael said, 'Do what your Lord has ordered you to do.' Abraham asked, 'Will you help me?' Ishmael said, 'I will help you.' Abraham said, Allah has ordered me to build a house here,' pointing to a hillock higher than the land surrounding it.\" The Prophet (ﷺ) added, \"Then they raised the foundations of the House (i.e. the Ka`ba). Ishmael brought the stones and Abraham was building, and when the walls became high, Ishmael brought this stone and put it for Abraham who stood over it and carried on building, while Ishmael was handing him the stones, and both of them were saying, 'O our Lord! Accept (this service) from us, Verily, You are the All-Hearing, the All-Knowing.' The Prophet (ﷺ) added, \"Then both of them went on building and going round the Ka`ba saying: O our Lord ! Accept (this service) from us, Verily, You are the All-Hearing, the All-Knowing.\" (2.127)","ar":"وَحَدَّثَنِي عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنْ أَيُّوبَ السَّخْتِيَانِيِّ، وَكَثِيرِ بْنِ كَثِيرِ بْنِ الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ،، يَزِيدُ أَحَدُهُمَا عَلَى الآخَرِ عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ ابْنُ عَبَّاسٍ أَوَّلَ مَا اتَّخَذَ النِّسَاءُ الْمِنْطَقَ مِنْ قِبَلِ أُمِّ إِسْمَاعِيلَ، اتَّخَذَتْ مِنْطَقًا لَتُعَفِّيَ أَثَرَهَا عَلَى سَارَةَ، ثُمَّ جَاءَ بِهَا إِبْرَاهِيمُ، وَبِابْنِهَا إِسْمَاعِيلَ وَهْىَ تُرْضِعُهُ حَتَّى وَضَعَهُمَا عِنْدَ الْبَيْتِ عِنْدَ دَوْحَةٍ، فَوْقَ زَمْزَمَ فِي أَعْلَى الْمَسْجِدِ، وَلَيْسَ بِمَكَّةَ يَوْمَئِذٍ أَحَدٌ، وَلَيْسَ بِهَا مَاءٌ، فَوَضَعَهُمَا هُنَالِكَ، وَوَضَعَ عِنْدَهُمَا جِرَابًا فِيهِ تَمْرٌ وَسِقَاءً فِيهِ مَاءٌ، ثُمَّ قَفَّى إِبْرَاهِيمُ مُنْطَلِقًا فَتَبِعَتْهُ أُمُّ إِسْمَاعِيلَ فَقَالَتْ يَا إِبْرَاهِيمُ أَيْنَ تَذْهَبُ وَتَتْرُكُنَا بِهَذَا الْوَادِي الَّذِي لَيْسَ فِيهِ إِنْسٌ وَلاَ شَىْءٌ فَقَالَتْ لَهُ ذَلِكَ مِرَارًا، وَجَعَلَ لاَ يَلْتَفِتُ إِلَيْهَا فَقَالَتْ لَهُ آللَّهُ الَّذِي أَمَرَكَ بِهَذَا قَالَ نَعَمْ‏.‏ قَالَتْ إِذًا لاَ يُضَيِّعُنَا‏.‏ ثُمَّ رَجَعَتْ، فَانْطَلَقَ إِبْرَاهِيمُ حَتَّى إِذَا كَانَ عِنْدَ الثَّنِيَّةِ حَيْثُ لاَ يَرَوْنَهُ اسْتَقْبَلَ بِوَجْهِهِ الْبَيْتَ، ثُمَّ دَعَا بِهَؤُلاَءِ الْكَلِمَاتِ وَرَفَعَ يَدَيْهِ، فَقَالَ ‏{‏رَبَّنَا إِنِّي أَسْكَنْتُ مِنْ ذُرِّيَّتِي بِوَادٍ غَيْرِ ذِي زَرْعٍ‏}‏ حَتَّى بَلَغَ ‏{‏يَشْكُرُونَ‏}‏‏.‏ وَجَعَلَتْ أُمُّ إِسْمَاعِيلَ تُرْضِعُ إِسْمَاعِيلَ، وَتَشْرَبُ مِنْ ذَلِكَ الْمَاءِ، حَتَّى إِذَا نَفِدَ مَا فِي السِّقَاءِ عَطِشَتْ وَعَطِشَ ابْنُهَا، وَجَعَلَتْ تَنْظُرُ إِلَيْهِ يَتَلَوَّى ـ أَوْ قَالَ يَتَلَبَّطُ ـ فَانْطَلَقَتْ كَرَاهِيَةَ أَنْ تَنْظُرَ إِلَيْهِ، فَوَجَدَتِ الصَّفَا أَقْرَبَ جَبَلٍ فِي الأَرْضِ يَلِيهَا، فَقَامَتْ عَلَيْهِ ثُمَّ اسْتَقْبَلَتِ الْوَادِيَ تَنْظُرُ هَلْ تَرَى أَحَدًا فَلَمْ تَرَ أَحَدًا، فَهَبَطَتْ مِنَ، الصَّفَا حَتَّى إِذَا بَلَغَتِ الْوَادِيَ رَفَعَتْ طَرَفَ دِرْعِهَا، ثُمَّ سَعَتْ سَعْىَ الإِنْسَانِ الْمَجْهُودِ، حَتَّى جَاوَزَتِ الْوَادِيَ، ثُمَّ أَتَتِ الْمَرْوَةَ، فَقَامَتْ عَلَيْهَا وَنَظَرَتْ هَلْ تَرَى أَحَدًا، فَلَمْ تَرَ أَحَدًا، فَفَعَلَتْ ذَلِكَ سَبْعَ مَرَّاتٍ ـ قَالَ ابْنُ عَبَّاسٍ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ فَذَلِكَ سَعْىُ النَّاسِ بَيْنَهُمَا ‏\"‏‏.‏ ـ فَلَمَّا أَشْرَفَتْ عَلَى الْمَرْوَةِ سَمِعَتْ صَوْتًا، فَقَالَتْ صَهٍ‏.‏ تُرِيدَ نَفْسَهَا، ثُمَّ تَسَمَّعَتْ، فَسَمِعَتْ أَيْضًا، فَقَالَتْ قَدْ أَسْمَعْتَ، إِنْ كَانَ عِنْدَكَ غِوَاثٌ‏.‏ فَإِذَا هِيَ بِالْمَلَكِ، عِنْدَ مَوْضِعِ زَمْزَمَ، فَبَحَثَ بِعَقِبِهِ ـ أَوْ قَالَ بِجَنَاحِهِ ـ حَتَّى ظَهَرَ الْمَاءُ، فَجَعَلَتْ تُحَوِّضُهُ وَتَقُولُ بِيَدِهَا هَكَذَا، وَجَعَلَتْ تَغْرِفُ مِنَ الْمَاءِ فِي سِقَائِهَا، وَهْوَ يَفُورُ بَعْدَ مَا تَغْرِفُ ـ قَالَ ابْنُ عَبَّاسٍ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ يَرْحَمُ اللَّهُ أُمَّ إِسْمَاعِيلَ لَوْ تَرَكَتْ زَمْزَمَ ـ أَوْ قَالَ لَوْ لَمْ تَغْرِفْ مِنَ الْمَاءِ ـ لَكَانَتْ زَمْزَمُ عَيْنًا مَعِينًا ‏\"‏‏.‏ ـ قَالَ فَشَرِبَتْ وَأَرْضَعَتْ وَلَدَهَا، فَقَالَ لَهَا الْمَلَكُ لاَ تَخَافُوا الضَّيْعَةَ، فَإِنَّ هَا هُنَا بَيْتَ اللَّهِ، يَبْنِي هَذَا الْغُلاَمُ، وَأَبُوهُ، وَإِنَّ اللَّهَ لاَ يُضِيعُ أَهْلَهُ‏.‏ وَكَانَ الْبَيْتُ مُرْتَفِعًا مِنَ الأَرْضِ كَالرَّابِيَةِ، تَأْتِيهِ السُّيُولُ فَتَأْخُذُ عَنْ يَمِينِهِ وَشِمَالِهِ، فَكَانَتْ كَذَلِكَ، حَتَّى مَرَّتْ بِهِمْ رُفْقَةٌ مِنْ جُرْهُمَ ـ أَوْ أَهْلُ بَيْتٍ مِنْ جُرْهُمَ ـ مُقْبِلِينَ مِنْ طَرِيقِ كَدَاءٍ فَنَزَلُوا فِي أَسْفَلِ مَكَّةَ، فَرَأَوْا طَائِرًا عَائِفًا‏.‏ فَقَالُوا إِنَّ هَذَا الطَّائِرَ لَيَدُورُ عَلَى مَاءٍ، لَعَهْدُنَا بِهَذَا الْوَادِي وَمَا فِيهِ مَاءٌ، فَأَرْسَلُوا جَرِيًّا أَوْ جَرِيَّيْنِ، فَإِذَا هُمْ بِالْمَاءِ، فَرَجَعُوا فَأَخْبَرُوهُمْ بِالْمَاءِ، فَأَقْبَلُوا، قَالَ وَأُمُّ إِسْمَاعِيلَ عِنْدَ الْمَاءِ فَقَالُوا أَتَأْذَنِينَ لَنَا أَنْ نَنْزِلَ عِنْدَكِ فَقَالَتْ نَعَمْ، وَلَكِنْ لاَ حَقَّ لَكُمْ فِي الْمَاءِ‏.‏ قَالُوا نَعَمْ‏.‏ قَالَ ابْنُ عَبَّاسٍ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ فَأَلْفَى ذَلِكَ أُمَّ إِسْمَاعِيلَ، وَهْىَ تُحِبُّ الإِنْسَ ‏\"‏ فَنَزَلُوا وَأَرْسَلُوا إِلَى أَهْلِيهِمْ، فَنَزَلُوا مَعَهُمْ حَتَّى إِذَا كَانَ بِهَا أَهْلُ أَبْيَاتٍ مِنْهُمْ، وَشَبَّ الْغُلاَمُ، وَتَعَلَّمَ الْعَرَبِيَّةَ مِنْهُمْ، وَأَنْفَسَهُمْ وَأَعْجَبَهُمْ حِينَ شَبَّ، فَلَمَّا أَدْرَكَ زَوَّجُوهُ امْرَأَةً مِنْهُمْ، وَمَاتَتْ أُمُّ إِسْمَاعِيلَ، فَجَاءَ إِبْرَاهِيمُ، بَعْدَ مَا تَزَوَّجَ إِسْمَاعِيلُ يُطَالِعُ تَرِكَتَهُ، فَلَمْ يَجِدْ إِسْمَاعِيلَ، فَسَأَلَ امْرَأَتَهُ عَنْهُ فَقَالَتْ خَرَجَ يَبْتَغِي لَنَا‏.‏ ثُمَّ سَأَلَهَا عَنْ عَيْشِهِمْ وَهَيْئَتِهِمْ فَقَالَتْ نَحْنُ بِشَرٍّ، نَحْنُ فِي ضِيقٍ وَشِدَّةٍ‏.‏ فَشَكَتْ إِلَيْهِ‏.‏ قَالَ فَإِذَا جَاءَ زَوْجُكِ فَاقْرَئِي عَلَيْهِ السَّلاَمَ، وَقُولِي لَهُ يُغَيِّرْ عَتَبَةَ بَابِهِ‏.‏ فَلَمَّا جَاءَ إِسْمَاعِيلُ، كَأَنَّهُ آنَسَ شَيْئًا، فَقَالَ هَلْ جَاءَكُمْ مِنْ أَحَدٍ قَالَتْ نَعَمْ، جَاءَنَا شَيْخٌ كَذَا وَكَذَا، فَسَأَلَنَا عَنْكَ فَأَخْبَرْتُهُ، وَسَأَلَنِي كَيْفَ عَيْشُنَا فَأَخْبَرْتُهُ أَنَّا فِي جَهْدٍ وَشِدَّةٍ‏.‏ قَالَ فَهَلْ أَوْصَاكِ بِشَىْءٍ قَالَتْ نَعَمْ، أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ السَّلاَمَ، وَيَقُولُ غَيِّرْ عَتَبَةَ بَابِكَ‏.‏ قَالَ ذَاكِ أَبِي وَقَدْ أَمَرَنِي أَنْ أُفَارِقَكِ الْحَقِي بِأَهْلِكِ‏.‏ فَطَلَّقَهَا، وَتَزَوَّجَ مِنْهُمْ أُخْرَى، فَلَبِثَ عَنْهُمْ إِبْرَاهِيمُ مَا شَاءَ اللَّهُ ثُمَّ أَتَاهُمْ بَعْدُ، فَلَمْ يَجِدْهُ، فَدَخَلَ عَلَى امْرَأَتِهِ، فَسَأَلَهَا عَنْهُ‏.‏ فَقَالَتْ خَرَجَ يَبْتَغِي لَنَا‏.‏ قَالَ كَيْفَ أَنْتُمْ وَسَأَلَهَا عَنْ عَيْشِهِمْ، وَهَيْئَتِهِمْ‏.‏ فَقَالَتْ نَحْنُ بِخَيْرٍ وَسَعَةٍ‏.‏ وَأَثْنَتْ عَلَى اللَّهِ‏.‏ فَقَالَ مَا طَعَامُكُمْ قَالَتِ اللَّحْمُ‏.‏ قَالَ فَمَا شَرَابُكُمْ قَالَتِ الْمَاءُ‏.‏ فَقَالَ اللَّهُمَّ بَارِكْ لَهُمْ فِي اللَّحْمِ وَالْمَاءِ‏.‏ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ وَلَمْ يَكُنْ لَهُمْ يَوْمَئِذٍ حَبٌّ، وَلَوْ كَانَ لَهُمْ دَعَا لَهُمْ فِيهِ ‏\"‏‏.‏ قَالَ فَهُمَا لاَ يَخْلُو عَلَيْهِمَا أَحَدٌ بِغَيْرِ مَكَّةَ إِلاَّ لَمْ يُوَافِقَاهُ‏.‏ قَالَ فَإِذَا جَاءَ زَوْجُكِ فَاقْرَئِي عَلَيْهِ السَّلاَمَ، وَمُرِيهِ يُثْبِتُ عَتَبَةَ بَابِهِ، فَلَمَّا جَاءَ إِسْمَاعِيلُ قَالَ هَلْ أَتَاكُمْ مِنْ أَحَدٍ قَالَتْ نَعَمْ أَتَانَا شَيْخٌ حَسَنُ الْهَيْئَةِ، وَأَثْنَتْ عَلَيْهِ، فَسَأَلَنِي عَنْكَ فَأَخْبَرْتُهُ، فَسَأَلَنِي كَيْفَ عَيْشُنَا فَأَخْبَرْتُهُ أَنَّا بِخَيْرٍ‏.‏ قَالَ فَأَوْصَاكِ بِشَىْءٍ قَالَتْ نَعَمْ، هُوَ يَقْرَأُ عَلَيْكَ السَّلاَمَ، وَيَأْمُرُكَ أَنْ تُثْبِتَ عَتَبَةَ بَابِكَ‏.‏ قَالَ ذَاكِ أَبِي، وَأَنْتِ الْعَتَبَةُ، أَمَرَنِي أَنْ أُمْسِكَكِ‏.‏ ثُمَّ لَبِثَ عَنْهُمْ مَا شَاءَ اللَّهُ، ثُمَّ جَاءَ بَعْدَ ذَلِكَ، وَإِسْمَاعِيلُ يَبْرِي نَبْلاً لَهُ تَحْتَ دَوْحَةٍ قَرِيبًا مِنْ زَمْزَمَ، فَلَمَّا رَآهُ قَامَ إِلَيْهِ، فَصَنَعَا كَمَا يَصْنَعُ الْوَالِدُ بِالْوَلَدِ وَالْوَلَدُ بِالْوَالِدِ، ثُمَّ قَالَ يَا إِسْمَاعِيلُ، إِنَّ اللَّهَ أَمَرَنِي بِأَمْرٍ‏.‏ قَالَ فَاصْنَعْ مَا أَمَرَكَ رَبُّكَ‏.‏ قَالَ وَتُعِينُنِي قَالَ وَأُعِينُكَ‏.‏ قَالَ فَإِنَّ اللَّهَ أَمَرَنِي أَنْ أَبْنِيَ هَا هُنَا بَيْتًا‏.‏ وَأَشَارَ إِلَى أَكَمَةٍ مُرْتَفِعَةٍ عَلَى مَا حَوْلَهَا‏.‏ قَالَ فَعِنْدَ ذَلِكَ رَفَعَا الْقَوَاعِدَ مِنَ الْبَيْتِ، فَجَعَلَ إِسْمَاعِيلُ يَأْتِي بِالْحِجَارَةِ، وَإِبْرَاهِيمُ يَبْنِي، حَتَّى إِذَا ارْتَفَعَ الْبِنَاءُ جَاءَ بِهَذَا الْحَجَرِ فَوَضَعَهُ لَهُ، فَقَامَ عَلَيْهِ وَهْوَ يَبْنِي، وَإِسْمَاعِيلُ يُنَاوِلُهُ الْحِجَارَةَ، وَهُمَا يَقُولاَنِ ‏{‏رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ‏}‏‏.‏ قَالَ فَجَعَلاَ يَبْنِيَانِ حَتَّى يَدُورَا حَوْلَ الْبَيْتِ، وَهُمَا يَقُولاَنِ ‏{‏رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3365","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3365","x":"Narrated Ibn `Abbas:\n\nWhen Abraham had differences with his wife), (because of her jealousy of Hajar, Ishmael's mother), he took Ishmael and his mother and went away. They had a water-skin with them containing some water, Ishmael's mother used to drink water from the water-skin so that her milk would increase for her child. When Abraham reached Mecca, he made her sit under a tree and afterwards returned home. Ishmael's mother followed him, and when they reached Kada', she called him from behind, 'O Abraham! To whom are you leaving us?' He replied, '(I am leaving you) to Allah's (Care).' She said, 'I am satisfied to be with Allah.' She returned to her place and started drinking water from the water-skin, and her milk increased for her child. When the water had all been used up, she said to herself, 'I'd better go and look so that I may see somebody.' She ascended the Safa mountain and looked, hoping to see somebody, but in vain. When she came down to the valley, she ran till she reached the Marwa mountain. She ran to and fro (between the two mountains) many times. They she said to herself, 'i'd better go and see the state of the child,' she went and found it in a state of one on the point of dying. She could not endure to watch it dying and said (to herself), 'If I go and look, I may find somebody.' She went and ascended the Safa mountain and looked for a long while but could not find anybody. Thus she completed seven rounds (of running) between Safa and Marwa. Again she said (to herself), 'I'd better go back and see the state of the child.' But suddenly she heard a voice, and she said to that strange voice, 'Help us if you can offer any help.' Lo! It was Gabriel (who had made the voice). Gabriel hit the earth with his heel like this (Ibn `Abbas hit the earth with his heel to Illustrate it), and so the water gushed out. Ishmael's mother was astonished and started digging. (Abu Al-Qasim) (i.e. the Prophet) said, \"If she had left the water, (flow naturally without her intervention), it would have been flowing on the surface of the earth.\") Ishmael's mother started drinking from the water and her milk increased for her child. Afterwards some people of the tribe of Jurhum, while passing through the bottom of the valley, saw some birds, and that astonished them, and they said, 'Birds can only be found at a place where there is water.' They sent a messenger who searched the place and found the water, and returned to inform them about it. Then they all went to her and said, 'O ishmael's mother! Will you allow us to be with you (or dwell with you)?' (And thus they stayed there.) Later on her boy reached the age of puberty and married a lady from them. Then an idea occurred to Abraham which he disclosed to his wife (Sarah), 'I want to call on my dependents I left (at Mecca).' When he went there, he greeted (Ishmael's wife) and said, 'Where is Ishmael?' She replied, 'He has gone out hunting.' Abraham said (to her), 'When he comes, tell him to change the threshold of his gate.' When he came, she told him the same whereupon Ishmael said to her, 'You are the threshold, so go to your family (i.e. you are divorced).' Again Abraham thought of visiting his dependents whom he had left (at Mecca), and he told his wife (Sarah) of his intentions. Abraham came to Ishmael's house and asked. \"Where is Ishmael?\" Ishmael's wife replied, \"He has gone out hunting,\" and added, \"Will you stay (for some time) and have something to eat and drink?' Abraham asked, 'What is your food and what is your drink?' She replied, 'Our food is meat and our drink is water.' He said, 'O Allah! Bless their meals and their drink.\" Abu Al-Qa-sim (i.e. Prophet) said, \"Because of Abraham's invocation there are blessings (in Mecca).\" Once more Abraham thought of visiting his family he had left (at Mecca), so he told his wife (Sarah) of his decision. He went and found Ishmael behind the Zamzam well, mending his arrows. He said, \"O Ishmael, Your Lord has ordered me to build a house for Him.\" Ishmael said, \"Obey (the order of) your Lord.\" Abraham said, \"Allah has also ordered me that you should help me therein.\" Ishmael said, \"Then I will do.\" So, both of them rose and Abraham started building (the Ka`ba) while Ishmael went on handing him the stones, and both of them were saying, \"O our Lord ! Accept (this service) from us, Verily, You are the All-Hearing, the All-Knowing.\" (2.127). When the building became high and the old man (i.e. Abraham) could no longer lift the stones (to such a high position), he stood over the stone of Al- Maqam and Ishmael carried on handing him the stones, and both of them were saying, 'O our Lord! Accept (this service) from us, Verily You are All-Hearing, All-Knowing.\" (2.127)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو، قَالَ حَدَّثَنَا إِبْرَاهِيمُ بْنُ نَافِعٍ، عَنْ كَثِيرِ بْنِ كَثِيرٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ لَمَّا كَانَ بَيْنَ إِبْرَاهِيمَ وَبَيْنَ أَهْلِهِ مَا كَانَ، خَرَجَ بِإِسْمَاعِيلَ وَأُمِّ إِسْمَاعِيلَ، وَمَعَهُمْ شَنَّةٌ فِيهَا مَاءٌ، فَجَعَلَتْ أُمُّ إِسْمَاعِيلَ تَشْرَبُ مِنَ الشَّنَّةِ فَيَدِرُّ لَبَنُهَا عَلَى صَبِيِّهَا حَتَّى قَدِمَ مَكَّةَ، فَوَضَعَهَا تَحْتَ دَوْحَةٍ، ثُمَّ رَجَعَ إِبْرَاهِيمُ إِلَى أَهْلِهِ، فَاتَّبَعَتْهُ أُمُّ إِسْمَاعِيلَ، حَتَّى لَمَّا بَلَغُوا كَدَاءً نَادَتْهُ مِنْ وَرَائِهِ يَا إِبْرَاهِيمُ إِلَى مَنْ تَتْرُكُنَا قَالَ إِلَى اللَّهِ‏.‏ قَالَتْ رَضِيتُ بِاللَّهِ‏.‏ قَالَ فَرَجَعَتْ فَجَعَلَتْ تَشْرَبُ مِنَ الشَّنَّةِ وَيَدِرُّ لَبَنُهَا عَلَى صَبِيِّهَا، حَتَّى لَمَّا فَنِيَ الْمَاءُ قَالَتْ لَوْ ذَهَبْتُ فَنَظَرْتُ لَعَلِّي أُحِسُّ أَحَدًا‏.‏ قَالَ فَذَهَبَتْ فَصَعِدَتِ الصَّفَا فَنَظَرَتْ وَنَظَرَتْ هَلْ تُحِسُّ أَحَدًا فَلَمْ تُحِسَّ أَحَدًا، فَلَمَّا بَلَغَتِ الْوَادِيَ سَعَتْ وَأَتَتِ الْمَرْوَةَ فَفَعَلَتْ ذَلِكَ أَشْوَاطًا، ثُمَّ قَالَتْ لَوْ ذَهَبْتُ فَنَظَرْتُ مَا فَعَلَ ـ تَعْنِي الصَّبِيَّ ـ فَذَهَبَتْ فَنَظَرَتْ، فَإِذَا هُوَ عَلَى حَالِهِ كَأَنَّهُ يَنْشَغُ لِلْمَوْتِ، فَلَمْ تُقِرَّهَا نَفْسُهَا، فَقَالَتْ لَوْ ذَهَبْتُ فَنَظَرْتُ لَعَلِّي أُحِسُّ أَحَدًا، فَذَهَبَتْ فَصَعِدَتِ الصَّفَا فَنَظَرَتْ وَنَظَرَتْ فَلَمْ تُحِسَّ أَحَدًا، حَتَّى أَتَمَّتْ سَبْعًا، ثُمَّ قَالَتْ لَوْ ذَهَبْتُ فَنَظَرْتُ مَا فَعَلَ، فَإِذَا هِيَ بِصَوْتٍ فَقَالَتْ أَغِثْ إِنْ كَانَ عِنْدَكَ خَيْرٌ‏.‏ فَإِذَا جِبْرِيلُ، قَالَ فَقَالَ بِعَقِبِهِ هَكَذَا، وَغَمَزَ عَقِبَهُ عَلَى الأَرْضِ، قَالَ فَانْبَثَقَ الْمَاءُ، فَدَهَشَتْ أُمُّ إِسْمَاعِيلَ فَجَعَلَتْ تَحْفِزُ‏.‏ قَالَ فَقَالَ أَبُو الْقَاسِمِ صلى الله عليه وسلم ‏\"‏ لَوْ تَرَكَتْهُ كَانَ الْمَاءُ ظَاهِرًا ‏\"‏‏.‏ قَالَ فَجَعَلَتْ تَشْرَبُ مِنَ الْمَاءِ، وَيَدِرُّ لَبَنُهَا عَلَى صَبِيِّهَا ـ قَالَ ـ فَمَرَّ نَاسٌ مِنْ جُرْهُمَ بِبَطْنِ الْوَادِي، فَإِذَا هُمْ بِطَيْرٍ، كَأَنَّهُمْ أَنْكَرُوا ذَاكَ، وَقَالُوا مَا يَكُونُ الطَّيْرُ إِلاَّ عَلَى مَاءٍ‏.‏ فَبَعَثُوا رَسُولَهُمْ، فَنَظَرَ فَإِذَا هُمْ بِالْمَاءِ، فَأَتَاهُمْ فَأَخْبَرَهُمْ فَأَتَوْا إِلَيْهَا، فَقَالُوا يَا أُمَّ إِسْمَاعِيلَ، أَتَأْذَنِينَ لَنَا أَنْ نَكُونَ مَعَكِ أَوْ نَسْكُنَ مَعَكِ فَبَلَغَ ابْنُهَا فَنَكَحَ فِيهِمُ امْرَأَةً، قَالَ ثُمَّ إِنَّهُ بَدَا لإِبْرَاهِيمَ فَقَالَ لأَهْلِهِ إِنِّي مُطَّلِعٌ تَرِكَتِي‏.‏ قَالَ فَجَاءَ فَسَلَّمَ فَقَالَ أَيْنَ إِسْمَاعِيلُ فَقَالَتِ امْرَأَتُهُ ذَهَبَ يَصِيدُ‏.‏ قَالَ قُولِي لَهُ إِذَا جَاءَ غَيِّرْ عَتَبَةَ بَابِكَ‏.‏ فَلَمَّا جَاءَ أَخْبَرَتْهُ قَالَ أَنْتِ ذَاكِ فَاذْهَبِي إِلَى أَهْلِكِ‏.‏ قَالَ ثُمَّ إِنَّهُ بَدَا لإِبْرَاهِيمَ فَقَالَ لأَهْلِهِ إِنِّي مُطَّلِعٌ تَرِكَتِي‏.‏ قَالَ فَجَاءَ فَقَالَ أَيْنَ إِسْمَاعِيلُ فَقَالَتِ امْرَأَتُهُ ذَهَبَ يَصِيدُ، فَقَالَتْ أَلاَ تَنْزِلُ فَتَطْعَمَ وَتَشْرَبَ فَقَالَ وَمَا طَعَامُكُمْ وَمَا شَرَابُكُمْ قَالَتْ طَعَامُنَا اللَّحْمُ، وَشَرَابُنَا الْمَاءُ‏.‏ قَالَ اللَّهُمَّ بَارِكْ لَهُمْ فِي طَعَامِهِمْ وَشَرَابِهِمْ‏.‏ قَالَ فَقَالَ أَبُو الْقَاسِمِ صلى الله عليه وسلم ‏\"‏ بَرَكَةٌ بِدَعْوَةِ إِبْرَاهِيمَ ‏\"‏‏.‏ قَالَ ثُمَّ إِنَّهُ بَدَا لإِبْرَاهِيمَ فَقَالَ لأَهْلِهِ إِنِّي مُطَّلِعٌ تَرِكَتِي‏.‏ فَجَاءَ فَوَافَقَ إِسْمَاعِيلَ مِنْ وَرَاءِ زَمْزَمَ، يُصْلِحُ نَبْلاً لَهُ، فَقَالَ يَا إِسْمَاعِيلُ، إِنَّ رَبَّكَ أَمَرَنِي أَنْ أَبْنِيَ لَهُ بَيْتًا‏.‏ قَالَ أَطِعْ رَبَّكَ‏.‏ قَالَ إِنَّهُ قَدْ أَمَرَنِي أَنْ تُعِينَنِي عَلَيْهِ‏.‏ قَالَ إِذًا أَفْعَلَ‏.‏ أَوْ كَمَا قَالَ‏.‏ قَالَ فَقَامَا فَجَعَلَ إِبْرَاهِيمُ يَبْنِي، وَإِسْمَاعِيلُ يُنَاوِلُهُ الْحِجَارَةَ، وَيَقُولاَنِ ‏{‏رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ‏}‏ قَالَ حَتَّى ارْتَفَعَ الْبِنَاءُ وَضَعُفَ الشَّيْخُ عَلَى نَقْلِ الْحِجَارَةِ، فَقَامَ عَلَى حَجَرِ الْمَقَامِ، فَجَعَلَ يُنَاوِلُهُ الْحِجَارَةَ، وَيَقُولاَنِ ‏{‏رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ ‏}‏‏.‏","v":[]}],"136":[{"c":"Sahih Bukhari","r":"Hadith 4485","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4485","x":"Narrated Abu Huraira:\n\nThe people of the Scripture (Jews) used to recite the Torah in Hebrew and they used to explain it in Arabic to the Muslims. On that Allah's Messenger (ﷺ) said, \"Do not believe the people of the Scripture or disbelieve them, but say:-- \"We believe in Allah and what is revealed to us.\" (2.136)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عُثْمَانُ بْنُ عُمَرَ، أَخْبَرَنَا عَلِيُّ بْنُ الْمُبَارَكِ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ كَانَ أَهْلُ الْكِتَابِ يَقْرَءُونَ التَّوْرَاةَ بِالْعِبْرَانِيَّةِ، وَيُفَسِّرُونَهَا بِالْعَرَبِيَّةِ لأَهْلِ الإِسْلاَمِ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لاَ تُصَدِّقُوا أَهْلَ الْكِتَابِ وَلاَ تُكَذِّبُوهُمْ، وَقُولُوا ‏{‏آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ‏}‏ الآيَةَ‏\"‏‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 1107","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-1107","x":"Ibn 'Abbas (May Allah be pleased with them) reported:\n\nThe Messenger of Allah (ﷺ) used to recite during the two Rak'ah of Fajr prayer: \"Say (O Muslims): We believe in Allah and that which has been sent down to us...\" (2:136) which is in Surat Al-Baqarah in the first Rak'ah and the Verse: \"We believe in Allah, and bear witness that we are Muslims (i.e., we submit to Allah.\" (3:52) in the second Rak'ah.According to another narration, he (ﷺ) recited from Surat Al-'Imran the Verses: \"Come to a word which is just between us and you...\" (3:64).[Muslim].","ar":"وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم، كان يقرأ في ركعتي الفجر في الأولى منهما‏:‏ ‏{‏قولوا آمنا بالله وما أنزل إلينا‏}‏ الآية التي في البقرة، وفي الآخرة منهما‏:‏ ‏{‏آمنا بالله واشهد بأنا مسلمون‏}.‏ وفي رواية‏:‏ في الآخرة التي في آل عمران‏:‏ ‏{‏تعالوا إلى كلمة سواء بيننا وبينكم‏}‏‏.‏ ‏(‏‏(‏رواهما مسلم‏)‏‏)‏‏.‏","v":[]}],"141":[{"c":"Sahih Bukhari","r":"Hadith 399","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-399","x":"Narrated Bara' bin `Azib:\n\nAllah's Messenger (ﷺ) prayed facing Baitul-Maqdis for sixteen or seventeen months but he loved to face the Ka`ba (at Mecca) so Allah revealed: \"Verily, We have seen the turning of your face to the heaven!\" (2:144) So the Prophet (ﷺ) faced the Ka`ba and the fools amongst the people namely \"the Jews\" said, \"What has turned them from their Qibla (Baitul-Maqdis) which they formerly observed\"\" (Allah revealed): \"Say: 'To Allah belongs the East and the West. He guides whom he will to a straight path'.\" (2:142) A man prayed with the Prophet (facing the Ka`ba) and went out. He saw some of the Ansar praying the `Asr prayer with their faces towards Baitul-Maqdis, he said, \"I bear witness that I prayed with Allah's Messenger (ﷺ) facing the Ka`ba.\" So all the people turned their faces towards the Ka`ba.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ رَجَاءٍ، قَالَ حَدَّثَنَا إِسْرَائِيلُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ ـ رضى الله عنهما ـ قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ، فَأَنْزَلَ اللَّهُ ‏{‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ‏}‏ فَتَوَجَّهَ نَحْوَ الْكَعْبَةِ، وَقَالَ السُّفَهَاءُ مِنَ النَّاسِ ـ وَهُمُ الْيَهُودُ ـ مَا وَلاَّهُمْ عَنْ قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا ‏{‏قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ‏}‏ فَصَلَّى مَعَ النَّبِيِّ صلى الله عليه وسلم رَجُلٌ ثُمَّ خَرَجَ بَعْدَ مَا صَلَّى، فَمَرَّ عَلَى قَوْمٍ مِنَ الأَنْصَارِ فِي صَلاَةِ الْعَصْرِ نَحْوَ بَيْتِ الْمَقْدِسِ فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَأَنَّهُ تَوَجَّهَ نَحْوَ الْكَعْبَةِ‏.‏ فَتَحَرَّفَ الْقَوْمُ حَتَّى تَوَجَّهُوا نَحْوَ الْكَعْبَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 403","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-403","x":"Narrated `Abdullah bin `Umar:\n\nWhile the people were offering the Fajr prayer at Quba' (near Medina), someone came to them and said: \"It has been revealed to Allah's Messenger (ﷺ) tonight, and he has been ordered to pray facing the Ka`ba.\" So turn your faces to the Ka`ba. Those people were facing Sham (Jerusalem) so they turned their faces towards Ka`ba (at Mecca).","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكُ بْنُ أَنَسٍ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ بَيْنَا النَّاسُ بِقُبَاءٍ فِي صَلاَةِ الصُّبْحِ إِذْ جَاءَهُمْ آتٍ فَقَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ، وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ الْكَعْبَةَ فَاسْتَقْبِلُوهَا، وَكَانَتْ وُجُوهُهُمْ إِلَى الشَّأْمِ، فَاسْتَدَارُوا إِلَى الْكَعْبَةِ‏.‏","v":[]}],"142":[{"c":"Sahih Bukhari","r":"Hadith 399","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-399","x":"Narrated Bara' bin `Azib:\n\nAllah's Messenger (ﷺ) prayed facing Baitul-Maqdis for sixteen or seventeen months but he loved to face the Ka`ba (at Mecca) so Allah revealed: \"Verily, We have seen the turning of your face to the heaven!\" (2:144) So the Prophet (ﷺ) faced the Ka`ba and the fools amongst the people namely \"the Jews\" said, \"What has turned them from their Qibla (Baitul-Maqdis) which they formerly observed\"\" (Allah revealed): \"Say: 'To Allah belongs the East and the West. He guides whom he will to a straight path'.\" (2:142) A man prayed with the Prophet (facing the Ka`ba) and went out. He saw some of the Ansar praying the `Asr prayer with their faces towards Baitul-Maqdis, he said, \"I bear witness that I prayed with Allah's Messenger (ﷺ) facing the Ka`ba.\" So all the people turned their faces towards the Ka`ba.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ رَجَاءٍ، قَالَ حَدَّثَنَا إِسْرَائِيلُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ ـ رضى الله عنهما ـ قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ، فَأَنْزَلَ اللَّهُ ‏{‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ‏}‏ فَتَوَجَّهَ نَحْوَ الْكَعْبَةِ، وَقَالَ السُّفَهَاءُ مِنَ النَّاسِ ـ وَهُمُ الْيَهُودُ ـ مَا وَلاَّهُمْ عَنْ قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا ‏{‏قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ‏}‏ فَصَلَّى مَعَ النَّبِيِّ صلى الله عليه وسلم رَجُلٌ ثُمَّ خَرَجَ بَعْدَ مَا صَلَّى، فَمَرَّ عَلَى قَوْمٍ مِنَ الأَنْصَارِ فِي صَلاَةِ الْعَصْرِ نَحْوَ بَيْتِ الْمَقْدِسِ فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَأَنَّهُ تَوَجَّهَ نَحْوَ الْكَعْبَةِ‏.‏ فَتَحَرَّفَ الْقَوْمُ حَتَّى تَوَجَّهُوا نَحْوَ الْكَعْبَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 403","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-403","x":"Narrated `Abdullah bin `Umar:\n\nWhile the people were offering the Fajr prayer at Quba' (near Medina), someone came to them and said: \"It has been revealed to Allah's Messenger (ﷺ) tonight, and he has been ordered to pray facing the Ka`ba.\" So turn your faces to the Ka`ba. Those people were facing Sham (Jerusalem) so they turned their faces towards Ka`ba (at Mecca).","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكُ بْنُ أَنَسٍ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ بَيْنَا النَّاسُ بِقُبَاءٍ فِي صَلاَةِ الصُّبْحِ إِذْ جَاءَهُمْ آتٍ فَقَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ، وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ الْكَعْبَةَ فَاسْتَقْبِلُوهَا، وَكَانَتْ وُجُوهُهُمْ إِلَى الشَّأْمِ، فَاسْتَدَارُوا إِلَى الْكَعْبَةِ‏.‏","v":[]}],"143":[{"c":"Sahih Bukhari","r":"Hadith 40","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-40","x":"Narrated Al-Bara' (bin 'Azib):\n\nWhen the Prophet (ﷺ) came to Medina, he stayed first with his grandfathers or maternal uncles from Ansar. He offered his prayers facing Baitul-Maqdis (Jerusalem) for sixteen or seventeen months, but he wished that he could pray facing the Ka'ba (at Mecca). The first prayer which he offered facing the Ka'ba was the 'Asr prayer in the company of some people. Then one of those who had offered that prayer with him came out and passed by some people in a mosque who were bowing during their prayers (facing Jerusalem). He said addressing them, \"By Allah, I testify that I have prayed with Allah's Messenger (ﷺ) facing Mecca (Ka'ba).' Hearing that, those people changed their direction towards the Ka'ba immediately. Jews and the people of the scriptures used to be pleased to see the Prophet (ﷺ) facing Jerusalem in prayers but when he changed his direction towards the Ka'ba, during the prayers, they disapproved of it. Al-Bara' added, \"Before we changed our direction towards the Ka'ba (Mecca) in prayers, some Muslims had died or had been killed and we did not know what to say about them (regarding their prayers.) Allah then revealed: And Allah would never make your faith (prayers) to be lost (i.e. the prayers of those Muslims were valid).' \" (2:143).","ar":"حَدَّثَنَا عَمْرُو بْنُ خَالِدٍ، قَالَ حَدَّثَنَا زُهَيْرٌ، قَالَ حَدَّثَنَا أَبُو إِسْحَاقَ، عَنِ الْبَرَاءِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ أَوَّلَ مَا قَدِمَ الْمَدِينَةَ نَزَلَ عَلَى أَجْدَادِهِ ـ أَوْ قَالَ أَخْوَالِهِ ـ مِنَ الأَنْصَارِ، وَأَنَّهُ صَلَّى قِبَلَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا، أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ الْبَيْتِ، وَأَنَّهُ صَلَّى أَوَّلَ صَلاَةٍ صَلاَّهَا صَلاَةَ الْعَصْرِ، وَصَلَّى مَعَهُ قَوْمٌ، فَخَرَجَ رَجُلٌ مِمَّنْ صَلَّى مَعَهُ، فَمَرَّ عَلَى أَهْلِ مَسْجِدٍ، وَهُمْ رَاكِعُونَ فَقَالَ أَشْهَدُ بِاللَّهِ لَقَدْ صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم قِبَلَ مَكَّةَ، فَدَارُوا كَمَا هُمْ قِبَلَ الْبَيْتِ، وَكَانَتِ الْيَهُودُ قَدْ أَعْجَبَهُمْ إِذْ كَانَ يُصَلِّي قِبَلَ بَيْتِ الْمَقْدِسِ، وَأَهْلُ الْكِتَابِ، فَلَمَّا وَلَّى وَجْهَهُ قِبَلَ الْبَيْتِ أَنْكَرُوا ذَلِكَ‏.‏ قَالَ زُهَيْرٌ حَدَّثَنَا أَبُو إِسْحَاقَ عَنِ الْبَرَاءِ فِي حَدِيثِهِ هَذَا أَنَّهُ مَاتَ عَلَى الْقِبْلَةِ قَبْلَ أَنْ تُحَوَّلَ رِجَالٌ وَقُتِلُوا، فَلَمْ نَدْرِ مَا نَقُولُ فِيهِمْ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 399","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-399","x":"Narrated Bara' bin `Azib:\n\nAllah's Messenger (ﷺ) prayed facing Baitul-Maqdis for sixteen or seventeen months but he loved to face the Ka`ba (at Mecca) so Allah revealed: \"Verily, We have seen the turning of your face to the heaven!\" (2:144) So the Prophet (ﷺ) faced the Ka`ba and the fools amongst the people namely \"the Jews\" said, \"What has turned them from their Qibla (Baitul-Maqdis) which they formerly observed\"\" (Allah revealed): \"Say: 'To Allah belongs the East and the West. He guides whom he will to a straight path'.\" (2:142) A man prayed with the Prophet (facing the Ka`ba) and went out. He saw some of the Ansar praying the `Asr prayer with their faces towards Baitul-Maqdis, he said, \"I bear witness that I prayed with Allah's Messenger (ﷺ) facing the Ka`ba.\" So all the people turned their faces towards the Ka`ba.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ رَجَاءٍ، قَالَ حَدَّثَنَا إِسْرَائِيلُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ ـ رضى الله عنهما ـ قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ، فَأَنْزَلَ اللَّهُ ‏{‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ‏}‏ فَتَوَجَّهَ نَحْوَ الْكَعْبَةِ، وَقَالَ السُّفَهَاءُ مِنَ النَّاسِ ـ وَهُمُ الْيَهُودُ ـ مَا وَلاَّهُمْ عَنْ قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا ‏{‏قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ‏}‏ فَصَلَّى مَعَ النَّبِيِّ صلى الله عليه وسلم رَجُلٌ ثُمَّ خَرَجَ بَعْدَ مَا صَلَّى، فَمَرَّ عَلَى قَوْمٍ مِنَ الأَنْصَارِ فِي صَلاَةِ الْعَصْرِ نَحْوَ بَيْتِ الْمَقْدِسِ فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَأَنَّهُ تَوَجَّهَ نَحْوَ الْكَعْبَةِ‏.‏ فَتَحَرَّفَ الْقَوْمُ حَتَّى تَوَجَّهُوا نَحْوَ الْكَعْبَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 403","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-403","x":"Narrated `Abdullah bin `Umar:\n\nWhile the people were offering the Fajr prayer at Quba' (near Medina), someone came to them and said: \"It has been revealed to Allah's Messenger (ﷺ) tonight, and he has been ordered to pray facing the Ka`ba.\" So turn your faces to the Ka`ba. Those people were facing Sham (Jerusalem) so they turned their faces towards Ka`ba (at Mecca).","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكُ بْنُ أَنَسٍ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ بَيْنَا النَّاسُ بِقُبَاءٍ فِي صَلاَةِ الصُّبْحِ إِذْ جَاءَهُمْ آتٍ فَقَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ، وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ الْكَعْبَةَ فَاسْتَقْبِلُوهَا، وَكَانَتْ وُجُوهُهُمْ إِلَى الشَّأْمِ، فَاسْتَدَارُوا إِلَى الْكَعْبَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3339","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3339","x":"Narrated Abu Sa`id:\n\nAllah's Messenger (ﷺ) said, \"Noah and his nation will come (on the Day of Resurrection and Allah will ask (Noah), \"Did you convey (the Message)?' He will reply, 'Yes, O my Lord!' Then Allah will ask Noah's nation, 'Did Noah convey My Message to you?' They will reply, 'No, no prophet came to us.' Then Allah will ask Noah, 'Who will stand a witness for you?' He will reply, 'Muhammad and his followers (will stand witness for me).' So, I and my followers will stand as witnesses for him (that he conveyed Allah's Message).\" That is, (the interpretation) of the Statement of Allah: \"Thus we have made you a just and the best nation that you might be witnesses Over mankind..\" (2.143)","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَجِيءُ نُوحٌ وَأُمَّتُهُ فَيَقُولُ اللَّهُ تَعَالَى هَلْ بَلَّغْتَ فَيَقُولُ نَعَمْ، أَىْ رَبِّ‏.‏ فَيَقُولُ لأُمَّتِهِ هَلْ بَلَّغَكُمْ فَيَقُولُونَ لاَ، مَا جَاءَنَا مِنْ نَبِيٍّ‏.‏ فَيَقُولُ لِنُوحٍ مَنْ يَشْهَدُ لَكَ فَيَقُولُ مُحَمَّدٌ صلى الله عليه وسلم وَأُمَّتُهُ، فَنَشْهَدُ أَنَّهُ قَدْ بَلَّغَ، وَهْوَ قَوْلُهُ جَلَّ ذِكْرُهُ ‏{‏وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ‏}‏ وَالْوَسَطُ الْعَدْلُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4486","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4486","x":"Narrated Al-Bara:\n\nThe Prophet (ﷺ) prayed facing Bait-ulMaqdis (i.e. Jerusalem) for sixteen or seventeen months but he wished that his Qibla would be the Ka`ba (at Mecca). (So Allah Revealed (2.144) and he offered `Asr prayers(in his Mosque facing Ka`ba at Mecca) and some people prayed with him. A man from among those who had prayed with him, went out and passed by some people offering prayer in another mosque, and they were in the state of bowing. He said, \"I, (swearing by Allah,) testify that I have prayed with the Prophet (ﷺ) facing Mecca.\" Hearing that, they turned their faces to the Ka`ba while they were still bowing. Some men had died before the Qibla was changed towards the Ka`ba. They had been killed and we did not know what to say about them (i.e. whether their prayers towards Jerusalem were accepted or not). So Allah revealed:-- \"And Allah would never make your faith (i.e. prayer) to be lost (i.e. your prayers offered (towards Jerusalem). Truly Allah is Full of Pity, Most Merciful towards mankind.\" (2.143)","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، سَمِعَ زُهَيْرًا، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، رضى الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم صَلَّى إِلَى بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ الْبَيْتِ، وَإِنَّهُ صَلَّى ـ أَوْ صَلاَّهَا ـ صَلاَةَ الْعَصْرِ، وَصَلَّى مَعَهُ قَوْمٌ، فَخَرَجَ رَجُلٌ مِمَّنْ كَانَ صَلَّى مَعَهُ، فَمَرَّ عَلَى أَهْلِ الْمَسْجِدِ وَهُمْ رَاكِعُونَ قَالَ أَشْهَدُ بِاللَّهِ لَقَدْ صَلَّيْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم قِبَلَ مَكَّةَ، فَدَارُوا كَمَا هُمْ قِبَلَ الْبَيْتِ، وَكَانَ الَّذِي مَاتَ عَلَى الْقِبْلَةِ قَبْلَ أَنْ تُحَوَّلَ قِبَلَ الْبَيْتِ رِجَالٌ قُتِلُوا لَمْ نَدْرِ مَا نَقُولُ فِيهِمْ، فَأَنْزَلَ اللَّهُ ‏{‏وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4487","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4487","x":"Narrated Abu Sa`id Al-Khudri:\n\nAllah's Messenger (ﷺ) said, \"Noah will be called on the Day of Resurrection and he will say, 'Labbaik and Sa`daik, O my Lord!' Allah will say, 'Did you convey the Message?' Noah will say, 'Yes.' His nation will then be asked, 'Did he convey the Message to you?' They will say, 'No Warner came to us.' Then Allah will say (to Noah), 'Who will bear witness in your favor?' He will say, 'Muhammad and his followers. So they (i.e. Muslims) will testify that he conveyed the Message. And the Apostle (Muhammad) will be a witness over yourselves, and that is what is meant by the Statement of Allah \"Thus We have made of you a just and the best nation that you may be witnesses over mankind and the Apostle (Muhammad) will be a witness over yourselves.\" (2.143)","ar":"حَدَّثَنَا يُوسُفُ بْنُ رَاشِدٍ، حَدَّثَنَا جَرِيرٌ، وَأَبُو أُسَامَةَ ـ وَاللَّفْظُ لِجَرِيرٍ ـ عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، وَقَالَ أَبُو أُسَامَةَ، حَدَّثَنَا أَبُو صَالِحٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يُدْعَى نُوحٌ يَوْمَ الْقِيَامَةِ فَيَقُولُ لَبَّيْكَ وَسَعْدَيْكَ يَا رَبِّ‏.‏ فَيَقُولُ هَلْ بَلَّغْتَ فَيَقُولُ نَعَمْ‏.‏ فَيُقَالُ لأُمَّتِهِ هَلْ بَلَّغَكُمْ فَيَقُولُونَ مَا أَتَانَا مِنْ نَذِيرٍ‏.‏ فَيَقُولُ مَنْ يَشْهَدُ لَكَ فَيَقُولُ مُحَمَّدٌ وَأُمَّتُهُ‏.‏ فَتَشْهَدُونَ أَنَّهُ قَدْ بَلَّغَ ‏\"‏‏.‏ ‏{‏وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا‏}‏ فَذَلِكَ قَوْلُهُ جَلَّ ذِكْرُهُ ‏{‏وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا‏}‏ وَالْوَسَطُ الْعَدْلُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7349","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7349","x":"Narrated Abu Sa`id Al-Khudri:\n\nAllah's Messenger (ﷺ) said, \"Noah will be brought (before Allah) on the Day of Resurrection, and will be asked, 'Did you convey the message of Allah?\" He will reply, 'Yes, O Lord.' And then Noah's nation will be asked, 'Did he (Noah) convey Allah's message to you?' They will reply, 'No warner came to us.' Then Noah will be asked, 'Who are your witnesses?' He will reply. '(My witnesses are) Muhammad and his followers.' Thereupon you (Muslims) will be brought and you will bear witness.\" Then the Prophet (ﷺ) recited: 'And thus We have made of you (Muslims) a just and the best nation, that you might be witness over the nations, and the Apostle a witness over you.' (2.143)","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ مَنْصُورٍ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنَا أَبُو صَالِحٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يُجَاءُ بِنُوحٍ يَوْمَ الْقِيَامَةِ فَيُقَالُ لَهُ هَلْ بَلَّغْتَ فَيَقُولُ نَعَمْ يَا رَبِّ‏.‏ فَتُسْأَلُ أُمَّتُهُ هَلْ بَلَّغَكُمْ فَيَقُولُونَ مَا جَاءَنَا مِنْ نَذِيرٍ‏.‏ فَيَقُولُ مَنْ شُهُودُكَ فَيَقُولُ مُحَمَّدٌ وَأُمَّتُهُ‏.‏ فَيُجَاءُ بِكُمْ فَتَشْهَدُونَ ‏\"‏‏.‏ ثُمَّ قَرَأَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏{‏وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا‏}‏ قَالَ عَدْلاً ‏{‏لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا‏}‏ وَعَنْ جَعْفَرِ بْنِ عَوْنٍ، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذَا‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1010","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1010","x":"It was narrated that Bara’ said:\n\n\"We prayed with the Messenger of Allah (ﷺ) facing towards Baitul-Maqdis (Jerusalem) for eighteen months, then the Qiblah was changed to the Ka’bah two months after the Prophet (ﷺ) entered Al-Madinah. When the Messenger of Allah (ﷺ) prayed towards Baitul-Maqdis, he would often lift his face towards the heavens, and Allah knew what was in the heart of His Prophet and how he longed to face the Ka’bah (during prayer). Jibril appeared (in the sky), and the Messenger of Allah (ﷺ) started watching him as he was descending between the heavens and the earth, waiting to see what he would bring. Then Allah revealed the words: ‘Verily, We have seen the turning of your face towards the heaven. Surely, We shall turn you to a Qiblah that shall please you, so turn your face in the direction of Al-Masjid Al-Haram (at Makkah). And wherever you people are, turn your faces (during prayer) in that direction.’ [2:144] Then someone came to us and said: ‘The Qiblah has been changed to the Ka’bah.’ We had performed two Rak’ah facing towards Jerusalem. And we were bowing. So we turned around, and we continued our prayer. The Messenger of Allah (ﷺ) said: ‘O Jibril! What about our prayer facing towards Baitul- Maqdis?’ Then Allah revealed the words: \"And Allah would never make your faith to be lost.\" [2:143]","ar":"حَدَّثَنَا عَلْقَمَةُ بْنُ عَمْرٍو الدَّارِمِيُّ، حَدَّثَنَا أَبُو بَكْرِ بْنُ عَيَّاشٍ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ صَلَّيْنَا مَعَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ نَحْوَ بَيْتِ الْمَقْدِسِ ثَمَانِيَةَ عَشَرَ شَهْرًا وَصُرِفَتِ الْقِبْلَةُ إِلَى الْكَعْبَةِ بَعْدَ دُخُولِهِ إِلَى الْمَدِينَةِ بِشَهْرَيْنِ وَكَانَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ إِذَا صَلَّى إِلَى بَيْتِ الْمَقْدِسِ أَكْثَرَ تَقَلُّبَ وَجْهِهِ فِي السَّمَاءِ وَعَلِمَ اللَّهُ مِنْ قَلْبِ نَبِيِّهِ ـ صلى الله عليه وسلم ـ أَنَّهُ يَهْوَى الْكَعْبَةَ فَصَعِدَ جِبْرِيلُ فَجَعَلَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ يُتْبِعُهُ بَصَرَهُ وَهُوَ يَصْعَدُ بَيْنَ السَّمَاءِ وَالأَرْضِ يَنْظُرُ مَا يَأْتِيهِ بِهِ فَأَنْزَلَ اللَّهُ ‏{قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ}‏ الآيَةَ فَأَتَانَا آتٍ فَقَالَ إِنَّ الْقِبْلَةَ قَدْ صُرِفَتْ إِلَى الْكَعْبَةِ وَقَدْ صَلَّيْنَا رَكْعَتَيْنِ إِلَى بَيْتِ الْمَقْدِسِ وَنَحْنُ رُكُوعٌ فَتَحَوَّلْنَا فَبَنَيْنَا عَلَى مَا مَضَى مِنْ صَلاَتِنَا فَقَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\"‏ يَا جِبْرِيلُ كَيْفَ حَالُنَا فِي صَلاَتِنَا إِلَى بَيْتِ الْمَقْدِسِ ‏\"‏ ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ}‏ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 37, Hadith 4284","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-37/Hadith-4284","x":"It was narrated from Abu Sa’eed that the Messenger of Allah (ﷺ) said:\n\n\"A Prophet will come accompanied by two men, and a Prophet will come accompanied by three, and (some will come) with more or less than that. It will be said to him: ‘Did you convey the message to your people?’ And he will say: ‘Yes.’ Then his people will be called and it will be said: ‘Did he convey the message to you?’ They will say: ‘No.’ Then it will be said: ‘Who will bear witness for you?’ He will say: ‘Muhammad and his nation.’ So the nation of Muhammad will be called and it will be said: ‘Did this man convey the message?’ They will say: ‘Yes.’ He will say: ‘How did you know that?’ They will say: ‘Our Prophet told us that the Messengers had conveyed the message, and we believed him.’ This is what Allah says: \"Thus We have made you, a just (and the best) nation, that you be witnesses over mankind and the Messenger (Muhammad (ﷺ)) be a witness over you.’\" [2:143]","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، وَأَحْمَدُ بْنُ سِنَانٍ، قَالاَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\"‏ يَجِيءُ النَّبِيُّ يَوْمَ الْقِيَامَةِ وَمَعَهُ الرَّجُلُ وَيَجِيءُ النَّبِيُّ وَمَعَهُ الرَّجُلاَنِ وَيَجِيءُ النَّبِيُّ وَمَعَهُ الثَّلاَثَةُ وَأَكْثَرُ مِنْ ذَلِكَ وَأَقَلُّ فَيُقَالُ لَهُ هَلْ بَلَّغْتَ قَوْمَكَ فَيَقُولُ نَعَمْ ‏.‏ فَيُدْعَى قَوْمُهُ فَيُقَالُ هَلَ بَلَّغَكُمْ فَيَقُولُونَ لاَ ‏.‏ فَيُقَالُ مَنْ شَهِدَ لَكَ فَيَقُولُ مُحَمَّدٌ وَأُمَّتُهُ ‏.‏ فَتُدْعَى أُمَّةُ مُحَمَّدٍ فَيُقَالُ هَلْ بَلَّغَ هَذَا فَيَقُولُونَ نَعَمْ ‏.‏ فَيَقُولُ وَمَا عِلْمُكُمْ بِذَلِكَ فَيَقُولُونَ أَخْبَرَنَا نَبِيُّنَا بِذَلِكَ أَنَّ الرُّسُلَ قَدْ بَلَّغُوا فَصَدَّقْنَاهُ ‏.‏ قَالَ فَذَلِكُمْ قَوْلُهُ تَعَالَى ‏{وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا}‏ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2961","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2961","x":"Narrated Abu Sa'eed:\n\nthat about Allah's saying: Thus we have made you a Wasata nation (2:143) - the Prophet (ﷺ) said: \"The meaning of Wasata is just.\" [Abu 'Eisa said: This Hadith is [Hasan] Sahih. (Another chain) From Abu Sa'eed who narrated that: \"The Messenger of Allah a said: 'Nuh will be called and it will be said: \"Did you deliver (the Message)? \"He will say: \"Yes\" and his people will be called and it will be said: \"Did he call you?\" They will say: \"No warner came to us. No one came to us.' It will be said: \"Who will testify for you?\" So it is said: \"Muhammad and his Ummah (community).\" He (ﷺ) said: You will be brought to testify that he delivered (the Message) and that is His saying: Thus, we have made you a Wasata nation that you will be witnesses over mankind and the Messenger (Muhammad) will be a witness over you.' And Al-Wasat is \"Just.\" (Sahih) Abu 'Eisa said: This Hadith is Hasan Sahih.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم فِي قَوْلِهِ ‏:‏ ‏(‏كََذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا ‏)‏ قَالَ ‏\"‏ عَدْلاً ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا جَعْفَرُ بْنُ عَوْنٍ، أَخْبَرَنَا الأَعْمَشُ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يُدْعَى نُوحٌ فَيُقَالُ هَلْ بَلَّغْتَ فَيَقُولُ نَعَمْ ‏.‏ فَيُدْعَى قَوْمُهُ فَيُقَالُ هَلْ بَلَّغَكُمْ فَيَقُولُونَ مَا أَتَانَا مِنْ نَذِيرٍ وَمَا أَتَانَا مِنْ أَحَدٍ ‏.‏ فَيَقُولُ مَنْ شُهُودُكَ فَيَقُولُ مُحَمَّدٌ وَأُمَّتُهُ ‏.‏ قَالَ فَيُؤْتَى بِكُمْ تَشْهَدُونَ أَنَّهُ قَدْ بَلَّغَ فَذَلِكَ قَوْلُ اللَّهِ ‏:‏ ‏(‏ وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا ‏)‏ وَالْوَسَطُ الْعَدْلُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا جَعْفَرُ بْنُ عَوْنٍ، عَنِ الأَعْمَشِ، نَحْوَهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2964","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2964","x":"Narrated Ibn 'Abbas:\n\n\"When the Prophet (ﷺ) began facing the Ka'bah they said: 'O Messenger of Allah! How about our brothers who died while they were praying toward Bait Al-Maqdis?' So Allah Most High revealed: Allah would not allow your faith to be wasted. (2:143)\"","ar":"حَدَّثَنَا هَنَّادٌ، وَأَبُو عَمَّارٍ قَالاَ حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ سِمَاكٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَمَّا وُجِّهَ النَّبِيُّ صلى الله عليه وسلم إِلَى الْكَعْبَةِ قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ بِإِخْوَانِنَا الَّذِينَ مَاتُوا وَهُمْ يُصَلُّونَ إِلَى بَيْتِ الْمَقْدِسِ فَأَنْزَلَ اللَّهُ‏:‏ ‏(‏وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ ‏)‏ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"144":[{"c":"Sunan Abu Dawud","r":"Hadith 1045","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1045","x":"Anas said:\n\nThe Prophet (ﷺ) and his Companions used to pray in the direction of Jerusalem. When the following verse was revealed: \" So turn thy face towards the inviolable mosque\"; and Ye (O Muslims), wheresoever ye may be, turn your face towards it\"(ii. 144), a man passed by the people of Banu Salamah. He called them while they were bowing in the morning prayer facing Jerusalem: Lo, the qiblah (direction of prayer) has been changed towards the ka’bah. He called them twice. So they turned their faces towards the Ka’bah while they were bowing.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، عَنْ ثَابِتٍ، وَحُمَيْدٍ، عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم وَأَصْحَابَهُ كَانُوا يُصَلُّونَ نَحْوَ بَيْتِ الْمَقْدِسِ فَلَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏{‏ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ‏}‏ فَمَرَّ رَجُلٌ مِنْ بَنِي سَلِمَةَ فَنَادَاهُمْ وَهُمْ رُكُوعٌ فِي صَلاَةِ الْفَجْرِ نَحْوَ بَيْتِ الْمَقْدِسِ أَلاَ إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ إِلَى الْكَعْبَةِ مَرَّتَيْنِ فَمَالُوا كَمَا هُمْ رُكُوعٌ إِلَى الْكَعْبَةِ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 1050","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1050","x":"If anyone performs ablution, doing it well, then come to the Friday prayer, listens and keeps silence, his sins between that time and the next Friday will be forgiven, with three days extra; but he who touches pebbles has caused an interruption.","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ أَتَى الْجُمُعَةَ فَاسْتَمَعَ وَأَنْصَتَ غُفِرَ لَهُ مَا بَيْنَ الْجُمُعَةِ إِلَى الْجُمُعَةِ وَزِيَادَةُ ثَلاَثَةِ أَيَّامٍ وَمَنْ مَسَّ الْحَصَى فَقَدْ لَغَا ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 399","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-399","x":"Narrated Bara' bin `Azib:\n\nAllah's Messenger (ﷺ) prayed facing Baitul-Maqdis for sixteen or seventeen months but he loved to face the Ka`ba (at Mecca) so Allah revealed: \"Verily, We have seen the turning of your face to the heaven!\" (2:144) So the Prophet (ﷺ) faced the Ka`ba and the fools amongst the people namely \"the Jews\" said, \"What has turned them from their Qibla (Baitul-Maqdis) which they formerly observed\"\" (Allah revealed): \"Say: 'To Allah belongs the East and the West. He guides whom he will to a straight path'.\" (2:142) A man prayed with the Prophet (facing the Ka`ba) and went out. He saw some of the Ansar praying the `Asr prayer with their faces towards Baitul-Maqdis, he said, \"I bear witness that I prayed with Allah's Messenger (ﷺ) facing the Ka`ba.\" So all the people turned their faces towards the Ka`ba.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ رَجَاءٍ، قَالَ حَدَّثَنَا إِسْرَائِيلُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ ـ رضى الله عنهما ـ قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ، فَأَنْزَلَ اللَّهُ ‏{‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ‏}‏ فَتَوَجَّهَ نَحْوَ الْكَعْبَةِ، وَقَالَ السُّفَهَاءُ مِنَ النَّاسِ ـ وَهُمُ الْيَهُودُ ـ مَا وَلاَّهُمْ عَنْ قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا ‏{‏قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ‏}‏ فَصَلَّى مَعَ النَّبِيِّ صلى الله عليه وسلم رَجُلٌ ثُمَّ خَرَجَ بَعْدَ مَا صَلَّى، فَمَرَّ عَلَى قَوْمٍ مِنَ الأَنْصَارِ فِي صَلاَةِ الْعَصْرِ نَحْوَ بَيْتِ الْمَقْدِسِ فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَأَنَّهُ تَوَجَّهَ نَحْوَ الْكَعْبَةِ‏.‏ فَتَحَرَّفَ الْقَوْمُ حَتَّى تَوَجَّهُوا نَحْوَ الْكَعْبَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 403","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-403","x":"Narrated `Abdullah bin `Umar:\n\nWhile the people were offering the Fajr prayer at Quba' (near Medina), someone came to them and said: \"It has been revealed to Allah's Messenger (ﷺ) tonight, and he has been ordered to pray facing the Ka`ba.\" So turn your faces to the Ka`ba. Those people were facing Sham (Jerusalem) so they turned their faces towards Ka`ba (at Mecca).","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكُ بْنُ أَنَسٍ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ بَيْنَا النَّاسُ بِقُبَاءٍ فِي صَلاَةِ الصُّبْحِ إِذْ جَاءَهُمْ آتٍ فَقَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ، وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ الْكَعْبَةَ فَاسْتَقْبِلُوهَا، وَكَانَتْ وُجُوهُهُمْ إِلَى الشَّأْمِ، فَاسْتَدَارُوا إِلَى الْكَعْبَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4486","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4486","x":"Narrated Al-Bara:\n\nThe Prophet (ﷺ) prayed facing Bait-ulMaqdis (i.e. Jerusalem) for sixteen or seventeen months but he wished that his Qibla would be the Ka`ba (at Mecca). (So Allah Revealed (2.144) and he offered `Asr prayers(in his Mosque facing Ka`ba at Mecca) and some people prayed with him. A man from among those who had prayed with him, went out and passed by some people offering prayer in another mosque, and they were in the state of bowing. He said, \"I, (swearing by Allah,) testify that I have prayed with the Prophet (ﷺ) facing Mecca.\" Hearing that, they turned their faces to the Ka`ba while they were still bowing. Some men had died before the Qibla was changed towards the Ka`ba. They had been killed and we did not know what to say about them (i.e. whether their prayers towards Jerusalem were accepted or not). So Allah revealed:-- \"And Allah would never make your faith (i.e. prayer) to be lost (i.e. your prayers offered (towards Jerusalem). Truly Allah is Full of Pity, Most Merciful towards mankind.\" (2.143)","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، سَمِعَ زُهَيْرًا، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، رضى الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم صَلَّى إِلَى بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ الْبَيْتِ، وَإِنَّهُ صَلَّى ـ أَوْ صَلاَّهَا ـ صَلاَةَ الْعَصْرِ، وَصَلَّى مَعَهُ قَوْمٌ، فَخَرَجَ رَجُلٌ مِمَّنْ كَانَ صَلَّى مَعَهُ، فَمَرَّ عَلَى أَهْلِ الْمَسْجِدِ وَهُمْ رَاكِعُونَ قَالَ أَشْهَدُ بِاللَّهِ لَقَدْ صَلَّيْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم قِبَلَ مَكَّةَ، فَدَارُوا كَمَا هُمْ قِبَلَ الْبَيْتِ، وَكَانَ الَّذِي مَاتَ عَلَى الْقِبْلَةِ قَبْلَ أَنْ تُحَوَّلَ قِبَلَ الْبَيْتِ رِجَالٌ قُتِلُوا لَمْ نَدْرِ مَا نَقُولُ فِيهِمْ، فَأَنْزَلَ اللَّهُ ‏{‏وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7252","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7252","x":"Narrated Al-Bara':\n\nWhen Allah's Messenger (ﷺ) arrived at Medina, he prayed facing Jerusalem for sixteen or seventeen months but he wished that he would be ordered to face the Ka`ba. So Allah revealed: -- 'Verily! We have seen the turning of your face towards the heaven; surely we shall turn you to a prayer direction (Qibla) that shall please you.' (2.144) Thus he was directed towards the Ka`ba. A man prayed the `Asr prayer with the Prophet (ﷺ) and then went out, and passing by some people from the Ansar, he said, \"I testify. that I have prayed with the Prophet (ﷺ) and he (the Prophet) has prayed facing the Ka`ba.\" Thereupon they, who were bowing in the `Asr prayer, turned towards the Ka`ba.","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ لَمَّا قَدِمَ رَسُولُ اللَّهِ صلى الله عليه وسلم الْمَدِينَةَ صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ، أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا‏}‏ فَوُجِّهَ نَحْوَ الْكَعْبَةِ، وَصَلَّى مَعَهُ رَجُلٌ الْعَصْرَ، ثُمَّ خَرَجَ فَمَرَّ عَلَى قَوْمٍ مِنَ الأَنْصَارِ فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ النَّبِيِّ صلى الله عليه وسلم وَأَنَّهُ قَدْ وُجِّهَ إِلَى الْكَعْبَةِ‏.‏ فَانْحَرَفُوا وَهُمْ رُكُوعٌ فِي صَلاَةِ الْعَصْرِ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1010","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1010","x":"It was narrated that Bara’ said:\n\n\"We prayed with the Messenger of Allah (ﷺ) facing towards Baitul-Maqdis (Jerusalem) for eighteen months, then the Qiblah was changed to the Ka’bah two months after the Prophet (ﷺ) entered Al-Madinah. When the Messenger of Allah (ﷺ) prayed towards Baitul-Maqdis, he would often lift his face towards the heavens, and Allah knew what was in the heart of His Prophet and how he longed to face the Ka’bah (during prayer). Jibril appeared (in the sky), and the Messenger of Allah (ﷺ) started watching him as he was descending between the heavens and the earth, waiting to see what he would bring. Then Allah revealed the words: ‘Verily, We have seen the turning of your face towards the heaven. Surely, We shall turn you to a Qiblah that shall please you, so turn your face in the direction of Al-Masjid Al-Haram (at Makkah). And wherever you people are, turn your faces (during prayer) in that direction.’ [2:144] Then someone came to us and said: ‘The Qiblah has been changed to the Ka’bah.’ We had performed two Rak’ah facing towards Jerusalem. And we were bowing. So we turned around, and we continued our prayer. The Messenger of Allah (ﷺ) said: ‘O Jibril! What about our prayer facing towards Baitul- Maqdis?’ Then Allah revealed the words: \"And Allah would never make your faith to be lost.\" [2:143]","ar":"حَدَّثَنَا عَلْقَمَةُ بْنُ عَمْرٍو الدَّارِمِيُّ، حَدَّثَنَا أَبُو بَكْرِ بْنُ عَيَّاشٍ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ صَلَّيْنَا مَعَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ نَحْوَ بَيْتِ الْمَقْدِسِ ثَمَانِيَةَ عَشَرَ شَهْرًا وَصُرِفَتِ الْقِبْلَةُ إِلَى الْكَعْبَةِ بَعْدَ دُخُولِهِ إِلَى الْمَدِينَةِ بِشَهْرَيْنِ وَكَانَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ إِذَا صَلَّى إِلَى بَيْتِ الْمَقْدِسِ أَكْثَرَ تَقَلُّبَ وَجْهِهِ فِي السَّمَاءِ وَعَلِمَ اللَّهُ مِنْ قَلْبِ نَبِيِّهِ ـ صلى الله عليه وسلم ـ أَنَّهُ يَهْوَى الْكَعْبَةَ فَصَعِدَ جِبْرِيلُ فَجَعَلَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ يُتْبِعُهُ بَصَرَهُ وَهُوَ يَصْعَدُ بَيْنَ السَّمَاءِ وَالأَرْضِ يَنْظُرُ مَا يَأْتِيهِ بِهِ فَأَنْزَلَ اللَّهُ ‏{قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ}‏ الآيَةَ فَأَتَانَا آتٍ فَقَالَ إِنَّ الْقِبْلَةَ قَدْ صُرِفَتْ إِلَى الْكَعْبَةِ وَقَدْ صَلَّيْنَا رَكْعَتَيْنِ إِلَى بَيْتِ الْمَقْدِسِ وَنَحْنُ رُكُوعٌ فَتَحَوَّلْنَا فَبَنَيْنَا عَلَى مَا مَضَى مِنْ صَلاَتِنَا فَقَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\"‏ يَا جِبْرِيلُ كَيْفَ حَالُنَا فِي صَلاَتِنَا إِلَى بَيْتِ الْمَقْدِسِ ‏\"‏ ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ}‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 525a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-525a","x":"Al-Bara' b. 'Azib reported:\n\nI said prayer with the Apostle (ﷺ) turning towards Bait-ul-Maqdis for sixteen months till this verse of Surah Baqara wis revealed:\" And wherever you are turn your faces towards it\" (ii. 144). This verse was revealed when the Apostle (ﷺ) had said prayer. A person amongst his people passed by the people of Ansar as they were engaged in prayer. He narrated to them (this command of Allah) and they turned their faces towards the Ka'ba.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ صَلَّيْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم إِلَى بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا حَتَّى نَزَلَتِ الآيَةُ الَّتِي فِي الْبَقَرَةِ ‏{‏ وَحَيْثُمَا كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ‏}‏ فَنَزَلَتْ بَعْدَ مَا صَلَّى النَّبِيُّ صلى الله عليه وسلم فَانْطَلَقَ رَجُلٌ مِنَ الْقَوْمِ فَمَرَّ بِنَاسٍ مِنَ الأَنْصَارِ وَهُمْ يُصَلُّونَ فَحَدَّثَهُمْ فَوَلَّوْا وُجُوهَهُمْ قِبَلَ الْبَيْتِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 527","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-527","x":"Anas reported:\n\nThe Messenger of Allah (ﷺ) used to pray towards Bait-ul-Maqdis, that it was revealed (to him):\" Indeed We see the turning of the face to heaven, wherefore We shall assuredly cause thee to turn towards Qibla which shall please thee. So turn thy face towards the sacred Mosque (Ka'ba)\" (ii. 144). A person from Banu Salama was going; (he found the people) in ruk'u (while) praying the dawn prayer and they had said one rak'ah. He said in a loud voice: Listen! the Qibla has been changed and they turned towards (the new) Qibla (Ka'ba) in that very state.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَفَّانُ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يُصَلِّي نَحْوَ بَيْتِ الْمَقْدِسِ فَنَزَلَتْ ‏{‏ قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ‏}‏ فَمَرَّ رَجُلٌ مِنْ بَنِي سَلِمَةَ وَهُمْ رُكُوعٌ فِي صَلاَةِ الْفَجْرِ وَقَدْ صَلَّوْا رَكْعَةً فَنَادَى أَلاَ إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ ‏.‏ فَمَالُوا كَمَا هُمْ نَحْوَ الْقِبْلَةِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 1, Book 2, Hadith 340","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-1/Book-2/Hadith-340","x":"Al-Bara bin Azib narrated:\n\n\"When Allah's Messener arrived in Al-Madinah, he faced Bait Al-Maqdis in Salat for sixteen or seventeen months. Allah's Messenger longed to face the direction of the Ka'bah, so Allah Most High revealed: Verily! We have seen the turning of your face towards the heaven. Surely We shall turn you o a Qiblah that shall please you. So turn your face in the direction of Al-Masjid Al-Haram.So he faced the Ka'bah, and he liked that. A man performed the Asr prayer with him, then passed by some of the Ansar who were bowing in Salat for Asr while facing Bait Al-Maqdis.\" He told them that he had faced the direction of the Ka'bah, so they changed (their direction) while they were bowing.\" [He said:] There are narrations on this topic from Ibn Umar, Ibn Abbas, Umarah bin Aws, Amr bin Awf Al-Muzani and Anas.","ar":"حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ لَمَّا قَدِمَ رَسُولُ اللَّهِ صلى الله عليه وسلم الْمَدِينَةَ صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ فَأَنْزَلَ اللَّهُ تَعَالَىْ‏:‏ ‏(‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ‏)‏ فَوُجِّهَ نَحْوَ الْكَعْبَةِ وَكَانَ يُحِبُّ ذَلِكَ فَصَلَّى رَجُلٌ مَعَهُ الْعَصْرَ ثُمَّ مَرَّ عَلَى قَوْمٍ مِنَ الأَنْصَارِ وَهُمْ رُكُوعٌ فِي صَلاَةِ الْعَصْرِ نَحْوَ بَيْتِ الْمَقْدِسِ فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَنَّهُ قَدْ وُجِّهَ إِلَى الْكَعْبَةِ ‏.‏ قَالَ فَانْحَرَفُوا وَهُمْ رُكُوعٌ ‏.‏ قَالَ وَفِي الْبَابِ عَنِ ابْنِ عُمَرَ وَابْنِ عَبَّاسٍ وَعُمَارَةَ بْنِ أَوْسٍ وَعَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ وَأَنَسٍ ‏.‏ قَالَ أَبُو عِيسَى وَحَدِيثُ الْبَرَاءِ حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رَوَاهُ سُفْيَانُ الثَّوْرِيُّ عَنْ أَبِي إِسْحَاقَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2962","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2962","x":"Narrated Al-Bara bin 'Azib:\n\n\"When the Messenger of Allah (ﷺ) arrived in Al-Madinah, he performed Salat facing the direction of Bait Al-Maqdis (Jerusalem) for sixteen or seventeen months. The Messenger of Allah (ﷺ) longed to face toward the Ka'bah, so Allah, Might and Sublime is He revealed: Verily, WE have seen the turning of your face towards the heave. Surely, We Shall turn your face in the direction of Al-Masjid Al-Haram (2:144). So he faced the direction of the Ka'bah and he longed for that. (One day) a man performed Salat Al-'Asr along with him.\" He said: \"Then he passed by some people of the Ansar performing Salat Al-'Asr, while they were bowing toward Bait Al-Maqdis. He told them that he testifies that he performed Salat with the Messenger of Allah (ﷺ), and he had faced the direction of the Ka'bah.\" He said: \"So they turned while they were bowing.\"","ar":"حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ لَمَّا قَدِمَ رَسُولُ اللَّهِ صلى الله عليه وسلم الْمَدِينَةَ صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ فَأَنْزَلَ اللَّهُ‏:‏ ‏(‏ قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ ‏)‏ فَوَجَّهَ نَحْوَ الْكَعْبَةِ وَكَانَ يُحِبُّ ذَلِكَ فَصَلَّى رَجُلٌ مَعَهُ الْعَصْرَ قَالَ ثُمَّ مَرَّ عَلَى قَوْمٍ مِنَ الأَنْصَارِ وَهُمْ رُكُوعٌ فِي صَلاَةِ الْعَصْرِ نَحْوَ بَيْتِ الْمَقْدِسِ فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَنَّهُ قَدْ وُجِّهَ إِلَى الْكَعْبَةِ قَالَ فَانْحَرَفُوا وَهُمْ رُكُوعٌ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ سُفْيَانُ الثَّوْرِيُّ عَنْ أَبِي إِسْحَاقَ ‏.‏","v":[]}],"149":[{"c":"Sahih Bukhari","r":"Hadith 4492","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4492","x":"Narrated Al-Bara:\n\nWe prayed along with the Prophet (ﷺ) facing Jerusalem for sixteen or seventeen months. Then Allah ordered him to turn his face towards the Qibla (in Mecca):-- \"And from whence-so-ever you start forth (for prayers) turn your face in the direction of (the Sacred Mosque of Mecca) Al-Masjid-ul Haram..\" (2.149)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى، عَنْ سُفْيَانَ، حَدَّثَنِي أَبُو إِسْحَاقَ، قَالَ سَمِعْتُ الْبَرَاءَ ـ رضى الله عنه ـ قَالَ صَلَّيْنَا مَعَ النَّبِيِّ صلى الله عليه وسلم نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ ـ أَوْ سَبْعَةَ عَشَرَ ـ شَهْرًا، ثُمَّ صَرَفَهُ نَحْوَ الْقِبْلَةِ‏.‏","v":[]}],"150":[{"c":"Sahih Bukhari","r":"Hadith 4493","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4493","x":"Narrated Ibn `Umar:\n\nWhile some people were at Quba (offering) morning prayer, a man came to them and said, \"Last night Qur'anic Verses have been revealed whereby the Prophet (ﷺ) has been ordered to face the Ka`ba (at Mecca), so you too should face it.\" So they, keeping their postures, turned towards the Ka`ba. Formerly the people were facing Sham (Jerusalem) (Allah said):-- \"And from whence-so-ever you start forth (for prayers), turn your face in the direction of the Sacred Mosque of Mecca (Al-Masjid-ul-Haram), and whence-so-ever you are, turn your face towards it (when you pray)\" (2.150)","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ دِينَارٍ، قَالَ سَمِعْتُ ابْنَ عُمَرَ ـ رضى الله عنهما ـ يَقُولُ بَيْنَا النَّاسُ فِي الصُّبْحِ بِقُبَاءٍ إِذْ جَاءَهُمْ رَجُلٌ فَقَالَ أُنْزِلَ اللَّيْلَةَ قُرْآنٌ، فَأُمِرَ أَنْ يَسْتَقْبِلَ الْكَعْبَةَ، فَاسْتَقْبِلُوهَا‏.‏ وَاسْتَدَارُوا كَهَيْئَتِهِمْ، فَتَوَجَّهُوا إِلَى الْكَعْبَةِ وَكَانَ وَجْهُ النَّاسِ إِلَى الشَّأْمِ‏.‏","v":[]}],"154":[{"c":"Sunan Abu Dawud","r":"Hadith 2526","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2526","x":"Narrated Abdullah ibn Amr ibn al-'As:\n\nThe Prophet (ﷺ) said: The warrior gets his reward, and the one who equips him gets his own reward and that of the warrior.","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ الْحَسَنِ الْمِصِّيصِيُّ، حَدَّثَنَا حَجَّاجٌ، - يَعْنِي ابْنَ مُحَمَّدٍ - ح وَحَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ شُعَيْبٍ، حَدَّثَنَا ابْنُ وَهْبٍ، عَنِ اللَّيْثِ بْنِ سَعْدٍ، عَنْ حَيْوَةَ بْنِ شُرَيْحٍ، عَنِ ابْنِ شُفَىٍّ، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏:‏ ‏\n\n\"‏ لِلْغَازِي أَجْرُهُ، وَلِلْجَاعِلِ أَجْرُهُ وَأَجْرُ الْغَازِي ‏\"\n\n‏ ‏.‏","v":[]}],"158":[{"c":"Sunan Abu Dawud","r":"Hadith 1906","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1906","x":"Ja’far bin Muhammad reported on the authority of his father The Prophet (ﷺ) prayed the noon and the afternoon prayers with one adhan and two iqamahs at ‘Arafah and he did not offer supererogatory prayers between them. He prayed the sunset and night prayers at Al Muzdalifah with one adhan and two iqamahs and he did not offer supererogatory prayers between them. Abu Dawud said This tradition has been narrated by Hatim bin Isma’il as a part of the lengthy tradition. Muhammad bin ‘Ali Al Ju’fi narrated it from Ja’far from his father on the authority of Jabir, like the tradition transmitted by Hatim bin Isma’il. But this version has He offered the sunset and night prayers with one adhan and one iqamah.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، حَدَّثَنَا سُلَيْمَانُ يَعْنِي ابْنَ بِلاَلٍ، ح وَحَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ، - الْمَعْنَى وَاحِدٌ - عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم صَلَّى الظُّهْرَ وَالْعَصْرَ بِأَذَانٍ وَاحِدٍ بِعَرَفَةَ وَلَمْ يُسَبِّحْ بَيْنَهُمَا وَإِقَامَتَيْنِ وَصَلَّى الْمَغْرِبَ وَالْعِشَاءَ بِجَمْعٍ بِأَذَانٍ وَاحِدٍ وَإِقَامَتَيْنِ وَلَمْ يُسَبِّحْ بَيْنَهُمَا ‏.‏ قَالَ أَبُو دَاوُدَ هَذَا الْحَدِيثُ أَسْنَدَهُ حَاتِمُ بْنُ إِسْمَاعِيلَ فِي الْحَدِيثِ الطَّوِيلِ وَوَافَقَ حَاتِمَ بْنَ إِسْمَاعِيلَ عَلَى إِسْنَادِهِ مُحَمَّدُ بْنُ عَلِيٍّ الْجُعْفِيُّ عَنْ جَعْفَرٍ عَنْ أَبِيهِ عَنْ جَابِرٍ إِلاَّ أَنَّهُ قَالَ فَصَلَّى الْمَغْرِبَ وَالْعَتَمَةَ بِأَذَانٍ وَإِقَامَةٍ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1643","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1643","x":"Narrated `Urwa:\n\nI asked `Aisha : \"How do you interpret the statement of Allah,. : Verily! (the mountains) As-Safa and Al-Marwa are among the symbols of Allah, and whoever performs the Hajj to the Ka`ba or performs `Umra, it is not harmful for him to perform Tawaf between them (Safa and Marwa.) (2.158). By Allah! (it is evident from this revelation) there is no harm if one does not perform Tawaf between Safa and Marwa.\" `Aisha said, \"O, my nephew! Your interpretation is not true. Had this interpretation of yours been correct, the statement of Allah should have been, 'It is not harmful for him if he does not perform Tawaf between them.' But in fact, this divine inspiration was revealed concerning the Ansar who used to assume lhram for worship ping an idol called \"Manat\" which they used to worship at a place called Al-Mushallal before they embraced Islam, and whoever assumed Ihram (for the idol), would consider it not right to perform Tawaf between Safa and Marwa. When they embraced Islam, they asked Allah's Messenger (ﷺ) (p.b.u.h) regarding it, saying, \"O Allah's Apostle! We used to refrain from Tawaf between Safa and Marwa.\" So Allah revealed: 'Verily; (the mountains) As-Safa and Al-Marwa are among the symbols of Allah.' \" Aisha added, \"Surely, Allah's Apostle set the tradition of Tawaf between Safa and Marwa, so nobody is allowed to omit the Tawaf between them.\" Later on I (`Urwa) told Abu Bakr bin `Abdur-Rahman (of `Aisha's narration) and he said, 'I have not heard of such information, but I heard learned men saying that all the people, except those whom `Aisha mentioned and who used to assume lhram for the sake of Manat, used to perform Tawaf between Safa and Marwa. When Allah referred to the Tawaf of the Ka`ba and did not mention Safa and Marwa in the Qur'an, the people asked, 'O Allah's Messenger (ﷺ)! We used to perform Tawaf between Safa and Marwa and Allah has revealed (the verses concerning) Tawaf of the Ka`ba and has not mentioned Safa and Marwa. Is there any harm if we perform Tawaf between Safa and Marwa?' So Allah revealed: \"Verily As-Safa and Al- Marwa are among the symbols of Allah.\" Abu Bakr said, \"It seems that this verse was revealed concerning the two groups, those who used to refrain from Tawaf between Safa and Marwa in the Pre- Islamic Period of ignorance and those who used to perform the Tawaf then, and after embracing Islam they refrained from the Tawaf between them as Allah had enjoined Tawaf of the Ka`ba and did not mention Tawaf (of Safa and Marwa) till later after mentioning the Tawaf of the Ka`ba.'","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ عُرْوَةُ سَأَلْتُ عَائِشَةَ ـ رضى الله عنها ـ فَقُلْتُ لَهَا أَرَأَيْتِ قَوْلَ اللَّهِ تَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا‏}‏ فَوَاللَّهِ مَا عَلَى أَحَدٍ جُنَاحٌ أَنْ لاَ يَطُوفَ بِالصَّفَا وَالْمَرْوَةِ‏.‏ قَالَتْ بِئْسَ مَا قُلْتَ يَا ابْنَ أُخْتِي إِنَّ هَذِهِ لَوْ كَانَتْ كَمَا أَوَّلْتَهَا عَلَيْهِ كَانَتْ لاَ جُنَاحَ عَلَيْهِ أَنْ لاَ يَتَطَوَّفَ بِهِمَا، وَلَكِنَّهَا أُنْزِلَتْ فِي الأَنْصَارِ، كَانُوا قَبْلَ أَنْ يُسْلِمُوا يُهِلُّونَ لِمَنَاةَ الطَّاغِيَةِ الَّتِي كَانُوا يَعْبُدُونَهَا عِنْدَ الْمُشَلَّلِ، فَكَانَ مَنْ أَهَلَّ يَتَحَرَّجُ أَنْ يَطُوفَ بِالصَّفَا وَالْمَرْوَةِ، فَلَمَّا أَسْلَمُوا سَأَلُوا رَسُولَ اللَّهِ صلى الله عليه وسلم عَنْ ذَلِكَ قَالُوا يَا رَسُولَ اللَّهِ، إِنَّا كُنَّا نَتَحَرَّجُ أَنْ نَطُوفَ بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ‏}‏ الآيَةَ‏.‏ قَالَتْ عَائِشَةُ ـ رضى الله عنها ـ وَقَدْ سَنَّ رَسُولُ اللَّهِ صلى الله عليه وسلم الطَّوَافَ بَيْنَهُمَا، فَلَيْسَ لأَحَدٍ أَنْ يَتْرُكَ الطَّوَافَ بَيْنَهُمَا‏.‏ ثُمَّ أَخْبَرْتُ أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ، فَقَالَ إِنَّ هَذَا لَعِلْمٌ مَا كُنْتُ سَمِعْتُهُ، وَلَقَدْ سَمِعْتُ رِجَالاً مِنْ أَهْلِ الْعِلْمِ، يَذْكُرُونَ أَنَّ النَّاسَ إِلاَّ مَنْ ذَكَرَتْ عَائِشَةُ مِمَّنْ كَانَ يُهِلُّ بِمَنَاةَ، كَانُوا يَطُوفُونَ كُلُّهُمْ بِالصَّفَا وَالْمَرْوَةِ، فَلَمَّا ذَكَرَ اللَّهُ تَعَالَى الطَّوَافَ بِالْبَيْتِ، وَلَمْ يَذْكُرِ الصَّفَا وَالْمَرْوَةَ فِي الْقُرْآنِ قَالُوا يَا رَسُولَ اللَّهِ كُنَّا نَطُوفُ بِالصَّفَا وَالْمَرْوَةِ، وَإِنَّ اللَّهَ أَنْزَلَ الطَّوَافَ بِالْبَيْتِ، فَلَمْ يَذْكُرِ الصَّفَا فَهَلْ عَلَيْنَا مِنْ حَرَجٍ أَنْ نَطَّوَّفَ بِالصَّفَا وَالْمَرْوَةِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ‏}‏ الآيَةَ‏.‏ قَالَ أَبُو بَكْرٍ فَأَسْمَعُ هَذِهِ الآيَةَ نَزَلَتْ فِي الْفَرِيقَيْنِ كِلَيْهِمَا فِي الَّذِينَ كَانُوا يَتَحَرَّجُونَ أَنْ يَطُوفُوا بِالْجَاهِلِيَّةِ بِالصَّفَا وَالْمَرْوَةِ، وَالَّذِينَ يَطُوفُونَ ثُمَّ تَحَرَّجُوا أَنْ يَطُوفُوا بِهِمَا فِي الإِسْلاَمِ مِنْ أَجْلِ أَنَّ اللَّهَ تَعَالَى أَمَرَ بِالطَّوَافِ بِالْبَيْتِ، وَلَمْ يَذْكُرِ الصَّفَا حَتَّى ذَكَرَ ذَلِكَ بَعْدَ مَا ذَكَرَ الطَّوَافَ بِالْبَيْتِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1648","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1648","x":"Narrated `Asim:\n\nI asked Anas bin Malik: \"Did you use to dislike to perform Tawaf between Safa and Marwa?\" He said, \"Yes, as it was of the ceremonies of the days of the Pre-Islamic period of ignorance, till Allah revealed: 'Verily! (The two mountains) As-Safa and Al-Marwa are among the symbols of Allah. It is therefore no sin for him who performs the pilgrimage to the Ka`ba, or performs `Umra, to perform Tawaf between them.' \" (2.158)","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدٍ، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا عَاصِمٌ، قَالَ قُلْتُ لأَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ أَكُنْتُمْ تَكْرَهُونَ السَّعْىَ بَيْنَ الصَّفَا وَالْمَرْوَةِ قَالَ نَعَمْ‏.‏ لأَنَّهَا كَانَتْ مِنْ شَعَائِرِ الْجَاهِلِيَّةِ، حَتَّى أَنْزَلَ اللَّهُ ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1649","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1649","x":"Narrated Ibn `Abbas:\n\nAllah's Messenger (ﷺ) performed Tawaf of the Ka`ba and the Sa`i of Safa and Marwa so as to show his strength to the pagans.","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرِو بْنِ دِينَارٍ، عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ إِنَّمَا سَعَى رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ لِيُرِيَ الْمُشْرِكِينَ قُوَّتَهُ‏.‏ زَادَ الْحُمَيْدِيُّ حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا عَمْرٌو، سَمِعْتُ عَطَاءً، عَنِ ابْنِ عَبَّاسٍ، مِثْلَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1790","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1790","x":"Narrated Hisham Ibn `Urwa from his father who said:\n\nWhile I was a youngster, I asked `Aisha the wife of the Prophet. \"What about the meaning of the Statement of Allah; \"Verily! (the mountains) As-Safa and Al Marwa, are among the symbols of Allah. So, it is not harmful if those who perform Hajj or `Umra of the House (Ka`ba at Mecca) to perform the going (Tawaf) between them? (2.158) I understand (from that) that there is no harm if somebody does not perform the Tawaf between them.\" `Aisha replied, \"No, for if it were as you are saying, then the recitation would have been like this: 'It is not harmful not to perform Tawaf between them.' This verse was revealed in connection with the Ansar who used to assume the Ihram for the idol Manat which was put beside a place called Qudaid and those people thought it not right to perform the Tawaf of As- Safa and Al-Marwa. When Islam came, they asked Allah's Messenger (ﷺ) about that, and Allah revealed:-- \"Verily! (the mountains) As-Safa and Al-Marwa Are among the symbols of Allah. So, it is not harmful of those who perform Hajj or `Umra of the House (Ka`ba at Mecca) to perform the going (Tawaf) between them.\" (2.158) Sufyan and Abu Muawiya added from Hisham (from `Aisha): \"The Hajj or `Umra of the person who does not perform the going (Tawaf) between As-Safa and Al-Marwa is incomplete in Allah's sight.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، أَنَّهُ قَالَ قُلْتُ لِعَائِشَةَ ـ رضى الله عنها ـ زَوْجِ النَّبِيِّ صلى الله عليه وسلم وَأَنَا يَوْمَئِذٍ حَدِيثُ السِّنِّ أَرَأَيْتِ قَوْلَ اللَّهِ تَبَارَكَ وَتَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا‏}‏ فَلاَ أُرَى عَلَى أَحَدٍ شَيْئًا أَنْ لاَ يَطَّوَّفَ بِهِمَا‏.‏ فَقَالَتْ عَائِشَةُ كَلاَّ، لَوْ كَانَتْ كَمَا تَقُولُ كَانَتْ فَلاَ جُنَاحَ عَلَيْهِ أَنْ لاَ يَطَّوَّفَ بِهِمَا‏.‏ إِنَّمَا أُنْزِلَتْ هَذِهِ الآيَةُ فِي الأَنْصَارِ كَانُوا يُهِلُّونَ لِمَنَاةَ، وَكَانَتْ مَنَاةُ حَذْوَ قُدَيْدٍ، وَكَانُوا يَتَحَرَّجُونَ أَنْ يَطُوفُوا بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَلَمَّا جَاءَ الإِسْلاَمُ سَأَلُوا رَسُولَ اللَّهِ صلى الله عليه وسلم عَنْ ذَلِكَ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا‏}‏‏.‏ زَادَ سُفْيَانُ وَأَبُو مُعَاوِيَةَ عَنْ هِشَامٍ مَا أَتَمَّ اللَّهُ حَجَّ امْرِئٍ وَلاَ عُمْرَتَهُ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4495","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4495","x":"Narrated `Urwa:\n\nI said to `Aisha, the wife of the Prophet, and I was at that time a young boy, \"How do you interpret the Statement of Allah: \"Verily, Safa and Marwa (i.e. two mountains at Mecca) are among the Symbols of Allah.\" So it is not harmful of those who perform the Hajj to the House of Allah) or perform the Umra, to ambulate (Tawaf) between them. In my opinion it is not sinful for one not to ambulate (Tawaf) between them.\" `Aisha said, \"Your interpretation is wrong for as you say, the Verse should have been: \"So it is not harmful of those who perform the Hajj or Umra to the House, not to ambulate (Tawaf) between them.' This Verse was revealed in connection with the Ansar who (during the Pre-Islamic Period) used to visit Manat (i.e. an idol) after assuming their Ihram, and it was situated near Qudaid (i.e. a place at Mecca), and they used to regard it sinful to ambulate between Safa and Marwa after embracing Islam. When Islam came, they asked Allah's Messenger (ﷺ) about it, whereupon Allah revealed:-- \"Verily, Safa and Marwa (i.e. two mountains at Mecca) are among the Symbols of Allah. So it is not harmful of those who perform the Hajj of the House (of Allah) or perform the Umra, to ambulate (Tawaf) between them.\" (2.158)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، أَنَّهُ قَالَ قُلْتُ لِعَائِشَةَ زَوْجِ النَّبِيِّ صلى الله عليه وسلم وَأَنَا يَوْمَئِذٍ حَدِيثُ السِّنِّ أَرَأَيْتِ قَوْلَ اللَّهِ تَبَارَكَ وَتَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا‏}‏ فَمَا أُرَى عَلَى أَحَدٍ شَيْئًا أَنْ لاَ يَطَّوَّفَ بِهِمَا‏.‏ فَقَالَتْ عَائِشَةُ كَلاَّ لَوْ كَانَتْ كَمَا تَقُولُ كَانَتْ فَلاَ جُنَاحَ عَلَيْهِ أَنْ لاَ يَطَّوَّفَ بِهِمَا، إِنَّمَا أُنْزِلَتْ هَذِهِ الآيَةُ فِي الأَنْصَارِ، كَانُوا يُهِلُّونَ لِمَنَاةَ، وَكَانَتْ مَنَاةُ حَذْوَ قُدَيْدٍ، وَكَانُوا يَتَحَرَّجُونَ أَنْ يَطُوفُوا بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَلَمَّا جَاءَ الإِسْلاَمُ سَأَلُوا رَسُولَ اللَّهِ صلى الله عليه وسلم عَنْ ذَلِكَ فَأَنْزَلَ اللَّهُ ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4496","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4496","x":"Narrated `Asim bin Sulaiman:\n\nI asked Anas bin Malik about Safa and Marwa. Anas replied, \"We used to consider (i.e. going around) them a custom of the Pre-islamic period of Ignorance, so when Islam came, we gave up going around them. Then Allah revealed\" \"Verily, Safa and Marwa (i.e. two mountains at Mecca) are among the Symbols of Allah. So it is not harmful of those who perform the Hajj of the House (of Allah) or perform the Umra to ambulate (Tawaf) between them.\" (2.158)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنْ عَاصِمِ بْنِ سُلَيْمَانَ، قَالَ سَأَلْتُ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ عَنِ الصَّفَا، وَالْمَرْوَةِ،‏.‏ فَقَالَ كُنَّا نَرَى أَنَّهُمَا مِنْ أَمْرِ الْجَاهِلِيَّةِ، فَلَمَّا كَانَ الإِسْلاَمُ أَمْسَكْنَا عَنْهُمَا، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ ‏}‏ إِلَى قَوْلِهِ ‏{‏أَنْ يَطَّوَّفَ بِهِمَا‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4861","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4861","x":"Narrated `Urwa:\n\nI asked `Aisha (regarding the Sai between As Safa and Al-Marwa). She said, \"Out of reverence to the idol Manat which was placed in Al-Mushailal, those who used to assume Ihram in its name, used not to perform Sai between As-Safa and Al-Marwa, so Allah revealed: 'Verily! The As-Safa and Al-Marwa (two mountains at Mecca) are among the symbols of Allah.' (2.158). Thereupon, Allah's Messenger (ﷺ) and the Muslims used to perform Sai (between them).\" Sufyan said: The (idol) Manat was at Al-Mushailal in Qudaid. `Aisha added, \"The Verse was revealed in connection with the Ansar. They and (the tribe of) Ghassan used to assume lhram in the name of Manat before they embraced Islam.\" `Aisha added, \"There were men from the Ansar who used to assume lhram in the name of Manat which was an idol between Mecca and Medina. They said, \"O Allah's Messenger (ﷺ)! We used not to perform the Tawaf (Sai) between As-Safa and Al-Marwa out of reverence to Manat.\"","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا الزُّهْرِيُّ، سَمِعْتُ عُرْوَةَ، قُلْتُ لِعَائِشَةَ ـ رضى الله عنها ـ فَقَالَتْ إِنَّمَا كَانَ مَنْ أَهَلَّ بِمَنَاةَ الطَّاغِيَةِ الَّتِي بِالْمُشَلَّلِ لاَ يَطُوفُونَ بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ‏}‏ فَطَافَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَالْمُسْلِمُونَ‏.‏ قَالَ سُفْيَانُ مَنَاةُ بِالْمُشَلَّلِ مِنْ قُدَيْدٍ‏.‏ وَقَالَ عَبْدُ الرَّحْمَنِ بْنُ خَالِدٍ عَنِ ابْنِ شِهَابٍ قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ نَزَلَتْ فِي الأَنْصَارِ كَانُوا هُمْ وَغَسَّانُ قَبْلَ أَنْ يُسْلِمُوا يُهِلُّونَ لِمَنَاةَ‏.‏ مِثْلَهُ‏.‏ وَقَالَ مَعْمَرٌ عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَائِشَةَ كَانَ رِجَالٌ مِنَ الأَنْصَارِ مِمَّنْ كَانَ يُهِلُّ لِمَنَاةَ ـ وَمَنَاةُ صَنَمٌ بَيْنَ مَكَّةَ وَالْمَدِينَةِ ـ قَالُوا يَا نَبِيَّ اللَّهِ كُنَّا لاَ نَطُوفُ بَيْنَ الصَّفَا وَالْمَرْوَةِ تَعْظِيمًا لِمَنَاةَ‏.‏ نَحْوَهُ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 25, Hadith 2986","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-25/Hadith-2986","x":"It was narrated that Hisham bin ‘Urwah said:\n\n\"My father told me: ‘I said to ‘Aishah: \"I do not think there is any sin on me if I do not perform Tawaf* between Safa and Marwah.\" She said: \"Allah says: ‘Verily, Safa and Marwah are of the Symbols of Allah. So it is not a sin on him who performs Hajj or ‘Umrah of the House to perform Tawaf between them.’\" [2:158] If the matter were as you say, then it would have said, ‘it is not a sin on him to not perform the Sa’y between them.’ Rather this was revealed concerning some people among the Ansar who previously, when they stated the Talbiyah, they used to recite it for Manat, and it was not lawful for them to perform Sa’y between Safa and Marwah. When they arrived with the Prophet (ﷺ) for Hajj, they mentioned that to him, and Allah revealed this Verse. By Allah, Allah will not accept the Hajj as complete if one who does not perform Sa’y between Safa and Marwah.’\"","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، قَالَ أَخْبَرَنِي أَبِي قَالَ، قُلْتُ لِعَائِشَةَ مَا أَرَى عَلَىَّ جُنَاحًا أَنْ لاَ أَطَّوَّفَ بَيْنَ الصَّفَا وَالْمَرْوَةِ ‏.‏ قَالَتْ إِنَّ اللَّهَ يَقُولُ ‏{إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا}‏ وَلَوْ كَانَ كَمَا تَقُولُ لَكَانَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ لاَ يَطَّوَّفَ بِهِمَا ‏.‏ إِنَّمَا أُنْزِلَ هَذَا فِي نَاسٍ مِنَ الأَنْصَارِ كَانُوا إِذَا أَهَلُّوا أَهَلُّوا لِمَنَاةَ فَلاَ يَحِلُّ لَهُمْ أَنْ يَطَّوَّفُوا بَيْنَ الصَّفَا وَالْمَرْوَةِ فَلَمَّا قَدِمُوا مَعَ النَّبِيِّ ـ صلى الله عليه وسلم ـ فِي الْحَجِّ ذَكَرُوا ذَلِكَ لَهُ فَأَنْزَلَهَا اللَّهُ فَلَعَمْرِي مَا أَتَمَّ اللَّهُ عَزَّ وَجَلَّ حَجَّ مَنْ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 25, Hadith 3074","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-25/Hadith-3074","x":"Ja’far bin Muhammad narrated that his father said:\n\n\"We entered upon Jabir bin ‘Abdullah, and when we reached him he asked about the people (i.e., what their names were, etc.). When he reached me, I said: ‘I am Muhammad bin ‘Ali bin Husain.’ He stretched forth his hand towards my head, and undid my top button, then undid my lower button. Then he placed his hand on my chest, and I was a young boy at that time. Then he said: ‘Welcome to you, ask whatever you want.’ So I asked him, and he was blind. The time for prayer came, so he stood up, wrapping himself in a woven cloth. Every time he put it on his shoulders, its edges came up, because it was too small. And his cloak was beside him on a hook. He led us in prayer, then he said: ‘Tell us about the Hajj of the Messenger of Allah (ﷺ).’ He held up his hands, showing nine (fingers), and said: ‘The Messenger of Allah (ﷺ) stayed for nine years without performing Hajj, then it was announced to the people in the tenth year that the Messenger of Allah (ﷺ) was going for Hajj. So many people came to Al-Madinah, all of them seeking to follow the Messenger of Allah (ﷺ) and do what he did. He set out and we set out with him, and we came to Dhul-Hulaifah where Asma’ bint ‘Umais gave birth to Muhammad bin Abu Bakr. She sent word to the Messenger of Allah (ﷺ) asking what she should do. He said: \"Perform Ghusl, fasten a cloth around your waist and enter Ihram.\" The Messenger of Allah (ﷺ) prayed in the mosque, then he rode Qaswa’ (his she-camel) until, when his she-camel arose with him upon Baida’,’ Jabir said: ‘As far as I could see, I saw people riding and walking in front of him, and I saw the same to his right and left, and behind him, and the Messenger of Allah (ﷺ) was among us and Qur’an was being revealed to him, and he understood its meaning. Whatever he did, we did too. Then he began the Talbiyah of monotheism: \"Labbaika Allahumma labbaik, labbaika la sharika laka labbaik. Innal-hamda wan-ni’mata laka wal-mulk, la sharika laka (Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Verily all praise and blessings are Yours, and all sovereignty, You have no partner).\" And the people repeated his words. And the Messenger of Allah (ﷺ) approved of that. And the Messenger of Allah (ﷺ) continued to recite the Talbiyah.’ Jabir said: ‘We did not intend (to do) anything but Hajj. We were not aware of ‘Umrah. Then when we reached the House with him, he touched the Corner, and walked quickly (Ramal) for three circuits and walked (normally) for four. Then he stood at the place of Ibrahim and said: \"And take you (people) the place of Ibrahim as a place of prayer.\" [2:125] He stood with the place between him and the House. My father used to say:* \"And I do not think that he mentioned it other than from the Prophet (ﷺ): ‘That he used to recite in those two Rak’ah (at the place of Ibrahim): \"Say: ‘O you disbelievers!’\" [Al-Kafirun (109)] and \"Say: ‘He is Allah, (the) One.’\" [Al-Ikhlas (112)] \"Then he went back to the House and touched the Corner, then he went out through the gate to Safa. When he drew near to Safa he recited: \"Verily, Safa and Marwah are among the symbols of Allah,\" [2:158] (and said:) \"We will start with that with which Allah started.\" So he started with Safa and climbed it until he could see the House, then proclaimed the greatness of Allah (by saying: Allahu Akbar) and said Tahlil (La ilaha illallah) and praised Him (saying Al-Hamdulillah), and he said: \"La ilaha illallah wahdahu la sharika lahu, lahul-mulku, wa lahul-hamdu, yuhyi wa yumit wa huwa ‘ala kulli shai’in Qadir. La ilaha illallah wahdahu, La sharika lahu anjaza wa’dahu, wa nasara ‘abduhu, wa hazamal-Ahzaba wahdahu (None has the right to be worshiped but Allah alone, with no partner or associate; His is the dominion, all praise is due to Him, He gives life and causes death and He is able to do all things. None has the right to be worshiped but Allah alone; He has no partner or associate, He fulfilled His promise, granted victory to His slave, and defeated the Confederates alone).\" And he said that three times, supplication in between. Then he headed towards Marwah walking normally until, when he started to go downhill, he walked quickly (Ramal) in the bottom of the valley. When he started to go uphill, he walked normally, until he reached Marwah, and he did atop Marwah what he had done atop Safa. At the end of his Sa’y, atop Marwah he said: \"If I had known before what I have come to know now, I would not have garlanded the sacrificial animal, and I would have made it ‘Umrah. Whoever among you does not have a sacrificial animal with him, let him exit Ihram and make it ‘Umrah.\" So all the people exited Ihram and cut their hair, except the Prophet (ﷺ) and those who had sacrificial animals with them. Suraqah bin Malik bin Ju’shum stood up and said: \"O Messenger of Allah! Is this for this year only, or forever and ever?\" The Messenger of Allah (ﷺ) interlaced his fingers and said: \"‘Umrah is included in Hajj like this,\" twice. \"No, it is forever and ever.\" ‘Ali brought the camels of the Prophet (ﷺ), and he found that Fatimah was one of those who had exited Ihram. She had put on a dyed garment and used kohl. ‘Ali disliked this action on her part, but she said: \"My father told me to do this.\" ‘Ali used to say in Iraq: \"So I went to the Messenger of Allah (ﷺ), feeling upset with Fatimah because of what she had done, to ask the Messenger of Allah (ﷺ) about what she had said that he said, and that I had disliked that. He said: ‘She spoke the truth, she spoke the truth. What did you say when you began your Hajj?’\" He said: \"I said: ‘O Allah, I begin the Talbiyah for that for which your Messenger (ﷺ) begins the Talbiyah.’ (He said:) ‘And I have the sacrificial animal with me, so do not exit Ihram.’ He said: \"The total number of sacrificial animals that ‘Ali had brought from Yemen and that the Prophet (ﷺ) brought from Al-Madinah were one hundred. Then all the people exited Ihram and cut their hair, apart from the Prophet (ﷺ) and those who had sacrificial animals with them. When the day of Tarwiyah came (the 8th of Dhul-Hijjah), they headed for Mina and began the Talbiyah for Hajj. The Messenger of Allah (ﷺ) rode. He prayed Zuhr, ‘Asr, Maghrib, ‘Isha’ and Fajr at Mina. Then he stayed for a short while until the sun rose, and he ordered that a tent of goat hair be pitched for him in Namirah. Then the Messenger of Allah (ﷺ) set out, and the Quraish were certain that he was going to stay at Al-Mash’ar Haram or at Al-Muzdalifah, as Quraish used to do during the Ignorance days. But the Messenger of Allah (ﷺ) continued until he came to ‘Arafat, where he found that the tent had been pitched for him in Namirah, and he stopped there. Then when the sun had passed its zenith, he called for Qaswa’ and she was saddled for him. He rode until he came to the bottom of the valley, and he addressed the people and said: ‘Your blood and your wealth are sacred to you, as sacred as this day of yours, in this month of yours, in this land of yours. Every matter of Ignorance days is abolished, beneath these two feet of mine. The blood feuds of the Ignorance days are abolished, and the first blood feud of Rabi’ah bin Harith, who was nursed among Banu Sa’d and killed by Hudhail. The usuries of Ignorance days are abolished, and the first usury (that I abolish) is our usury, the usury due to ‘Abbas bin ‘Abdul-Muttalib. It is all abolished. Fear Allah with regard to women, for you have taken them as a trust from Allah, and intimacy with them has become permissible to you through Allah’s Word. Your rights over them are that they should not allow anyone whom you dislike to sit on your bedding.** If they do that, then hit them, but in a manner that does not cause injury or leave a mark. Their rights over you are that you should provide for them and clothe them in a reasonable manner. I have left behind you something which, if you adhere to it, you will never go astray: the Book of Allah. You will be asked about me. What will you say?’ They said: ‘We bear witness that you have conveyed (the message) and fulfilled (your duty) and offered sincere advice.’ He gestured with his forefinger towards the sky and then towards the people, (and said:) ‘O Allah, bear witness, O Allah bear witness,’ three times. Then Bilal called the Adhan, then the Iqamah, and he prayed Zuhr. Then he made Iqamah and prayed ‘Asr, and he did not offer any prayer between them. Then the Messenger of Allah (ﷺ) rode until he came to the place of standing, and he made his she-camel face Sakharat*** with the path in the sand in front of him, and he faced the Qiblah, then he remained standing until the sun had set and the afterglow had lessened somewhat, when the disk of the sun disappeared. Then he seated Usamah bin Zaid behind him and the Messenger of Allah (ﷺ) set out. He pulled Qaswa’s reins tight until her head was touching the saddle, and he gestured with his right hand: ‘O people, calmly, calmly!’ Every time he came to a hill, he released the reins a little so that she could climb. Then he came to Muzdalifah where he prayed Maghrib and ‘Isha’ with one Adhan and two Iqamah, offering no prayer in between. Then the Messenger of Allah (ﷺ) lay down until dawn came, and he prayed Fajr, when he saw that morning had come, with one Adhan and one Iqamah. Then he rode Qaswa’ until he came to Al-Mash’ar Al-Haram. He climbed it and praised Allah and proclaimed His greatness and that He is the only One worthy of worship. Then he remained standing until it had become quite bright, then he moved on before the sun rose. He seated Fadl bin ‘Abbas behind him, who was a man with lovely hair, white and handsome. When the Messenger of Allah (ﷺ) moved on, he passed some women riding camels. Fadl started to look at them, so the Messenger of Allah (ﷺ) put his hand on the other side. Fadl turned his face to the other side to look. When he came to Muhassir, he sped up a little. Then he followed the middle road that brings you out to the biggest Pillar, until he reached the Pillar that is by the tree. He threw seven pebbles, saying the Takbir with each throw, pebbles suitable for Khadhf (i.e., the size of a chickpea) throwing from the bottom of the valley. Then he went to the place of slaughter, and slaughtered sixty-three camels with his own hand. Then he handed it over to ‘Ali who slaughtered the rest, and he gave him a share in his sacrificial animal. Then he ordered that a piece from each camel be brought; (the pieces) were put in a pot and cooked, and they (the Prophet (ﷺ) and ‘Ali) ate from the meat and drank from the soup. Then the Messenger of Allah (ﷺ) hastened to the House, and prayed Zuhr in Makkah. He came to Banu ‘Abdul-Muttalib, who were providing water to the pilgrims at Zamzam, and said: ‘Draw me some water, O Banu ‘Abdul-Muttalib. Were it not that the people would overwhelm you, I would have drawn water with you.’ So they drew up a bucket for him and he drank from it.’\" * It appears that the speaker is Ja’far bin Muhammad who is narrating from his father, from Jabir. **And they say that the meaning if ‘your furniture’ or, ‘your special place’ in which case the objective is to say that the wife is not to admit anyone in the house whom the husband would be displeased with. ***Sakharat plural of Sakhrah rock or boulder. Nawawi said: \"They are the rocks that lay at the base of the Mount of Mercy, and it is the mount in the middle of ‘Arafat.\"","ar":"حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا حَاتِمُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا جَعْفَرُ بْنُ مُحَمَّدٍ، عَنْ أَبِيهِ، قَالَ دَخَلْنَا عَلَى جَابِرِ بْنِ عَبْدِ اللَّهِ فَلَمَّا انْتَهَيْنَا إِلَيْهِ سَأَلَ عَنِ الْقَوْمِ، حَتَّى انْتَهَى إِلَىَّ فَقُلْتُ أَنَا مُحَمَّدُ بْنُ عَلِيِّ بْنِ الْحُسَيْنِ، ‏.‏ فَأَهْوَى بِيَدِهِ إِلَى رَأْسِي فَحَلَّ زِرِّي الأَعْلَى ثُمَّ حَلَّ زِرِّي الأَسْفَلَ ثُمَّ وَضَعَ كَفَّهُ بَيْنَ ثَدْيَىَّ وَأَنَا يَوْمَئِذٍ غُلاَمٌ شَابٌّ فَقَالَ مَرْحَبًا بِكَ سَلْ عَمَّا شِئْتَ ‏.‏ فَسَأَلْتُهُ وَهُوَ أَعْمَى فَجَاءَ وَقْتُ الصَّلاَةِ فَقَامَ فِي نِسَاجَةٍ مُلْتَحِفًا بِهَا كُلَّمَا وَضَعَهَا عَلَى مَنْكِبَيْهِ رَجَعَ طَرَفَاهَا إِلَيْهِ مِنْ صِغَرِهَا وَرِدَاؤُهُ إِلَى جَانِبِهِ عَلَى الْمِشْجَبِ فَصَلَّى بِنَا فَقُلْتُ أَخْبِرْنَا عَنْ حَجَّةِ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ ‏.‏ فَقَالَ بِيَدِهِ فَعَقَدَ تِسْعًا وَقَالَ إِنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ مَكَثَ تِسْعَ سِنِينَ لَمْ يَحُجَّ فَأَذَّنَ فِي النَّاسِ فِي الْعَاشِرَةِ أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ حَاجٌّ فَقَدِمَ الْمَدِينَةَ بَشَرٌ كَثِيرٌ كُلُّهُمْ يَلْتَمِسُ أَنْ يَأْتَمَّ بِرَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ وَيَعْمَلَ بِمِثْلِ عَمَلِهِ فَخَرَجَ وَخَرَجْنَا مَعَهُ فَأَتَيْنَا ذَا الْحُلَيْفَةِ فَوَلَدَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ مُحَمَّدَ بْنَ أَبِي بَكْرٍ فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ كَيْفَ أَصْنَعُ قَالَ ‏\"‏ اغْتَسِلِي وَاسْتَثْفِرِي بِثَوْبٍ وَأَحْرِمِي ‏\"‏ ‏.‏ فَصَلَّى رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ فِي الْمَسْجِدِ ثُمَّ رَكِبَ الْقَصْوَاءَ ‏.‏ حَتَّى إِذَا اسْتَوَتْ بِهِ نَاقَتُهُ عَلَى الْبَيْدَاءِ - قَالَ جَابِرٌ نَظَرْتُ إِلَى مَدِّ بَصَرِي مِنْ بَيْنِ يَدَيْهِ بَيْنَ رَاكِبٍ وَمَاشٍ وَعَنْ يَمِينِهِ مِثْلُ ذَلِكَ وَعَنْ يَسَارِهِ مِثْلُ ذَلِكَ وَمِنْ خَلْفِهِ مِثْلُ ذَلِكَ وَرَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ بَيْنَ أَظْهُرِنَا وَعَلَيْهِ يَنْزِلُ الْقُرْآنُ وَهُوَ يَعْرِفُ تَأْوِيلَهُ مَا عَمِلَ مِنْ شَىْءٍ عَمِلْنَا بِهِ فَأَهَلَّ بِالتَّوْحِيدِ ‏\"‏ لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لاَ شَرِيكَ لَكَ ‏\"‏ ‏.‏ وَأَهَلَّ النَّاسُ بِهَذَا الَّذِي يُهِلُّونَ بِهِ فَلَمْ يَرُدَّ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ عَلَيْهِمْ شَيْئًا مِنْهُ وَلَزِمَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ تَلْبِيَتَهُ ‏.‏ قَالَ جَابِرٌ لَسْنَا نَنْوِي إِلاَّ الْحَجَّ لَسْنَا نَعْرِفُ الْعُمْرَةَ حَتَّى إِذَا أَتَيْنَا الْبَيْتَ مَعَهُ اسْتَلَمَ الرُّكْنَ فَرَمَلَ ثَلاَثًا وَمَشَى أَرْبَعًا ثُمَّ قَامَ إِلَى مَقَامِ إِبْرَاهِيمَ فَقَالَ ‏\"‏ ‏{وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى}‏ ‏\"‏ ‏.‏ فَجَعَلَ الْمَقَامَ بَيْنَهُ وَبَيْنَ الْبَيْتِ فَكَانَ أَبِي يَقُولُ - وَلاَ أَعْلَمُهُ إِلاَّ ذَكَرَهُ عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ - إِنَّهُ كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ ‏{قُلْ يَا أَيُّهَا الْكَافِرُونَ}‏ وَ ‏{قُلْ هُوَ اللَّهُ أَحَدٌ }‏ ‏.‏ ثُمَّ رَجَعَ إِلَى الْبَيْتِ فَاسْتَلَمَ الرُّكْنَ ثُمَّ خَرَجَ مِنَ الْبَابِ إِلَى الصَّفَا حَتَّى إِذَا دَنَا مِنَ الصَّفَا قَرَأَ ‏\"‏ ‏{إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ ‏)‏ ‏.‏ نَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ ‏\"‏ ‏.‏ فَبَدَأَ بِالصَّفَا ‏.‏ فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ فَكَبَّرَ اللَّهَ وَهَلَّلَهُ وَحَمِدَهُ وَقَالَ ‏\"‏ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ ‏\"‏ ‏.‏ ثُمَّ دَعَا بَيْنَ ذَلِكَ وَقَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ ثُمَّ نَزَلَ إِلَى الْمَرْوَةِ فَمَشَى حَتَّى إِذَا انْصَبَّتْ قَدَمَاهُ رَمَلَ فِي بَطْنِ الْوَادِي حَتَّى إِذَا صَعِدَتَا - يَعْنِي قَدَمَاهُ - مَشَى حَتَّى أَتَى الْمَرْوَةَ فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا فَلَمَّا كَانَ آخِرُ طَوَافِهِ عَلَى الْمَرْوَةِ ‏.‏ قَالَ ‏\"‏ لَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ لَمْ أَسُقِ الْهَدْىَ وَجَعَلْتُهَا عُمْرَةً فَمَنْ كَانَ مِنْكُمْ لَيْسَ مَعَهُ هَدْىٌ فَلْيَحْلِلْ وَلْيَجْعَلْهَا عُمْرَةً ‏\"‏ ‏.‏ فَحَلَّ النَّاسُ كُلُّهُمْ وَقَصَّرُوا إِلاَّ النَّبِيَّ ـ صلى الله عليه وسلم ـ وَمَنْ كَانَ مَعَهُ الْهَدْىُ فَقَامَ سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ فَقَالَ يَا رَسُولَ اللَّهِ أَلِعَامِنَا هَذَا أَمْ لأَبَدِ الأَبَدِ قَالَ فَشَبَّكَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ أَصَابِعَهُ فِي الأُخْرَى وَقَالَ ‏\"‏ دَخَلَتِ الْعُمْرَةُ فِي الْحَجِّ هَكَذَا - مَرَّتَيْنِ - لاَ بَلْ لأَبَدِ الأَبَدِ ‏\"‏ ‏.‏ قَالَ وَقَدِمَ عَلِيٌّ بِبُدْنٍ إِلَى النَّبِيِّ ـ صلى الله عليه وسلم ـ ‏.‏ فَوَجَدَ فَاطِمَةَ مِمَّنْ حَلَّ وَلَبِسَتْ ثِيابًا صَبِيغًا وَاكْتَحَلَتْ فَأَنْكَرَ ذَلِكَ عَلَيْهَا عَلِيٌّ فَقَالَتْ أَمَرَنِي أَبِي بِهَذَا ‏.‏ فَكَانَ عَلِيٌّ يَقُولُ بِالْعِرَاقِ فَذَهَبْتُ إِلَى رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ مُحَرِّشًا عَلَى فَاطِمَةَ فِي الَّذِي صَنَعَتْهُ مُسْتَفْتِيًا رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ فِي الَّذِي ذَكَرَتْ عَنْهُ وَأَنْكَرْتُ ذَلِكَ عَلَيْهَا ‏.‏ فَقَالَ ‏\"‏ صَدَقَتْ صَدَقَتْ مَاذَا قُلْتَ حِينَ فَرَضْتَ الْحَجَّ ‏\"‏ ‏.‏ قَالَ قُلْتُ اللَّهُمَّ إِنِّي أُهِلُّ بِمَا أَهَلَّ بِهِ رَسُولُكَ ـ صلى الله عليه وسلم ـ ‏.‏ قَالَ ‏\"‏ فَإِنَّ مَعِيَ الْهَدْىَ فَلاَ تَحِلُّ ‏\"‏ ‏.‏ قَالَ فَكَانَ جَمَاعَةُ الْهَدْىِ الَّذِي جَاءَ بِهِ عَلِيٌّ مِنَ الْيَمَنِ وَالَّذِي أَتَى بِهِ النَّبِيُّ ـ صلى الله عليه وسلم ـ مِنَ الْمَدِينَةِ مِائَةً ثُمَّ حَلَّ النَّاسُ كُلُّهُمْ وَقَصَّرُوا إِلاَّ النَّبِيَّ ـ صلى الله عليه وسلم ـ وَمَنْ كَانَ مَعَهُ هَدْىٌ فَلَمَّا كَانَ يَوْمُ التَّرْوِيَةِ وَتَوَجَّهُوا إِلَى مِنًى أَهَلُّوا بِالْحَجِّ ‏.‏ فَرَكِبَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ فَصَلَّى بِمِنًى الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ وَالصُّبْحَ ثُمَّ مَكَثَ قَلِيلاً حَتَّى طَلَعَتِ الشَّمْسُ وَأَمَرَ بِقُبَّةٍ مِنْ شَعَرٍ فَضُرِبَتْ لَهُ بِنَمِرَةَ فَسَارَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ لاَ تَشُكُّ قُرَيْشٌ إِلاَّ أَنَّهُ وَاقِفٌ عِنْدَ الْمَشْعَرِ الْحَرَامِ أَوِ الْمُزْدَلِفَةِ كَمَا كَانَتْ قُرَيْشٌ تَصْنَعُ فِي الْجَاهِلِيَّةِ فَأَجَازَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ حَتَّى أَتَى عَرَفَةَ فَوَجَدَ الْقُبَّةَ قَدْ ضُرِبَتْ لَهُ بِنَمِرَةَ فَنَزَلَ بِهَا حَتَّى إِذَا زَاغَتِ الشَّمْسُ أَمَرَ بِالْقَصْوَاءِ فَرُحِلَتْ لَهُ فَرَكِبَ حَتَّى أَتَى بَطْنَ الْوَادِي فَخَطَبَ النَّاسَ فَقَالَ ‏\"‏ إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا أَلاَ وَإِنَّ كُلَّ شَىْءٍ مِنْ أَمْرِ الْجَاهِلِيَّةِ مَوْضُوعٌ تَحْتَ قَدَمَىَّ هَاتَيْنِ وَدِمَاءُ الْجَاهِلِيَّةِ مَوْضُوعَةٌ وَأَوَّلُ دَمٍ أَضَعُهُ دَمُ رَبِيعَةَ بْنِ الْحَارِثِ - كَانَ مُسْتَرْضِعًا فِي بَنِي سَعْدٍ فَقَتَلَتْهُ هُذَيْلٌ - وَرِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ وَأَوَّلُ رِبًا أَضَعُهُ رِبَانَا رِبَا الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ فَإِنَّهُ مَوْضُوعٌ كُلُّهُ فَاتَّقُوا اللَّهَ فِي النِّسَاءِ فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانَةِ اللَّهِ وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ وَإِنَّ لَكُمْ عَلَيْهِنَّ أَنْ لاَ يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ وَلَهُنَّ عَلَيْكُمْ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ وَقَدْ تَرَكْتُ فِيكُمْ مَا لَمْ تَضِلُّوا إِنِ اعْتَصَمْتُمْ بِهِ كِتَابَ اللَّهِ وَأَنْتُمْ مَسْئُولُونَ عَنِّي فَمَا أَنْتُمْ قَائِلُونَ ‏\"‏ ‏.‏ قَالُوا نَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ وَأَدَّيْتَ وَنَصَحْتَ ‏.‏ فَقَالَ بِإِصْبَعِهِ السَّبَّابَةِ إِلَى السَّمَاءِ وَيَنْكُبُهَا إِلَى النَّاسِ ‏\"‏ اللَّهُمَّ اشْهَدِ اللَّهُمَّ اشْهَدْ ‏\"‏ ‏.‏ ثَلاَثَ مَرَّاتٍ ثُمَّ أَذَّنَ بِلاَلٌ ثُمَّ أَقَامَ فَصَلَّى الظُّهْرَ ثُمَّ أَقَامَ فَصَلَّى الْعَصْرَ وَلَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا ثُمَّ رَكِبَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ حَتَّى أَتَى الْمَوْقِفَ فَجَعَلَ بَطْنَ نَاقَتِهِ إِلَى الصَّخَرَاتِ وَجَعَلَ حَبْلَ الْمُشَاةِ بَيْنَ يَدَيْهِ وَاسْتَقْبَلَ الْقِبْلَةَ فَلَمْ يَزَلْ وَاقِفًا حَتَّى غَرَبَتِ الشَّمْسُ وَذَهَبَتِ الصُّفْرَةُ قَلِيلاً حَتَّى غَابَ الْقُرْصُ وَأَرْدَفَ أُسَامَةَ بْنَ زَيْدٍ خَلْفَهُ فَدَفَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ وَقَدْ شَنَقَ الْقَصْوَاءَ بِالزِّمَامِ حَتَّى إِنَّ رَأْسَهَا لَيُصِيبُ مَوْرِكَ رَحْلِهِ وَيَقُولُ بِيَدِهِ الْيُمْنَى ‏\"‏ أَيُّهَا النَّاسُ السَّكِينَةَ السَّكِينَةَ ‏\"‏ ‏.‏ كُلَّمَا أَتَى حَبْلاً مِنَ الْحِبَالِ أَرْخَى لَهَا قَلِيلاً حَتَّى تَصْعَدَ ثُمَّ أَتَى الْمُزْدَلِفَةَ فَصَلَّى بِهَا الْمَغْرِبَ وَالْعِشَاءَ بِأَذَانٍ وَاحِدٍ وَإِقَامَتَيْنِ وَلَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا ثُمَّ اضْطَجَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ حَتَّى طَلَعَ الْفَجْرُ فَصَلَّى الْفَجْرَ حِينَ تَبَيَّنَ لَهُ الصُّبْحُ بِأَذَانٍ وَإِقَامَةٍ ثُمَّ رَكِبَ الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَرَقِيَ عَلَيْهِ فَحَمِدَ اللَّهَ وَكَبَّرَهُ وَهَلَّلَهُ فَلَمْ يَزَلْ وَاقِفًا حَتَّى أَسْفَرَ جِدًّا ثُمَّ دَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ وَأَرْدَفَ الْفَضْلَ بْنَ الْعَبَّاسِ وَكَانَ رَجُلاً حَسَنَ الشَّعَرِ أَبْيَضَ وَسِيمًا فَلَمَّا دَفَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ مَرَّ الظُّعُنُ يَجْرِينَ فَطَفِقَ الْفَضْلُ يَنْظُرُ إِلَيْهِنَّ فَوَضَعَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ يَدَهُ مِنَ الشِّقِّ الآخَرِ فَصَرَفَ الْفَضْلُ وَجْهَهُ مِنَ الشِّقِّ الآخَرِ يَنْظُرُ حَتَّى أَتَى مُحَسِّرًا حَرَّكَ قَلِيلاً ثُمَّ سَلَكَ الطَّرِيقَ الْوُسْطَى الَّتِي تُخْرِجُكَ إِلَى الْجَمْرَةِ الْكُبْرَى حَتَّى أَتَى الْجَمْرَةَ الَّتِي عِنْدَ الشَّجَرَةِ فَرَمَى بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ مِنْهَا مِثْلِ حَصَى الْخَذْفِ وَرَمَى مِنْ بَطْنِ الْوَادِي ثُمَّ انْصَرَفَ إِلَى الْمَنْحَرِ فَنَحَرَ ثَلاَثًا وَسِتِّينَ بَدَنَةً بِيَدِهِ وَأَعْطَى عَلِيًّا فَنَحَرَ مَا غَبَرَ وَأَشْرَكَهُ فِي هَدْيِهِ ثُمَّ أَمَرَ مِنْ كُلِّ بَدَنَةٍ بِبَضْعَةٍ فَجُعِلَتْ فِي قِدْرٍ فَطُبِخَتْ فَأَكَلاَ مِنْ لَحْمِهَا وَشَرِبَا مِنْ مَرَقِهَا ثُمَّ أَفَاضَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ إِلَى الْبَيْتِ فَصَلَّى بِمَكَّةَ الظُّهْرَ فَأَتَى بَنِي عَبْدِ الْمُطَّلِبِ وَهُمْ يَسْقُونَ عَلَى زَمْزَمَ فَقَالَ ‏\"‏ انْزِعُوا بَنِي عَبْدِ الْمُطَّلِبِ لَوْلاَ أَنْ يَغْلِبَكُمُ النَّاسُ عَلَى سِقَايَتِكُمْ لَنَزَعْتُ مَعَكُمْ ‏\"‏ ‏.‏ فَنَاوَلُوهُ دَلْوًا فَشَرِبَ مِنْهُ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1277a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1277a","x":"Hisham b. 'Urwa reported on the authority of his father who narrated from 'A'isha. He said to 'A'isha:\n\nI think if a person does not run between al- Safa' and al-Marwa, It does not do any harm to him (so far as Hajj is concerned). She said: Why (do you think so)? I said: For Allah says:\" Verily al-Safa' and al-Marwa are among the Signs of Allah\" (ii. 158) (to the end of the verse), whereupon she said: Allah does not complete the Hajj of a person or his Umra if he does not observe Sa'i between al-Safa' and al-marwa; and if it were so as you state, then (the wording would have been (fala janah an la yatufu biha) [\" There is no harm for him if he does not circumambulate between them']. Do you know in what context (this verse was revealed)? (It was revealed in this context) that the Ansar in the Days of Ignorance pronounced the Talbiya for two idols. (fixedl on the bank of the river which were called Isaf and Na'ila. The people went there, and then circumambulated between al-Safa' and al-Marwa and then got their heads shaved. With the advent of Islam they (the Muslims) did not like to circumambulate between them as they used to do during the Days of Ignorance. It was on account of this that Allah. the Exalted and Majestic, revealed:\" Verily al-Safe and al-Marwa are among the Signs of Allah\" to the end of the verse. She said: Then people began to observe Sa'i.","ar":"حَدَّثَنَا يَحْيَى بْنُ يَحْيَى، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَ قُلْتُ لَهَا إِنِّي لأَظُنُّ رَجُلاً لَوْ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ مَا ضَرَّهُ ‏.‏ قَالَتْ لِمَ قُلْتُ لأَنَّ اللَّهَ تَعَالَى يَقُولُ ‏{‏ إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ‏}‏ إِلَى آخِرِ الآيَةِ ‏.‏ فَقَالَتْ مَا أَتَمَّ اللَّهُ حَجَّ امْرِئٍ وَلاَ عُمْرَتَهُ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ وَلَوْ كَانَ كَمَا تَقُولُ لَكَانَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ لاَ يَطَّوَّفَ بِهِمَا ‏.‏ وَهَلْ تَدْرِي فِيمَا كَانَ ذَاكَ إِنَّمَا كَانَ ذَاكَ أَنَّ الأَنْصَارَ كَانُوا يُهِلُّونَ فِي الْجَاهِلِيَّةِ لِصَنَمَيْنِ عَلَى شَطِّ الْبَحْرِ يُقَالُ لَهُمَا إِسَافٌ وَنَائِلَةٌ ‏.‏ ثُمَّ يَجِيئُونَ فَيَطُوفُونَ بَيْنَ الصَّفَا وَالْمَرْوَةِ ثُمَّ يَحْلِقُونَ ‏.‏ فَلَمَّا جَاءَ الإِسْلاَمُ كَرِهُوا أَنْ يَطُوفُوا بَيْنَهُمَا لِلَّذِي كَانُوا يَصْنَعُونَ فِي الْجَاهِلِيَّةِ قَالَتْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ‏ {‏ إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ‏}‏ إِلَى آخِرِهَا - قَالَتْ - فَطَافُوا ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2965","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2965","x":"Narrated Az-Zuhri:\n\nthat 'Urqah said: \"I said to 'Aishah: 'I do not see anything wrong if someone does not go between As-Safa and Al-Marwah, nor any harm if I do not go between them.' She said: 'How horrible is what you have said O my nephew! The Messenger of Allah (ﷺ) would go between them, and the Muslims go between them. It was only that the people who assumed Ihram in the name of the false deity Mannah, which was in Al-Mushallal, would not go between As-Safa and Al-Marwah. So, Allah Blessed and Most High revealed: So it is not a sin for those who perform Hajj or go 'Umrah to the House to go between them (2:158). And if it were as you say, then it would be: \"Then there is no harm on him if he does not go between them.\" Az-Zuhri said: \"I mentioned that to Abu Bakr bin 'Abdur-Rahman bin Al-Harith bin Hisham. He was surprised at that and he said: 'Indeed this is knowledge. I had heard some men among the people of knowledge saying that those Arabs who would not go between As-Safa and Al-Marwah said, that going between these two rocks is a matter from Jahiliyyah. And others among the Ansar said: \"We have only been ordered with going around the House, we were not ordered to do so with As-Safa and Al-Marwah.\" So Allah Most High revealed: Indeed As-Safa and Al-Marwah are of the symbols of Allah...' (2.158) Abu Bakr bin 'Abdur-Rahman said: 'So I thought that it was revealed about these people, and those people.'\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، قَالَ سَمِعْتُ الزُّهْرِيَّ، يُحَدِّثُ عَنْ عُرْوَةَ، قَالَ قُلْتُ لِعَائِشَةَ مَا أَرَى عَلَى أَحَدٍ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ شَيْئًا وَمَا أُبَالِي أَنْ لاَ أَطَّوَّفَ بَيْنَهُمَا ‏.‏ فَقَالَتْ بِئْسَمَا قُلْتَ يَا ابْنَ أُخْتِي طَافَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَطَافَ الْمُسْلِمُونَ وَإِنَّمَا كَانَ مَنْ أَهَلَّ لِمَنَاةَ الطَّاغِيَةِ الَّتِي بِالْمُشَلَّلِ لاَ يَطُوفُونَ بَيْنَ الصَّفَا وَالْمَرْوَةِ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا ‏)‏ وَلَوْ كَانَتْ كَمَا تَقُولُ لَكَانَتْ فَلاَ جُنَاحَ عَلَيْهِ أَنْ لاَ يَطَّوَّفَ بِهِمَا قَالَ الزُّهْرِيُّ فَذَكَرْتُ ذَلِكَ لأَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ فَأَعْجَبَهُ ذَلِكَ وَقَالَ إِنَّ هَذَا لَعِلْمٌ وَلَقَدْ سَمِعْتُ رِجَالاً مِنْ أَهْلِ الْعِلْمِ يَقُولُونَ إِنَّمَا كَانَ مَنْ لاَ يَطَّوَّفُ بَيْنَ الصَّفَا وَالْمَرْوَةِ مِنَ الْعَرَبِ يَقُولُونَ إِنَّ طَوَافَنَا بَيْنَ هَذَيْنِ الْحَجَرَيْنِ مِنْ أَمْرِ الْجَاهِلِيَّةِ وَقَالَ آخَرُونَ مِنَ الأَنْصَارِ إِنَّمَا أُمِرْنَا بِالطَّوَافِ بِالْبَيْتِ وَلَمْ نُؤْمَرْ بِهِ بَيْنَ الصَّفَا وَالْمَرْوَةِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏(‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ ‏)‏ قَالَ أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ فَأُرَاهَا قَدْ نَزَلَتْ فِي هَؤُلاَءِ وَهَؤُلاَءِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2966","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2966","x":"Narrated 'Asim Al-Ahwal:\n\n\"I asked Anas bin Malik about As-Safa and Al-Marwah, and he said: 'They were among the rites of Jahiliyyah.' He said: 'So during Islam, we refrained from them, then Allah, Blessed and Most High, revealed: Indeed As-Safa and Al-Marwah are of the symbols of Allah. So it is not a sin for those who perform Hajj or 'Umrah to the house to go between them. (2:158)' He said: 'So it is voluntarily then verily, Allah is the All-Recogniser, the All-Knowing. (2:158)'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا يَزِيدُ بْنُ أَبِي حَكِيمٍ، عَنْ سُفْيَانَ، عَنْ عَاصِمٍ الأَحْوَلِ، قَالَ سَأَلْتُ أَنَسَ بْنَ مَالِكٍ عَنِ الصَّفَا، وَالْمَرْوَةِ، فَقَالَ كَانَا مِنْ شَعَائِرِ الْجَاهِلِيَّةِ فَلَمَّا كَانَ الإِسْلاَمُ أَمْسَكْنَا عَنْهُمَا فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلاَ جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا ‏)‏ قَالَ هُمَا تَطَوُّعٌ ‏(‏فَمَنْ تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2967","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2967","x":"Narrated Jabir bin 'Abdullah:\n\n\"When the Messenger of Allah (ﷺ) arrived in Makkah, performing Tawaf around the House seven times, I heard him reciting: And take the Maqam of Ibrahim as a place of prayer (2:125). So he performed Salat behind the Maqam, then he came to the (Black) Stone, then he said: 'We begin with what Allah began with.' So he began at As-Safa and recited: Indeed As-Safa and Al-Marwah are among the Symbols of Allah (2:158).\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم حِينَ قَدِمَ مَكَّةَ طَافَ بِالْبَيْتِ سَبْعًا فَقَرَأَ ‏:‏ ‏(‏وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى ‏)‏ فَصَلَّى خَلْفَ الْمَقَامِ ثُمَّ أَتَى الْحَجَرَ فَاسْتَلَمَهُ ثُمَّ قَالَ ‏\"‏ نَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ ‏\"‏ ‏.‏ وَقَرَأَ ‏:‏ ‏(‏إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"159":[{"c":"Sahih Bukhari","r":"Hadith 118","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-118","x":"Narrated Abu Huraira:\n\nPeople say that I have narrated many Hadiths (The Prophet's narration). Had it not been for two verses in the Qur'an, I would not have narrated a single Hadith, and the verses are: \"Verily those who conceal the clear sign and the guidance which We have sent down... (up to) Most Merciful.\" (2:159-160). And no doubt our Muhajir (emigrant) brothers used to be busy in the market with their business (bargains) and our Ansari brothers used to be busy with their property (agriculture). But I (Abu Huraira) used to stick to Allah's Messenger (ﷺ) contented with what will fill my stomach and I used to attend that which they used not to attend and I used to memorize that which they used not to memorize.","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنِي مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ إِنَّ النَّاسَ يَقُولُونَ أَكْثَرَ أَبُو هُرَيْرَةَ، وَلَوْلاَ آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُ حَدِيثًا، ثُمَّ يَتْلُو ‏{‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ‏}‏ إِلَى قَوْلِهِ ‏{‏الرَّحِيمُ‏}‏ إِنَّ إِخْوَانَنَا مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمُ الصَّفْقُ بِالأَسْوَاقِ، وِإِنَّ إِخْوَانَنَا مِنَ الأَنْصَارِ كَانَ يَشْغَلُهُمُ الْعَمَلُ فِي أَمْوَالِهِمْ، وَإِنَّ أَبَا هُرَيْرَةَ كَانَ يَلْزَمُ رَسُولَ اللَّهِ صلى الله عليه وسلم بِشِبَعِ بَطْنِهِ وَيَحْضُرُ مَا لاَ يَحْضُرُونَ، وَيَحْفَظُ مَا لاَ يَحْفَظُونَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 160","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-160","x":"After performing the ablution 'Uthman said, \"I am going to tell you a Hadith which I would not have told you, had I not been compelled by a certain Holy Verse (the sub narrator 'Urwa said:\n\nThis verse is: \"Verily, those who conceal the clear signs and the guidance which we have sent down...)\" (2:159). I heard the Prophet (ﷺ) saying, 'If a man performs ablution perfectly and then offers the compulsory congregational prayer, Allah will forgive his sins committed between that (prayer) and the (next) prayer till he offers it.","ar":"وَعَنْ إِبْرَاهِيمَ، قَالَ قَالَ صَالِحُ بْنُ كَيْسَانَ قَالَ ابْنُ شِهَابٍ وَلَكِنْ عُرْوَةُ يُحَدِّثُ عَنْ حُمْرَانَ،، فَلَمَّا تَوَضَّأَ عُثْمَانُ قَالَ أَلاَ أُحَدِّثُكُمْ حَدِيثًا لَوْلاَ آيَةٌ مَا حَدَّثْتُكُمُوهُ، سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\"‏ لاَ يَتَوَضَّأُ رَجُلٌ فَيُحْسِنُ وُضُوءَهُ، وَيُصَلِّي الصَّلاَةَ إِلاَّ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلاَةِ حَتَّى يُصَلِّيَهَا ‏\"‏‏.‏ قَالَ عُرْوَةُ الآيَةُ ‏{‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2350","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2350","x":"Narrated Abu Huraira:\n\nThe people say that Abu Huraira narrates too many narrations. In fact Allah knows whether I say the truth or not. They also ask, \"Why do the emigrants and the Ansar not narrate as he does?\" In fact, my emigrant brethren were busy trading in the markets, and my Ansar brethren were busy with their properties. I was a poor man keeping the company of Allah's Messenger (ﷺ) and was satisfied with what filled my stomach. So, I used to be present while they (i.e. the emigrants and the Ansar) were absent, and I used to remember while they forgot (the Hadith). One day the Prophet (ﷺ) said, \"Whoever spreads his sheet till I finish this statement of mine and then gathers it on his chest, will never forget anything of my statement.\" So, I spread my covering sheet which was the only garment I had, till the Prophet (ﷺ) finished his statement and then I gathered it over my chest. By Him Who had sent him (i.e. Allah's Apostle) with the truth, since then I did not forget even a single word of that statement of his, until this day of mine. By Allah, but for two verses in Allah's Book, I would never have related any narration (from the Prophet). (These two verses are): \"Verily! Those who conceal the clear signs and the guidance which we have sent down.....(up to) the Merciful.' (2.159-160)","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنِ ابْنِ شِهَابٍ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ يَقُولُونَ إِنَّ أَبَا هُرَيْرَةَ يُكْثِرُ الْحَدِيثَ‏.‏ وَاللَّهُ الْمَوْعِدُ، وَيَقُولُونَ مَا لِلْمُهَاجِرِينَ وَالأَنْصَارِ لاَ يُحَدِّثُونَ مِثْلَ أَحَادِيثِهِ وَإِنَّ إِخْوَتِي مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمُ الصَّفْقُ بِالأَسْوَاقِ، وَإِنَّ إِخْوَتِي مِنَ الأَنْصَارِ كَانَ يَشْغَلُهُمْ عَمَلُ أَمْوَالِهِمْ، وَكُنْتُ امْرَأً مِسْكِينًا أَلْزَمُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى مِلْءِ بَطْنِي، فَأَحْضُرُ حِينَ يَغِيبُونَ وَأَعِي حِينَ يَنْسَوْنَ، وَقَالَ النَّبِيُّ صلى الله عليه وسلم يَوْمًا ‏\"‏ لَنْ يَبْسُطَ أَحَدٌ مِنْكُمْ ثَوْبَهُ حَتَّى أَقْضِيَ مَقَالَتِي هَذِهِ، ثُمَّ يَجْمَعَهُ إِلَى صَدْرِهِ، فَيَنْسَى مِنْ مَقَالَتِي شَيْئًا أَبَدًا ‏\"‏‏.‏ فَبَسَطْتُ نَمِرَةً لَيْسَ عَلَىَّ ثَوْبٌ غَيْرَهَا، حَتَّى قَضَى النَّبِيُّ صلى الله عليه وسلم مَقَالَتَهُ، ثُمَّ جَمَعْتُهَا إِلَى صَدْرِي، فَوَالَّذِي بَعَثَهُ بِالْحَقِّ مَا نَسِيتُ مِنْ مَقَالَتِهِ تِلْكَ إِلَى يَوْمِي هَذَا، وَاللَّهِ لَوْلاَ آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمْ شَيْئًا أَبَدًا ‏{‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ‏}‏ إِلَى قَوْلِهِ ‏{‏الرَّحِيمُ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2492c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2492c","x":"Ibn Shihab transmitted on the authority of Ibn Musayyib that Abu Huraira said:\n\nPeople say that Abu Huraira transmits so many ahadith, whereas Allah is the Reckoner, and they say: How is it with Muhajirs and the Ansar that they do not narrate ahadith like him (like Abu Huraira)? Abu Huraira said: I tell you that my brothers from Ansar remained busy with their lands and my brothers Muhajirs were busy in transactions in the bazars, but I always kept myself attached to Allah's Messenger (ﷺ) with bare subsistence. I remained present (in the company of the Holy Prophet), whereas they had been absent. I retained in my mind (what the Prophet said), whereas they forgot it. One day Allah's Messenger (ﷺ) said: He who amongst you spreads the cloth and listens to my talk and would then press it against his chest would never forget anything heard from me. So I spread my mantle and when he had concluded his talk I then pressed it against my chest and so I never forgot after that day anything that he (the Holy Prophet) said. And if these two verses would not have been revealed in the Book I would have never transmitted anything (to anybody):\" Those who conceal the clear evidence and the guidance that We revealed\" (ii. 159) tip to the last verse.","ar":"قَالَ ابْنُ شِهَابٍ وَقَالَ ابْنُ الْمُسَيَّبِ إِنَّ أَبَا هُرَيْرَةَ قَالَ يَقُولُونَ إِنَّ أَبَا هُرَيْرَةَ قَدْ أَكْثَرَ وَاللَّهُ الْمَوْعِدُ وَيَقُولُونَ مَا بَالُ الْمُهَاجِرِينَ وَالأَنْصَارِ لاَ يَتَحَدَّثُونَ مِثْلَ أَحَادِيثِهِ وَسَأُخْبِرُكُمْ عَنْ ذَلِكَ إِنَّ إِخْوَانِي مِنَ الأَنْصَارِ كَانَ يَشْغَلُهُمْ عَمَلُ أَرَضِيهِمْ وَإِنَّ إِخْوَانِي مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمُ الصَّفْقُ بِالأَسْوَاقِ وَكُنْتُ أَلْزَمُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى مِلْءِ بَطْنِي فَأَشْهَدُ إِذَا غَابُوا وَأَحْفَظُ إِذَا نَسُوا وَلَقَدْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَوْمًا ‏\"‏ أَيُّكُمْ يَبْسُطُ ثَوْبَهُ فَيَأْخُذُ مِنْ حَدِيثِي هَذَا ثُمَّ يَجْمَعُهُ إِلَى صَدْرِهِ فَإِنَّهُ لَمْ يَنْسَ شَيْئًا سَمِعَهُ ‏\"‏ ‏.‏ فَبَسَطْتُ بُرْدَةً عَلَىَّ حَتَّى فَرَغَ مِنْ حَدِيثِهِ ثُمَّ جَمَعْتُهَا إِلَى صَدْرِي فَمَا نَسِيتُ بَعْدَ ذَلِكَ الْيَوْمِ شَيْئًا حَدَّثَنِي بِهِ وَلَوْلاَ آيَتَانِ أَنْزَلَهُمَا اللَّهُ فِي كِتَابِهِ مَا حَدَّثْتُ شَيْئًا أَبَدًا ‏{‏ إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى‏}‏ إِلَى آخِرِ الآيَتَيْنِ ‏.‏","v":[]}],"160":[{"c":"Sahih Bukhari","r":"Hadith 118","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-118","x":"Narrated Abu Huraira:\n\nPeople say that I have narrated many Hadiths (The Prophet's narration). Had it not been for two verses in the Qur'an, I would not have narrated a single Hadith, and the verses are: \"Verily those who conceal the clear sign and the guidance which We have sent down... (up to) Most Merciful.\" (2:159-160). And no doubt our Muhajir (emigrant) brothers used to be busy in the market with their business (bargains) and our Ansari brothers used to be busy with their property (agriculture). But I (Abu Huraira) used to stick to Allah's Messenger (ﷺ) contented with what will fill my stomach and I used to attend that which they used not to attend and I used to memorize that which they used not to memorize.","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنِي مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ إِنَّ النَّاسَ يَقُولُونَ أَكْثَرَ أَبُو هُرَيْرَةَ، وَلَوْلاَ آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُ حَدِيثًا، ثُمَّ يَتْلُو ‏{‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ‏}‏ إِلَى قَوْلِهِ ‏{‏الرَّحِيمُ‏}‏ إِنَّ إِخْوَانَنَا مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمُ الصَّفْقُ بِالأَسْوَاقِ، وِإِنَّ إِخْوَانَنَا مِنَ الأَنْصَارِ كَانَ يَشْغَلُهُمُ الْعَمَلُ فِي أَمْوَالِهِمْ، وَإِنَّ أَبَا هُرَيْرَةَ كَانَ يَلْزَمُ رَسُولَ اللَّهِ صلى الله عليه وسلم بِشِبَعِ بَطْنِهِ وَيَحْضُرُ مَا لاَ يَحْضُرُونَ، وَيَحْفَظُ مَا لاَ يَحْفَظُونَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2350","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2350","x":"Narrated Abu Huraira:\n\nThe people say that Abu Huraira narrates too many narrations. In fact Allah knows whether I say the truth or not. They also ask, \"Why do the emigrants and the Ansar not narrate as he does?\" In fact, my emigrant brethren were busy trading in the markets, and my Ansar brethren were busy with their properties. I was a poor man keeping the company of Allah's Messenger (ﷺ) and was satisfied with what filled my stomach. So, I used to be present while they (i.e. the emigrants and the Ansar) were absent, and I used to remember while they forgot (the Hadith). One day the Prophet (ﷺ) said, \"Whoever spreads his sheet till I finish this statement of mine and then gathers it on his chest, will never forget anything of my statement.\" So, I spread my covering sheet which was the only garment I had, till the Prophet (ﷺ) finished his statement and then I gathered it over my chest. By Him Who had sent him (i.e. Allah's Apostle) with the truth, since then I did not forget even a single word of that statement of his, until this day of mine. By Allah, but for two verses in Allah's Book, I would never have related any narration (from the Prophet). (These two verses are): \"Verily! Those who conceal the clear signs and the guidance which we have sent down.....(up to) the Merciful.' (2.159-160)","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنِ ابْنِ شِهَابٍ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ يَقُولُونَ إِنَّ أَبَا هُرَيْرَةَ يُكْثِرُ الْحَدِيثَ‏.‏ وَاللَّهُ الْمَوْعِدُ، وَيَقُولُونَ مَا لِلْمُهَاجِرِينَ وَالأَنْصَارِ لاَ يُحَدِّثُونَ مِثْلَ أَحَادِيثِهِ وَإِنَّ إِخْوَتِي مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمُ الصَّفْقُ بِالأَسْوَاقِ، وَإِنَّ إِخْوَتِي مِنَ الأَنْصَارِ كَانَ يَشْغَلُهُمْ عَمَلُ أَمْوَالِهِمْ، وَكُنْتُ امْرَأً مِسْكِينًا أَلْزَمُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى مِلْءِ بَطْنِي، فَأَحْضُرُ حِينَ يَغِيبُونَ وَأَعِي حِينَ يَنْسَوْنَ، وَقَالَ النَّبِيُّ صلى الله عليه وسلم يَوْمًا ‏\"‏ لَنْ يَبْسُطَ أَحَدٌ مِنْكُمْ ثَوْبَهُ حَتَّى أَقْضِيَ مَقَالَتِي هَذِهِ، ثُمَّ يَجْمَعَهُ إِلَى صَدْرِهِ، فَيَنْسَى مِنْ مَقَالَتِي شَيْئًا أَبَدًا ‏\"‏‏.‏ فَبَسَطْتُ نَمِرَةً لَيْسَ عَلَىَّ ثَوْبٌ غَيْرَهَا، حَتَّى قَضَى النَّبِيُّ صلى الله عليه وسلم مَقَالَتَهُ، ثُمَّ جَمَعْتُهَا إِلَى صَدْرِي، فَوَالَّذِي بَعَثَهُ بِالْحَقِّ مَا نَسِيتُ مِنْ مَقَالَتِهِ تِلْكَ إِلَى يَوْمِي هَذَا، وَاللَّهِ لَوْلاَ آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمْ شَيْئًا أَبَدًا ‏{‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ‏}‏ إِلَى قَوْلِهِ ‏{‏الرَّحِيمُ‏}‏","v":[]}],"163":[{"c":"Sunan Ibn Majah","r":"Volume 4, Book 31, Hadith 3549","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-31/Hadith-3549","x":"It was narrated from ‘Abdur-Rahman bin Abi Laila that his father Abu Laila said:\n\n\"I was sitting with the Prophet (ﷺ) when a Bedouin came to him and said: ‘I have a brother who is sick.’ He said: ‘What is the matter with your brother?’ He said: ‘He suffers from a slight mental derangement.’ He said: ‘Go and bring him.’\" He said: \"(So he went) and he brought him. He made him sit down in front of him and I heard him seeking refuge for him with Fatihatil-Kitab; four Verses from the beginning of Al-Baqarah, two Verses from its middle: ‘And your Ilah (God) is One Ilah (God – Allah),’ [2:163] and Ayat Al-Kursi; and three Verses from its end; a Verse from Al ‘Imran, I think it was: ‘Allah bears witness that La ilaha illa Huwa (none has the right to be worshipped but He),’ [3:18] a Verse from Al-A’raf: ‘Indeed, your Lord is Allah,’ [7:54] a Verse from Al-Mu’minun: ‘And whoever invokes (or worships), besides Allah, any other ilah (god), of whom he has no proof,’[23:117] a Verse from Al-Jinn: ‘And He, exalted is the Majesty of our Lord,’ [72:3] ten Verses from the beginning of As-Saffat; three Verses from the end of Al-Hashr; (then) ‘Say: He is Allah, (the) One,’ [112:1] and Al-Mu’awwidhatain. Then the Bedouin stood up, healed, and there was nothing wrong with him.\"","ar":"حَدَّثَنَا هَارُونُ بْنُ حَيَّانَ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى، أَنْبَأَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، حَدَّثَنَا أَبُو جَنَابٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ أَبِيهِ أَبِي لَيْلَى، قَالَ كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ـ صلى الله عليه وسلم ـ إِذْ جَاءَهُ أَعْرَابِيٌّ فَقَالَ إِنَّ لِي أَخًا وَجِعًا ‏.‏ قَالَ ‏\"‏ مَا وَجَعُ أَخِيكَ ‏\"‏ ‏.‏ قَالَ بِهِ لَمَمٌ ‏.‏ قَالَ ‏\"‏ اذْهَبْ فَأْتِنِي بِهِ ‏\"‏ ‏.‏ قَالَ فَذَهَبَ فَجَاءَ بِهِ فَأَجْلَسَهُ بَيْنَ يَدَيْهِ فَسَمِعْتُهُ عَوَّذَهُ بِفَاتِحَةِ الْكِتَابِ وَأَرْبَعِ آيَاتٍ مِنْ أَوَّلِ الْبَقَرَةِ وَآيَتَيْنِ مِنْ وَسَطِهَا وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ وَآيَةِ الْكُرْسِيِّ وَثَلاَثِ آيَاتٍ مِنْ خَاتِمَتِهَا وَآيَةٍ مِنْ آلِ عِمْرَانَ - أَحْسِبُهُ قَالَ ‏{شَهِدَ اللَّهُ أَنَّهُ لاَ إِلَهَ إِلاَّ هُوَ}‏ - وَآيَةٍ مِنَ الأَعْرَافِ ‏{إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ}‏ الآيَةَ وَآيَةٍ مِنَ الْمُؤْمِنِينَ ‏{وَمَنْ يَدْعُ مَعَ اللَّهِ إِلهًا آخَرَ لاَ بُرْهَانَ لَهُ بِهِ }‏ وَآيَةٍ مِنَ الْجِنِّ ‏{وَأَنَّهُ تَعَالَى جَدُّ رِبِّنَا مَا اتَّخَذَ صَاحِبَةً وَلاَ وَلَدًا}‏ وَعَشْرِ آيَاتٍ مِنْ أَوَّلِ الصَّافَّاتِ وَثَلاَثِ آيَاتٍ مِنْ آخِرِ الْحَشْرِ وَ ‏{قُلْ هُوَ اللَّهُ أَحَدٌ }‏ وَالْمُعَوِّذَتَيْنِ ‏.‏ فَقَامَ الأَعْرَابِيُّ قَدْ بَرَأَ لَيْسَ بِهِ بَأْسٌ ‏.‏","v":[]}],"172":[{"c":"Sahih Muslim","r":"Hadith 1015","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1015","x":"Abu Huraira reported Allah's Messenger (ﷺ) as saying:\n\nO people, Allah is Good and He therefore, accepts only that which is good. And Allah commanded the believers as He commanded the Messengers by saying: \"O Messengers, eat of the good things, and do good deeds; verily I am aware of what you do\" (xxiii. 51). And He said: \"O those who believe, eat of the good things that We gave you\" (ii. 172). He then made a mention of a person who travels widely, his hair disheveled and covered with dust. He lifts his hand towards the sky (and thus makes the supplication): \"O Lord, O Lord,\" whereas his diet is unlawful, his drink is unlawful, and his clothes are unlawful and his nourishment is unlawful. How can then his supplication be accepted?","ar":"وَحَدَّثَنِي أَبُو كُرَيْبٍ، مُحَمَّدُ بْنُ الْعَلاَءِ حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا فُضَيْلُ بْنُ مَرْزُوقٍ، حَدَّثَنِي عَدِيُّ بْنُ ثَابِتٍ، عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَيُّهَا النَّاسُ إِنَّ اللَّهَ طَيِّبٌ لاَ يَقْبَلُ إِلاَّ طَيِّبًا وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ ‏{‏ يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ‏}‏ وَقَالَ ‏{‏ يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ‏}‏ ‏\"‏ ‏.‏ ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ يَا رَبِّ يَا رَبِّ وَمَطْعَمُهُ حَرَامٌ وَمَشْرَبُهُ حَرَامٌ وَمَلْبَسُهُ حَرَامٌ وَغُذِيَ بِالْحَرَامِ فَأَنَّى يُسْتَجَابُ لِذَلِكَ ‏\"‏ ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 1851","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-1851","x":"Abu Hurairah (May Allah be pleased with him) said:\n\nThe Messenger of Allah (ﷺ) said, \"O people! Allah is Pure and, therefore, accepts only that which is pure. Allah has commanded the believers as He has commanded His Messengers by saying: 'O Messengers! Eat of the good things, and do good deeds.' (23:51) And He said: 'O you who believe (in the Oneness of Allah - Islamic Monotheism)! Eat of the lawful things that We have provided you...\"' (2:172). Then he (ﷺ) made a mention of the person who travels for a long period of time, his hair are dishevelled and covered with dust. He lifts his hand towards the sky and thus makes the supplication: 'My Rubb! My Rubb!' But his food is unlawful, his drink is unlawful, his clothes are unlawful and his nourishment is unlawful, how can, then his supplication be accepted?\"[Muslim].","ar":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\n\"‏يا أيها الناس إن الله طيب لا يقبل إلا طيباً، وإن الله أمر المؤمنين بما أمر به المرسلين، فقال تعالى‏:‏ ‏{‏يا أيها الرسل كلوا من الطيباب واعلموا صالحاً‏}‏، وقال تعالى‏:‏ ‏{‏يا أيها الذين آمنوا كلوا من طيبات ما رزقناكم‏}‏ ثم ذكر الرجل يطيل السفر أشعث أغبر يمد يديه إلى السماء ‏:‏ يا رب يارب، ومطعمه حرام، ومشربه حرام، وملبسه حرام، وغذي بالحرام فأنى يستجاب لذلك‏!‏‏؟‏‏\"\n\n‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2989","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2989","x":"Narrated Abu Hurairah:\n\nthat the Messenger of Allah (ﷺ) said: \"O you people! Indeed Allah is Tayyib (good) and he does not accept but what is good. And indeed Allah ordered the believers with what He ordered the Messengers. He (ﷺ) said: 'O you Messengers! Eat of the good things and do righteous deeds. Verily I am well acquainted with what you do (23:51).' And He said: 'O you who believe! Eat from the good things We have provided you (2:172).' He said: \"And he mentioned a man: 'Who is undertaking a long journey, whose hair is dishevelled and he is covered with dust. He raises his hands to the heavens and says: \"O Lord! O Lord!\" Yet his food is from the unlawful, his drink is from the unlawful, his clothing is from the unlawful, and he was nourished by the unlawful. So how can that be accepted?'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا فُضَيْلُ بْنُ مَرْزُوقٍ، عَنْ عَدِيِّ بْنِ ثَابِتٍ، عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أَيُّهَا النَّاسُ إِنَّ اللَّهَ طَيِّبٌ وَلاَ يَقْبَلُ إِلاَّ طَيِّبًا وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ ‏:‏ ‏(‏يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ ‏)‏ وَقَالَ أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ ‏)‏ ‏\"‏ ‏.‏ قَالَ \"وَذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَهُ إِلَى السَّمَاءِ يَا رَبِّ يَا رَبِّ وَمَطْعَمُهُ حَرَامٌ وَمَشْرَبُهُ حَرَامٌ وَمَلْبَسُهُ حَرَامٌ وَغُذِيَ بِالْحَرَامِ فَأَنَّى يُسْتَجَابُ لِذَلِكَ \"‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ وَإِنَّمَا نَعْرِفُهُ مِنْ حَدِيثِ فُضَيْلِ بْنِ مَرْزُوقٍ وَأَبُو حَازِمٍ هُوَ الأَشْجَعِيُّ اسْمُهُ سَلْمَانُ مَوْلَى عَزَّةَ الأَشْجَعِيَّةِ ‏.‏","v":[]}],"176":[{"c":"Muwatta Malik","r":"Book 58, Hadith 1845","u":"https://quranx.com/Hadith/Malik/In-Book/Book-58/Hadith-1845","x":"Malik related to me that Ishaq ibn Abdullah ibn Abi Talha heard Anas ibn Malik say, \"Abu Talha had the greatest amount of property in palm-trees among the Ansar in Madina. The dearest of his properties to him was Bayruha which was in front of the mosque. The Messenger of Allah, may Allah bless him and grant him peace, used to go into it and drink from the pleasant water which was in it.\" Anas continued, \"When this ayat was sent down 'You will not obtain rightness of action until you expend of what you love,' (Sura 2 ayat l76), Abu Talha went to the Messenger of Allah, may Allah bless him and grant him peace, and said, 'Messenger of Allah! Allah, the Blessed, the Exalted, has said, \"You will not obtain until you expend of what you love.\" The property which I love the best is Bayruha. It is sadaqa for Allah. I hope for its good and for it to be stored up with Allah. Place it wherever you wish, Messengerof Allah. ' \" \"The Messenger of Allah, may Allah bless him and grant him peace, said, 'Well done! That is property which profits! That is property which profits. I have heard what you have said about it and I think that you should give it to your relatives.' Abu Talha said, 'I will do it, Messenger of Allah!' Abu Talha therefore divided it among his relatives and the children of his paternal uncle.\"","ar":"وَحَدَّثَنِي مَالِكٌ، عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ، أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ كَانَ أَبُو طَلْحَةَ أَكْثَرَ أَنْصَارِيٍّ بِالْمَدِينَةِ مَالاً مِنْ نَخْلٍ وَكَانَ أَحَبُّ أَمْوَالِهِ إِلَيْهِ بَيْرُحَاءَ وَكَانَتْ مُسْتَقْبِلَةَ الْمَسْجِدِ وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدْخُلُهَا وَيَشْرَبُ مِنْ مَاءٍ فِيهَا طَيِّبٍ قَالَ أَنَسٌ فَلَمَّا أُنْزِلَتْ هَذِهِ الآيَةُ ‏{‏ لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ‏}‏ قَامَ أَبُو طَلْحَةَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ ‏{‏لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ‏}‏ وَإِنَّ أَحَبَّ أَمْوَالِي إِلَىَّ بَيْرُحَاءَ وَإِنَّهَا صَدَقَةٌ لِلَّهِ أَرْجُو بِرَّهَا وَذُخْرَهَا عِنْدَ اللَّهِ فَضَعْهَا يَا رَسُولَ اللَّهِ حَيْثُ شِئْتَ قَالَ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ بَخْ ذَلِكَ مَالٌ رَابِحٌ ذَلِكَ مَالٌ رَابِحٌ وَقَدْ سَمِعْتُ مَا قُلْتَ فِيهِ وَإِنِّي أَرَى أَنْ تَجْعَلَهَا فِي الأَقْرَبِينَ ‏\"\n\n‏ ‏.‏ فَقَالَ أَبُو طَلْحَةَ أَفْعَلُ يَا رَسُولَ اللَّهِ فَقَسَمَهَا أَبُو طَلْحَةَ فِي أَقَارِبِهِ وَبَنِي عَمِّهِ ‏.‏","v":[]}],"177":[{"c":"Jami` at-Tirmidhi","r":"Volume 2, Book 5, Hadith 659","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-2/Book-5/Hadith-659","x":"Fatimah bint Qais narrated that :\n\nshe asked -or, the Prophet was asked - about Zakat, and he said: \"Indeed there is a duty on wealthy aside from Zakat.\" Then he recited this Ayah which is in Al-Baqarah: 'It is not Al-Birr (piety, righteousness) that you turn your faces.' (Al-Baqarah 2:177)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ أَحْمَدَ بْنِ مَدُّويَهْ، حَدَّثَنَا الأَسْوَدُ بْنُ عَامِرٍ، عَنْ شَرِيكٍ، عَنْ أَبِي حَمْزَةَ، عَنِ الشَّعْبِيِّ، عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، قَالَتْ سَأَلْتُ أَوْ سُئِلَ النَّبِيُّ صلى الله عليه وسلم عَنِ الزَّكَاةِ فَقَالَ ‏\"‏ إِنَّ فِي الْمَالِ لَحَقًّا سِوَى الزَّكَاةِ ‏\"‏ ‏.‏ ثُمَّ تَلاَ هَذِهِ الآيَةَ الَّتِي فِي الْبَقَرَةِ ‏(‏ لَيْسَ الْبِرَّ أَنْ تُوَلُّوا وُجُوهَكُمْ ‏)‏ الآيَةَ ‏.‏","v":[]}],"178":[{"c":"Sahih Bukhari","r":"Hadith 2355","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2355","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"No bloodmoney will be charged if somebody dies in a mine or in a well or is killed by an animal; and if somebody finds a treasure in his land he has to give one-fifth of it to the Government.\"","ar":"حَدَّثَنَا مَحْمُودٌ، أَخْبَرَنَا عُبَيْدُ اللَّهِ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي حَصِينٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ الْمَعْدِنُ جُبَارٌ، وَالْبِئْرُ جُبَارٌ، وَالْعَجْمَاءُ جُبَارٌ، وَفِي الرِّكَازِ الْخُمُسُ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4498","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4498","x":"Narrated Ibn `Abbas:\n\nThe law of Qisas (i.e. equality in punishment) was prescribed for the children of Israel, but the Diya (i.e. blood money was not ordained for them). So Allah said to this Nation (i.e. Muslims): \"O you who believe! The law of Al-Qisas (i.e. equality in punishment) is prescribed for you in cases of murder: The free for the free, the slave for the slave, and the female for the female. But if the relatives (or one of them) of the killed (person) forgive their brother (i.e. the killers something of Qisas (i.e. not to kill the killer by accepting blood money in the case of intentional murder)----then the relatives (of the killed person) should demand blood-money in a reasonable manner and the killer must pay with handsome gratitude. This is an allevitation and a Mercy from your Lord, (in comparison to what was prescribed for the nations before you). So after this, whoever transgresses the limits (i.e. to kill the killer after taking the blood-money) shall have a painful torment.\" (2.178)","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا عَمْرٌو، قَالَ سَمِعْتُ مُجَاهِدًا، قَالَ سَمِعْتُ ابْنَ عَبَّاسٍ ـ رضى الله عنهما ـ يَقُولُ كَانَ فِي بَنِي إِسْرَائِيلَ الْقِصَاصُ، وَلَمْ تَكُنْ فِيهِمُ الدِّيَةُ فَقَالَ اللَّهُ تَعَالَى لِهَذِهِ الأُمَّةِ ‏{‏كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالأُنْثَى بِالأُنْثَى فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَىْءٌ‏}‏ فَالْعَفْوُ أَنْ يَقْبَلَ الدِّيَةَ فِي الْعَمْدِ ‏{‏فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ‏}‏ يَتَّبِعُ بِالْمَعْرُوفِ وَيُؤَدِّي بِإِحْسَانٍ، ‏{‏ذَلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ‏}‏ وَرَحْمَةٌ مِمَّا كُتِبَ عَلَى مَنْ كَانَ قَبْلَكُمْ‏.‏ ‏{‏فَمَنِ اعْتَدَى بَعْدَ ذَلِكَ فَلَهُ عَذَابٌ أَلِيمٌ‏}‏ قَتَلَ بَعْدَ قَبُولِ الدِّيَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6881","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6881","x":"Narrated Ibn `Abbas:\n\nFor the children of Israel the punishment for crime was Al-Qisas only (i.e., the law of equality in punishment) and the payment of Blood money was not permitted as an alternate. But Allah said to this nation (Muslims): 'O you who believe! Qisas is prescribed for you in case of murder,.....(up to)...end of the Verse. (2.178) Ibn `Abbas added: Remission (forgiveness) in this Verse, means to accept the Blood-money in an intentional murder. Ibn `Abbas added: The Verse: 'Then the relatives should demand Blood-money in a reasonable manner.' (2.178) means that the demand should be reasonable and it is to be compensated with handsome gratitude.","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنْ مُجَاهِدٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَتْ فِي بَنِي إِسْرَائِيلَ قِصَاصٌ، وَلَمْ تَكُنْ فِيهِمُ الدِّيَةُ فَقَالَ اللَّهُ لِهَذِهِ الأُمَّةِ ‏{‏كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى‏}‏ إِلَى هَذِهِ الآيَةِ ‏{‏فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَىْءٌ‏}‏‏.‏ قَالَ ابْنُ عَبَّاسٍ فَالْعَفْوُ أَنْ يَقْبَلَ الدِّيَةَ فِي الْعَمْدِ، قَالَ ‏{‏فَاتِّبَاعٌ بِالْمَعْرُوفِ‏}‏ أَنْ يَطْلُبَ بِمَعْرُوفٍ وَيُؤَدِّيَ بِإِحْسَانٍ‏.‏","v":[]}],"180":[{"c":"Sunan Abu Dawud","r":"Hadith 2875","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2875","x":"'Umair, A Companion of the Prophet (ﷺ) said:\n\nA man asked him (the Prophet): Messenger of Allah, what are the grave sins? He replied: They are nine. He then mentioned the tradition to the same effect. This version adds: \"And disobedience to the Muslim parents, and to violate the sacred House, your qiblah (direction of prayer), in your life and after death.","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ يَعْقُوبَ الْجُوزَجَانِيُّ، حَدَّثَنَا مُعَاذُ بْنُ هَانِئٍ، حَدَّثَنَا حَرْبُ بْنُ شَدَّادٍ، حَدَّثَنَا يَحْيَى بْنُ أَبِي كَثِيرٍ، عَنْ عَبْدِ الْحَمِيدِ بْنِ سِنَانٍ، عَنْ عُبَيْدِ بْنِ عُمَيْرٍ، عَنْ أَبِيهِ، أَنَّهُ حَدَّثَهُ - وَكَانَتْ، لَهُ صُحْبَةٌ - أَنَّ رَجُلاً، سَأَلَهُ فَقَالَ يَا رَسُولَ اللَّهِ مَا الْكَبَائِرُ فَقَالَ ‏\"‏ هُنَّ تِسْعٌ ‏\"‏ ‏.‏ فَذَكَرَ مَعْنَاهُ زَادَ ‏\"‏ وَعُقُوقُ الْوَالِدَيْنِ الْمُسْلِمَيْنِ وَاسْتِحْلاَلُ الْبَيْتِ الْحَرَامِ قِبْلَتِكُمْ أَحْيَاءً وَأَمْوَاتًا ‏\"‏ ‏.‏","v":[]}],"183":[{"c":"Sunan Abu Dawud","r":"Hadith 2320","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2320","x":"Ibn ‘Umar reported the Apostle of Allaah(ﷺ) as saying \"The month consists of twenty nine days, but do not fast till you sight it (the moon) and do not break your fast till you sight it. If the weather is cloudy, calculate it thirty days. When the twenty-ninth of Sha’ban came, Ibn ‘Umar would send someone (who tried) to sight the moon for him. If it was sighted then well and good, in case it was not sighted and there was no cloud and dust before him (on the horizon) he would not keep fast the next day. If there appeared (on the horizon) before him cloud or dust, he would fast the following day. Ibn ‘Umar would end his fasting alone with the people and did not follow this calculation.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ دَاوُدَ الْعَتَكِيُّ، حَدَّثَنَا حَمَّادٌ، حَدَّثَنَا أَيُّوبُ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ الشَّهْرُ تِسْعٌ وَعِشْرُونَ فَلاَ تَصُومُوا حَتَّى تَرَوْهُ وَلاَ تُفْطِرُوا حَتَّى تَرَوْهُ فَإِنْ غُمَّ عَلَيْكُمْ فَاقْدُرُوا لَهُ ثَلاَثِينَ ‏\"\n\n‏ ‏.‏ قَالَ فَكَانَ ابْنُ عُمَرَ إِذَا كَانَ شَعْبَانُ تِسْعًا وَعِشْرِينَ نُظِرَ لَهُ فَإِنْ رُؤِيَ فَذَاكَ وَإِنْ لَمْ يُرَ وَلَمْ يَحُلْ دُونَ مَنْظَرِهِ سَحَابٌ وَلاَ قَتَرَةٌ أَصْبَحَ مُفْطِرًا فَإِنْ حَالَ دُونَ مَنْظَرِهِ سَحَابٌ أَوْ قَتَرَةٌ أَصْبَحَ صَائِمًا ‏.‏ قَالَ فَكَانَ ابْنُ عُمَرَ يُفْطِرُ مَعَ النَّاسِ وَلاَ يَأْخُذُ بِهَذَا الْحِسَابِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1145a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1145a","x":"Salama b. Akwa' (Allah be pleased with him) reported that when this verse was revealed:\n\n\"And as for those who can fast (but do not) expiation is the feeding of a needy person\" (ii. 183), (he who liked to observe fast did observe it) and he who felt reluctant to observe it ate and expiated till the verse was revealed which abrogated it.","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا بَكْرٌ، - يَعْنِي ابْنَ مُضَرَ - عَنْ عَمْرِو بْنِ الْحَارِثِ، عَنْ بُكَيْرٍ، عَنْ يَزِيدَ، مَوْلَى سَلَمَةَ عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، - رضى الله عنه - قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏{‏ وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ‏}‏ كَانَ مَنْ أَرَادَ أَنْ يُفْطِرَ وَيَفْتَدِيَ ‏.‏ حَتَّى نَزَلَتِ الآيَةُ الَّتِي بَعْدَهَا فَنَسَخَتْهَا ‏.‏","v":[]}],"184":[{"c":"Sunan Abu Dawud","r":"Hadith 2322","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2322","x":"Narrated Abdullah ibn Mas'ud:\n\nWe kept fast for twenty-nine days along with the Prophet (ﷺ) more often than we kept fast for thirty days.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، عَنِ ابْنِ أَبِي زَائِدَةَ، عَنْ عِيسَى بْنِ دِينَارٍ، عَنْ أَبِيهِ، عَنْ عَمْرِو بْنِ الْحَارِثِ بْنِ أَبِي ضِرَارٍ، عَنِ ابْنِ مَسْعُودٍ، قَالَ لَمَا صُمْنَا مَعَ النَّبِيِّ صلى الله عليه وسلم تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْنَا مَعَهُ ثَلاَثِينَ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2325","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2325","x":"Narrated Aisha, Ummul Mu'minin:\n\nThe Messenger of Allah (ﷺ) used to count the days in Sha'ban in a manner he did not count any other month; then he fasted when he sighted the new moon of Ramadan; but if the weather was cloudy he counted thirty days and then fasted.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنِي مُعَاوِيَةُ بْنُ صَالِحٍ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ، قَالَ سَمِعْتُ عَائِشَةَ، - رضى الله عنها - تَقُولُ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَتَحَفَّظُ مِنْ شَعْبَانَ مَا لاَ يَتَحَفَّظُ مِنْ غَيْرِهِ ثُمَّ يَصُومُ لِرُؤْيَةِ رَمَضَانَ فَإِنْ غُمَّ عَلَيْهِ عَدَّ ثَلاَثِينَ يَوْمًا ثُمَّ صَامَ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1949","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1949","x":"Narrated Nafi`:\n\nIbn `Umar recited the verse: \"They had a choice either to fast or to feed a poor person for every day, and said that the order of this Verse was canceled.","ar":"حَدَّثَنَا عَيَّاشٌ، حَدَّثَنَا عَبْدُ الأَعْلَى، حَدَّثَنَا عُبَيْدُ اللَّهِ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ قَرَأَ فِدْيَةٌ طَعَامُ مَسَاكِينَ‏.‏ قَالَ هِيَ مَنْسُوخَةٌ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1959","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1959","x":"Narrated Abu Usama from Hisham bin 'Urwa from Fatima:\n\nAsma bint Abi Bakr said, \"We broke our fast during the lifetime of the Prophet (ﷺ) on a cloudy day and then the sun appeared.\" Hisham was asked, \"Were they ordered to fast in lieu of that day?\" He replied, \"It had to be made up for.\" Ma`mar said, \"I heard Hisham saying, \"I don't know whether they fasted in lieu of that day or not.\"","ar":"حَدَّثَنِي عَبْدُ اللَّهِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ فَاطِمَةَ، عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ـ رضى الله عنهما ـ قَالَتْ أَفْطَرْنَا عَلَى عَهْدِ النَّبِيِّ صلى الله عليه وسلم يَوْمَ غَيْمٍ، ثُمَّ طَلَعَتِ الشَّمْسُ‏.‏ قِيلَ لِهِشَامٍ فَأُمِرُوا بِالْقَضَاءِ قَالَ بُدٌّ مِنْ قَضَاءٍ‏.‏ وَقَالَ مَعْمَرٌ سَمِعْتُ هِشَامًا لاَ أَدْرِي أَقْضَوْا أَمْ لاَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4505","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4505","x":"Narrated 'Ata:\n\nThat he heard Ibn `Abbas reciting the Divine Verse:-- \"And for those who can fast they had a choice either fast, or feed a poor for every day..\" (2.184) Ibn `Abbas said, \"This Verse is not abrogated, but it is meant for old men and old women who have no strength to fast, so they should feed one poor person for each day of fasting (instead of fasting).","ar":"حَدَّثَنِي إِسْحَاقُ، أَخْبَرَنَا رَوْحٌ، حَدَّثَنَا زَكَرِيَّاءُ بْنُ إِسْحَاقَ، حَدَّثَنَا عَمْرُو بْنُ دِينَارٍ، عَنْ عَطَاءٍ، سَمِعَ ابْنَ عَبَّاسٍ، يَقْرَأُ ‏{‏وَعَلَى الَّذِينَ يُطَوَّقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ ‏}‏‏.‏ قَالَ ابْنُ عَبَّاسٍ لَيْسَتْ بِمَنْسُوخَةٍ، هُوَ الشَّيْخُ الْكَبِيرُ وَالْمَرْأَةُ الْكَبِيرَةُ لاَ يَسْتَطِيعَانِ أَنْ يَصُومَا، فَلْيُطْعِمَانِ مَكَانَ كُلِّ يَوْمٍ مِسْكِينًا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4507","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4507","x":"Narrated Salama:\n\nWhen the Divine Revelation: \"For those who can fast, they had a choice either fast, or feed a poor for every day,\" (2.184) was revealed, it was permissible for one to give a ransom and give up fasting, till the Verse succeeding it was revealed and abrogated it.","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا بَكْرُ بْنُ مُضَرَ، عَنْ عَمْرِو بْنِ الْحَارِثِ، عَنْ بُكَيْرِ بْنِ عَبْدِ اللَّهِ، عَنْ يَزِيدَ، مَوْلَى سَلَمَةَ بْنِ الأَكْوَعِ عَنْ سَلَمَةَ، قَالَ لَمَّا نَزَلَتْ ‏{‏وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ‏}‏ كَانَ مَنْ أَرَادَ أَنْ يُفْطِرَ وَيَفْتَدِيَ حَتَّى نَزَلَتِ الآيَةُ الَّتِي بَعْدَهَا فَنَسَخَتْهَا‏.‏ مَاتَ بُكَيْرٌ قَبْلَ يَزِيدَ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1145b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1145b","x":"Salama b. Akwa' reported:\n\nWe, during the lifetime of the Messenger of Allah (ﷺ), in one month of Ramadan (observed fast according to our liking). He who wished to fast lasted and he who wished to break broke it and fed a needy person as an expiation 1544 till this verse was revealed:\" He who witnesses among you the month (of Ramadan) he should observe fast during it\" (ii. 184).","ar":"حَدَّثَنِي عَمْرُو بْنُ سَوَّادٍ الْعَامِرِيُّ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، أَخْبَرَنَا عَمْرُو بْنُ، الْحَارِثِ عَنْ بُكَيْرِ بْنِ الأَشَجِّ، عَنْ يَزِيدَ، مَوْلَى سَلَمَةَ بْنِ الأَكْوَعِ عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، - رضى الله عنه - أَنَّهُ قَالَ كُنَّا فِي رَمَضَانَ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم مَنْ شَاءَ صَامَ وَمَنْ شَاءَ أَفْطَرَ فَافْتَدَى بِطَعَامِ مِسْكِينٍ حَتَّى أُنْزِلَتْ هَذِهِ الآيَةُ ‏{‏ فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 2, Book 6, Hadith 798","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-2/Book-6/Hadith-798","x":"Salamah bin Al-Akwa said:\n\n\"When the following was revealed: 'And for those upon whom it is difficult, (they may) feed a poor person' - if one of us wanted we would not fast, and pay the ransom, until the Ayah after it was revealed abrogating it.\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا بَكْرُ بْنُ مُضَرَ، عَنْ عَمْرِو بْنِ الْحَارِثِ، عَنْ بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الأَشَجِّ، عَنْ يَزِيدَ، مَوْلَى سَلَمَةَ بْنِ الأَكْوَعِ عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، قَالَ لَمَّا نَزَلَتْ ‏:‏ ‏(‏وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ ‏)‏ كَانَ مَنْ أَرَادَ مِنَّا أَنْ يُفْطِرَ وَيَفْتَدِيَ حَتَّى نَزَلَتِ الآيَةُ الَّتِي بَعْدَهَا فَنَسَخَتْهَا ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ ‏.‏ وَيَزِيدُ هُوَ ابْنُ أَبِي عُبَيْدٍ مَوْلَى سَلَمَةَ بْنِ الأَكْوَعِ ‏.‏","v":[]}],"185":[{"c":"Sunan Abu Dawud","r":"Hadith 2322","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2322","x":"Narrated Abdullah ibn Mas'ud:\n\nWe kept fast for twenty-nine days along with the Prophet (ﷺ) more often than we kept fast for thirty days.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، عَنِ ابْنِ أَبِي زَائِدَةَ، عَنْ عِيسَى بْنِ دِينَارٍ، عَنْ أَبِيهِ، عَنْ عَمْرِو بْنِ الْحَارِثِ بْنِ أَبِي ضِرَارٍ، عَنِ ابْنِ مَسْعُودٍ، قَالَ لَمَا صُمْنَا مَعَ النَّبِيِّ صلى الله عليه وسلم تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْنَا مَعَهُ ثَلاَثِينَ ‏.‏","v":[]}],"186":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2969","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2969","x":"Narrated An-Nu'man bin Bashir:\n\nfrom the Prophet (ﷺ) regarding Allah's saying: Your Lord said: Invoke Me, I shall respond to you (40:60, it appears that the author intended to apply it to Al-Baqarah 2:186). - he said: \"The supplication is the worship.\" And he recited: 'Your Lord said: Invoke Me, I shall respond to you.' up to His saying: 'in humiliation.'\"","ar":"حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ ذَرٍّ، عَنْ يُسَيْعٍ الْكِنْدِيِّ، عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم فِي قَوْلِهِ ‏:‏ ‏(‏وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ ‏)‏ قَالَ ‏\"‏ الدُّعَاءُ هُوَ الْعِبَادَةُ ‏\"‏ ‏.‏ وَقَرَأَ ‏:‏‏(‏ وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ ‏)‏ إِلَى قَوْلِهِ ‏(‏ دَاخِرِينَ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"187":[{"c":"Sunan Abu Dawud","r":"Hadith 2320","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2320","x":"Ibn ‘Umar reported the Apostle of Allaah(ﷺ) as saying \"The month consists of twenty nine days, but do not fast till you sight it (the moon) and do not break your fast till you sight it. If the weather is cloudy, calculate it thirty days. When the twenty-ninth of Sha’ban came, Ibn ‘Umar would send someone (who tried) to sight the moon for him. If it was sighted then well and good, in case it was not sighted and there was no cloud and dust before him (on the horizon) he would not keep fast the next day. If there appeared (on the horizon) before him cloud or dust, he would fast the following day. Ibn ‘Umar would end his fasting alone with the people and did not follow this calculation.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ دَاوُدَ الْعَتَكِيُّ، حَدَّثَنَا حَمَّادٌ، حَدَّثَنَا أَيُّوبُ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ الشَّهْرُ تِسْعٌ وَعِشْرُونَ فَلاَ تَصُومُوا حَتَّى تَرَوْهُ وَلاَ تُفْطِرُوا حَتَّى تَرَوْهُ فَإِنْ غُمَّ عَلَيْكُمْ فَاقْدُرُوا لَهُ ثَلاَثِينَ ‏\"\n\n‏ ‏.‏ قَالَ فَكَانَ ابْنُ عُمَرَ إِذَا كَانَ شَعْبَانُ تِسْعًا وَعِشْرِينَ نُظِرَ لَهُ فَإِنْ رُؤِيَ فَذَاكَ وَإِنْ لَمْ يُرَ وَلَمْ يَحُلْ دُونَ مَنْظَرِهِ سَحَابٌ وَلاَ قَتَرَةٌ أَصْبَحَ مُفْطِرًا فَإِنْ حَالَ دُونَ مَنْظَرِهِ سَحَابٌ أَوْ قَتَرَةٌ أَصْبَحَ صَائِمًا ‏.‏ قَالَ فَكَانَ ابْنُ عُمَرَ يُفْطِرُ مَعَ النَّاسِ وَلاَ يَأْخُذُ بِهَذَا الْحِسَابِ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2321","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2321","x":"Narrated Ayyub :\n\n'Umar b. 'Abd al-'Aziz wrote (a letter) to the people of Basrah: It has reached us from the Messenger of Allah (ﷺ), like the tradition narrated by Ibn 'Umar from the Prophet (ﷺ). This version adds: The best calculation is that when we sight the moon of Sha'ban on such-and-such date, fasting will being on such-and-such dates, Allah willing, except they they sight the moon before that (date).","ar":"حَدَّثَنَا حُمَيْدُ بْنُ مَسْعَدَةَ، حَدَّثَنَا عَبْدُ الْوَهَّابِ، حَدَّثَنِي أَيُّوبُ، قَالَ كَتَبَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ إِلَى أَهْلِ الْبَصْرَةِ بَلَغَنَا عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ نَحْوَ حَدِيثِ ابْنِ عُمَرَ عَنِ النَّبِيِّ صلى الله عليه وسلم زَادَ وَإِنَّ أَحْسَنَ مَا يُقَدَّرُ لَهُ إِذَا رَأَيْنَا هِلاَلَ شَعْبَانَ لِكَذَا وَكَذَا فَالصَّوْمُ إِنْ شَاءَ اللَّهُ لِكَذَا وَكَذَا إِلاَّ أَنْ تَرَوُا الْهِلاَلَ قَبْلَ ذَلِكَ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2356","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2356","x":"Narrated Anas ibn Malik:\n\nThe Messenger of Allah (ﷺ) used to break his fast before praying with some fresh dates; but if there were no fresh dates, he had a few dry dates, and if there were no dry dates, he took some mouthfuls of water.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا جَعْفَرُ بْنُ سُلَيْمَانَ، حَدَّثَنَا ثَابِتٌ الْبُنَانِيُّ، أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُفْطِرُ عَلَى رُطَبَاتٍ قَبْلَ أَنْ يُصَلِّيَ فَإِنْ لَمْ تَكُنْ رُطَبَاتٌ فَعَلَى تَمَرَاتٍ فَإِنْ لَمْ تَكُنْ حَسَا حَسَوَاتٍ مِنْ مَاءٍ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1915","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1915","x":"Narrated Al-Bara:\n\nIt was the custom among the companions of Muhammad that if any of them was fasting and the food was presented (for breaking his fast), but he slept before eating, he would not eat that night and the following day till sunset. Qais bin Sirma-al-Ansari was fasting and came to his wife at the time of Iftar (breaking one's fast) and asked her whether she had anything to eat. She replied, \"No, but I would go and bring some for you.\" He used to do hard work during the day, so he was overwhelmed by sleep and slept. When his wife came and saw him, she said, \"Disappointment for you.\" When it was midday on the following day, he fainted and the Prophet (ﷺ) was informed about the whole matter and the following verses were revealed: \"You are permitted To go to your wives (for sexual relation) At the night of fasting.\" So, they were overjoyed by it. And then Allah also revealed: \"And eat and drink Until the white thread Of dawn appears to you Distinct from the black thread (of the night).\" (2.187)","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ ـ رضى الله عنه ـ قَالَ كَانَ أَصْحَابُ مُحَمَّدٍ صلى الله عليه وسلم إِذَا كَانَ الرَّجُلُ صَائِمًا، فَحَضَرَ الإِفْطَارُ، فَنَامَ قَبْلَ أَنْ يُفْطِرَ لَمْ يَأْكُلْ لَيْلَتَهُ وَلاَ يَوْمَهُ، حَتَّى يُمْسِيَ، وَإِنَّ قَيْسَ بْنَ صِرْمَةَ الأَنْصَارِيَّ كَانَ صَائِمًا، فَلَمَّا حَضَرَ الإِفْطَارُ أَتَى امْرَأَتَهُ، فَقَالَ لَهَا أَعِنْدَكِ طَعَامٌ قَالَتْ لاَ وَلَكِنْ أَنْطَلِقُ، فَأَطْلُبُ لَكَ‏.‏ وَكَانَ يَوْمَهُ يَعْمَلُ، فَغَلَبَتْهُ عَيْنَاهُ، فَجَاءَتْهُ امْرَأَتُهُ، فَلَمَّا رَأَتْهُ قَالَتْ خَيْبَةً لَكَ‏.‏ فَلَمَّا انْتَصَفَ النَّهَارُ غُشِيَ عَلَيْهِ، فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ‏}‏ فَفَرِحُوا بِهَا فَرَحًا شَدِيدًا، وَنَزَلَتْ ‏{‏وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ‏}‏‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 18, Hadith 683","u":"https://quranx.com/Hadith/Malik/In-Book/Book-18/Hadith-683","x":"Yahya related to me from Malik from Ibn Shihab that A'isha and Hafsa, the wives of the Prophet, may Allah bless him and grant him peace, began fasting voluntarily one morning and then food was given to them and they broke their fast with it. Then the Messenger of Allah, may Allah bless him and grant him peace, came in. A'isha said, \"Hafsa asked, anticipating me in speech - she took after her father Umar - 'Messenger of Allah, A'isha and I began the morning fasting voluntarily and then food was given us and we broke the fast with it.' The Messenger of Allah, may Allah bless him and grant him peace, said, 'Fast another day in its place.' \"","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، أَنَّ عَائِشَةَ، وَحَفْصَةَ، زَوْجَىِ النَّبِيِّ صلى الله عليه وسلم أَصْبَحَتَا صَائِمَتَيْنِ مُتَطَوِّعَتَيْنِ فَأُهْدِيَ لَهُمَا طَعَامٌ فَأَفْطَرَتَا عَلَيْهِ فَدَخَلَ عَلَيْهِمَا رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَتْ عَائِشَةُ فَقَالَتْ حَفْصَةُ وَبَدَرَتْنِي بِالْكَلاَمِ - وَكَانَتْ بِنْتَ أَبِيهَا - يَا رَسُولَ اللَّهِ إِنِّي أَصْبَحْتُ أَنَا وَعَائِشَةُ صَائِمَتَيْنِ مُتَطَوِّعَتَيْنِ فَأُهْدِيَ إِلَيْنَا طَعَامٌ فَأَفْطَرْنَا عَلَيْهِ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ اقْضِيَا مَكَانَهُ يَوْمًا آخَرَ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 19, Hadith 696","u":"https://quranx.com/Hadith/Malik/In-Book/Book-19/Hadith-696","x":"Yahya related to me from Malik that he had heard that al-Qasim ibn Muhammad and Nafi, the mawla of Abdullah ibn Umar said, \"You cannot do itikaf unless you are fasting, because of what Allah, the Blessed and Exalted, says in His Book, 'And eat and drink until the white thread becomes clear to you from the black thread of dawn, then complete the fast until night-time, and do not have intercourse with them while you are doing itikaf in mosques,' (Sura 2 ayat 187). Allah only mentions itikaf together with fasting.\" Malik said, \"That is what we go by here.\"","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ الْقَاسِمَ بْنَ مُحَمَّدٍ، وَنَافِعًا، مَوْلَى عَبْدِ اللَّهِ بْنِ عُمَرَ قَالاَ لاَ اعْتِكَافَ إِلاَّ بِصِيَامٍ بِقَوْلِ اللَّهِ تَبَارَكَ وَتَعَالَى فِي كِتَابِهِ ‏{‏وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ وَلاَ تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ‏}‏ فَإِنَّمَا ذَكَرَ اللَّهُ الاِعْتِكَافَ مَعَ الصِّيَامِ ‏.‏ قَالَ مَالِكٌ وَعَلَى ذَلِكَ الأَمْرُ عِنْدَنَا أَنَّهُ لاَ اعْتِكَافَ إِلاَّ بِصِيَامٍ ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 18, Hadith 50","u":"https://quranx.com/Hadith/Malik/USC-MSA/Book-18/Hadith-50","x":"Yahya said that he heard Malik say, \"Someone who eats or drinks out of neglect or forgetfulness during a voluntary fast does not have to repeat his fast, but he should continue fasting for the rest of the day in which he eats or drinks while voluntarily fasting, and not stop fasting. Someone to whom something unexpected happens which causes him to break his fast while he is fasting voluntarily does not have to repeat his fast if he has broken it for a reason, and not simply because he decided to break his fast. Just as I do not think that someone has to repeat a voluntary prayer if he has had to stop it because of some discharge which he could prevent and which meant that he had to repeat his wudu.\" Malik said, \"Once a man has begun doing any of the right actions (al-amal as-saliha) such as the prayer, the fast and the hajj, or similar right actions of a voluntary nature, he should not stop until he has completed it according to what the sunna for that action is. If he says the takbir he should not stop until he has prayed two rakas. If he is fasting he should not break his fast until he has completed that day's fast. If he goes into ihram he should not return until he has completed his hajj, and if he begins doing tawaf he should not stop doing so until he has gone around the Kaba seven times. He should not stop doing any of these actions once he has started them until he has completed them, except if something happens such as illness or some other matter by which a man is excused. This is because Allah, the Blessed and Exalted, says in His Book, 'And eat and drink until the white thread becomes clear to you from the black thread of dawn, (and) then complete the fast until night-time,' (Sura 2 ayat 187), and so he must complete his fast as Allah has said. Allah, the Exalted, (also) says, 'And complete the hajj and the umra for Allah,' and so if a man were to go into ihram for a voluntary hajj having done his one obligatory hajj (on a previous occasion), he could not then stop doing his hajj having once begun it and leave ihram while in the middle of his hajj. Anyone that begins a voluntary act must complete it once he has begun doing it, just as an obligatory act must be completed. This is the best of what I have heard.\"","ar":"","v":[]},{"c":"Sahih Muslim","r":"Hadith 1090","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1090","x":"'Adi b. Hatim (Allah be pleased with him) reported that when (this verse) was revealed:\n\n\" Until the white streak of the dawn becomes distinct from the dark streak\" (ii. 187) Adi b. Hatim said: Messenger of Allah, verily I keep underneath my pillow two strings, one white and the other black, by which I distinguish night from dawn. Upon this the Messenger of Allah (ﷺ) said: Your pillow seems to be very large. For the word khait implies the blackness of the night and the whiteness of the dawn.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ، عَنْ حُصَيْنٍ، عَنِ الشَّعْبِيِّ، عَنْ عَدِيِّ بْنِ حَاتِمٍ، - رضى الله عنه - قَالَ لَمَّا نَزَلَتْ ‏{‏ حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ‏}‏ قَالَ لَهُ عَدِيُّ بْنُ حَاتِمٍ يَا رَسُولَ اللَّهِ إِنِّي أَجْعَلُ تَحْتَ وِسَادَتِي عِقَالَيْنِ عِقَالاً أَبْيَضَ وَعِقَالاً أَسْوَدَ أَعْرِفُ اللَّيْلَ مِنَ النَّهَارِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ وِسَادَتَكَ لَعَرِيضٌ إِنَّمَا هُوَ سَوَادُ اللَّيْلِ وَبَيَاضُ النَّهَارِ ‏\"‏ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2968","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2968","x":"Narrated Al-Bara bin 'Azib:\n\n\"It was the custom among the Companions of Muhammad (ﷺ), that if any of them was fasting and the food was presented but he had slept before eating, he would not eat that night, nor the following day until the evening. Qais bin Sirmah Al-Ansari fasted and came to his wife at the time of Iftar, and said to her: 'No, but I will go and bring something for you.' He worked during the day, so his eyes (sleep) overcame him. Then his wife came, and when she saw him she said: 'You shall be disappointed.' About the middle of the next day he fainted. That was mentioned to the Prophet (ﷺ), so this Ayah was revealed: 'It is made lawful for you to have sexual relations with your women on the night of the fasts. So they were very happy about that. 'And eat and drink until the white thread (light) of dawn appears distinct to you from the black thread (of night). (2:187)'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ بْنِ يُونُسَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ كَانَ أَصْحَابُ النَّبِيِّ صلى الله عليه وسلم إِذَا كَانَ الرَّجُلُ صَائِمًا فَحَضَرَ الإِفْطَارُ فَنَامَ قَبْلَ أَنْ يُفْطِرَ لَمْ يَأْكُلْ لَيْلَتَهُ وَلاَ يَوْمَهُ حَتَّى يُمْسِيَ وَإِنَّ قَيْسَ بْنَ صِرْمَةَ الأَنْصَارِيَّ كَانَ صَائِمًا فَلَمَّا حَضَرَهُ الإِفْطَارُ أَتَى امْرَأَتَهُ فَقَالَ هَلْ عِنْدَكِ طَعَامٌ قَالَتْ لاَ وَلَكِنْ أَنْطَلِقُ فَأَطْلُبُ لَكَ ‏.‏ وَكَانَ يَوْمَهُ يَعْمَلُ فَغَلَبَتْهُ عَيْنُهُ وَجَاءَتْهُ امْرَأَتُهُ فَلَمَّا رَأَتْهُ قَالَتْ خَيْبَةً لَكَ ‏.‏ فَلَمَّا انْتَصَفَ النَّهَارُ غُشِيَ عَلَيْهِ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَنَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏ أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ ‏)‏ فَفَرِحُوا بِهَا فَرَحًا شَدِيدًا ‏:‏ ‏(‏فَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2970","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2970","x":"Narrated 'Adi bin Hatim:\n\n\"When 'Until the white (light) thread of dawn appears distinct to you from the black thread (of night)' was revealed, the Prophet (ﷺ) said to me: 'That only refers to the whiteness of the day from the blackness of the night.'\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا حُصَيْنٌ، عَنِ الشَّعْبِيِّ، أَخْبَرَنَا عَدِيُّ بْنُ حَاتِمٍ، قَالَ لَمَّا نَزَلَتْ ‏:‏ ‏(‏ حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ ‏)‏ قَالَ لِي النَّبِيُّ صلى الله عليه وسلم ‏\"‏ إِنَّمَا ذَاكَ بَيَاضُ النَّهَارِ مِنْ سَوَادِ اللَّيْلِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، حَدَّثَنَا مُجَالِدٌ، عَنِ الشَّعْبِيِّ، عَنْ عَدِيِّ بْنِ حَاتِمٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم مِثْلَ ذَلِكَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3299","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3299","x":"Salamah bin Sakhr Al Ansari said:\n\n\"I was a man who had an issue with intercourse with a women that none other than me had. When (the month of) Ramadan entered, I pronounced Zihar upon my wife (to last) until the end of Ramadan, fearing that I might have an encounter with her during the night, and I would continue doing that until daylight came upon me, and I would not be able to stop. One night while she was serving me, something of her became exposed for me, so I rushed myself upon her. When the morning came I went to my people to inform them about what happened to me. I said: ‘Accompany me to the Messenger of Allah to inform him about my case.’ They said: ‘No by Allah! We shall not do that, we feat that something will be revealed about us in the Qur’an, or the Messenger of Allah might say something about us, the disgrace of which will remain upon us. But you do and do whatever you want.’\" He said: \"So I left and I went to the Messenger of Allah, and informed him of my case. He said: ‘You are the one who did that?\" I said: ‘I am the one.’ He said: ‘You are the one who did that?\" I said: ‘I am the one.’ He said: ‘You are the one who did that?\" I said: ‘I am the one, it is before you, so give me Allah’s judgment, for I shall be patient with that.’ He said: ‘Free a slave.’\" He said: \"I struck the sides of my neck with me hands, and said: ‘No by the One Who sent you with the Truth! I possess nothing besides it.’ He said: ‘Then fast for two months’ I said: ‘O Messenger of Allah! Did this occur to me other than when I was fasting?’ He said: ‘Then feed sixty poor people.’ I said: ‘By the One Who sent you with the Truth! We have spent these nights of ours hungry without an evening meal.’ He said: ‘Go to the one with the charity from Banu Ruzaiq, tell him to give it to you, then feed a Wasq of it, on your behalf, to sixty poor people. Then help yourself and your dependants with the remainder of it.’\" He said: \"I returned to my people and said: ‘I found dejection and bad ideas with you, and I found liberalness and blessing with the Messenger of Allah. He ordered me to take your charity, so give it to me.’ So they gave it to me.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، وَالْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ، عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، عَنْ سَلَمَةَ بْنِ صَخْرٍ الأَنْصَارِيِّ، قَالَ كُنْتُ رَجُلاً قَدْ أُوتِيتُ مِنْ جِمَاعِ النِّسَاءِ مَا لَمْ يُؤْتَ غَيْرِي فَلَمَّا دَخَلَ رَمَضَانُ تَظَاهَرْتُ مِنَ امْرَأَتِي حَتَّى يَنْسَلِخَ رَمَضَانُ فَرَقًا مِنْ أَنْ أُصِيبَ مِنْهَا فِي لَيْلَتِي فَأَتَتَابَعَ فِي ذَلِكَ إِلَى أَنْ يُدْرِكَنِي النَّهَارُ وَأَنَا لاَ أَقْدِرُ أَنْ أَنْزِعَ فَبَيْنَمَا هِيَ تَخْدُمُنِي ذَاتَ لَيْلَةٍ إِذْ تَكَشَّفَ لِي مِنْهَا شَيْءٌ فَوَثَبْتُ عَلَيْهَا فَلَمَّا أَصْبَحْتُ غَدَوْتُ عَلَى قَوْمِي فَأَخْبَرْتُهُمْ خَبَرِي فَقُلْتُ انْطَلِقُوا مَعِي إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَأُخْبِرُهُ بِأَمْرِي ‏.‏ فَقَالُوا لاَ وَاللَّهِ لاَ نَفْعَلُ نَتَخَوَّفُ أَنْ يَنْزِلَ فِينَا قُرْآنٌ أَوْ يَقُولَ فِينَا رَسُولُ اللَّهِ صلى الله عليه وسلم مَقَالَةً يَبْقَى عَلَيْنَا عَارُهَا وَلَكِنِ اذْهَبْ أَنْتَ فَاصْنَعْ مَا بَدَا لَكَ ‏.‏ قَالَ فَخَرَجْتُ فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَأَخْبَرْتُهُ خَبَرِي ‏.‏ فَقَالَ ‏\"‏ أَنْتَ بِذَاكَ ‏\"‏ ‏.‏ قُلْتُ أَنَا بِذَاكَ ‏.‏ قَالَ ‏\"‏ أَنْتَ بِذَاكَ ‏\"‏ ‏.‏ قُلْتُ أَنَا بِذَاكَ ‏.‏ قَالَ ‏\"‏ أَنْتَ بِذَاكَ ‏\"‏ ‏.‏ قُلْتُ أَنَا بِذَاكَ وَهَا أَنَا ذَا فَأَمْضِ فِيَّ حُكْمَ اللَّهِ فَإِنِّي صَابِرٌ لِذَلِكَ ‏.‏ قَالَ ‏\"‏ أَعْتِقْ رَقَبَةً ‏\"‏ ‏.‏ قَالَ فَضَرَبْتُ صَفْحَةَ عُنُقِي بِيَدِي فَقُلْتُ لاَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَصْبَحْتُ أَمْلِكُ غَيْرَهَا ‏.‏ قَالَ ‏\"‏ صُمْ شَهْرَيْنِ ‏\"‏ ‏.‏ قُلْتُ يَا رَسُولَ اللَّهِ وَهَلْ أَصَابَنِي مَا أَصَابَنِي إِلاَّ فِي الصِّيَامِ ‏.‏ قَالَ ‏\"‏ فَأَطْعِمْ سِتِّينَ مِسْكِينًا ‏\"‏ ‏.‏ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ بِتْنَا لَيْلَتَنَا هَذِهِ وَحْشَى مَا لَنَا عَشَاءٌ ‏.‏ قَالَ ‏\"‏ اذْهَبْ إِلَى صَاحِبِ صَدَقَةِ بَنِي زُرَيْقٍ فَقُلْ لَهُ فَلْيَدْفَعْهَا إِلَيْكَ فَأَطْعِمْ عَنْكَ مِنْهَا وَسْقًا سِتِّينَ مِسْكِينًا ثُمَّ اسْتَعِنْ بِسَائِرِهِ عَلَيْكَ وَعَلَى عِيَالِكَ ‏\"‏ ‏.‏ قَالَ فَرَجَعْتُ إِلَى قَوْمِي فَقُلْتُ وَجَدْتُ عِنْدَكُمُ الضِّيقَ وَسُوءَ الرَّأْىِ وَوَجَدْتُ عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم السَّعَةَ وَالْبَرَكَةَ أَمَرَ لِي بِصَدَقَتِكُمْ فَادْفَعُوهَا إِلَىَّ فَدَفَعُوهَا إِلَىَّ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏ قَالَ مُحَمَّدٌ سُلَيْمَانُ بْنُ يَسَارٍ لَمْ يَسْمَعْ عِنْدِي مِنْ سَلَمَةَ بْنِ صَخْرٍ ‏.‏ قَالَ وَيُقَالُ سَلَمَةُ بْنُ صَخْرٍ وَسَلْمَانُ بْنُ صَخْرٍ ‏.‏ وَفِي الْبَابِ عَنْ خَوْلَةَ بِنْتِ ثَعْلَبَةَ وَهِيَ امْرَأَةُ أَوْسِ بْنِ الصَّامِتِ ‏.‏","v":[]}],"189":[{"c":"Sahih Bukhari","r":"Hadith 1803","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1803","x":"Narrated Abu 'Is-haq:\n\nI heard Al-Bara' saying, \"The above Verse was revealed regarding us, for the Ansar on returning from Hajj never entered their houses through the proper doors but from behind. One of the Ansar came and entered through the door and he was taunted for it. Therefore, the following was revealed: -- \"It is not righteousness That you enter the houses from the back, But the righteous man is He who fears Allah, Obeys His order and keeps away from What He has forbidden So, enter houses through the proper doors.\" (2.189)","ar":"حَدَّثَنَا أَبُو الْوَلِيدِ، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، قَالَ سَمِعْتُ الْبَرَاءَ ـ رضى الله عنه ـ يَقُولُ نَزَلَتْ هَذِهِ الآيَةُ فِينَا، كَانَتِ الأَنْصَارُ إِذَا حَجُّوا فَجَاءُوا لَمْ يَدْخُلُوا مِنْ قِبَلِ أَبْوَابِ بُيُوتِهِمْ، وَلَكِنْ مِنْ ظُهُورِهَا، فَجَاءَ رَجُلٌ مِنَ الأَنْصَارِ، فَدَخَلَ مِنْ قِبَلِ بَابِهِ، فَكَأَنَّهُ عُيِّرَ بِذَلِكَ، فَنَزَلَتْ ‏{‏وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِهَا وَلَكِنَّ الْبِرَّ مَنِ اتَّقَى وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4512","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4512","x":"Narrated Al-Bara:\n\nIn the Pre-lslamic Period when the people assumed Ihram, they would enter their houses from the back. So Allah revealed:-- \"And it is not righteousness that you enter houses from the back, but the righteous man is he who fears Allah, obeys His Orders and keeps away from what He has forbidden. So enter houses through their doors.\" (2.189)","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ كَانُوا إِذَا أَحْرَمُوا فِي الْجَاهِلِيَّةِ أَتَوُا الْبَيْتَ مِنْ ظَهْرِهِ، فَأَنْزَلَ اللَّهُ ‏{‏وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِهَا وَلَكِنَّ الْبِرَّ مَنِ اتَّقَى وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3026","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3026","x":"Bara' reported:\n\nWhen the Ansar performed the Pilgrimage, they did not enter their houses but from behind. A person from the Ansar came and he began to enter from his door but it was said to him (why he was doing something in contravention to the common practice of coming to the houses from behind). Then this verse was revealed.\" Piety is not that you come to the doors from behind\" (ii. 189).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا غُنْدَرٌ، عَنْ شُعْبَةَ، ح وَحَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَابْنُ بَشَّارٍ - وَاللَّفْظُ لاِبْنِ الْمُثَنَّى - قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، عَنْ شُعْبَةَ، عَنْ أَبِي إِسْحَاقَ، قَالَ سَمِعْتُ الْبَرَاءَ، يَقُولُ كَانَتِ الأَنْصَارُ إِذَا حَجُّوا فَرَجَعُوا لَمْ يَدْخُلُوا الْبُيُوتَ إِلاَّ مِنْ ظُهُورِهَا - قَالَ - فَجَاءَ رَجُلٌ مِنَ الأَنْصَارِ فَدَخَلَ مِنْ بَابِهِ فَقِيلَ لَهُ فِي ذَلِكَ فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِهَا‏}‏ ‏.‏","v":[]}],"191":[{"c":"Jami` at-Tirmidhi","r":"Volume 3, Book 19, Hadith 1568","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-3/Book-19/Hadith-1568","x":"Narrated 'Imran bin Husain:\n\nThat the Prophet (ﷺ) ransomed two men for the Muslims with a man from the idolaters. [Abu 'Eisa said:] This Hadith is Hasan Sahih. The paternal uncle of Abu Al-Muhallab's name is 'Abdur Rahman bin 'Amr, and they also say it was Muhawiyah bin 'Amr. And Abu Qilabah's name is 'Abdullah bin Zaid Al-Jarmi (narrator in the chain) This is acted upon according to most of the people of knowledge among the Companions of the Prophet(ﷺ) and others. It is for the Imam to decide to be generous with whom he wills among the captives, or to kill whom he wills among them, or to ransom whom he wills among them. Some of the people of knowledge preferred killing over ransoming. Al-Awzai' said: \"It has been conveyed to me. that this Ayah is abrogated: Thereafter (is the time) either for generosity (to free them without ranson) or ransom (47:4). It was abrogated by: Kill them wherever you find them (2:191). This was narrated to us by Hannad (who said): \"Ibn Al-Mubarak narrated to us, from Al-Awza'i.\" Ishaq bin Mansur said: \"I said to Ahmad: 'When the captives are captured' is killing or ransoming better to you?' He said: 'If they are able to ransom' then there is no harm in it. And if they kill, then I do not know of any harm in it.'\" Ishaq said: \"Wiping them out is better to me, unless it is someone well-known, so that it is hoped that a large amount will be obtained for him.\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا أَيُّوبُ، عَنْ أَبِي قِلاَبَةَ، عَنْ عَمِّهِ، عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم فَدَى رَجُلَيْنِ مِنَ الْمُسْلِمِينَ بِرَجُلٍ مِنَ الْمُشْرِكِينَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَعَمُّ أَبِي قِلاَبَةَ هُوَ أَبُو الْمُهَلَّبِ وَاسْمُهُ عَبْدُ الرَّحْمَنِ بْنُ عَمْرٍو وَيُقَالُ مُعَاوِيَةُ بْنُ عَمْرٍو وَأَبُو قِلاَبَةَ اسْمُهُ عَبْدُ اللَّهِ بْنُ زَيْدٍ الْجَرْمِيُّ ‏.‏ وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَغَيْرِهِمْ أَنَّ لِلإِمَامِ أَنْ يَمُنَّ عَلَى مَنْ شَاءَ مِنَ الأُسَارَى وَيَقْتُلَ مَنْ شَاءَ مِنْهُمْ وَيَفْدِيَ مَنْ شَاءَ ‏.‏ وَاخْتَارَ بَعْضُ أَهْلِ الْعِلْمِ الْقَتْلَ عَلَى الْفِدَاءِ ‏.‏ وَقَالَ الأَوْزَاعِيُّ بَلَغَنِي أَنَّ هَذِهِ الآيَةَ مَنْسُوخَةٌ قَوْلُهُ تَعَالَى‏:‏ ‏(‏فَإِِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً‏)‏ نَسَخَتْهَا‏:‏ ‏(‏وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ ‏)‏ حَدَّثَنَا بِذَلِكَ هَنَّادٌ حَدَّثَنَا ابْنُ الْمُبَارَكِ عَنِ الأَوْزَاعِيِّ ‏.‏ قَالَ إِسْحَاقُ بْنُ مَنْصُورٍ قُلْتُ لأَحْمَدَ إِذَا أُسِرَ الأَسِيرُ يُقْتَلُ أَوْ يُفَادَى أَحَبُّ إِلَيْكَ قَالَ إِنْ قَدَرُوا أَنْ يُفَادُوا فَلَيْسَ بِهِ بَأْسٌ وَإِنْ قُتِلَ فَمَا أَعْلَمُ بِهِ بَأْسًا ‏.‏ قَالَ إِسْحَاقُ بْنُ إِبْرَاهِيمَ الإِثْخَانُ أَحَبُّ إِلَىَّ إِلاَّ أَنْ يَكُونَ مَعْرُوفًا فَأَطْمَعُ بِهِ الْكَثِيرَ ‏.‏","v":[]}],"193":[{"c":"Sahih Bukhari","r":"Hadith 7095","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7095","x":"Narrated Sa`id bin Jubair:\n\n`Abdullah bin `Umar came to us and we hoped that he would narrate to us a good Hadith. But before we asked him, a man got up and said to him, \"O Abu `Abdur-Rahman! Narrate to us about the battles during the time of the afflictions, as Allah says:-- 'And fight them until there is no more afflictions (i.e. no more worshipping of others besides Allah).'\" (2.193) Ibn `Umar said (to the man), \"Do you know what is meant by afflictions? Let your mother bereave you! Muhammad used to fight against the pagans, for a Muslim was put to trial in his religion (The pagans will either kill him or chain him as a captive). His fighting was not like your fighting which is carried on for the sake of ruling.\"","ar":"حَدَّثَنَا إِسْحَاقُ الْوَاسِطِيُّ، حَدَّثَنَا خَالِدٌ، عَنْ بَيَانٍ، عَنْ وَبَرَةَ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ خَرَجَ عَلَيْنَا عَبْدُ اللَّهِ بْنُ عُمَرَ فَرَجَوْنَا أَنْ يُحَدِّثَنَا، حَدِيثًا حَسَنًا ـ قَالَ ـ فَبَادَرَنَا إِلَيْهِ رَجُلٌ فَقَالَ يَا أَبَا عَبْدِ الرَّحْمَنِ حَدِّثْنَا عَنِ الْقِتَالِ فِي الْفِتْنَةِ وَاللَّهُ يَقُولُ ‏{‏وَقَاتِلُوهُمْ حَتَّى لاَ تَكُونَ فِتْنَةٌ‏}‏ فَقَالَ هَلْ تَدْرِي مَا الْفِتْنَةُ ثَكِلَتْكَ أُمُّكَ، إِنَّمَا كَانَ مُحَمَّدٌ صلى الله عليه وسلم يُقَاتِلُ الْمُشْرِكِينَ، وَكَانَ الدُّخُولُ فِي دِينِهِمْ فِتْنَةً، وَلَيْسَ كَقِتَالِكُمْ عَلَى الْمُلْكِ‏.‏","v":[]}],"195":[{"c":"Sunan Abu Dawud","r":"Hadith 2518","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2518","x":"‘Amr said \"I heard from Abu Wa’il a tradition which surprised me, he then narrated the tradition to the same effect (as mentioned before).","ar":"حَدَّثَنَا عَلِيُّ بْنُ مُسْلِمٍ، حَدَّثَنَا أَبُو دَاوُدَ، عَنْ شُعْبَةَ، عَنْ عَمْرٍو، قَالَ ‏:‏ سَمِعْتُ مِنْ أَبِي وَائِلٍ، حَدِيثًا أَعْجَبَنِي ‏.‏ فَذَكَرَ مَعْنَاهُ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4516","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4516","x":"Narrated Abu Wail:\n\nHudhaifa said, \"The Verse:-- \"And spend (of your wealth) in the Cause of Allah and do not throw yourselves in destruction,\" (2.195) was revealed concerning spending in Allah's Cause (i.e. Jihad).","ar":"حَدَّثَنَا إِسْحَاقُ، أَخْبَرَنَا النَّضْرُ، حَدَّثَنَا شُعْبَةُ، عَنْ سُلَيْمَانَ، قَالَ سَمِعْتُ أَبَا وَائِلٍ، عَنْ حُذَيْفَةَ، ‏{‏وَأَنْفِقُوا فِي سَبِيلِ اللَّهِ وَلاَ تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ‏}‏ قَالَ نَزَلَتْ فِي النَّفَقَةِ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2972","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2972","x":"Narrated Aslam bin 'Imran At-Tujibi:\n\n\"We were in a Roman city, when a large column of Romans came out to us. So about the same number or more of the Muslims went towards them. The commander of the people of Egypt was 'Uqbah bin 'Amir, and the commenter of the (our) group was Fadalah bin 'Ubaid. One man among the Muslims reached the Roman line until he entered amidst them, so the people started screaming: 'Subhan Allah! He has thrown himself into destruction!' Abu Ayyub Al-Ansari said: 'O you people! You give this interpretation for this Ayah, while this Ayah was only revealed about us, the people among the Ansar, when Allah made Islam might, and increased its supporters. Some of us secretly said to each other, outside of the presence of the Messenger of Allah (ﷺ): \"Our wealth has been ruined, and Allah has strengthened Islam, and increased its supporters, so if we tend to our wealth then what we lost of it shall be revitalized for us.\" So Allah, Blessed and Most High, revealed to His Prophet (ﷺ), rebuking what we said: 'And spend in the cause of Allah, and do not throw yourselves into destruction. (2:195)' So the destruction was tending to the wealth and maintaining it.' Abu Ayyub did not cease traveling in Allah's cause, until he was buried in the land of the Romans.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا الضَّحَّاكُ بْنُ مَخْلَدٍ أَبُو عَاصِمٍ النَّبِيلُ، عَنْ حَيْوَةَ بْنِ شُرَيْحٍ، عَنْ يَزِيدَ بْنِ أَبِي حَبِيبٍ، عَنْ أَسْلَمَ أَبِي عِمْرَانَ التُّجِيبِيِّ، قَالَ كُنَّا بِمَدِينَةِ الرُّومِ فَأَخْرَجُوا إِلَيْنَا صَفًّا عَظِيمًا مِنَ الرُّومِ فَخَرَجَ إِلَيْهِمْ مِنَ الْمُسْلِمِينَ مِثْلُهُمْ أَوْ أَكْثَرُ وَعَلَى أَهْلِ مِصْرَ عُقْبَةُ بْنُ عَامِرٍ وَعَلَى الْجَمَاعَةِ فَضَالَةُ بْنُ عُبَيْدٍ فَحَمَلَ رَجُلٌ مِنَ الْمُسْلِمِينَ عَلَى صَفِّ الرُّومِ حَتَّى دَخَلَ فِيهِمْ فَصَاحَ النَّاسُ وَقَالُوا سُبْحَانَ اللَّهِ يُلْقِي بِيَدَيْهِ إِلَى التَّهْلُكَةِ فَقَامَ أَبُو أَيُّوبَ الأَنْصَارِيُّ فَقَالَ يَا أَيُّهَا النَّاسُ إِنَّكُمْ تَتَأَوَّلُونَ هَذِهِ الآيَةَ هَذَا التَّأْوِيلَ وَإِنَّمَا نَزَلَتْ هَذِهِ الآيَةُ فِينَا مَعْشَرَ الأَنْصَارِ لَمَّا أَعَزَّ اللَّهُ الإِسْلاَمَ وَكَثُرَ نَاصِرُوهُ فَقَالَ بَعْضُنَا لِبَعْضٍ سِرًّا دُونَ رَسُولِ اللَّهِ صلى الله عليه وسلم إِنَّ أَمْوَالَنَا قَدْ ضَاعَتْ وَإِنَّ اللَّهَ قَدْ أَعَزَّ الإِسْلاَمَ وَكَثُرَ نَاصِرُوهُ فَلَوْ أَقَمْنَا فِي أَمْوَالِنَا فَأَصْلَحْنَا مَا ضَاعَ مِنْهَا ‏.‏ فَأَنْزَلَ اللَّهُ عَلَى نَبِيِّهِ صلى الله عليه وسلم يَرُدُّ عَلَيْنَا مَا قُلْنَا‏:‏ ‏(‏وَأَنْفِقُوا فِي سَبِيلِ اللَّهِ وَلاَ تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ ‏)‏ فَكَانَتِ التَّهْلُكَةُ الإِقَامَةَ عَلَى الأَمْوَالِ وَإِصْلاَحَهَا وَتَرَكْنَا الْغَزْوَ فَمَا زَالَ أَبُو أَيُّوبَ شَاخِصًا فِي سَبِيلِ اللَّهِ حَتَّى دُفِنَ بِأَرْضِ الرُّومِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ ‏.‏","v":[]}],"196":[{"c":"Sahih Bukhari","r":"Hadith 1559","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1559","x":"Narrated Abu Musa:\n\nThe Prophet (ﷺ) sent me to some people in Yemen and when I returned, I found him at Al-Batha. He asked me, \"With what intention have you assumed Ihram (i.e. for Hajj or for Umra or for both?\") I replied, \"I have assumed Ihram with an intention like that of the Prophet.\" He asked, \"Have you a Hadi with you?\" I replied in the negative. He ordered me to perform Tawaf round the Ka`ba and between Safa and Marwa and then to finish my Ihram. I did so and went to a woman from my tribe who combed my hair or washed my head. Then, when `Umar came (i.e. became Caliph) he said, \"If we follow Allah's Book, it orders us to complete Hajj and Umra; as Allah says: \"Perform the Hajj and Umra for Allah.\" (2.196). And if we follow the tradition of the Prophet (ﷺ) who did not finish his Ihram till he sacrificed his Hadi.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنْ قَيْسِ بْنِ مُسْلِمٍ، عَنْ طَارِقِ بْنِ شِهَابٍ، عَنْ أَبِي مُوسَى ـ رضى الله عنه ـ قَالَ بَعَثَنِي النَّبِيُّ صلى الله عليه وسلم إِلَى قَوْمٍ بِالْيَمَنِ فَجِئْتُ وَهْوَ بِالْبَطْحَاءِ فَقَالَ ‏\"‏ بِمَا أَهْلَلْتَ ‏\"‏‏.‏ قُلْتُ أَهْلَلْتُ كَإِهْلاَلِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ هَلْ مَعَكَ مِنْ هَدْىٍ ‏\"‏‏.‏ قُلْتُ لاَ‏.‏ فَأَمَرَنِي فَطُفْتُ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ ثُمَّ أَمَرَنِي فَأَحْلَلْتُ فَأَتَيْتُ امْرَأَةً مِنْ قَوْمِي فَمَشَطَتْنِي، أَوْ غَسَلَتْ رَأْسِي، فَقَدِمَ عُمَرُ ـ رضى الله عنه ـ فَقَالَ إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ فَإِنَّهُ يَأْمُرُنَا بِالتَّمَامِ قَالَ اللَّهُ ‏{‏وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ‏}‏ وَإِنْ نَأْخُذْ بِسُنَّةِ النَّبِيِّ صلى الله عليه وسلم فَإِنَّهُ لَمْ يَحِلَّ حَتَّى نَحَرَ الْهَدْىَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1572","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1572","x":"Ibn 'Abbas said that he has been asked regarding Hajj-at-Tamattu' on which he said:\n\n\"The Muhajirin and the Ansar and the wives of the Prophet (ﷺ) and we did the same. When we reached Makkah, Allah's Messenger (ﷺ) said, \"Give up your intention of doing the Hajj (at this moment) and perform 'Umra, except the one who had garlanded the Hady.\" So, we performed Tawaf round the Ka'bah and [Sa'y] between As-safa and Al-MArwa, slept with our wives and wore ordinary (stitched) clothes. The Prophet (ﷺ) added, \"Whoever has garlanded his Hady is not allowed to finish the Ihram till the Hady has reached its destination (has been sacrificed)\". Then on the night of Tarwiya (8th Dhul Hijjah, in the afternoon) he ordered us to assume Ihram for Hajj and when we have performed all the ceremonies of Hajj, we came and performed Tawaf round the Ka'bah and (Sa'y) between As-Safa and Al-Marwa, and then our Hajj was complete, and we had to sacrifice a Hady according to the statement of Allah: \"... He must slaughter a Hady such as he can afford, but if he cannot afford it, he should observer Saum (fasts) three days during the Hajj and seven days after his return (to his home)….\" (V. 2:196). And the sacrifice of the sheep is sufficient. So, the Prophet (ﷺ) and his Companions joined the two religious deeds, (i.e. Hajj and 'Umra) in one year, for Allah revealed (the permissibility) of such practice in His book and in the Sunna (legal ways) of His Prophet (ﷺ) and rendered it permissible for all the people except those living in Makkah. Allah says: \"This is for him whose family is not present at the Al-Masjid-Al-Haram, (i.e. non resident of Makkah).\" The months of Hajj which Allah mentioned in His book are: Shawwal, Dhul-Qa'da and Dhul-Hijjah. Whoever performed Hajj-at-Tamattu' in those months, then slaughtering or fasting is compulsory for him. The words: 1. Ar-Rafatha means sexual intercourse. 2. Al-Fasuq means all kinds of sin, and 3. Al-Jidal means to dispute.","ar":"وَقَالَ أَبُو كَامِلٍ فُضَيْلُ بْنُ حُسَيْنٍ الْبَصْرِيُّ حَدَّثَنَا أَبُو مَعْشَرٍ، حَدَّثَنَا عُثْمَانُ بْنُ غِيَاثٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ أَنَّهُ سُئِلَ عَنْ مُتْعَةِ الْحَجِّ، فَقَالَ أَهَلَّ الْمُهَاجِرُونَ وَالأَنْصَارُ وَأَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم فِي حَجَّةِ الْوَدَاعِ وَأَهْلَلْنَا، فَلَمَّا قَدِمْنَا مَكَّةَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ اجْعَلُوا إِهْلاَلَكُمْ بِالْحَجِّ عُمْرَةً إِلاَّ مَنْ قَلَّدَ الْهَدْىَ ‏\"‏‏.‏ فَطُفْنَا بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ وَأَتَيْنَا النِّسَاءَ، وَلَبِسْنَا الثِّيَابَ وَقَالَ ‏\"‏ مَنْ قَلَّدَ الْهَدْىَ فَإِنَّهُ لاَ يَحِلُّ لَهُ حَتَّى يَبْلُغَ الْهَدْىُ مَحِلَّهُ ‏\"‏‏.‏ ثُمَّ أَمَرَنَا عَشِيَّةَ التَّرْوِيَةِ أَنْ نُهِلَّ بِالْحَجِّ، فَإِذَا فَرَغْنَا مِنَ الْمَنَاسِكِ جِئْنَا فَطُفْنَا بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ فَقَدْ تَمَّ حَجُّنَا، وَعَلَيْنَا الْهَدْىُ كَمَا قَالَ اللَّهُ تَعَالَى ‏{‏فَمَا اسْتَيْسَرَ مِنَ الْهَدْىِ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاَثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ‏}‏ إِلَى أَمْصَارِكُمْ‏.‏ الشَّاةُ تَجْزِي، فَجَمَعُوا نُسُكَيْنِ فِي عَامٍ بَيْنَ الْحَجِّ وَالْعُمْرَةِ، فَإِنَّ اللَّهَ تَعَالَى أَنْزَلَهُ فِي كِتَابِهِ وَسَنَّهُ نَبِيُّهُ صلى الله عليه وسلم وَأَبَاحَهُ لِلنَّاسِ غَيْرَ أَهْلِ مَكَّةَ، قَالَ اللَّهُ ‏{‏ذَلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ‏}‏ وَأَشْهُرُ الْحَجِّ الَّتِي ذَكَرَ اللَّهُ تَعَالَى شَوَّالٌ وَذُو الْقَعْدَةِ وَذُو الْحَجَّةِ، فَمَنْ تَمَتَّعَ فِي هَذِهِ الأَشْهُرِ فَعَلَيْهِ دَمٌ أَوْ صَوْمٌ، وَالرَّفَثُ الْجِمَاعُ، وَالْفُسُوقُ الْمَعَاصِي، وَالْجِدَالُ الْمِرَاءُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1815","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1815","x":"Narrated Ka`b bin `Umra:\n\nAllah's Messenger (ﷺ) stood beside me at Al-Hudaibiya and the lice were falling from my head in great number. He asked me, \"Have your lice troubled you?\" I replied in the affirmative. He ordered me to get my head shaved. Ka`b added, \"This Holy Verse:--'And if any of you is ill, or has ailment in his scalp (2.196), etc. was revealed regarding me. \"The Prophet (ﷺ) then ordered me either to fast three days, or to feed six poor persons with one Faraq (three Sas) (of dates), or to slaughter a sheep, etc. (sacrifice) whatever was available.","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا سَيْفٌ، قَالَ حَدَّثَنِي مُجَاهِدٌ، قَالَ سَمِعْتُ عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى، أَنَّ كَعْبَ بْنَ عُجْرَةَ، حَدَّثَهُ قَالَ وَقَفَ عَلَىَّ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْحُدَيْبِيَةِ، وَرَأْسِي يَتَهَافَتُ قَمْلاً فَقَالَ ‏\"‏ يُؤْذِيكَ هَوَامُّكَ ‏\"‏‏.‏ قُلْتُ نَعَمْ‏.‏ قَالَ ‏\"‏ فَاحْلِقْ رَأْسَكَ ـ أَوْ قَالَ ـ احْلِقْ ‏\"‏‏.‏ قَالَ فِيَّ نَزَلَتْ هَذِهِ الآيَةُ ‏{‏فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ‏}‏ إِلَى آخِرِهَا‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ صُمْ ثَلاَثَةَ أَيَّامٍ، أَوْ تَصَدَّقْ بِفَرَقٍ بَيْنَ سِتَّةٍ، أَوِ انْسُكْ بِمَا تَيَسَّرَ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4191","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4191","x":"Narrated Ka`b bin Ujra:\n\nWe were in the company of Allah's Messenger (ﷺ) at Al-Hudaibiya in the state of Ihram and the pagans did not allow us to proceed (to the Ka`ba). I had thick hair and lice started falling on my face. The Prophet (ﷺ) passed by me and said, \"Are the lice of your head troubling you?\" I replied, Yes.\" (The sub-narrator added, \"Then the following Divine Verse was revealed:-- \"And if anyone of you is ill or has an ailment in his scalp, (necessitating shaving) must pay a ransom (Fida) of either fasting or feeding the poor, Or offering a sacrifice.\" (2.196)","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ هِشَامٍ أَبُو عَبْدِ اللَّهِ، حَدَّثَنَا هُشَيْمٌ، عَنْ أَبِي بِشْرٍ، عَنْ مُجَاهِدٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ كَعْبِ بْنِ عُجْرَةَ، قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم بِالْحُدَيْبِيَةِ وَنَحْنُ مُحْرِمُونَ، وَقَدْ حَصَرَنَا الْمُشْرِكُونَ ـ قَالَ ـ وَكَانَتْ لِي وَفْرَةٌ فَجَعَلَتِ الْهَوَامُّ تَسَّاقَطُ عَلَى وَجْهِي، فَمَرَّ بِي النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ أَيُؤْذِيكَ هَوَامُّ رَأْسِكَ ‏\"‏‏.‏ قُلْتُ نَعَمْ‏.‏ قَالَ وَأُنْزِلَتْ هَذِهِ الآيَةُ ‏{‏فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4517","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4517","x":"Narrated `Abdullah bin Maqal:\n\nI sat with Ka`b bin Ujra in this mosque, i.e. Kufa Mosque, and asked him about the meaning of: \"Pay a ransom (i.e. Fidya) of either fasting or.... (2.196)\" He said, \"I was taken to the Prophet (ﷺ) while lice were falling on my face. The Prophet (ﷺ) said, 'I did not think that your trouble reached to such an extent. Can you afford to slaughter a sheep (as a ransom for shaving your head)?' I said, 'No.' He said, 'Then fast for three days, or feed six poor persons by giving half a Sa of food for each and shave your head.' So the above Verse was revealed especially for me and generally for all of you.\"","ar":"حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الأَصْبَهَانِيِّ، قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ مَعْقِلٍ، قَالَ قَعَدْتُ إِلَى كَعْبِ بْنِ عُجْرَةَ فِي هَذَا الْمَسْجِدِ ـ يَعْنِي مَسْجِدَ الْكُوفَةِ ـ فَسَأَلْتُهُ عَنْ فِدْيَةٌ مِنْ صِيَامٍ فَقَالَ حُمِلْتُ إِلَى النَّبِيِّ صلى الله عليه وسلم وَالْقَمْلُ يَتَنَاثَرُ عَلَى وَجْهِي فَقَالَ ‏\"‏ مَا كُنْتُ أُرَى أَنَّ الْجَهْدَ قَدْ بَلَغَ بِكَ هَذَا، أَمَا تَجِدُ شَاةً ‏\"‏‏.‏ قُلْتُ لاَ‏.‏ قَالَ ‏\"‏ صُمْ ثَلاَثَةَ أَيَّامٍ، أَوْ أَطْعِمْ سِتَّةَ مَسَاكِينَ، لِكُلِّ مِسْكِينٍ نِصْفُ صَاعٍ مِنْ طَعَامٍ، وَاحْلِقْ رَأْسَكَ ‏\"‏‏.‏ فَنَزَلَتْ فِيَّ خَاصَّةً وَهْىَ لَكُمْ عَامَّةً‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 25, Hadith 3079","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-25/Hadith-3079","x":"It was narrated that ‘Abdullah bin Ma’qil said:\n\n\"I sat with Ka’b bin ‘Ujrah in the mosque and asked him about this Verse: ‘He must pay a compensation of either fasting (three days) or giving charity (feeding six poor persons) or offering sacrifice (one sheep).’ [2:196] Ka’b said: it was revealed concerning me. I had trouble with my head, so I was carried to the Messenger of Allah (ﷺ), with lice crawling on my face. He said: ‘I did not think that you were suffering as much as I see. Do you have a sheep?’ I said: ‘No.’ Then this Verse was revealed: \"He must pay a Fidyah (ransom) of either fasting (three days) or giving Sadaqah (charity – feeding six poor persons) or offering sacrifice (one sheep).\" [2:196] He said: ‘Fasting is three days, charity is to be given to six poor persons, giving each one half of a Sa’ of food, and the sacrifice is a sheep.’\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، وَمُحَمَّدُ بْنُ الْوَلِيدِ، قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الأَصْبَهَانِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مَعْقِلٍ، قَالَ قَعَدْتُ إِلَى كَعْبِ بْنِ عُجْرَةَ فِي الْمَسْجِدِ فَسَأَلْتُهُ عَنْ هَذِهِ الآيَةِ، ‏{فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ}‏ ‏.‏ قَالَ كَعْبٌ فِيَّ أُنْزِلَتْ كَانَ بِي أَذًى مِنْ رَأْسِي فَحُمِلْتُ إِلَى رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ وَالْقَمْلُ يَتَنَاثَرُ عَلَى وَجْهِي فَقَالَ ‏\"‏ مَا كُنْتُ أُرَى الْجُهْدَ بَلَغَ مِنْكَ مَا أَرَى أَتَجِدُ شَاةً ‏\"‏ ‏.‏ قُلْتُ لاَ ‏.‏ قَالَ فَنَزَلَتْ هَذِهِ الآيَةُ ‏{فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ}‏ ‏.‏ قَالَ فَالصَّوْمُ ثَلاَثَةُ أَيَّامٍ وَالصَّدَقَةُ عَلَى سِتَّةِ مَسَاكِينَ لِكُلِّ مِسْكِينٍ نِصْفُ صَاعٍ مِنْ طَعَامٍ وَالنُّسُكُ شَاةٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2973","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2973","x":"Narrated Mujahid:\n\nthat Ka'b bin 'Ujrah said: \"By the one in Whose Hand is my soul! This Ayah was revealed referring to my case: 'And whosoever of you is ill or has an ailment on his scalp (necessitating shaving) he must pay Fidyah of either fasting or giving charity, or a sacrifice. (2:196)'\" He said: \"We were with the Messenger of Allah (ﷺ) at Al-Hudaibiyyah and we were in a state of Ihram. The idolaters had held us back, and I had a good deal of hair, and the lice were falling on my face. The Prophet (ﷺ) passed by me and said: 'The lice on your head are bothering you?'\" He said: \"I said: 'Yes.' He said: 'Then shave.' And this Ayah was revealed.\" Mujahid said: \"The fasting is for three days, the feeding is six needy people, and the sacrifice is a sheep or more.\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، أَخْبَرَنَا هُشَيْمٌ، أَخْبَرَنَا مُغِيرَةُ، عَنْ مُجَاهِدٍ، قَالَ قَالَ كَعْبُ بْنُ عُجْرَةَ وَالَّذِي نَفْسِي بِيَدِهِ لَفِيَّ أُنْزِلَتْ هَذِهِ الآيَةُ وَإِيَّاىَ عَنَى بِهَا ‏:‏ ‏(‏فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ ‏)‏ قَالَ كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم بِالْحُدَيْبِيَةِ وَنَحْنُ مُحْرِمُونَ وَقَدْ حَصَرَنَا الْمُشْرِكُونَ وَكَانَتْ لِي وَفْرَةٌ فَجَعَلَتِ الْهَوَامُّ تَسَاقَطُ عَلَى وَجْهِي فَمَرَّ بِيَ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ كَأَنَّ هَوَامَّ رَأْسِكَ تُؤْذِيكَ ‏\"‏ ‏.‏ قَالَ قُلْتُ نَعَمْ ‏.‏ قَالَ ‏\"‏ فَاحْلِقْ ‏\"‏ ‏.‏ وَنَزَلَتْ هَذِهِ الآيَةُ ‏.‏ قَالَ مُجَاهِدٌ الصِّيَامُ ثَلاَثَةُ أَيَّامٍ وَالطَّعَامُ سِتَّةُ مَسَاكِينَ وَالنُّسُكُ شَاةٌ فَصَاعِدًا ‏.‏ حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، حَدَّثَنَا هُشَيْمٌ، عَنْ أَبِي بِشْرٍ، عَنْ مُجَاهِدٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ كَعْبِ بْنِ عُجْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِنَحْوِ ذَلِكَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، حَدَّثَنَا هُشَيْمٌ، عَنْ أَشْعَثَ بْنِ سَوَّارٍ، عَنِ الشَّعْبِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مَعْقِلٍ، عَنْ كَعْبِ بْنِ عُجْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِنَحْوِ ذَلِكَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ عَبْدُ الرَّحْمَنِ بْنُ الأَصْبَهَانِيِّ عَنْ عَبْدِ اللَّهِ بْنِ مَعْقِلٍ أَيْضًا ‏.‏","v":[]}],"197":[{"c":"Sahih Bukhari","r":"Hadith 1523","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1523","x":"Narrated Ibn `Abbas:\n\nThe people of Yemen used to come for Hajj and used not to bring enough provisions with them and used to say that they depend on Allah. On their arrival in Medina they used to beg the people, and so Allah revealed, \"And take a provision (with you) for the journey, but the best provision is the fear of Allah.\" (2.197).","ar":"حَدَّثَنَا يَحْيَى بْنُ بِشْرٍ، حَدَّثَنَا شَبَابَةُ، عَنْ وَرْقَاءَ، عَنْ عَمْرِو بْنِ دِينَارٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَ أَهْلُ الْيَمَنِ يَحُجُّونَ وَلاَ يَتَزَوَّدُونَ وَيَقُولُونَ نَحْنُ الْمُتَوَكِّلُونَ، فَإِذَا قَدِمُوا مَكَّةَ سَأَلُوا النَّاسَ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى‏}‏‏.‏ رَوَاهُ ابْنُ عُيَيْنَةَ عَنْ عَمْرٍو عَنْ عِكْرِمَةَ مُرْسَلاً‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 20, Hadith 877","u":"https://quranx.com/Hadith/Malik/In-Book/Book-20/Hadith-877","x":"Yahya related to me from Malik from Hisham ibn Urwa that Abdullah ibn az-Zubayr used to say, \"Know that the whole of Arafa is a standing-place except for the middle of Urana, and that the wholeof Muzdalifa is a standing-place except for the middle of Muhassir.\" Malik said, \"Allah, the Blessed and Exalted says, 'There is to be no rafath, no fusuq and no jidal during the hajj.' \" (Sura 2 ayat 197). He added, \"Rafath is sexual relations with women, and Allah knows best. Allah, the Blessed and Exalted says, 'Rafath with your women is permitted to you on the night of the fast.' (Sura 2 ayat 197). Fusuq are sacrifices made to idols, and Allah knows best. Allah, the Blessed and Exalted, says, 'Or a fisq offered up to other than Allah.' (Sura 2 ayat 197) Jidal (arguing) during the hajj refers to when the Quraysh used to stand near the mashar al-haram at Quzah in Muzdalifa, while the Arabs and others would stand at Arafa, and they would argue about who was the more correct. Allah, the Blessed and Exalted, says, 'And we appointed a method of sacrifice for every nation, which they followed, so let them not dispute with you about the matter, and call to your Lord. Surely you are on a straight guidance.' (Sura 22 ayat 67) This is what jidal refers to in our opinion, and Allah knows best. This I have heard from the people of knowledge.\"","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، أَنَّهُ كَانَ يَقُولُ اعْلَمُوا أَنَّ عَرَفَةَ كُلَّهَا مَوْقِفٌ إِلاَّ بَطْنَ عُرَنَةَ وَأَنَّ الْمُزْدَلِفَةَ كُلَّهَا مَوْقِفٌ إِلاَّ بَطْنَ مُحَسِّرٍ ‏.‏ قَالَ مَالِكٌ قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏{‏فَلاَ رَفَثَ وَلاَ فُسُوقَ وَلاَ جِدَالَ فِي الْحَجِّ ‏}‏ قَالَ فَالرَّفَثُ إِصَابَةُ النِّسَاءِ وَاللَّهُ أَعْلَمُ قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏{‏أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ ‏}‏ قَالَ وَالْفُسُوقُ الذَّبْحُ لِلأَنْصَابِ وَاللَّهُ أَعْلَمُ قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏{‏أَوْ فِسْقًا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ‏}‏ ‏.‏ قَالَ وَالْجِدَالُ فِي الْحَجِّ أَنَّ قُرَيْشًا كَانَتْ تَقِفُ عِنْدَ الْمَشْعَرِ الْحَرَامِ بِالْمُزْدَلِفَةِ بِقُزَحَ وَكَانَتِ الْعَرَبُ وَغَيْرُهُمْ يَقِفُونَ بِعَرَفَةَ فَكَانُوا يَتَجَادَلُونَ يَقُولُ هَؤُلاَءِ نَحْنُ أَصْوَبُ وَيَقُولُ هَؤُلاَءِ نَحْنُ أَصْوَبُ فَقَالَ اللَّهُ تَعَالَى وَ ‏{‏لِكُلِّ أُمَّةٍ جَعَلْنَا مَنْسَكًا هُمْ نَاسِكُوهُ فَلاَ يُنَازِعُنَّكَ فِي الأَمْرِ وَادْعُ إِلَى رَبِّكَ إِنَّكَ لَعَلَى هُدًى مُسْتَقِيمٍ‏}‏ فَهَذَا الْجِدَالُ فِيمَا نُرَى وَاللَّهُ أَعْلَمُ وَقَدْ سَمِعْتُ ذَلِكَ مِنْ أَهْلِ الْعِلْمِ ‏.‏","v":[]}],"198":[{"c":"Sunan Abu Dawud","r":"Hadith 1735","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1735","x":"`Abd Allah bin `Abbas said :\n\nIn the beginning when Hajj was prescribed, people used to trade during Hajj. The narrator then narrated the rest of the tradition upto the words, `season of Hajj’.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا ابْنُ أَبِي فُدَيْكٍ، أَخْبَرَنِي ابْنُ أَبِي ذِئْبٍ، عَنْ عُبَيْدِ بْنِ عُمَيْرٍ، - قَالَ أَحْمَدُ بْنُ صَالِحٍ كَلاَمًا مَعْنَاهُ أَنَّهُ مَوْلَى ابْنِ عَبَّاسٍ - عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، أَنَّ النَّاسَ، فِي أَوَّلِ مَا كَانَ الْحَجُّ كَانُوا يَبِيعُونَ فَذَكَرَ مَعْنَاهُ إِلَى قَوْلِهِ مَوَاسِمِ الْحَجِّ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 1737","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1737","x":"Ibn Umar said :\n\nThe Messenger of Allah (SWAS) appointed the following places for putting on Ihram : Dhul al-Hulaifah for the people of Madina, al-Juhfah for the people of Syria and al-Qarn for the people of Najd and have been told that appointed Yalamlam for the people of Yemen.","ar":"حَدَّثَنَا الْقَعْنَبِيُّ، عَنْ مَالِكٍ، ح وَحَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا مَالِكٌ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ وَقَّتَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأَهْلِ الْمَدِينَةِ ذَا الْحُلَيْفَةِ وَلأَهْلِ الشَّامِ الْجُحْفَةَ وَلأَهْلِ نَجْدٍ قَرْنًا وَبَلَغَنِي أَنَّهُ وَقَّتَ لأَهْلِ الْيَمَنِ يَلَمْلَمَ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 1738","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1738","x":"Ibn `Abbas and Tawus reported :\n\nThe Messenger of Allah (SWAS) appointed places for putting on Ihram and narrated the rest of the tradition to the same effect (as mentioned above). One of them said and Yalamlam for the people of Yemen. The other narrator said Alamlam. These (places for Ihram) are appointed for these regions and for people of other regions who come to them intending to perform Hajj and `Umrah. The place where those who live nearer to Makkah should put on Ihram from where they start and so on up to the inhabitants of Makkah itself who put on Ihram in it. This is the version of Ibn Tawus.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادٌ، عَنْ عَمْرِو بْنِ دِينَارٍ، عَنْ طَاوُسٍ، عَنِ ابْنِ عَبَّاسٍ، وَعَنِ ابْنِ طَاوُسٍ، عَنْ أَبِيهِ، قَالاَ وَقَّتَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِمَعْنَاهُ قَالَ أَحَدُهُمَا وَلأَهْلِ الْيَمَنِ يَلَمْلَمَ ‏.‏ وَقَالَ أَحَدُهُمَا أَلَمْلَمَ قَالَ ‏\n\n\"‏ فَهُنَّ لَهُمْ وَلِمَنْ أَتَى عَلَيْهِنَّ مِنْ غَيْرِ أَهْلِهِنَّ مِمَّنْ كَانَ يُرِيدُ الْحَجَّ وَالْعُمْرَةَ وَمَنْ كَانَ دُونَ ذَلِكَ ‏.‏ - قَالَ ابْنُ طَاوُسٍ - مِنْ حَيْثُ أَنْشَأَ قَالَ وَكَذَلِكَ حَتَّى أَهْلُ مَكَّةَ يُهِلُّونَ مِنْهَا ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1770","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1770","x":"Narrated Ibn ' `Abbas:\n\nDhul-Majaz and `Ukaz were the markets of the people during the Pre-Islamic period of ignorance. When the people embraced Islam, they disliked to do bargaining there till the following Holy Verses were revealed:-- There is no harm for you If you seek of the bounty Of your Lord (during Hajj by trading, etc.) (2.198)","ar":"حَدَّثَنَا عُثْمَانُ بْنُ الْهَيْثَمِ، أَخْبَرَنَا ابْنُ جُرَيْجٍ، قَالَ عَمْرُو بْنُ دِينَارٍ قَالَ ابْنُ عَبَّاسٍ ـ رضى الله عنهما ـ كَانَ ذُو الْمَجَازِ وَعُكَاظٌ مَتْجَرَ النَّاسِ فِي الْجَاهِلِيَّةِ، فَلَمَّا جَاءَ الإِسْلاَمُ كَأَنَّهُمْ كَرِهُوا ذَلِكَ حَتَّى نَزَلَتْ ‏{‏لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْ‏}‏ فِي مَوَاسِمِ الْحَجِّ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2050","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2050","x":"Narrated Ibn `Abbas:\n\n`Ukaz, Majanna and Dhul-Majaz were marketplaces in the Pre-Islamic period of ignorance. When Islam came, Muslims felt that marketing there might be a sin. So, the Divine Inspiration came: \"There is no harm for you to seek the bounty of your Lord (in the seasons of Hajj).\" (2.198) Ibn `Abbas recited the Verse in this way.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَتْ عُكَاظٌ وَمِجَنَّةُ وَذُو الْمَجَازِ أَسْوَاقًا فِي الْجَاهِلِيَّةِ، فَلَمَّا كَانَ الإِسْلاَمُ فَكَأَنَّهُمْ تَأَثَّمُوا فِيهِ فَنَزَلَتْ ‏{‏لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْ ‏}‏ فِي مَوَاسِمِ الْحَجِّ، قَرَأَهَا ابْنُ عَبَّاسٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2098","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2098","x":"Narrated Ibn `Abbas:\n\n`Ukaz, Majanna and Dhul-Majaz were markets in the Pre-Islamic period. When the people embraced Islam they considered it a sin to trade there. So, the following Holy Verse came:-- 'There is no harm for you if you seek of the bounty of your Lord (Allah) in the Hajj season.\" (2.198) Ibn `Abbas recited it like this.","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَتْ عُكَاظٌ وَمَجَنَّةُ وَذُو الْمَجَازِ أَسْوَاقًا فِي الْجَاهِلِيَّةِ، فَلَمَّا كَانَ الإِسْلاَمُ تَأَثَّمُوا مِنَ التِّجَارَةِ فِيهَا، فَأَنْزَلَ اللَّهُ ‏{‏لَيْسَ عَلَيْكُمْ جُنَاحٌ‏}‏ فِي مَوَاسِمِ الْحَجِّ، قَرَأَ ابْنُ عَبَّاسٍ كَذَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4519","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4519","x":"Narrated Ibn `Abbas:\n\n`Ukaz, Mijanna and Dhul-Majaz were markets during the Pre-islamic Period. They (i.e. Muslims) considered it a sin to trade there during the Hajj time (i.e. season), so this Verse was revealed:-- \"There is no harm for you if you seek of the Bounty of your Lord during the Hajj season.\" (2.198)","ar":"حَدَّثَنِي مُحَمَّدٌ، قَالَ أَخْبَرَنِي ابْنُ عُيَيْنَةَ، عَنْ عَمْرٍو، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَتْ عُكَاظٌ وَمَجَنَّةُ وَذُو الْمَجَازِ أَسْوَاقًا فِي الْجَاهِلِيَّةِ فَتَأَثَّمُوا أَنْ يَتَّجِرُوا فِي الْمَوَاسِمِ فَنَزَلَتْ ‏{‏لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْ‏}‏ فِي مَوَاسِمِ الْحَجِّ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 1284","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-1284","x":"Ibn 'Abbas (May Allah be pleased with them) reported:\n\nUkaz, Mijannah and Dhul-Majaz were markets during the pre-Islamic period. The Companions disliked trading there till the following Ayat of the Noble Qur'an were revealed: \"There is no sin on you if you seek the Bounty of your Rubb (during pilgrimage by trading)...\" (2:198)[Al- Bukhari].","ar":"وعن ابن عباس رضي الله عنهما قال‏:‏ كانت عكاظ ومجنة، وذو المجاز أسواقًا في الجاهلية، فتأثموا أن يتجروا في المواسم، فنزلت‏:‏ ‏{‏ليس عليكم جناح أن تبتغوا فضلا من ربكم‏}‏ ‏(‏‏(‏البقرة‏:‏ 198‏)‏‏)‏ في مواسم الحج‏.‏‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏","v":[]}],"199":[{"c":"Sahih Bukhari","r":"Hadith 1665","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1665","x":"Narrated `Urwa:\n\nDuring the Pre-Islamic period of Ignorance, the people used to perform Tawaf of the Ka`ba naked except the Hums; and the Hums were Quraish and their offspring. The Hums used to give clothes to the men who would perform the Tawaf wearing them; and women (of the Hums) used to give clothes to the women who would perform the Tawaf wearing them. Those to whom the Hums did not give clothes would perform Tawaf round the Ka`ba naked. Most of the people used to go away (disperse) directly from `Arafat but they (Hums) used to depart after staying at Al-Muzdalifa. `Urwa added, \"My father narrated that `Aisha had said, 'The following verses were revealed about the Hums: Then depart from the place whence all the people depart--(2.199) `Urwa added, \"They (the Hums) used to stay at Al-Muzdalifa and used to depart from there (to Mina) and so they were sent to `Arafat (by Allah's order).\"","ar":"حَدَّثَنَا فَرْوَةُ بْنُ أَبِي الْمَغْرَاءِ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، قَالَ عُرْوَةُ كَانَ النَّاسُ يَطُوفُونَ فِي الْجَاهِلِيَّةِ عُرَاةً إِلاَّ الْحُمْسَ، وَالْحُمْسُ قُرَيْشٌ وَمَا وَلَدَتْ، وَكَانَتِ الْحُمْسُ يَحْتَسِبُونَ عَلَى النَّاسِ يُعْطِي الرَّجُلُ الرَّجُلَ الثِّيَابَ يَطُوفُ فِيهَا، وَتُعْطِي الْمَرْأَةُ الْمَرْأَةَ الثِّيَابَ تَطُوفُ فِيهَا، فَمَنْ لَمْ يُعْطِهِ الْحُمْسُ طَافَ بِالْبَيْتِ عُرْيَانًا، وَكَانَ يُفِيضُ جَمَاعَةُ النَّاسِ مِنْ عَرَفَاتٍ، وَيُفِيضُ الْحُمْسُ مِنْ جَمْعٍ‏.‏ قَالَ وَأَخْبَرَنِي أَبِي عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ هَذِهِ الآيَةَ نَزَلَتْ فِي الْحُمْسِ ‏{‏ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ‏}‏ قَالَ كَانُوا يُفِيضُونَ مِنْ جَمْعٍ فَدُفِعُوا إِلَى عَرَفَاتٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4520","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4520","x":"Narrated `Aisha:\n\nThe Quraish people and those who embraced their religion, used to stay at Muzdalifa and used to call themselves Al-Hums, while the rest of the Arabs used to stay at `Arafat. When Islam came, Allah ordered His Prophet to go to `Arafat and stay at it, and then pass on from there, and that is what is meant by the Statement of Allah:--\"Then depart from the place whence all the people depart......\" (2.199)","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا مُحَمَّدُ بْنُ خَازِمٍ، حَدَّثَنَا هِشَامٌ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ كَانَتْ قُرَيْشٌ وَمَنْ دَانَ دِينَهَا يَقِفُونَ بِالْمُزْدَلِفَةِ، وَكَانُوا يُسَمَّوْنَ الْحُمْسَ، وَكَانَ سَائِرُ الْعَرَبِ يَقِفُونَ بِعَرَفَاتٍ، فَلَمَّا جَاءَ الإِسْلاَمُ أَمَرَ اللَّهُ نَبِيَّهُ صلى الله عليه وسلم أَنْ يَأْتِيَ عَرَفَاتٍ، ثُمَّ يَقِفَ بِهَا ثُمَّ يُفِيضَ مِنْهَا، فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4521","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4521","x":"Narrated Ibn `Abbas:\n\nA man who wants to perform the Hajj (from Mecca) can perform the Tawaf around the Ka`ba as long as he is not in the state of Ihram till he assumes the Ihram for Hajj. Then, if he rides and proceeds to `Arafat, he should take a Hadi (i.e. animal for sacrifice), either a camel or a cow or a sheep, whatever he can afford; but if he cannot afford it, he should fast for three days during the Hajj before the day of `Arafat, but if the third day of his fasting happens to be the day of `Arafat (i.e. 9th of Dhul-Hijja) then it is no sin for him (to fast on it). Then he should proceed to `Arafat and stay there from the time of the `Asr prayer till darkness falls. Then the pilgrims should proceed from `Arafat, and when they have departed from it, they reach Jam' (i.e. Al-Muzdalifa) where they ask Allah to help them to be righteous and dutiful to Him, and there they remember Allah greatly or say Takbir (i.e. Allah is Greater) and Tahlil (i.e. None has the right to be worshipped but Allah) repeatedly before dawn breaks. Then, after offering the morning (Fajr) prayer you should pass on (to Mina) for the people used to do so and Allah said:-- \"Then depart from the place whence all the people depart. And ask for Allah's Forgiveness. Truly! Allah is Oft-Forgiving, Most Merciful.\" (2.199) Then you should go on doing so till you throw pebbles over the Jamra.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ أَبِي بَكْرٍ، حَدَّثَنَا فُضَيْلُ بْنُ سُلَيْمَانَ، حَدَّثَنَا مُوسَى بْنُ عُقْبَةَ، أَخْبَرَنِي كُرَيْبٌ، عَنِ ابْنِ عَبَّاسٍ، قَالَ يَطَوَّفُ الرَّجُلُ بِالْبَيْتِ مَا كَانَ حَلاَلاً حَتَّى يُهِلَّ بِالْحَجِّ، فَإِذَا رَكِبَ إِلَى عَرَفَةَ فَمَنْ تَيَسَّرَ لَهُ هَدِيَّةٌ مِنَ الإِبِلِ أَوِ الْبَقَرِ أَوِ الْغَنَمِ، مَا تَيَسَّرَ لَهُ مِنْ ذَلِكَ أَىَّ ذَلِكَ شَاءَ، غَيْرَ إِنْ لَمْ يَتَيَسَّرْ لَهُ فَعَلَيْهِ ثَلاَثَةُ أَيَّامٍ فِي الْحَجِّ، وَذَلِكَ قَبْلَ يَوْمِ عَرَفَةَ، فَإِنْ كَانَ آخِرُ يَوْمٍ مِنَ الأَيَّامِ الثَّلاَثَةِ يَوْمَ عَرَفَةَ فَلاَ جُنَاحَ عَلَيْهِ، ثُمَّ لِيَنْطَلِقْ حَتَّى يَقِفَ بِعَرَفَاتٍ مِنْ صَلاَةِ الْعَصْرِ إِلَى أَنْ يَكُونَ الظَّلاَمُ، ثُمَّ لِيَدْفَعُوا مِنْ عَرَفَاتٍ إِذَا أَفَاضُوا مِنْهَا حَتَّى يَبْلُغُوا جَمْعًا الَّذِي يُتَبَرَّرُ فِيهِ، ثُمَّ لِيَذْكُرُوا اللَّهَ كَثِيرًا، أَوْ أَكْثِرُوا التَّكْبِيرَ وَالتَّهْلِيلَ قَبْلَ أَنْ تُصْبِحُوا ثُمَّ أَفِيضُوا، فَإِنَّ النَّاسَ كَانُوا يُفِيضُونَ، وَقَالَ اللَّهُ تَعَالَى ‏{‏ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ‏}‏ حَتَّى تَرْمُوا الْجَمْرَةَ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 25, Hadith 3018","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-25/Hadith-3018","x":"It was narrated that ‘Aishah said:\n\n\"The Quraish said: ‘We are the neighbors of the House and we do not leave the sanctuary.’ Allah said: ‘Then depart from the place whence all the people depart.’\" [2:199]","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَنْبَأَنَا الثَّوْرِيُّ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ قَالَتْ قُرَيْشٌ نَحْنُ قَوَاطِنُ الْبَيْتِ لاَ نُجَاوِزُ الْحَرَمَ ‏.‏ فَقَالَ اللَّهُ عَزَّ وَجَلَّ ‏{ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ }‏ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 2, Book 7, Hadith 884","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-2/Book-7/Hadith-884","x":"Aishah narrated:\n\n\"The Quraish and those who followed their religion - and they were called Al-Hums - would stand at Al-Muzdalifah, and they would say: 'We are the people of Allah.' The others would stand at Arafat, so Allah the Mighty and Sublime revealed: Then depart from where the people depart.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الأَعْلَى الصَّنْعَانِيُّ الْبَصْرِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ كَانَتْ قُرَيْشٌ وَمَنْ كَانَ عَلَى دِينِهَا وَهُمُ الْحُمْسُ يَقِفُونَ بِالْمُزْدَلِفَةِ يَقُولُونَ نَحْنُ قَطِينُ اللَّهِ ‏.‏ وَكَانَ مَنْ سِوَاهُمْ يَقِفُونَ بِعَرَفَةَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ قَالَ وَمَعْنَى هَذَا الْحَدِيثِ أَنَّ أَهْلَ مَكَّةَ كَانُوا لاَ يَخْرُجُونَ مِنَ الْحَرَمِ وَعَرَفَةُ خَارِجٌ مِنَ الْحَرَمِ وَأَهْلُ مَكَّةَ كَانُوا يَقِفُونَ بِالْمُزْدَلِفَةِ وَيَقُولُونَ نَحْنُ قَطِينُ اللَّهِ يَعْنِي سُكَّانَ اللَّهِ وَمَنْ سِوَى أَهْلِ مَكَّةَ كَانُوا يَقِفُونَ بِعَرَفَاتٍ ‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى‏:‏ ‏(‏ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ ‏)‏ ‏.‏ وَالْحُمْسُ هُمْ أَهْلُ الْحَرَمِ ‏.‏","v":[]}],"201":[{"c":"Sahih Bukhari","r":"Hadith 4522","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4522","x":"Narrated Anas:\n\nThe Prophet (ﷺ) used to say, \"O Allah! Our Lord! Give us in this world that, which is good and in the Hereafter that, which is good and save us from the torment of the Fire.\" (2.201)","ar":"حَدَّثَنَا أَبُو مَعْمَرٍ، حَدَّثَنَا عَبْدُ الْوَارِثِ، عَنْ عَبْدِ الْعَزِيزِ، عَنْ أَنَسٍ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم يَقُولُ ‏\n\n\"‏ اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6389","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6389","x":"Narrated Anas:\n\nThe most frequent invocation of The Prophet (ﷺ) was: \"O Allah! Give to us in the world that which is good and in the Hereafter that which is good, and save us from the torment of the Fire.\" (2.201)","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا عَبْدُ الْوَارِثِ، عَنْ عَبْدِ الْعَزِيزِ، عَنْ أَنَسٍ، قَالَ كَانَ أَكْثَرُ دُعَاءِ النَّبِيِّ صلى الله عليه وسلم ‏\n\n\"‏ اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ ‏\"\n\n‏‏.‏","v":[]}],"203":[{"c":"Sunan Ibn Majah","r":"Volume 4, Book 25, Hadith 3015","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-25/Hadith-3015","x":"Sufyan bin Bukair bin ‘Ata’ said:\n\n\"I heard ‘Abdur-Rahman bin Ya’mur Dili say: ‘I saw the Messenger of Allah (ﷺ) when he was standing at ‘Arafat, and some people from Najd came to him and said: \"O Messenger of Allah, what is Hajj?\" He said: \"Hajj is ‘Arafah. Whoever comes before Fajr prayer on the night of Jam’, he has completed his Hajj. The days at Mina are three. ‘But whosoever hastens to leave in two days, there is no sin on him and whosoever stays on, there is no sin on him.’\" [2:203] Then he seated a man behind him on his mount and he started calling out these words.’\" Another chain reports a similar hadith.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَعَلِيُّ بْنُ مُحَمَّدٍ، قَالاَ حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا سُفْيَانُ، عَنْ بُكَيْرِ بْنِ عَطَاءٍ، سَمِعْتُ عَبْدَ الرَّحْمَنِ بْنَ يَعْمُرَ الدِّيلِيَّ، قَالَ شَهِدْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ وَهُوَ وَاقِفٌ بِعَرَفَةَ وَأَتَاهُ نَاسٌ مِنْ أَهْلِ نَجْدٍ فَقَالُوا يَا رَسُولَ اللَّهِ كَيْفَ الْحَجُّ قَالَ ‏\n\n\"‏ الْحَجُّ عَرَفَةُ فَمَنْ جَاءَ قَبْلَ صَلاَةِ الْفَجْرِ لَيْلَةَ جَمْعٍ فَقَدْ تَمَّ حَجُّهُ أَيَّامُ مِنًى ثَلاَثَةٌ فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلاَ إِثْمَ عَلَيْهِ ‏\"\n\n‏ ‏.‏ ثُمَّ أَرْدَفَ رَجُلاً خَلْفَهُ فَجَعَلَ يُنَادِي بِهِنَّ ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَنْبَأَنَا الثَّوْرِيُّ، عَنْ بُكَيْرِ بْنِ عَطَاءٍ اللَّيْثِيِّ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَعْمُرَ الدِّيلِيِّ، قَالَ أَتَيْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ بِعَرَفَةَ فَجَاءَهُ نَفَرٌ مِنْ أَهْلِ نَجْدٍ فَذَكَرَ نَحْوَهُ ‏.‏ قَالَ مُحَمَّدُ بْنُ يَحْيَى مَا أُرَى لِلثَّوْرِيِّ حَدِيثًا أَشْرَفَ مِنْهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2975","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2975","x":"Narrated 'Abdur-Rahman bin Ya'mar:\n\nthat the Messenger of Allah (ﷺ) said: \"The Hajj is 'Arafat, the Hajj is 'Arafat, the Hajj is 'Arafat. The days of Mina are three: But whoever hastens to leave in two days, there is no sin on him, and whoever stays on, there is no sin on him (2:203). And whoever sees (attends) the 'Arafah before the rising of Fajr, then he has performed the Hajj.\" Ibn Abi 'Umar said: \"Sufyan bin 'Uyainah said: 'This is the best Hadith that Ath-Thawri reported.'\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ سُفْيَانَ الثَّوْرِيِّ، عَنْ بُكَيْرِ بْنِ عَطَاءٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَعْمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ الْحَجُّ عَرَفَاتٌ الْحَجُّ عَرَفَاتٌ الْحَجُّ عَرَفَاتٌ أَيَّامُ مِنًى ثَلاَثٌ ‏:‏ ‏(‏فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلاَ إِثْمَ عَلَيْهِ ‏)‏ وَمَنْ أَدْرَكَ عَرَفَةَ قَبْلَ أَنْ يَطْلُعَ الْفَجْرُ فَقَدْ أَدْرَكَ الْحَجَّ ‏\"‏ ‏.‏ قَالَ ابْنُ أَبِي عُمَرَ قَالَ سُفْيَانُ بْنُ عُيَيْنَةَ وَهَذَا أَجْوَدُ حَدِيثٍ رَوَاهُ الثَّوْرِيُّ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَرَوَاهُ شُعْبَةُ عَنْ بُكَيْرِ بْنِ عَطَاءٍ وَلاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ بُكَيْرِ بْنِ عَطَاءٍ ‏.‏","v":[]}],"214":[{"c":"Sahih Bukhari","r":"Hadith 4524","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4524","x":"Narrated Ibn Abu Mulaika:\n\nIbn `Abbas recited: \"(Respite will be granted) until when the Apostles gave up hope (of their people) and thought that they were denied (by their people). There came to them Our Help....\" (12.110) reading Kudhibu without doubling the sound 'dh', and that was what he understood of the Verse. Then he went on reciting: \"..even the Apostle and those who believed along with him said: When (will come) Allah's Help? Yes, verily, Allah's Help is near.\" (2.214) Then I met `Urwa bin Az-Zubair and I mentioned that to him. He said, \"Aisha said, 'Allah forbid! By Allah, Allah never promised His Apostle anything but he knew that it would certainly happen before he died. But trials were continuously presented before the Apostles till they were afraid that their followers would accuse them of telling lies. So I used to recite:-- \"Till they (come to) think that they were treated as liars.\" reading 'Kudh-dhibu with double 'dh.'","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى، أَخْبَرَنَا هِشَامٌ، عَنِ ابْنِ جُرَيْجٍ، قَالَ سَمِعْتُ ابْنَ أَبِي مُلَيْكَةَ، يَقُولُ قَالَ ابْنُ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏حَتَّى إِذَا اسْتَيْأَسَ الرُّسُلُ وَظَنُّوا أَنَّهُمْ قَدْ كُذِبُوا‏}‏ خَفِيفَةً، ذَهَبَ بِهَا هُنَاكَ، وَتَلاَ ‏{‏حَتَّى يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَى نَصْرُ اللَّهِ أَلاَ إِنَّ نَصْرَ اللَّهِ قَرِيبٌ‏}‏ فَلَقِيتُ عُرْوَةَ بْنَ الزُّبَيْرِ فَذَكَرْتُ لَهُ ذَلِكَ فَقَالَ قَالَتْ عَائِشَةُ مَعَاذَ اللَّهِ، وَاللَّهِ مَا وَعَدَ اللَّهُ رَسُولَهُ مِنْ شَىْءٍ قَطُّ إِلاَّ عَلِمَ أَنَّهُ كَائِنٌ قَبْلَ أَنْ يَمُوتَ، وَلَكِنْ لَمْ يَزَلِ الْبَلاَءُ بِالرُّسُلِ حَتَّى خَافُوا أَنْ يَكُونَ مَنْ مَعَهُمْ يُكَذِّبُونَهُمْ، فَكَانَتْ تَقْرَؤُهَا ‏{‏وَظَنُّوا أَنَّهُمْ قَدْ كُذِّبُوا‏}‏ مُثَقَّلَةً‏.‏","v":[]}],"216":[{"c":"Sahih Bukhari","r":"Hadith 2785","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2785","x":"Narrated Abu Huraira:\n\nA man came to Allah's Messenger (ﷺ) and said, \"Instruct me as to such a deed as equals Jihad (in reward).\" He replied, \"I do not find such a deed.\" Then he added, \"Can you, while the Muslim fighter is in the battle-field, enter your mosque to perform prayers without cease and fast and never break your fast?\" The man said, \"But who can do that?\" Abu- Huraira added, \"The Mujahid (i.e. Muslim fighter) is rewarded even for the footsteps of his horse while it wanders bout (for grazing) tied in a long rope.\"","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ مَنْصُورٍ، أَخْبَرَنَا عَفَّانُ، حَدَّثَنَا هَمَّامٌ، حَدَّثَنَا مُحَمَّدُ بْنُ جُحَادَةَ، قَالَ أَخْبَرَنِي أَبُو حَصِينٍ، أَنَّ ذَكْوَانَ، حَدَّثَهُ أَنَّ أَبَا هُرَيْرَةَ ـ رضى الله عنه ـ حَدَّثَهُ قَالَ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ دُلَّنِي عَلَى عَمَلٍ يَعْدِلُ الْجِهَادَ‏.‏ قَالَ ‏\n\n\"‏ لاَ أَجِدُهُ ـ قَالَ ـ هَلْ تَسْتَطِيعُ إِذَا خَرَجَ الْمُجَاهِدُ أَنْ تَدْخُلَ مَسْجِدَكَ فَتَقُومَ وَلاَ تَفْتُرَ وَتَصُومَ وَلاَ تُفْطِرَ ‏\"\n\n‏‏.‏ قَالَ وَمَنْ يَسْتَطِيعُ ذَلِكَ قَالَ أَبُو هُرَيْرَةَ إِنَّ فَرَسَ الْمُجَاهِدِ لَيَسْتَنُّ فِي طِوَلِهِ فَيُكْتَبُ لَهُ حَسَنَاتٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2787","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2787","x":"Narrated Abu Huraira:\n\nI heard Allah's Messenger (ﷺ) saying, \"The example of a Mujahid in Allah's Cause-- and Allah knows better who really strives in His Cause----is like a person who fasts and prays continuously. Allah guarantees that He will admit the Mujahid in His Cause into Paradise if he is killed, otherwise He will return him to his home safely with rewards and war booty.\"","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، أَنَّ أَبَا هُرَيْرَةَ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\n\n\"‏ مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ ـ وَاللَّهُ أَعْلَمُ بِمَنْ يُجَاهِدُ فِي سَبِيلِهِ ـ كَمَثَلِ الصَّائِمِ الْقَائِمِ، وَتَوَكَّلَ اللَّهُ لِلْمُجَاهِدِ فِي سَبِيلِهِ بِأَنْ يَتَوَفَّاهُ أَنْ يُدْخِلَهُ الْجَنَّةَ، أَوْ يَرْجِعَهُ سَالِمًا مَعَ أَجْرٍ أَوْ غَنِيمَةٍ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2790","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2790","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"Whoever believes in Allah and His Apostle, offer prayer perfectly and fasts the month of Ramadan, will rightfully be granted Paradise by Allah, no matter whether he fights in Allah's Cause or remains in the land where he is born.\" The people said, \"O Allah's Messenger (ﷺ) ! Shall we acquaint the people with the is good news?\" He said, \"Paradise has one-hundred grades which Allah has reserved for the Mujahidin who fight in His Cause, and the distance between each of two grades is like the distance between the Heaven and the Earth. So, when you ask Allah (for something), ask for Al-firdaus which is the best and highest part of Paradise.\" (i.e. The sub-narrator added, \"I think the Prophet also said, 'Above it (i.e. Al-Firdaus) is the Throne of Beneficent (i.e. Allah), and from it originate the rivers of Paradise.\")","ar":"حَدَّثَنَا يَحْيَى بْنُ صَالِحٍ، حَدَّثَنَا فُلَيْحٌ، عَنْ هِلاَلِ بْنِ عَلِيٍّ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَنْ آمَنَ بِاللَّهِ وَبِرَسُولِهِ وَأَقَامَ الصَّلاَةَ وَصَامَ رَمَضَانَ، كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ جَاهَدَ فِي سَبِيلِ اللَّهِ، أَوْ جَلَسَ فِي أَرْضِهِ الَّتِي وُلِدَ فِيهَا ‏\"‏‏.‏ فَقَالُوا يَا رَسُولَ اللَّهِ أَفَلاَ نُبَشِّرُ النَّاسَ‏.‏ قَالَ ‏\"‏ إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِ اللَّهِ، مَا بَيْنَ الدَّرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، فَإِذَا سَأَلْتُمُ اللَّهَ فَاسْأَلُوهُ الْفِرْدَوْسَ، فَإِنَّهُ أَوْسَطُ الْجَنَّةِ وَأَعْلَى الْجَنَّةِ، أُرَاهُ فَوْقَهُ عَرْشُ الرَّحْمَنِ، وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ ‏\"‏‏.‏ قَالَ مُحَمَّدُ بْنُ فُلَيْحٍ عَنْ أَبِيهِ ‏\"‏ وَفَوْقَهُ عَرْشُ الرَّحْمَنِ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2795","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2795","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) said, \"Nobody who dies and finds good from Allah (in the Hereafter) would wish to come back to this world even if he were given the whole world and whatever is in it, except the martyr who, on seeing the superiority of martyrdom, would like to come back to the world and get killed again (in Allah's Cause).\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا مُعَاوِيَةُ بْنُ عَمْرٍو، حَدَّثَنَا أَبُو إِسْحَاقَ، عَنْ حُمَيْدٍ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ مَا مِنْ عَبْدٍ يَمُوتُ لَهُ عِنْدَ اللَّهِ خَيْرٌ، يَسُرُّهُ أَنْ يَرْجِعَ إِلَى الدُّنْيَا، وَأَنَّ لَهُ الدُّنْيَا وَمَا فِيهَا، إِلاَّ الشَّهِيدَ، لِمَا يَرَى مِنْ فَضْلِ الشَّهَادَةِ، فَإِنَّهُ يَسُرُّهُ أَنْ يَرْجِعَ إِلَى الدُّنْيَا فَيُقْتَلَ مَرَّةً أُخْرَى ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2796","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2796","x":"Narrated Anas:\n\nThe Prophet (ﷺ) said, \"A single endeavor (of fighting) in Allah's Cause in the afternoon or in the forenoon is better than all the world and whatever is in it. A place in Paradise as small as the bow or lash of one of you is better than all the world and whatever is in it. And if a houri from Paradise appeared to the people of the earth, she would fill the space between Heaven and the Earth with light and pleasant scent and her head cover is better than the world and whatever is in it.\"","ar":"وَسَمِعْتُ أَنَسَ بْنَ مَالِكٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم ‏\n\n\"‏ لَرَوْحَةٌ فِي سَبِيلِ اللَّهِ أَوْ غَدْوَةٌ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَلَقَابُ قَوْسِ أَحَدِكُمْ مِنَ الْجَنَّةِ أَوْ مَوْضِعُ قِيدٍ ـ يَعْنِي سَوْطَهُ ـ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَلَوْ أَنَّ امْرَأَةً مِنْ أَهْلِ الْجَنَّةِ اطَّلَعَتْ إِلَى أَهْلِ الأَرْضِ لأَضَاءَتْ مَا بَيْنَهُمَا وَلَمَلأَتْهُ رِيحًا، وَلَنَصِيفُهَا عَلَى رَأْسِهَا خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2817","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2817","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) said, \"Nobody who enters Paradise likes to go back to the world even if he got everything on the earth, except a Mujahid who wishes to return to the world so that he may be martyred ten times because of the dignity he receives (from Allah).\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا غُنْدَرٌ، حَدَّثَنَا شُعْبَةُ، قَالَ سَمِعْتُ قَتَادَةَ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ مَا أَحَدٌ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَلَهُ مَا عَلَى الأَرْضِ مِنْ شَىْءٍ، إِلاَّ الشَّهِيدُ، يَتَمَنَّى أَنْ يَرْجِعَ إِلَى الدُّنْيَا فَيُقْتَلَ عَشْرَ مَرَّاتٍ، لِمَا يَرَى مِنَ الْكَرَامَةِ ‏\"\n\n‏‏.‏","v":[]}],"219":[{"c":"Sunan Abu Dawud","r":"Hadith 3677","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3677","x":"Narrated An-Nu'man ibn Bashir:\n\nI heard the Messenger of Allah (ﷺ) say: Wine is made from grape-syrup, raisins, dried dates, wheat, barley, millet, and I forbid you from every intoxicant.","ar":"حَدَّثَنَا مَالِكُ بْنُ عَبْدِ الْوَاحِدِ أَبُو غَسَّانَ، حَدَّثَنَا مُعْتَمِرٌ، قَالَ قَرَأْتُ عَلَى الْفُضَيْلِ بْنِ مَيْسَرَةَ عَنْ أَبِي حَرِيزٍ، أَنَّ عَامِرًا، حَدَّثَهُ أَنَّ النُّعْمَانَ بْنَ بَشِيرٍ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\n\n\"‏ إِنَّ الْخَمْرَ مِنَ الْعَصِيرِ وَالزَّبِيبِ وَالتَّمْرِ وَالْحِنْطَةِ وَالشَّعِيرِ وَالذُّرَةِ وَإِنِّي أَنْهَاكُمْ عَنْ كُلِّ مُسْكِرٍ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 3678","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3678","x":"Abu Hurairah b. Bashir reported the Apostel of Allah (ﷺ)as saying:\n\nWine comes from these two trees, the date-palm and the grapes-vine. Abu Dawud said : The name of Abu KAthir al-Ubari is Yazid b. ‘Abd al-Rahman b. Ghufailat al-Sahmi. Some said: Uzainah. What is correct is Ghufailah.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبَانُ، حَدَّثَنِي يَحْيَى، عَنْ أَبِي كَثِيرٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏\"\n\n‏ ‏.‏ قَالَ أَبُو دَاوُدَ اسْمُ أَبِي كَثِيرٍ الْغُبَرِيِّ يَزِيدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ غُفَيْلَةَ السَّحْمِيُّ ‏.‏ وَقَالَ بَعْضُهُمْ أُذَيْنَةُ وَالصَّوَابُ غُفَيْلَةُ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 3680","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-3680","x":"Narrated Abdullah Ibn Abbas:\n\nThe Messenger of Allah (ﷺ) said: Every intoxicant is khamr (wine) and every intoxicant is forbidden. If anyone drinks wine, Allah will not accept prayer from him for forty days, but if he repents, Allah will accept his repentance. If he repeats it a fourth time, it is binding on Allah that He will give him tinat al-khabal to drink. He was asked: What is tinat al-khabal, Messenger of Allah? He replied: Discharge of wounds, flowing from the inhabitants of Hell. If anyone serves it to a minor who does not distinguish between the lawful and the unlawful, it is binding on Allah that He will give him to drink the discharge of wounds, flowing from the inhabitants of Hell.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ رَافِعٍ النَّيْسَابُورِيُّ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ عُمَرَ الصَّنْعَانِيُّ، قَالَ سَمِعْتُ النُّعْمَانَ، يَقُولُ عَنْ طَاوُسٍ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ كُلُّ مُخَمِّرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ وَمَنْ شَرِبَ مُسْكِرًا بُخِسَتْ صَلاَتُهُ أَرْبَعِينَ صَبَاحًا فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ فَإِنْ عَادَ الرَّابِعَةَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ ‏\"‏ ‏.‏ قِيلَ وَمَا طِينَةُ الْخَبَالِ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ صَدِيدُ أَهْلِ النَّارِ وَمَنْ سَقَاهُ صَغِيرًا لاَ يَعْرِفُ حَلاَلَهُ مِنْ حَرَامِهِ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ ‏\"‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 242","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-242","x":"Narrated Aisha:\n\nThe Prophet (ﷺ) said, \"All drinks that produce intoxication are Haram (forbidden to drink).","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنَا سُفْيَانُ، قَالَ حَدَّثَنَا الزُّهْرِيُّ، عَنْ أَبِي سَلَمَةَ، عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ كُلُّ شَرَابٍ أَسْكَرَ فَهُوَ حَرَامٌ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2316","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2316","x":"Narrated `Uqba bin Al-Harith:\n\nWhen An-Nuaman or his son was brought in a state of drunkenness, Allah's Messenger (ﷺ) ordered all those who were present in the house to beat him. I was one of those who beat him. We beat him with shoes and palm-leaf stalks.","ar":"حَدَّثَنَا ابْنُ سَلاَمٍ، أَخْبَرَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ، عَنْ أَيُّوبَ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، عَنْ عُقْبَةَ بْنِ الْحَارِثِ، قَالَ جِيءَ بِالنُّعَيْمَانِ أَوِ ابْنِ النُّعَيْمَانِ شَارِبًا، فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم مَنْ كَانَ فِي الْبَيْتِ أَنْ يَضْرِبُوا قَالَ فَكُنْتُ أَنَا فِيمَنْ ضَرَبَهُ، فَضَرَبْنَاهُ بِالنِّعَالِ وَالْجَرِيدِ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3049","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3049","x":"Narrated 'Amr bin Shurahbil [Abu Maisarah]:\n\nfrom 'Umar bin Al-Khattab, that he said: \"O Allah! Make the verdict concerning Khamr sufficiently clear for us!\" So (the Ayah) in Al-Baqarah was revealed: They ask you concerning Khamr and gambling. Say: \"In them is a great sin (2:219).\" So 'Umar was called, and it was recited to him, so he said: \"O Allah! Make the verdict concerning Khamr sufficiently clear for us!\" So (the Ayah) in An-Nisa was revealed: 'O you who believe! Approach not As-Salat while you are in a drunken state (4:43).' So 'Umar was called and it was recited him, so he said \"O Allah! Make the verdict concerning Khamr sufficiently clear for us!\" So (the Ayah) in Al-Ma'idah was revealed: Shaitan only wants to excite enmity and hatred between you with Khamr and gambling...' up to His saying: 'So will you not then abstain (5:91).' So 'Umar was called and it was recited to him, so he said: 'We abstained, we abstained.'\" Abü Maisarah narrated from 'Umar bin Al-Khattab who said: \"0 Allah! Make the verdict concerning Khamr sufficiently clear for us!\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ، أَخْبَرَنَا مُحَمَّدُ بْنُ يُوسُفَ، أَخْبَرَنَا إِسْرَائِيلُ، حَدَّثَنَا أَبُو إِسْحَاقَ، عَنْ عُمَرَ بْنِ شُرَحْبِيلَ أَبِي مَيْسَرَةَ، عَنْ عُمَرَ بْنِ الْخَطَّابِ، أَنَّهُ قَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ فَنَزَلَتِ الَّتِي فِي الْبَقَرَةِ ‏:‏ ‏(‏ يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ ‏)‏ الآيَةَ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ فَقَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ فَنَزَلَتِ الَّتِي فِي النِّسَاءِأَيُّهَا الَّذِينَ آمَنُوا لاَ تَقْرَبُوا الصَّلاَةَ وَأَنْتُمْ سُكَارَى ‏)‏ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ فَقَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ فَنَزَلَتِ الَّتِي فِي الْمَائِدَةِ ‏:‏ ‏(‏ إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ ‏)‏ إِلَى قَوْلِهَِ ( فَهَلْ أَنْتُمْ مُنْتَهُونَ ‏)‏ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ فَقَالَ انْتَهَيْنَا انْتَهَيْنَا ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رُوِيَ عَنْ إِسْرَائِيلَ هَذَا الْحَدِيثُ مُرْسَلٌ ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي مَيْسَرَةَ، عَمْرِو بْنِ شُرَحْبِيلَ أَنَّ عُمَرَ بْنَ الْخَطَّابِ، قَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانَ شِفَاءٍ ‏.‏ فَذَكَرَ نَحْوَهُ وَهَذَا أَصَحُّ مِنْ حَدِيثِ مُحَمَّدِ بْنِ يُوسُفَ ‏.‏","v":[]}],"220":[{"c":"Sunan Abu Dawud","r":"Hadith 2877","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2877","x":"Narrated Buraidah:\n\nA woman came to the Messenger of Allah (ﷺ) and said: I donated my slave-girl to my mother, but she died and left the slave-girl. He said: Your reward became due, and she came back to you in inheritance. She said: She died while a month's fasting was due from her. Would it be sufficient or be taken as completed if I fast on her behalf ? He said: Yes. She said: She also did not perform Hajj. Would it be sufficient or be taken completed if I perform (Hajj) on her behalf ? He said: Yes.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا زُهَيْرٌ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَطَاءٍ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، بُرَيْدَةَ أَنَّ امْرَأَةً، أَتَتْ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَتْ كُنْتُ تَصَدَّقْتُ عَلَى أُمِّي بِوَلِيدَةٍ وَإِنَّهَا مَاتَتْ وَتَرَكَتْ تِلْكَ الْوَلِيدَةَ ‏.‏ قَالَ ‏\"‏ قَدْ وَجَبَ أَجْرُكِ وَرَجَعَتْ إِلَيْكِ فِي الْمِيرَاثِ ‏\"‏ ‏.‏ قَالَتْ وَإِنَّهَا مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ أَفَيُجْزِئُ - أَوْ يَقْضِي - عَنْهَا أَنْ أَصُومَ عَنْهَا قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ قَالَتْ وَإِنَّهَا لَمْ تَحُجَّ أَفَيُجْزِئُ - أَوْ يَقْضِي - عَنْهَا أَنْ أَحُجَّ عَنْهَا قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2767","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2767","x":"Nafi' said:\n\n\"Ibn 'Umar never refused to be appointed as guardian.\" The most beloved thing to Ibn Sirin concerning an orphan's wealth was that the orphan's advisor and guardians would assemble to decide what is best for him. When Tawus was asked about something concerning an orphan's affairs, he would recite: '...And Allah knows him who means mischief from him who means good...' (V 2:220). 'Ata said concerning some orphans, \"The guardian is to provide for the young and the old orphans according to their needs from their shares.\"","ar":"وَقَالَ لَنَا سُلَيْمَانُ حَدَّثَنَا حَمَّادٌ، عَنْ أَيُّوبَ، عَنْ نَافِعٍ، قَالَ مَا رَدَّ ابْنُ عُمَرَ عَلَى أَحَدٍ وَصِيَّةً‏.‏ وَكَانَ ابْنُ سِيرِينَ أَحَبَّ الأَشْيَاءِ إِلَيْهِ فِي مَالِ الْيَتِيمِ أَنْ يَجْتَمِعَ إِلَيْهِ نُصَحَاؤُهُ وَأَوْلِيَاؤُهُ فَيَنْظُرُوا الَّذِي هُوَ خَيْرٌ لَهُ‏.‏ وَكَانَ طَاوُسٌ إِذَا سُئِلَ عَنْ شَىْءٍ مِنْ أَمْرِ الْيَتَامَى قَرَأَ ‏{‏وَاللَّهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ‏}‏‏.‏ وَقَالَ عَطَاءٌ فِي يَتَامَى الصَّغِيرُ وَالْكَبِيرُ يُنْفِقُ الْوَلِيُّ عَلَى كُلِّ إِنْسَانٍ بِقَدْرِهِ مِنْ حِصَّتِهِ‏.‏","v":[]}],"222":[{"c":"Sunan Abu Dawud","r":"Hadith 2170","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2170","x":"Abu Sa’id reported \"The people mentioned about withdrawing the penis before the Prophet (ﷺ). He said \"Why one of you does so? He did not say \"One of you should not do so\". Every soul that is to be born, Allaah will create it. Abu Dawud said \"Qaza’ah is a client of Ziyad\"","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ إِسْمَاعِيلَ الطَّالْقَانِيُّ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، عَنْ قَزَعَةَ، عَنْ أَبِي سَعِيدٍ، ذُكِرَ ذَلِكَ عِنْدَ النَّبِيِّ صلى الله عليه وسلم - يَعْنِي الْعَزْلَ - قَالَ ‏\"‏ فَلِمَ يَفْعَلُ أَحَدُكُمْ ‏\"‏ ‏.‏ وَلَمْ يَقُلْ فَلاَ يَفْعَلْ أَحَدُكُمْ ‏\"‏ فَإِنَّهُ لَيْسَتْ مِنْ نَفْسٍ مَخْلُوقَةٍ إِلاَّ اللَّهُ خَالِقُهَا ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ قَزَعَةُ مَوْلَى زِيَادٍ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 298","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-298","x":"Narrated Um Salama:\n\nWhile I was laying with the Prophet (ﷺ) under a single woolen sheet, I got the menses. I slipped away and put on the clothes for menses. He said, \"Have you got \"Nifas\" (menses)?\" I replied, \"Yes.\" He then called me and made me lie with him under the same sheet.","ar":"حَدَّثَنَا الْمَكِّيُّ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا هِشَامٌ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، عَنْ أَبِي سَلَمَةَ، أَنَّ زَيْنَبَ ابْنَةَ أُمِّ سَلَمَةَ، حَدَّثَتْهُ أَنَّ أُمَّ سَلَمَةَ حَدَّثَتْهَا قَالَتْ، بَيْنَا أَنَا مَعَ النَّبِيِّ، صلى الله عليه وسلم مُضْطَجِعَةً فِي خَمِيصَةٍ إِذْ حِضْتُ، فَانْسَلَلْتُ فَأَخَذْتُ ثِيَابَ حِيضَتِي قَالَ ‏\n\n\"‏ أَنُفِسْتِ ‏\"\n\n‏‏.‏ قُلْتُ نَعَمْ‏.‏ فَدَعَانِي فَاضْطَجَعْتُ مَعَهُ فِي الْخَمِيلَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 322","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-322","x":"Narrated Zainab bint Abi Salama:\n\nUm-Salama said, \"I got my menses while I was lying with the Prophet (ﷺ) under a woolen sheet. So I slipped away, took the clothes for menses and put them on. Allah's Messenger (ﷺ) said, 'Have you got your menses?' I replied, 'Yes.' Then he called me and took me with him under the woolen sheet.\" Um Salama further said, \"The Prophet (ﷺ) used to kiss me while he was fasting. The Prophet (ﷺ) and I used to take the bath of Janaba from a single pot.\"","ar":"حَدَّثَنَا سَعْدُ بْنُ حَفْصٍ، قَالَ حَدَّثَنَا شَيْبَانُ، عَنْ يَحْيَى، عَنْ أَبِي سَلَمَةَ، عَنْ زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ، حَدَّثَتْهُ أَنَّ أُمَّ سَلَمَةَ قَالَتْ حِضْتُ وَأَنَا مَعَ النَّبِيِّ، صلى الله عليه وسلم فِي الْخَمِيلَةِ، فَانْسَلَلْتُ فَخَرَجْتُ مِنْهَا، فَأَخَذْتُ ثِيَابَ حِيضَتِي فَلَبِسْتُهَا، فَقَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ أَنُفِسْتِ ‏\"\n\n‏‏.‏ قُلْتُ نَعَمْ، فَدَعَانِي فَأَدْخَلَنِي مَعَهُ فِي الْخَمِيلَةِ‏.‏ قَالَتْ وَحَدَّثَتْنِي أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يُقَبِّلُهَا وَهُوَ صَائِمٌ، وَكُنْتُ أَغْتَسِلُ أَنَا وَالنَّبِيُّ صلى الله عليه وسلم مِنْ إِنَاءٍ وَاحِدٍ مِنَ الْجَنَابَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 323","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-323","x":"Narrated Um Salama:\n\nWhile I was lying with the Prophet (ﷺ) under a woolen sheet, I got my menses. I slipped away and put on the clothes for menses. The Prophet (ﷺ) said, \"Have you got your menses?\" I replied, \"Yes.\" He called me and I slept with him under the woolen sheet.","ar":"حَدَّثَنَا مُعَاذُ بْنُ فَضَالَةَ، قَالَ حَدَّثَنَا هِشَامٌ، عَنْ يَحْيَى، عَنْ أَبِي سَلَمَةَ، عَنْ زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ، قَالَتْ بَيْنَا أَنَا مَعَ النَّبِيِّ، صلى الله عليه وسلم مُضْطَجِعَةً فِي خَمِيلَةٍ حِضْتُ، فَانْسَلَلْتُ فَأَخَذْتُ ثِيَابَ حِيضَتِي فَقَالَ ‏\n\n\"‏ أَنُفِسْتِ ‏\"\n\n‏‏.‏ فَقُلْتُ نَعَمْ‏.‏ فَدَعَانِي فَاضْطَجَعْتُ مَعَهُ فِي الْخَمِيلَةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1929","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1929","x":"Narrated Zainab:\n\n(daughter of Um Salama) that her mother said, \"While I was (lying) with Allah's Messenger (ﷺ) underneath a woolen sheet, I got the menstruation, and then slipped away and put on the clothes (which I used to wear) in menses. He asked, \"What is the matter? Did you get your menses?\" I replied in the affirmative and then entered underneath that woolen sheet. I and Allah's Messenger (ﷺ) used to take a bath from one water pot and he used to kiss me while he was fasting.\"","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ هِشَامِ بْنِ أَبِي عَبْدِ اللَّهِ، حَدَّثَنَا يَحْيَى بْنُ أَبِي كَثِيرٍ، عَنْ أَبِي سَلَمَةَ، عَنْ زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ، عَنْ أُمِّهَا ـ رضى الله عنهما ـ قَالَتْ بَيْنَمَا أَنَا مَعَ، رَسُولِ اللَّهِ صلى الله عليه وسلم فِي الْخَمِيلَةِ إِذْ حِضْتُ فَانْسَلَلْتُ، فَأَخَذْتُ ثِيَابَ حِيضَتِي فَقَالَ ‏\n\n\"‏ مَا لَكِ أَنُفِسْتِ ‏\"\n\n‏‏.‏ قُلْتُ نَعَمْ‏.‏ فَدَخَلْتُ مَعَهُ فِي الْخَمِيلَةِ، وَكَانَتْ هِيَ وَرَسُولُ اللَّهِ صلى الله عليه وسلم يَغْتَسِلاَنِ مِنْ إِنَاءٍ وَاحِدٍ، وَكَانَ يُقَبِّلُهَا وَهُوَ صَائِمٌ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2030","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2030","x":"Narrated `Aisha:\n\nThe Prophet (ﷺ) used to embrace me during my menses. He also used to put his head out of the mosque while he was in I`tikaf, and I would wash it during my menses.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنْ مَنْصُورٍ، عَنْ إِبْرَاهِيمَ، عَنِ الأَسْوَدِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ كَانَ النَّبِيُّ صلى الله عليه وسلم يُبَاشِرُنِي وَأَنَا حَائِضٌ‏.‏ وَكَانَ يُخْرِجُ رَأْسَهُ مِنَ الْمَسْجِدِ وَهْوَ مُعْتَكِفٌ فَأَغْسِلُهُ وَأَنَا حَائِضٌ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 302","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-302","x":"Thabit narrated it from Anas:\n\nAmong the Jews, when a woman menstruated, they did not dine with her, nor did they live with them in their houses; so the Companions of the Apostle (ﷺ) asked The Apostle (ﷺ), and Allah, the Exalted revealed:\" And they ask you about menstruation; say it is a pollution, so keep away from woman during menstruation\" to the end (Qur'an, ii. 222). The Messenger of Allah (ﷺ) said: Do everything except intercourse. The Jews heard of that and said: This man does not want to leave anything we do without opposing us in it. Usaid b. Hudair and Abbad b. Bishr came and said: Messenger of Allah, the Jews say such and such thing. We should not have, therefore, any contactwith them (as the Jews do). The face of the Messenger of Allah (way peace be upon him) underwent such a change that we thought he was angry with them, but when they went out, they happened to receive a gift of milk which was sent to the Messenger of Allah (ﷺ). He (the Holy Prophet) called for them and gave them drink, whereby they knew that he was not angry with them.","ar":"وَحَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، حَدَّثَنَا ثَابِتٌ، عَنْ أَنَسٍ، أَنَّ الْيَهُودَ، كَانُوا إِذَا حَاضَتِ الْمَرْأَةُ فِيهِمْ لَمْ يُؤَاكِلُوهَا وَلَمْ يُجَامِعُوهُنَّ فِي الْبُيُوتِ فَسَأَلَ أَصْحَابُ النَّبِيِّ صلى الله عليه وسلم النَّبِيَّ صلى الله عليه وسلم فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏ وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ‏}‏ إِلَى آخِرِ الآيَةِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ اصْنَعُوا كُلَّ شَىْءٍ إِلاَّ النِّكَاحَ ‏\"‏ ‏.‏ فَبَلَغَ ذَلِكَ الْيَهُودَ فَقَالُوا مَا يُرِيدُ هَذَا الرَّجُلُ أَنْ يَدَعَ مِنْ أَمْرِنَا شَيْئًا إِلاَّ خَالَفَنَا فِيهِ فَجَاءَ أُسَيْدُ بْنُ حُضَيْرٍ وَعَبَّادُ بْنُ بِشْرٍ فَقَالاَ يَا رَسُولَ اللَّهِ إِنَّ الْيَهُودَ تَقُولُ كَذَا وَكَذَا ‏.‏ فَلاَ نُجَامِعُهُنَّ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم حَتَّى ظَنَنَّا أَنْ قَدْ وَجَدَ عَلَيْهِمَا فَخَرَجَا فَاسْتَقْبَلَهُمَا هَدِيَّةٌ مِنْ لَبَنٍ إِلَى النَّبِيِّ صلى الله عليه وسلم فَأَرْسَلَ فِي آثَارِهِمَا فَسَقَاهُمَا فَعَرَفَا أَنْ لَمْ يَجِدْ عَلَيْهِمَا ‏.‏","v":[]},{"c":"Sunan an-Nasa'i","r":"Volume 1, Book 3, Hadith 369","u":"https://quranx.com/Hadith/Nasai/DarusSalam/Volume-1/Book-3/Hadith-369","x":"It was narrated that Anas said:\n\n\"When one of their womenfolk menstruated, the Jews would not eat or drink with them, or mix with them in their houses. They (the Companions) asked the Prophet of Allah (ﷺ) about that, and Allah, the Mighty and Sublime, revealed the Ayah: They ask you concerning menstruation. Say: \"That is an Adha (a harmful thing).[2] So the Messenger of Allah (ﷺ) commanded them to eat and drink with them (menstruating women) and to mix them in their houses, and to do everything with them except intercourse. The Jews said: 'The Messenger of Allah (ﷺ) does not leave anything of our affairs except he goes against it.' Usaid bin Hudair and 'Abbad bin Bishr went and told the Messenger of Allah (ﷺ) and they said: 'Should we have intercourse with them when they are menstruating?' The expression of the Messenger of Allah (ﷺ) changed greatly until we thought he was angry with them, and they left. Then the Messenger of Allah (ﷺ) received a gift of milk, so he sent someone to bring them back and he gave them some to drink, so we knew that he was not angry with them.\" [1] Al-Baqarah 2:222 [2] Al-Baqarah 2:222","ar":"أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا سُلَيْمَانُ بْنُ حَرْبٍ، قَالَ حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، قَالَ كَانَتِ الْيَهُودُ إِذَا حَاضَتِ الْمَرْأَةُ مِنْهُمْ لَمْ يُؤَاكِلُوهُنَّ وَلاَ يُشَارِبُوهُنَّ وَلاَ يُجَامِعُوهُنَّ فِي الْبُيُوتِ فَسَأَلُوا النَّبِيَّ صلى الله عليه وسلم فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى ‏}‏ الآيَةَ فَأَمَرَهُمْ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُؤَاكِلُوهُنَّ وَيُشَارِبُوهُنَّ وَيُجَامِعُوهُنَّ فِي الْبُيُوتِ وَأَنْ يَصْنَعُوا بِهِنَّ كُلَّ شَىْءٍ مَا خَلاَ الْجِمَاعَ ‏.‏ فَقَالَتِ الْيَهُودُ مَا يَدَعُ رَسُولُ اللَّهِ صلى الله عليه وسلم شَيْئًا مِنْ أَمْرِنَا إِلاَّ خَالَفَنَا ‏.‏ فَقَامَ أُسَيْدُ بْنُ حُضَيْرٍ وَعَبَّادُ بْنُ بِشْرٍ فَأَخْبَرَا رَسُولَ اللَّهِ صلى الله عليه وسلم قَالاَ أَنُجَامِعُهُنَّ فِي الْمَحِيضِ فَتَمَعَّرَ رَسُولُ اللَّهِ صلى الله عليه وسلم تَمَعُّرًا شَدِيدًا حَتَّى ظَنَنَّا أَنَّهُ قَدْ غَضِبَ فَقَامَا فَاسْتَقْبَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم هَدِيَّةَ لَبَنٍ فَبَعَثَ فِي آثَارِهِمَا فَرَدَّهُمَا فَسَقَاهُمَا فَعُرِفَ أَنَّهُ لَمْ يَغْضَبْ عَلَيْهِمَا ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 1, Book 1, Hadith 135","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-1/Book-1/Hadith-135","x":"Abu Hurairah narrated that :\n\nthe Prophet said: \"Whoever engages in sexual intercourse with a menstruating woman, or a woman in her anus, consults a soothsayer, then he has disbelieved in what was revealed to Muhammad.\"","ar":"حَدَّثَنَا بُنْدَارٌ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، وَعَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، وَبَهْزُ بْنُ أَسَدٍ، قَالُوا حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ حَكِيمٍ الأَثْرَمِ، عَنْ أَبِي تَمِيمَةَ الْهُجَيْمِيِّ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ مَنْ أَتَى حَائِضًا أَوِ امْرَأَةً فِي دُبُرِهَا أَوْ كَاهِنًا فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ صلى الله عليه وسلم ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى لاَ نَعْرِفُ هَذَا الْحَدِيثَ إِلاَّ مِنْ حَدِيثِ حَكِيمٍ الأَثْرَمِ عَنْ أَبِي تَمِيمَةَ الْهُجَيْمِيِّ عَنْ أَبِي هُرَيْرَةَ ‏.‏ وَإِنَّمَا مَعْنَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ عَلَى التَّغْلِيظِ ‏.‏ وَقَدْ رُوِيَ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ مَنْ أَتَى حَائِضًا فَلْيَتَصَدَّقْ بِدِينَارٍ ‏\"‏ ‏.‏ فَلَوْ كَانَ إِتْيَانُ الْحَائِضِ كُفْرًا لَمْ يُؤْمَرْ فِيهِ بِالْكَفَّارَةِ ‏.‏ وَضَعَّفَ مُحَمَّدٌ هَذَا الْحَدِيثَ مِنْ قِبَلِ إِسْنَادِهِ ‏.‏ وَأَبُو تَمِيمَةَ الْهُجَيْمِيُّ اسْمُهُ طَرِيفُ بْنُ مُجَالِدٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2977","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2977","x":"Narrated Anas:\n\n\"When the women among the Jews menstruated, they would not eat with them, nor drink with them, nor mingle with them in their homes. The Prophet (ﷺ) was asked about that, so Allah, Blessed and Most High, revealed: \"They ask you about menstruation. Say It is a Adha (harmful matter) (2:222).' So the Messenger of Allah (ﷺ) told them to eat with them, drink with them and to remain in the house with them, and to do everything besides intercourse with them. The Jews said: 'He does not want to leave any matter of ours without opposing us in it.'\" He said: \"Then 'Abbad bin Bishr and Usaid bin Hudair came to the Messenger of Allah (ﷺ) to inform him about that. They said: 'O Messenger of Allah! Should we not (then) have intercourse with them during their menstruation?' The face of the Messenger of Allah (ﷺ) changed color, until they thought that he was angry with them. So they left, and afterwards the Prophet (ﷺ) was given some milk as a gift, so he sent some of it to them to drink. Then they knew that he was not angry with them.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنِي سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، قَالَ كَانَتِ الْيَهُودُ إِذَا حَاضَتِ امْرَأَةٌ مِنْهُمْ لَمْ يُوَاكِلُوهَا وَلَمْ يُشَارِبُوهَا وَلَمْ يُجَامِعُوهَا فِي الْبُيُوتِ فَسُئِلَ النَّبِيُّ صلى الله عليه وسلم عَنْ ذَلِكَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏يَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى ‏)‏ فَأَمَرَهُمْ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُوَاكِلُوهُنَّ وَيُشَارِبُوهُنَّ وَأَنْ يَكُونُوا مَعَهُنَّ فِي الْبُيُوتِ وَأَنْ يَفْعَلُوا كُلَّ شَيْءٍ مَا خَلاَ النِّكَاحَ فَقَالَتِ الْيَهُودُ مَا يُرِيدُ أَنْ يَدَعَ شَيْئًا مِنْ أَمْرِنَا إِلاَّ خَالَفَنَا فِيهِ ‏.‏ قَالَ فَجَاءَ عَبَّادُ بْنُ بِشْرٍ وَأُسَيْدُ بْنُ حُضَيْرٍ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَخْبَرَاهُ بِذَلِكَ وَقَالاَ يَا رَسُولَ اللَّهِ أَفَلاَ نَنْكِحُهُنَّ فِي الْمَحِيضِ فَتَمَعَّرَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم حَتَّى ظَنَنَّا أَنَّهُ قَدْ غَضِبَ عَلَيْهِمَا فَقَامَا فَاسْتَقْبَلَتْهُمَا هَدِيَّةٌ مِنْ لَبَنٍ فَأَرْسَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي آثَارِهِمَا فَسَقَاهُمَا فَعَلِمْنَا أَنَّهُ لَمْ يَغْضَبْ عَلَيْهِمَا ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"223":[{"c":"Sunan Abu Dawud","r":"Hadith 2168","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2168","x":"Narrated Abdullah ibn Abbas:\n\nThe Prophet (ﷺ) said about a man who has sexual intercourse with a menstruating woman: He should give one or half dinar as sadaqah.","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ شُعْبَةَ، - غَيْرُهُ عَنْ سَعِيدٍ، - حَدَّثَنِي الْحَكَمُ، عَنْ عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ مِقْسَمٍ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم فِي الَّذِي يَأْتِي امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ ‏\n\n\"‏ يَتَصَدَّقُ بِدِينَارٍ أَوْ بِنِصْفِ دِينَارٍ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2169","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2169","x":"Narrated Abdullah ibn Abbas:\n\nIf a man has sexual intercourse (with menstruating woman) during her bleeding, he should give one dinar as sadaqah, and if he does so when bleeding has stopped, he should give half a dinar as sadaqah.","ar":"حَدَّثَنَا عَبْدُ السَّلاَمِ بْنُ مُطَهَّرٍ، حَدَّثَنَا جَعْفَرٌ، - يَعْنِي ابْنَ سُلَيْمَانَ - عَنْ عَلِيِّ بْنِ الْحَكَمِ الْبُنَانِيِّ، عَنْ أَبِي الْحَسَنِ الْجَزَرِيِّ، عَنْ مِقْسَمٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ إِذَا أَصَابَهَا فِي الدَّمِ فَدِينَارٌ وَإِذَا أَصَابَهَا فِي انْقِطَاعِ الدَّمِ فَنِصْفُ دِينَارٍ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4528","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4528","x":"Narrated Jabir:\n\nJews used to say: \"If one has sexual intercourse with his wife from the back, then she will deliver a squint-eyed child.\" So this Verse was revealed:-- \"Your wives are a tilth unto you; so go to your tilth when or how you will.\" (2.223)","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ الْمُنْكَدِرِ، سَمِعْتُ جَابِرًا ـ رضى الله عنه ـ قَالَ كَانَتِ الْيَهُودُ تَقُولُ إِذَا جَامَعَهَا مِنْ وَرَائِهَا جَاءَ الْوَلَدُ أَحْوَلَ‏.‏ فَنَزَلَتْ ‏{‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1435a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1435a","x":"Jabir (Allah be pleased with him) declared that the Jews used to say:\n\nWhen a man has intercourse with his wife through the vagina but being on her back. the child will have squint, so the verse came down:\" Your wives are your tilth; go then unto your tilth as you may desire\" (ii. 223)","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ وَعَمْرٌو النَّاقِدُ - وَاللَّفْظُ لأَبِي بَكْرٍ - قَالُوا حَدَّثَنَا سُفْيَانُ عَنِ ابْنِ الْمُنْكَدِرِ سَمِعَ جَابرًا يَقُولُ كَانَتِ الْيَهُودُ تَقُولُ إِذَا أَتَى الرَّجُلُ امْرَأَتَهُ مِنْ دُبُرِهَا فِي قُبُلِهَا كَانَ الْوَلَدُ أَحْوَلَ فَنَزَلَتْ ‏{‏ نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2978","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2978","x":"Narrated Jabir:\n\n\"The Jews would say: \"Whoever goes into his wife's vagina from behind her, then his children will be cross-eyed.' So Allah revealed: Your wives are a tilth for your, so go to your tilth when or how you will (2:223).\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الأَعْلَى، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، عَنْ حَمَّادِ بْنِ سَلَمَةَ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، نَحْوَهُ بِمَعْنَاهُ ‏.‏ حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ الْمُنْكَدِرِ، سَمِعَ جَابِرًا، يَقُولُ كَانَتِ الْيَهُودُ تَقُولُ مَنْ أَتَى امْرَأَتَهُ فِي قُبُلِهَا مِنْ دُبُرِهَا كَانَ الْوَلَدُ أَحْوَلَ فَنَزَلَتْ ‏:‏ ‏(‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2979","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2979","x":"Narrated Umm Salamah:\n\nfrom the Prophet (SA), regarding: Your wives are a tilth for you, so go to your tilth when or how you will (2:223). [He (ﷺ) said]: \"Meaning one valve.\" [Abu 'Eisa said:] This Hadith is Hasan Sahih. Ibn Khuthaim is 'Abdullãh bin 'Uthmãn bin. Khuthaim. Ibn Sãbit is 'AbdurRahmãn bin 'Abdullah bin Sabit A1-Jumahi Al-Makki, and Hafsah is the daughter of 'Abdur-Rahmãn bin Abi Bakr As-Siddiq (narrators in the chain). And it has been reported as: \"In one hole.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ خُثَيْمٍ، عَنِ ابْنِ سَابِطٍ، عَنْ حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ، عَنْ أُمِّ سَلَمَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم فِي قَوْلِهِ ‏:‏ ‏(‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏)‏ يَعْنِي صِمَامًا وَاحِدًا ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏ وَابْنُ خُثَيْمٍ هُوَ عَبْدُ اللَّهِ بْنُ عُثْمَانَ وَابْنُ سَابِطٍ هُوَ عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ سَابِطٍ الْجُمَحِيُّ الْمَكِّيُّ وَحَفْصَةُ هِيَ بِنْتُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ وَيُرْوَى فِي سِمَامٍ وَاحِدٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2980","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2980","x":"Narrated Ibn 'Abbas:\n\n\"'Umar came to the Messenger of Allah (ﷺ) and said: 'O Messenger of Allah! I am ruined!' He said: 'Why are you ruined?' He said: 'I turned my mount during the night (meaning that he went into his wife from behind).'\" He said: \"So the Messenger of Allah (ﷺ) did not say anything in reply to him. Then Allah revealed this Ayah to the Messenger of Allah (ﷺ): 'Your wives are a tilth for you, so go to your tilth when or how you will (2:223).' From the front, the back, avoiding the anus, and menstruation.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا الْحَسَنُ بْنُ مُوسَى، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ اللَّهِ الأَشْعَرِيُّ، عَنْ جَعْفَرِ بْنِ أَبِي الْمُغِيرَةِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ جَاءَ عُمَرُ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ هَلَكْتُ قَالَ ‏\"‏ وَمَا أَهْلَكَكَ ‏\"‏ ‏.‏ قَالَ حَوَّلْتُ رَحْلِي اللَّيْلَةَ ‏.‏ قَالَ فَلَمْ يَرُدَّ عَلَيْهِ رَسُولُ اللَّهِ صلى الله عليه وسلم شَيْئًا قَالَ فَأَنْزَلَ اللَّهُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم هَذِهِ الآيَةَ ‏:‏ ‏(‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏)‏ أَقْبِلْ وَأَدْبِرْ وَاتَّقِ الدُّبُرَ وَالْحِيضَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ وَيَعْقُوبُ بْنُ عَبْدِ اللَّهِ الأَشْعَرِيُّ هُوَ يَعْقُوبُ الْقُمِّيُّ ‏.‏","v":[]}],"224":[{"c":"Sahih Bukhari","r":"Hadith 2893","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2893","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) said to Abu Talha, \"Choose one of your boy servants to serve me in my expedition to Khaibar.\" So, Abu Talha took me letting me ride behind him while I was a boy nearing the age of puberty. I used to serve Allah's Messenger (ﷺ) when he stopped to rest. I heard him saying repeatedly, \"O Allah! I seek refuge with You from distress and sorrow, from helplessness and laziness, from miserliness and cowardice, from being heavily in debt and from being overcome by men.\" Then we reached Khaibar; and when Allah enabled him to conquer the Fort (of Khaibar), the beauty of Safiya bint Huyai bin Akhtab was described to him. Her husband had been killed while she was a bride. So Allah's Messenger (ﷺ) selected her for himself and took her along with him till we reached a place called Sa`d-AsSahba,' where her menses were over and he took her for his wife. Haris (a kind of dish) was served on a small leather sheet. Then Allah's Messenger (ﷺ) told me to call those who were around me. So, that was the marriage banquet of Allah's Messenger (ﷺ) and Safiya. Then we left for Medina. I saw Allah's Apostle folding a cloak round the hump of the camel so as to make a wide space for Safiya (to sit on behind him) He sat beside his camel letting his knees for Safiya to put her feet on so as to mount the camel. Then, we proceeded till we approached Medina; he looked at Uhud (mountain) and said, \"This is a mountain which loves us and is loved by us.\" Then he looked at Medina and said, \"O Allah! I make the area between its (i.e. Medina's) two mountains a sanctuary as Abraham made Mecca a sanctuary. O Allah! Bless them (i.e. the people of Medina) in their Mudd and Sa (i.e. measures).","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا يَعْقُوبُ، عَنْ عَمْرٍو، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لأَبِي طَلْحَةَ ‏\"‏ الْتَمِسْ غُلاَمًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي حَتَّى أَخْرُجَ إِلَى خَيْبَرَ ‏\"‏‏.‏ فَخَرَجَ بِي أَبُو طَلْحَةَ مُرْدِفِي، وَأَنَا غُلاَمٌ رَاهَقْتُ الْحُلُمَ، فَكُنْتُ أَخْدُمُ رَسُولَ اللَّهِ صلى الله عليه وسلم إِذَا نَزَلَ، فَكُنْتُ أَسْمَعُهُ كَثِيرًا يَقُولُ ‏\"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ ‏\"‏‏.‏ ثُمَّ قَدِمْنَا خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم لِنَفْسِهِ، فَخَرَجَ بِهَا حَتَّى بَلَغْنَا سَدَّ الصَّهْبَاءِ حَلَّتْ، فَبَنَى بِهَا، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى صَفِيَّةَ‏.‏ ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ فَيَضَعُ رُكْبَتَهُ، فَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ حَتَّى تَرْكَبَ، فَسِرْنَا حَتَّى إِذَا أَشْرَفْنَا عَلَى الْمَدِينَةِ نَظَرَ إِلَى أُحُدٍ فَقَالَ ‏\"‏ هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ ‏\"‏‏.‏ ثُمَّ نَظَرَ إِلَى الْمَدِينَةِ فَقَالَ ‏\"‏ اللَّهُمَّ إِنِّي أُحَرِّمُ مَا بَيْنَ لاَبَتَيْهَا بِمِثْلِ مَا حَرَّمَ إِبْرَاهِيمُ مَكَّةَ، اللَّهُمَّ بَارِكْ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ ‏\"‏‏.‏","v":[]}],"225":[{"c":"Sahih Bukhari","r":"Hadith 6663","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6663","x":"Narrated `Aisha:\n\nregarding: 'Allah will not call you to account for that which is unintentional in your oaths...' (2.225) This Verse was revealed concerning such oath formulas as: 'No, by Allah!' and 'Yes, by Allah!' something against his oath due to forgetfulness should he make expiation?). And the Statement of Allah: 'And there is no blame on you if you make a mistake therein.' (33.5) And Allah said:-- '(Moses said to Khadir): Call me not to account for what I forgot.' (18.73)","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى، عَنْ هِشَامٍ، قَالَ أَخْبَرَنِي أَبِي، عَنْ عَائِشَةَ ـ رضى الله عنها ‏{‏لاَ يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ‏}‏ قَالَ قَالَتْ أُنْزِلَتْ فِي قَوْلِهِ لاَ، وَاللَّهِ بَلَى وَاللَّهِ‏.‏","v":[]}],"228":[{"c":"Sunan Abu Dawud","r":"Hadith 2201","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2201","x":"‘Umar bin Al Khattab reported the Apostle of Allaah(ﷺ) as saying \"Actions are to be judged only by intentions and a man will have only what he intended. When one’s emigration is to Allaah and His Apostle, his emigration is to Allaah and His Apostle but his emigration is to a worldly end at which he aims or to a woman whom he marries, his emigration is to that for which he emigrated.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، حَدَّثَنِي يَحْيَى بْنُ سَعِيدٍ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ عَلْقَمَةَ بْنِ وَقَّاصٍ اللَّيْثِيِّ، قَالَ سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2288","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2288","x":"The tradition mentioned above has also been transmitted by Al Sha’bi through a different chain of narrators. This version has \"The husband of Fathima daughter of Qais pronounced her triple divorce. The Prophet (ﷺ) did not allow her to have maintenance and dwelling.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، حَدَّثَنَا سَلَمَةُ بْنُ كُهَيْلٍ، عَنِ الشَّعْبِيِّ، عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، أَنَّ زَوْجَهَا، طَلَّقَهَا ثَلاَثًا فَلَمْ يَجْعَلْ لَهَا النَّبِيُّ صلى الله عليه وسلم نَفَقَةً وَلاَ سُكْنَى ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2289","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2289","x":"Abu Salamah reported on the authority of Fatimah daughter of Qays who said to him that she was the wife of AbuHafs ibn al-Mughirah who divorced her by three pronouncements. She said that she came to the Messenger of Allah (ﷺ) and sought his opinion about her going out from her house. He commanded her to shift to (the house of )Ibn Umm Maktum who was blind. Marwan denied to confirm the tradition of Fatimah about the going out of a divorced woman from her house. Urwah said:\n\nAisha objected to Fatimah daughter of Qays. Abu Dawud said: Salih b. Kaisan, Ibn Juraij, and Shu'aib b. Abi Hamzah -- all of them narrated on the authority of al-Zuhru in a similar way. Abu Dawud said: Shu'aibn b. Abi Hamzah the name of Abu Hamzah is Dinar. He is a client of Ziyad.","ar":"حَدَّثَنَا يَزِيدُ بْنُ خَالِدٍ الرَّمْلِيُّ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي سَلَمَةَ، عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، أَنَّهَا أَخْبَرَتْهُ أَنَّهَا، كَانَتْ عِنْدَ أَبِي حَفْصِ بْنِ الْمُغِيرَةِ وَأَنَّ أَبَا حَفْصِ بْنَ الْمُغِيرَةِ طَلَّقَهَا آخِرَ ثَلاَثِ تَطْلِيقَاتٍ فَزَعَمَتْ أَنَّهَا جَاءَتْ رَسُولَ اللَّهِ صلى الله عليه وسلم فَاسْتَفْتَتْهُ فِي خُرُوجِهَا مِنْ بَيْتِهَا فَأَمَرَهَا أَنْ تَنْتَقِلَ إِلَى ابْنِ أُمِّ مَكْتُومٍ الأَعْمَى فَأَبَى مَرْوَانُ أَنْ يُصَدِّقَ حَدِيثَ فَاطِمَةَ فِي خُرُوجِ الْمُطَلَّقَةِ مِنْ بَيْتِهَا ‏.‏ قَالَ عُرْوَةُ وَأَنْكَرَتْ عَائِشَةُ - رضى الله عنها - عَلَى فَاطِمَةَ بِنْتِ قَيْسٍ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَلِكَ رَوَاهُ صَالِحُ بْنُ كَيْسَانَ وَابْنُ جُرَيْجٍ وَشُعَيْبُ بْنُ أَبِي حَمْزَةَ كُلُّهُمْ عَنِ الزُّهْرِيِّ ‏.‏ قَالَ أَبُو دَاوُدَ وَشُعَيْبُ بْنُ أَبِي حَمْزَةَ وَاسْمُ أَبِي حَمْزَةَ دِينَارٌ وَهُوَ مَوْلَى زِيَادٍ ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 29, Hadith 1232","u":"https://quranx.com/Hadith/Malik/In-Book/Book-29/Hadith-1232","x":"Yahya related to me from Malik from Ibn Shihab that Said ibn al- Musayyab said, \"The idda of the woman who bleeds constantly is a year.\" Malik said, \"What is done among us about a divorced woman whose periods stop when her husband divorces her is that she waits nine months. If she has not had a period in them, she has an idda of three months. If she has a period before the end of the three months, she accepts the period. If another nine months pass without her having a period, she does an idda of three months. If she has a second period before the end of those three months, she accepts the period. If nine months then pass without a period, she does an idda of three months. If she has a third period, the idda of the period is complete. If she does not have a period, she waits three months, and then she is free to marry. Her husband can return to her before she becomes free to marry unless he made her divorce irrevocable.\" Malik said, \"The sunna with us is that when a man divorces his wife and has the option to return to her, and she does part of her idda and then he returns to her and then parts from her before he has had intercourse with her, she does not add to what has passed of her idda. Her husband has wronged himself and erred if he returned to her and had no need of her.\" Malik said, \"What is done among us is that if a woman becomes a muslim while her husband is a kafir and then he becomes muslim, he is entitled to her as long as she is in her idda. If her idda is finished, he has no access to her. If he remarries her after the end of her idda, however, that is not counted as divorce. Islam removed her from him without divorce.\"","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، أَنَّهُ قَالَ عِدَّةُ الْمُسْتَحَاضَةِ سَنَةٌ ‏.‏ قَالَ مَالِكٌ الأَمْرُ عِنْدَنَا فِي الْمُطَلَّقَةِ الَّتِي تَرْفَعُهَا حَيْضَتُهَا حِينَ يُطَلِّقُهَا زَوْجُهَا أَنَّهَا تَنْتَظِرُ تِسْعَةَ أَشْهُرٍ فَإِنْ لَمْ تَحِضْ فِيهِنَّ اعْتَدَّتْ ثَلاَثَةَ أَشْهُرٍ فَإِنْ حَاضَتْ قَبْلَ أَنْ تَسْتَكْمِلَ الأَشْهُرَ الثَّلاَثَةَ اسْتَقْبَلَتِ الْحَيْضَ فَإِنْ مَرَّتْ بِهَا تِسْعَةُ أَشْهُرٍ قَبْلَ أَنْ تَحِيضَ اعْتَدَّتْ ثَلاَثَةَ أَشْهُرٍ فَإِنْ حَاضَتِ الثَّانِيَةَ قَبْلَ أَنْ تَسْتَكْمِلَ الأَشْهُرَ الثَّلاَثَةَ اسْتَقْبَلَتِ الْحَيْضَ فَإِنْ مَرَّتْ بِهَا تِسْعَةُ أَشْهُرٍ قَبْلَ أَنْ تَحِيضَ اعْتَدَّتْ ثَلاَثَةَ أَشْهُرٍ فَإِنْ حَاضَتِ الثَّالِثَةَ كَانَتْ قَدِ اسْتَكْمَلَتْ عِدَّةَ الْحَيْضِ فَإِنْ لَمْ تَحِضِ اسْتَقْبَلَتْ ثَلاَثَةَ أَشْهُرٍ ثُمَّ حَلَّتْ وَلِزَوْجِهَا عَلَيْهَا فِي ذَلِكَ الرَّجْعَةُ قَبْلَ أَنْ تَحِلَّ إِلاَّ أَنْ يَكُونَ قَدْ بَتَّ طَلاَقَهَا ‏.‏ قَالَ مَالِكٌ السُّنَّةُ عِنْدَنَا أَنَّ الرَّجُلَ إِذَا طَلَّقَ امْرَأَتَهُ وَلَهُ عَلَيْهَا رَجْعَةٌ فَاعْتَدَّتْ بَعْضَ عِدَّتِهَا ثُمَّ ارْتَجَعَهَا ثُمَّ فَارَقَهَا قَبْلَ أَنْ يَمَسَّهَا أَنَّهَا لاَ تَبْنِي عَلَى مَا مَضَى مِنْ عِدَّتِهَا وَأَنَّهَا تَسْتَأْنِفُ مِنْ يَوْمَ طَلَّقَهَا عِدَّةً مُسْتَقْبَلَةً وَقَدْ ظَلَمَ زَوْجُهَا نَفْسَهُ وَأَخْطَأَ إِنْ كَانَ ارْتَجَعَهَا وَلاَ حَاجَةَ لَهُ بِهَا ‏.‏ قَالَ مَالِكٌ وَالأَمْرُ عِنْدَنَا أَنَّ الْمَرْأَةَ إِذَا أَسْلَمَتْ وَزَوْجُهَا كَافِرٌ ثُمَّ أَسْلَمَ فَهُوَ أَحَقُّ بِهَا مَا دَامَتْ فِي عِدَّتِهَا فَإِنِ انْقَضَتْ عِدَّتُهَا فَلاَ سَبِيلَ لَهُ عَلَيْهَا وَإِنْ تَزَوَّجَهَا بَعْدَ انْقِضَاءِ عِدَّتِهَا لَمْ يُعَدَّ ذَلِكَ طَلاَقًا وَإِنَّمَا فَسَخَهَا مِنْهُ الإِسْلاَمُ بِغَيْرِ طَلاَقٍ ‏.‏","v":[]}],"229":[{"c":"Sunan Abu Dawud","r":"Hadith 2201","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2201","x":"‘Umar bin Al Khattab reported the Apostle of Allaah(ﷺ) as saying \"Actions are to be judged only by intentions and a man will have only what he intended. When one’s emigration is to Allaah and His Apostle, his emigration is to Allaah and His Apostle but his emigration is to a worldly end at which he aims or to a woman whom he marries, his emigration is to that for which he emigrated.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، حَدَّثَنِي يَحْيَى بْنُ سَعِيدٍ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ عَلْقَمَةَ بْنِ وَقَّاصٍ اللَّيْثِيِّ، قَالَ سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2324","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2324","x":"Narrated AbuHurayrah:\n\nThe Prophet (ﷺ) said: The end of Ramadan is on the day when you end it, and the 'Id (festival) of sacrifice is on the day when you sacrifice. The whole of Arafah is the place of staying, and the whole of Mina is the place of sacrifice, and all the roads of Mecca are the place of sacrifice, and the whole of Muzdalifah is the place of staying.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدٍ، حَدَّثَنَا حَمَّادٌ، - فِي حَدِيثِ أَيُّوبَ - عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، عَنْ أَبِي هُرَيْرَةَ، ذَكَرَ النَّبِيَّ صلى الله عليه وسلم فِيهِ قَالَ ‏\n\n\"‏ وَفِطْرُكُمْ يَوْمَ تُفْطِرُونَ وَأَضْحَاكُمْ يَوْمَ تُضَحُّونَ وَكُلُّ عَرَفَةَ مَوْقِفٌ وَكُلُّ مِنًى مَنْحَرٌ وَكُلُّ فِجَاجِ مَكَّةَ مَنْحَرٌ وَكُلُّ جَمْعٍ مَوْقِفٌ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2639","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2639","x":"Narrated Aisha:\n\nThe wife of Rifa`a Al-Qurazi came to the Prophet (ﷺ) and said, \"I was Rifa`a's wife, but he divorced me and it was a final irrevocable divorce. Then I married `Abdur-Rahman bin Az-Zubair but he is impotent.\" The Prophet (ﷺ) asked her 'Do you want to remarry Rifa`a? You cannot unless you had a complete sexual relation with your present husband.\" Abu Bakr was sitting with Allah's Messenger (ﷺ) and Khalid bin Sa`id bin Al-`As was at the door waiting to be admitted. He said, \"O Abu Bakr! Do you hear what this (woman) is revealing frankly before the Prophet (ﷺ) ?\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ جَاءَتِ امْرَأَةُ رِفَاعَةَ الْقُرَظِيِّ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ كُنْتُ عِنْدَ رِفَاعَةَ فَطَلَّقَنِي فَأَبَتَّ طَلاَقِي، فَتَزَوَّجْتُ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ، إِنَّمَا مَعَهُ مِثْلُ هُدْبَةِ الثَّوْبِ‏.‏ فَقَالَ ‏\n\n\"‏ أَتُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ لاَ حَتَّى تَذُوقِي عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ ‏\"\n\n‏‏.‏ وَأَبُو بَكْرٍ جَالِسٌ عِنْدَهُ وَخَالِدُ بْنُ سَعِيدِ بْنِ الْعَاصِ بِالْبَابِ يَنْتَظِرُ أَنْ يُؤْذَنَ لَهُ، فَقَالَ يَا أَبَا بَكْرٍ، أَلاَ تَسْمَعُ إِلَى هَذِهِ مَا تَجْهَرُ بِهِ عِنْدَ النَّبِيِّ صلى الله عليه وسلم‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 2, Book 11, Hadith 1192","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-2/Book-11/Hadith-1192","x":"Hisham bin Urwah narrated from his father, from Aishah that she said:\n\n\"The people were such that a man would divorce his wife when he wanted to divorce her, and she remained his wife when he wanted to take her back while she was in her Iddah, and he could divorce a hundred times, or even more, such that a man could say to his wife: 'By Allah! I will neither divorce you irrevocably, nor give you residence ever!' She would say: 'And how is that?' He would say: 'I will divorce you, and whenever your Iddah is just about to end I will take you back. So a woman went to Aishah to inform her about that, and Aishah was silent until the Prophet came. So she told him and the Prophet was silent, until the Qur'an was revealed: Divorce is two times, after that, retain her on reasonable terms or release her with kindness.'\" So Aishah said: \"So the people could carry on with divorce in the future, (knowing) who was divorced, and who was not divorced.\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا يَعْلَى بْنُ شَبِيبٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ كَانَ النَّاسُ وَالرَّجُلُ يُطَلِّقُ امْرَأَتَهُ مَا شَاءَ أَنْ يُطَلِّقَهَا وَهِيَ امْرَأَتُهُ إِذَا ارْتَجَعَهَا وَهِيَ فِي الْعِدَّةِ وَإِنْ طَلَّقَهَا مِائَةَ مَرَّةٍ أَوْ أَكْثَرَ حَتَّى قَالَ رَجُلٌ لاِمْرَأَتِهِ وَاللَّهِ لاَ أُطَلِّقُكِ فَتَبِينِي مِنِّي وَلاَ آوِيكِ أَبَدًا ‏.‏ قَالَتْ وَكَيْفَ ذَاكَ قَالَ أُطَلِّقُكِ فَكُلَّمَا هَمَّتْ عِدَّتُكِ أَنْ تَنْقَضِيَ رَاجَعْتُكِ ‏.‏ فَذَهَبَتِ الْمَرْأَةُ حَتَّى دَخَلَتْ عَلَى عَائِشَةَ فَأَخْبَرَتْهَا فَسَكَتَتْ عَائِشَةُ حَتَّى جَاءَ النَّبِيُّ صلى الله عليه وسلم فَأَخْبَرَتْهُ فَسَكَتَ النَّبِيُّ صلى الله عليه وسلم حَتَّى نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ الطَّلاَقُ مَرَّتَانِ فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ ‏)‏ قَالَتْ عَائِشَةُ فَاسْتَأْنَفَ النَّاسُ الطَّلاَقَ مُسْتَقْبَلاً مَنْ كَانَ طَلَّقَ وَمَنْ لَمْ يَكُنْ طَلَّقَ ‏.‏ حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، نَحْوَ هَذَا الْحَدِيثِ بِمَعْنَاهُ وَلَمْ يَذْكُرْ فِيهِ عَنْ عَائِشَةَ ‏.‏ قَالَ أَبُو عِيسَى وَهَذَا أَصَحُّ مِنْ حَدِيثِ يَعْلَى بْنِ شَبِيبٍ ‏.‏","v":[]}],"230":[{"c":"Sahih Bukhari","r":"Hadith 2639","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2639","x":"Narrated Aisha:\n\nThe wife of Rifa`a Al-Qurazi came to the Prophet (ﷺ) and said, \"I was Rifa`a's wife, but he divorced me and it was a final irrevocable divorce. Then I married `Abdur-Rahman bin Az-Zubair but he is impotent.\" The Prophet (ﷺ) asked her 'Do you want to remarry Rifa`a? You cannot unless you had a complete sexual relation with your present husband.\" Abu Bakr was sitting with Allah's Messenger (ﷺ) and Khalid bin Sa`id bin Al-`As was at the door waiting to be admitted. He said, \"O Abu Bakr! Do you hear what this (woman) is revealing frankly before the Prophet (ﷺ) ?\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ جَاءَتِ امْرَأَةُ رِفَاعَةَ الْقُرَظِيِّ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ كُنْتُ عِنْدَ رِفَاعَةَ فَطَلَّقَنِي فَأَبَتَّ طَلاَقِي، فَتَزَوَّجْتُ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ، إِنَّمَا مَعَهُ مِثْلُ هُدْبَةِ الثَّوْبِ‏.‏ فَقَالَ ‏\n\n\"‏ أَتُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ لاَ حَتَّى تَذُوقِي عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ ‏\"\n\n‏‏.‏ وَأَبُو بَكْرٍ جَالِسٌ عِنْدَهُ وَخَالِدُ بْنُ سَعِيدِ بْنِ الْعَاصِ بِالْبَابِ يَنْتَظِرُ أَنْ يُؤْذَنَ لَهُ، فَقَالَ يَا أَبَا بَكْرٍ، أَلاَ تَسْمَعُ إِلَى هَذِهِ مَا تَجْهَرُ بِهِ عِنْدَ النَّبِيِّ صلى الله عليه وسلم‏.‏","v":[]}],"231":[{"c":"Muwatta Malik","r":"Book 29, Hadith 1243","u":"https://quranx.com/Hadith/Malik/In-Book/Book-29/Hadith-1243","x":"Yahya related to me from Malik from Thawr ibn Zayd ad-Dili that Allah, the Blessed, the Exalted, sent down about a man who divorced his wife and then returned to her while he had no need of her and did not mean to keep her so as to make the idda period long for her by that in order to do her harm, \"Do not retain them by force, to transgress. Whoever does that has wronged himself.\" (Sura 2 ayat 231). Allah warns them by that ayat.","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ ثَوْرِ بْنِ زَيْدٍ الدِّيلِيِّ، أَنَّ الرَّجُلَ، كَانَ يُطَلِّقُ امْرَأَتَهُ ثُمَّ يُرَاجِعُهَا وَلاَ حَاجَةَ لَهُ بِهَا وَلاَ يُرِيدُ إِمْسَاكَهَا كَيْمَا يُطَوِّلَ بِذَلِكَ عَلَيْهَا الْعِدَّةَ لِيُضَارَّهَا فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏{‏وَلاَ تُمْسِكُوهُنَّ ضِرَارًا لِتَعْتَدُوا وَمَنْ يَفْعَلْ ذَلِكَ فَقَدْ ظَلَمَ نَفْسَهُ‏}‏ يَعِظُهُمُ اللَّهُ بِذَلِكَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2981","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2981","x":"Narrated Al-Hasan:\n\nfrom Ma'qil bin Yasar that he married his sister to a man among the Muslims during the time of the Messenger of Allah (ﷺ). She remained with him as long as she did, then he divorced her once without taking her back until her 'Iddah elapsed, but they desired each other again. He (Ma'qil) said to him: 'You ingrate! I honored you by marrying her to you, then you divorced her. By Allah! She will never be returned to you again.' Allah knew of his heed for her and her need for a husband, so Allah, Blessed and Most High, revealed: 'And when you have divorced women and they have fulfilled the term of their prescribed period...' up to His saying: '... and you do not know (2:232).' So when Ma'qil heard that he said: 'I heard my Lord and obey.' Then he called for him and said: 'I marry you, and honor you.'\" [Abu 'Eisa said:] This Hadith is Hasan Sahih. It has been reported through other routes from AlHasan, and that is reported from Hasan is Gharib. And in this Hadtth, there is proof that marriage is not allowed without a Wali, because Ma'qil bin Yasãr's sister was not a virgin, so if the matter was up to her, not her Wali, then she could have married herself, and she would have had no need for Ma'qil bin Yasãr to act as the Wali for her. And Allah only addressed the Wali in this Ayah, saying: Do not prevent them from marrying their (former) husbands. - so in this Ayah is the evidence that the authority is with the Wali in marrying (women) with their consent.","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا هِشَامُ بْنُ الْقَاسِمِ، عَنِ الْمُبَارَكِ بْنِ فَضَالَةَ، عَنِ الْحَسَنِ، عَنْ مَعْقِلِ بْنِ يَسَارٍ، أَنَّهُ زَوَّجَ أُخْتَهُ رَجُلاً مِنَ الْمُسْلِمِينَ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَكَانَتْ عِنْدَهُ مَا كَانَتْ ثُمَّ طَلَّقَهَا تَطْلِيقَةً لَمْ يُرَاجِعْهَا حَتَّى انْقَضَتِ الْعِدَّةُ فَهَوِيَهَا وَهَوِيَتْهُ ثُمَّ خَطَبَهَا مَعَ الْخُطَّابِ فَقَالَ لَهُ يَا لُكَعُ أَكْرَمْتُكَ بِهَا وَزَوَّجْتُكَهَا فَطَلَّقْتَهَا وَاللَّهِ لاَ تَرْجِعُ إِلَيْكَ أَبَدًا آخِرُ مَا عَلَيْكَ قَالَ فَعَلِمَ اللَّهُ حَاجَتَهُ إِلَيْهَا وَحَاجَتَهَا إِلَى بَعْلِهَا فَأَنْزَلَ اللَّهُ ‏(‏ وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ ‏)‏ إِلَى قَوْلِهِ ‏:‏‏(‏ وَأَنْتُمْ لاَ تَعْلَمُونَ ‏)‏ فَلَمَّا سَمِعَهَا مَعْقِلٌ قَالَ سَمْعًا لِرَبِّي وَطَاعَةً ثُمَّ دَعَاهُ فَقَالَ أُزَوِّجُكَ وَأُكْرِمُكَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنِ الْحَسَنِ ‏.‏ وَفِي هَذَا الْحَدِيثِ دَلاَلَةٌ عَلَى أَنَّهُ لاَ يَجُوزُ النِّكَاحُ بِغَيْرِ وَلِيٍّ لأَنَّ أُخْتَ مَعْقِلِ بْنِ يَسَارٍ كَانَتْ ثَيِّبًا فَلَوْ كَانَ الأَمْرُ إِلَيْهَا دُونَ وَلِيِّهَا لَزَوَّجَتْ نَفْسَهَا وَلَمْ تَحْتَجْ إِلَى وَلِيِّهَا مَعْقِلِ بْنِ يَسَارٍ وَإِنَّمَا خَاطَبَ اللَّهُ فِي الآيَةِ الأَوْلِيَاءَ فَقَالَ ‏:‏ ‏(‏ولَا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ ‏)‏ فَفِي هَذِهِ الآيَةِ دَلاَلَةٌ عَلَى أَنَّ الأَمْرَ إِلَى الأَوْلِيَاءِ فِي التَّزْوِيجِ مَعَ رِضَاهُنَّ ‏.‏","v":[]}],"232":[{"c":"Sunan Abu Dawud","r":"Hadith 2092","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2092","x":"Abu Hurairah reported the Prophet(ﷺ) as saying \" A woman who has been previously married should not be married until her permission is asked nor should a virgin be married without her permission. \"They (the people) asked \"What is her permission, Apostle of Allaah(ﷺ)? He replied \"it is by her keeping silence.\"","ar":"حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا أَبَانُ، حَدَّثَنَا يَحْيَى، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ تُنْكَحُ الثَّيِّبُ حَتَّى تُسْتَأْمَرَ وَلاَ الْبِكْرُ إِلاَّ بِإِذْنِهَا ‏\"‏ ‏.‏ قَالُوا يَا رَسُولَ اللَّهِ وَمَا إِذْنُهَا قَالَ ‏\"‏ أَنْ تَسْكُتَ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4529","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4529","x":"Narrated Al-Hasan:\n\nThe sister of Ma'qal bin Yasar was divorced by her husband who left her till she had fulfilled her term of 'Iddat (i.e. the period which should elapse before she can Remarry) and then he wanted to remarry her but Maqal refused, so this Verse was revealed:-- \"Do not prevent them from marrying their (former) husbands.\" (2.232)","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو عَامِرٍ الْعَقَدِيُّ، حَدَّثَنَا عَبَّادُ بْنُ رَاشِدٍ، حَدَّثَنَا الْحَسَنُ، قَالَ حَدَّثَنِي مَعْقِلُ بْنُ يَسَارٍ، قَالَ كَانَتْ لِي أُخْتٌ تُخْطَبُ إِلَىَّ‏.‏ وَقَالَ إِبْرَاهِيمُ عَنْ يُونُسَ، عَنِ الْحَسَنِ، حَدَّثَنِي مَعْقِلُ بْنُ يَسَارٍ،‏.‏ حَدَّثَنَا أَبُو مَعْمَرٍ، حَدَّثَنَا عَبْدُ الْوَارِثِ، حَدَّثَنَا يُونُسُ، عَنِ الْحَسَنِ، أَنَّ أُخْتَ، مَعْقِلِ بْنِ يَسَارٍ طَلَّقَهَا زَوْجُهَا، فَتَرَكَهَا حَتَّى انْقَضَتْ عِدَّتُهَا، فَخَطَبَهَا فَأَبَى مَعْقِلٌ، فَنَزَلَتْ ‏{‏فَلاَ تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5130","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5130","x":"Narrated Al-Hasan:\n\nconcerning the Verse: 'Do not prevent them' (2.232) Ma'qil bin Yasar told me that it was revealed in his connection. He said, \"I married my sister to a man and he divorced her, and when her days of 'Idda (three menstrual periods) were over, the man came again and asked for her hand, but I said to him, 'I married her to you and made her your bed (your wife) and favored you with her, but you divorced her. Now you come to ask for her hand again? No, by Allah, she will never go back to you (again)!' That man was not a bad man and his wife wanted to go back to him. So Allah revealed this Verse: 'Do not prevent them.' (2.232) So I said, 'Now I will do it (let her go back to him), O Allah's Messenger (ﷺ).\"So he married her to him again.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ أَبِي عَمْرٍو، قَالَ حَدَّثَنِي أَبِي قَالَ، حَدَّثَنِي إِبْرَاهِيمُ، عَنْ يُونُسَ، عَنِ الْحَسَنِ، ‏{‏فَلاَ تَعْضُلُوهُنَّ‏}‏ قَالَ حَدَّثَنِي مَعْقِلُ بْنُ يَسَارٍ، أَنَّهَا نَزَلَتْ فِيهِ قَالَ زَوَّجْتُ أُخْتًا لِي مِنْ رَجُلٍ فَطَلَّقَهَا، حَتَّى إِذَا انْقَضَتْ عِدَّتُهَا جَاءَ يَخْطُبُهَا، فَقُلْتُ لَهُ زَوَّجْتُكَ وَفَرَشْتُكَ وَأَكْرَمْتُكَ، فَطَلَّقْتَهَا، ثُمَّ جِئْتَ تَخْطُبُهَا، لاَ وَاللَّهِ لاَ تَعُودُ إِلَيْكَ أَبَدًا، وَكَانَ رَجُلاً لاَ بَأْسَ بِهِ وَكَانَتِ الْمَرْأَةُ تُرِيدُ أَنَّ تَرْجِعَ إِلَيْهِ فَأَنْزَلَ اللَّهُ هَذِهِ الآيَةَ ‏{‏فَلاَ تَعْضُلُوهُنَّ‏}‏ فَقُلْتُ الآنَ أَفْعَلُ يَا رَسُولَ اللَّهِ‏.‏ قَالَ فَزَوَّجَهَا إِيَّاهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5331","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5331","x":"Narrated Al-Hasan:\n\nThe sister of Ma'qil bin Yasar was married to a man and then that man divorced her and remained away from her till her period of the 'Iddah expired. Then he demanded for her hand in marriage, but Ma'qil got angry out of pride and haughtiness and said, \"He kept away from her when he could still retain her, and now he demands her hand again?\" So Ma'qil disagreed to remarry her to him. Then Allah revealed: 'When you have divorced women and they have fulfilled the term of their prescribed period, do not prevent them from marrying their (former) husbands.' (2.232) So the Prophet (ﷺ) sent for Ma'qil and recited to him (Allah's order) and consequently Ma'qil gave up his pride and haughtiness and yielded to Allah's order.","ar":"وَحَدَّثَنِي مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الأَعْلَى، حَدَّثَنَا سَعِيدٌ، عَنْ قَتَادَةَ، حَدَّثَنَا الْحَسَنُ، أَنَّ مَعْقِلَ بْنَ يَسَارٍ، كَانَتْ أُخْتُهُ تَحْتَ رَجُلٍ فَطَلَّقَهَا، ثُمَّ خَلَّى عَنْهَا حَتَّى انْقَضَتْ عِدَّتُهَا، ثُمَّ خَطَبَهَا فَحَمِيَ مَعْقِلٌ مِنَ ذَلِكَ أَنَفًا فَقَالَ خَلَّى عَنْهَا وَهْوَ يَقْدِرُ عَلَيْهَا، ثُمَّ يَخْطُبُهَا فَحَالَ بَيْنَهُ وَبَيْنَهَا، فَأَنْزَلَ اللَّهُ ‏{‏وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلاَ تَعْضُلُوهُنَّ‏}‏ إِلَى آخِرِ الآيَةِ، فَدَعَاهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَرَأَ عَلَيْهِ، فَتَرَكَ الْحَمِيَّةَ وَاسْتَقَادَ لأَمْرِ اللَّهِ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2981","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2981","x":"Narrated Al-Hasan:\n\nfrom Ma'qil bin Yasar that he married his sister to a man among the Muslims during the time of the Messenger of Allah (ﷺ). She remained with him as long as she did, then he divorced her once without taking her back until her 'Iddah elapsed, but they desired each other again. He (Ma'qil) said to him: 'You ingrate! I honored you by marrying her to you, then you divorced her. By Allah! She will never be returned to you again.' Allah knew of his heed for her and her need for a husband, so Allah, Blessed and Most High, revealed: 'And when you have divorced women and they have fulfilled the term of their prescribed period...' up to His saying: '... and you do not know (2:232).' So when Ma'qil heard that he said: 'I heard my Lord and obey.' Then he called for him and said: 'I marry you, and honor you.'\" [Abu 'Eisa said:] This Hadith is Hasan Sahih. It has been reported through other routes from AlHasan, and that is reported from Hasan is Gharib. And in this Hadtth, there is proof that marriage is not allowed without a Wali, because Ma'qil bin Yasãr's sister was not a virgin, so if the matter was up to her, not her Wali, then she could have married herself, and she would have had no need for Ma'qil bin Yasãr to act as the Wali for her. And Allah only addressed the Wali in this Ayah, saying: Do not prevent them from marrying their (former) husbands. - so in this Ayah is the evidence that the authority is with the Wali in marrying (women) with their consent.","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا هِشَامُ بْنُ الْقَاسِمِ، عَنِ الْمُبَارَكِ بْنِ فَضَالَةَ، عَنِ الْحَسَنِ، عَنْ مَعْقِلِ بْنِ يَسَارٍ، أَنَّهُ زَوَّجَ أُخْتَهُ رَجُلاً مِنَ الْمُسْلِمِينَ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَكَانَتْ عِنْدَهُ مَا كَانَتْ ثُمَّ طَلَّقَهَا تَطْلِيقَةً لَمْ يُرَاجِعْهَا حَتَّى انْقَضَتِ الْعِدَّةُ فَهَوِيَهَا وَهَوِيَتْهُ ثُمَّ خَطَبَهَا مَعَ الْخُطَّابِ فَقَالَ لَهُ يَا لُكَعُ أَكْرَمْتُكَ بِهَا وَزَوَّجْتُكَهَا فَطَلَّقْتَهَا وَاللَّهِ لاَ تَرْجِعُ إِلَيْكَ أَبَدًا آخِرُ مَا عَلَيْكَ قَالَ فَعَلِمَ اللَّهُ حَاجَتَهُ إِلَيْهَا وَحَاجَتَهَا إِلَى بَعْلِهَا فَأَنْزَلَ اللَّهُ ‏(‏ وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ ‏)‏ إِلَى قَوْلِهِ ‏:‏‏(‏ وَأَنْتُمْ لاَ تَعْلَمُونَ ‏)‏ فَلَمَّا سَمِعَهَا مَعْقِلٌ قَالَ سَمْعًا لِرَبِّي وَطَاعَةً ثُمَّ دَعَاهُ فَقَالَ أُزَوِّجُكَ وَأُكْرِمُكَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنِ الْحَسَنِ ‏.‏ وَفِي هَذَا الْحَدِيثِ دَلاَلَةٌ عَلَى أَنَّهُ لاَ يَجُوزُ النِّكَاحُ بِغَيْرِ وَلِيٍّ لأَنَّ أُخْتَ مَعْقِلِ بْنِ يَسَارٍ كَانَتْ ثَيِّبًا فَلَوْ كَانَ الأَمْرُ إِلَيْهَا دُونَ وَلِيِّهَا لَزَوَّجَتْ نَفْسَهَا وَلَمْ تَحْتَجْ إِلَى وَلِيِّهَا مَعْقِلِ بْنِ يَسَارٍ وَإِنَّمَا خَاطَبَ اللَّهُ فِي الآيَةِ الأَوْلِيَاءَ فَقَالَ ‏:‏ ‏(‏ولَا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ ‏)‏ فَفِي هَذِهِ الآيَةِ دَلاَلَةٌ عَلَى أَنَّ الأَمْرَ إِلَى الأَوْلِيَاءِ فِي التَّزْوِيجِ مَعَ رِضَاهُنَّ ‏.‏","v":[]}],"233":[{"c":"Muwatta Malik","r":"Book 41, Hadith 1513","u":"https://quranx.com/Hadith/Malik/In-Book/Book-41/Hadith-1513","x":"Malik related to me that he had heard that Uthman ibn Affan was brought a woman who had given birth after six months and he ordered her to be stoned. Ali ibn Abi Talib said to him, \"She does not deserve that. Allah, the Blessed, the Exalted, says in His Book, 'Their carrying and weaning is thirty months,' (Sura 46 ayat 15) and he said, 'Mothers suckle their children for two full years for whoever wishes to complete the suckling.' (Sura 2 ayat 233) Pregnancy can then be six months, so she does not deserve to be stoned.\" Uthman ibn Affan sent for her and found that she had already been stoned. Malik related to me that he asked Ibn Shihab about someone who committed sodomy. Ibn Shihab said, \"He is to be stoned, whether or not he is muhsan.\"","ar":"وَحَدَّثَنِي مَالِكٌ، أَنَّهُ بَلَغَهُ أَنَّ عُثْمَانَ بْنَ عَفَّانَ، أُتِيَ بِامْرَأَةٍ قَدْ وَلَدَتْ فِي سِتَّةِ أَشْهُرٍ فَأَمَرَ بِهَا أَنْ تُرْجَمَ فَقَالَ عَلِيُّ بْنُ أَبِي طَالِبٍ لَيْسَ ذَلِكَ عَلَيْهَا إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ فِي كِتَابِهِ ‏{‏وَحَمْلُهُ وَفِصَالُهُ ثَلاَثُونَ شَهْرًا‏}‏ وَقَالَ ‏{‏وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلاَدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ‏}‏ فَالْحَمْلُ يَكُونُ سِتَّةَ أَشْهُرٍ فَلاَ رَجْمَ عَلَيْهَا ‏.‏ فَبَعَثَ عُثْمَانُ بْنُ عَفَّانَ فِي أَثَرِهَا فَوَجَدَهَا قَدْ رُجِمَتْ ‏.‏","v":[]}],"234":[{"c":"Sunan Abu Dawud","r":"Hadith 2314","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2314","x":"Al Bara’ (bin Azib) said \"When a man fasted and slept, he could not eat till (another nigh) like it.\" Sarmah bin Qais Al Ansari came to his wife while he was fasting and asked her Do you have something (to eat)? She replied \"No\". Let me go and seek something for you. So, she went out and sleep overcame him. She came (back) and said (to him).You are deprived (of food). He fainted before noon. He used to work all day long at his land. This was mentioned to the Prophet (ﷺ). So the following verse was revealed. \"Permitted to you on the nights of the fasts, is the approach to your wives. They are your garments and ye are their garments. Allah knoweth what yes used to do secretly amongst yourselves. But he turned to you and forgave you. So now associate with them and seek what Allaah hath ordained for you. And eat and drink until the white thread of dawn appears to you. He recited up to the words \"of dawn\".","ar":"حَدَّثَنَا نَصْرُ بْنُ عَلِيِّ بْنِ نَصْرٍ الْجَهْضَمِيُّ، أَخْبَرَنَا أَبُو أَحْمَدَ، أَخْبَرَنَا إِسْرَائِيلُ، عَنْ إِسْحَاقَ، عَنِ الْبَرَاءِ، قَالَ كَانَ الرَّجُلُ إِذَا صَامَ فَنَامَ لَمْ يَأْكُلْ إِلَى مِثْلِهَا وَإِنَّ صِرْمَةَ بْنَ قَيْسٍ الأَنْصَارِيَّ أَتَى امْرَأَتَهُ وَكَانَ صَائِمًا فَقَالَ عِنْدَكِ شَىْءٌ قَالَتْ لاَ لَعَلِّي أَذْهَبُ فَأَطْلُبُ لَكَ شَيْئًا ‏.‏ فَذَهَبَتْ وَغَلَبَتْهُ عَيْنُهُ فَجَاءَتْ فَقَالَتْ خَيْبَةً لَكَ ‏.‏ فَلَمْ يَنْتَصِفِ النَّهَارُ حَتَّى غُشِيَ عَلَيْهِ وَكَانَ يَعْمَلُ يَوْمَهُ فِي أَرْضِهِ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَنَزَلَتْ ‏{‏ أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ ‏}‏ قَرَأَ إِلَى قَوْلِهِ ‏{‏ مِنَ الْفَجْرِ ‏}‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 371","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-371","x":"Narrated `Abdul `Aziz:\n\nAnas said, 'When Allah's Messenger (ﷺ) invaded Khaibar, we offered the Fajr prayer there (early in the morning) when it was still dark. The Prophet (ﷺ) rode and Abu Talha rode too and I was riding behind Abu Talha. The Prophet (ﷺ) passed through the lane of Khaibar quickly and my knee was touching the thigh of the Prophet (ﷺ). He uncovered his thigh and I saw the whiteness of the thigh of the Prophet. When he entered the town, he said, 'Allahu Akbar! Khaibar is ruined. Whenever we approach near a (hostile) nation (to fight) then evil will be the morning of those who have been warned.' He repeated this thrice. The people came out for their jobs and some of them said, 'Muhammad (has come).' (Some of our companions added, \"With his army.\") We conquered Khaibar, took the captives, and the booty was collected. Dihya came and said, 'O Allah's Prophet! Give me a slave girl from the captives.' The Prophet said, 'Go and take any slave girl.' He took Safiya bint Huyai. A man came to the Prophet (ﷺ) and said, 'O Allah's Messenger (ﷺ)s! You gave Safiya bint Huyai to Dihya and she is the chief mistress of the tribes of Quraidha and An-Nadir and she befits none but you.' So the Prophet (ﷺ) said, 'Bring him along with her.' So Dihya came with her and when the Prophet (ﷺ) saw her, he said to Dihya, 'Take any slave girl other than her from the captives.' Anas added: The Prophet (ﷺ) then manumitted her and married her.\" Thabit asked Anas, \"O Abu Hamza! What did the Prophet (ﷺ) pay her (as Mahr)?\" He said, \"Her self was her Mahr for he manumitted her and then married her.\" Anas added, \"While on the way, Um Sulaim dressed her for marriage (ceremony) and at night she sent her as a bride to the Prophet (ﷺ). So the Prophet was a bridegroom and he said, 'Whoever has anything (food) should bring it.' He spread out a leather sheet (for the food) and some brought dates and others cooking butter. (I think he (Anas) mentioned As-Sawaq). So they prepared a dish of Hais (a kind of meal). And that was Walima (the marriage banquet) of Allah's Messenger (ﷺ).\"","ar":"حَدَّثَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ ابْنُ عُلَيَّةَ، قَالَ حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ، عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم غَزَا خَيْبَرَ، فَصَلَّيْنَا عِنْدَهَا صَلاَةَ الْغَدَاةِ بِغَلَسٍ، فَرَكِبَ نَبِيُّ اللَّهِ صلى الله عليه وسلم وَرَكِبَ أَبُو طَلْحَةَ، وَأَنَا رَدِيفُ أَبِي طَلْحَةَ، فَأَجْرَى نَبِيُّ اللَّهِ صلى الله عليه وسلم فِي زُقَاقِ خَيْبَرَ، وَإِنَّ رُكْبَتِي لَتَمَسُّ فَخِذَ نَبِيِّ اللَّهِ صلى الله عليه وسلم، ثُمَّ حَسَرَ الإِزَارَ عَنْ فَخِذِهِ حَتَّى إِنِّي أَنْظُرُ إِلَى بَيَاضِ فَخِذِ نَبِيِّ اللَّهِ صلى الله عليه وسلم، فَلَمَّا دَخَلَ الْقَرْيَةَ قَالَ ‏\"‏ اللَّهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏\"‏‏.‏ قَالَهَا ثَلاَثًا‏.‏ قَالَ وَخَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ فَقَالُوا مُحَمَّدٌ ـ قَالَ عَبْدُ الْعَزِيزِ وَقَالَ بَعْضُ أَصْحَابِنَا ـ وَالْخَمِيسُ‏.‏ يَعْنِي الْجَيْشَ، قَالَ فَأَصَبْنَاهَا عَنْوَةً، فَجُمِعَ السَّبْىُ، فَجَاءَ دِحْيَةُ فَقَالَ يَا نَبِيَّ اللَّهِ، أَعْطِنِي جَارِيَةً مِنَ السَّبْىِ‏.‏ قَالَ ‏\"‏ اذْهَبْ فَخُذْ جَارِيَةً ‏\"‏‏.‏ فَأَخَذَ صَفِيَّةَ بِنْتَ حُيَىٍّ، فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ يَا نَبِيَّ اللَّهِ، أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حُيَىٍّ سَيِّدَةَ قُرَيْظَةَ وَالنَّضِيرِ، لاَ تَصْلُحُ إِلاَّ لَكَ‏.‏ قَالَ ‏\"‏ ادْعُوهُ بِهَا ‏\"‏‏.‏ فَجَاءَ بِهَا، فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صلى الله عليه وسلم قَالَ ‏\"‏ خُذْ جَارِيَةً مِنَ السَّبْىِ غَيْرَهَا ‏\"‏‏.‏ قَالَ فَأَعْتَقَهَا النَّبِيُّ صلى الله عليه وسلم وَتَزَوَّجَهَا‏.‏ فَقَالَ لَهُ ثَابِتٌ يَا أَبَا حَمْزَةَ، مَا أَصْدَقَهَا قَالَ نَفْسَهَا، أَعْتَقَهَا وَتَزَوَّجَهَا، حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا لَهُ أُمُّ سُلَيْمٍ فَأَهْدَتْهَا لَهُ مِنَ اللَّيْلِ، فَأَصْبَحَ النَّبِيُّ صلى الله عليه وسلم عَرُوسًا فَقَالَ ‏\"‏ مَنْ كَانَ عِنْدَهُ شَىْءٌ فَلْيَجِئْ بِهِ ‏\"‏‏.‏ وَبَسَطَ نِطَعًا، فَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ ـ قَالَ وَأَحْسِبُهُ قَدْ ذَكَرَ السَّوِيقَ ـ قَالَ فَحَاسُوا حَيْسًا، فَكَانَتْ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1280","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1280","x":"Narrated Zainab bint Abi Salama:\n\nWhen the news of the death of Abu Sufyan reached from Sham, Um Habiba on the third day, asked for a yellow perfume and scented her cheeks and forearms and said, \"No doubt, I would not have been in need of this, had I not heard the Prophet (ﷺ) saying: \"It is not legal for a woman who believes in Allah and the Last Day to mourn for more than three days for any dead person except her husband, for whom she should mourn for four months and ten days.\"","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا أَيُّوبُ بْنُ مُوسَى، قَالَ أَخْبَرَنِي حُمَيْدُ بْنُ نَافِعٍ، عَنْ زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ، قَالَتْ لَمَّا جَاءَ نَعْىُ أَبِي سُفْيَانَ مِنَ الشَّأْمِ دَعَتْ أُمُّ حَبِيبَةَ ـ رضى الله عنها ـ بِصُفْرَةٍ فِي الْيَوْمِ الثَّالِثِ، فَمَسَحَتْ عَارِضَيْهَا وَذِرَاعَيْهَا وَقَالَتْ إِنِّي كُنْتُ عَنْ هَذَا لَغَنِيَّةً، لَوْلاَ أَنِّي سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\n\n\"‏ لاَ يَحِلُّ لاِمْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ أَنْ تُحِدَّ عَلَى مَيِّتٍ فَوْقَ ثَلاَثٍ، إِلاَّ عَلَى زَوْجٍ، فَإِنَّهَا تُحِدُّ عَلَيْهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2228","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2228","x":"Narrated Anas:\n\nAmongst the captives was Safiya. First she was given to Dihya Al-Kalbi and then to the Prophet.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ كَانَ فِي السَّبْىِ صَفِيَّةُ، فَصَارَتْ إِلَى دَحْيَةَ الْكَلْبِيِّ، ثُمَّ صَارَتْ إِلَى النَّبِيِّ صلى الله عليه وسلم‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2235","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2235","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) came to Khaibar and when Allah made him victorious and he conquered the town by breaking the enemy's defense, the beauty of Safiya bint Huyai bin Akhtab was mentioned to him and her husband had been killed while she was a bride. Allah's Messenger (ﷺ) selected her for himself and he set out in her company till he reached Sadd-ar-Rawha' where her menses were over and he married her. Then Hais (a kind of meal) was prepared and served on a small leather sheet (used for serving meals). Allah's Messenger (ﷺ) then said to me, \"Inform those who are around you (about the wedding banquet).\" So that was the marriage banquet given by Allah's Messenger (ﷺ) for (his marriage with) Safiya. After that we proceeded to Medina and I saw that Allah's Messenger (ﷺ) was covering her with a cloak while she was behind him. Then he would sit beside his camel and let Safiya put her feet on his knees to ride (the camel).","ar":"حَدَّثَنَا عَبْدُ الْغَفَّارِ بْنُ دَاوُدَ، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ قَدِمَ النَّبِيُّ صلى الله عليه وسلم خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا، وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم لِنَفْسِهِ فَخَرَجَ بِهَا، حَتَّى بَلَغْنَا سَدَّ الرَّوْحَاءِ حَلَّتْ، فَبَنَى بِهَا، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"\n\n‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى صَفِيَّةَ، ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ، قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ فَيَضَعُ رُكْبَتَهُ، فَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ، حَتَّى تَرْكَبَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4200","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4200","x":"Narrated Anas:\n\nThe Prophet (ﷺ) offered the Fajr Prayer near Khaibar when it was still dark and then said, \"Allahu-Akbar! Khaibar is destroyed, for whenever we approach a (hostile) nation (to fight), then evil will be the morning for those who have been warned.\" Then the inhabitants of Khaibar came out running on the roads. The Prophet (ﷺ) had their warriors killed, their offspring and woman taken as captives. Safiya was amongst the captives, She first came in the share of Dahya Alkali but later on she belonged to the Prophet. The Prophet (ﷺ) made her manumission as her 'Mahr'.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ صَلَّى النَّبِيُّ صلى الله عليه وسلم الصُّبْحَ قَرِيبًا مِنْ خَيْبَرَ بِغَلَسٍ ثُمَّ قَالَ ‏\n\n\"‏ اللَّهُ أَكْبَرُ خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ، فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏\"\n\n‏‏.‏ فَخَرَجُوا يَسْعَوْنَ فِي السِّكَكِ، فَقَتَلَ النَّبِيُّ صلى الله عليه وسلم الْمُقَاتِلَةَ، وَسَبَى الذُّرِّيَّةَ، وَكَانَ فِي السَّبْىِ صَفِيَّةُ، فَصَارَتْ إِلَى دِحْيَةَ الْكَلْبِيِّ، ثُمَّ صَارَتْ إِلَى النَّبِيِّ صلى الله عليه وسلم، فَجَعَلَ عِتْقَهَا صَدَاقَهَا‏.‏ فَقَالَ عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ لِثَابِتٍ يَا أَبَا مُحَمَّدٍ آنْتَ قُلْتَ لأَنَسٍ مَا أَصْدَقَهَا فَحَرَّكَ ثَابِتٌ رَأْسَهُ تَصْدِيقًا لَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4201","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4201","x":"Narrated `Abdul `Aziz bin Suhaib:\n\nAnas bin Malik said, \"The Prophet (ﷺ) took Safiya as a captive. He manumitted her and married her.\" Thabit asked Anas, \"What did he give her as Mahr (i.e. marriage gift)?\" Anas replied. \"Her Mahr was herself, for he manumitted her.\"","ar":"حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ يَقُولُ سَبَى النَّبِيُّ صلى الله عليه وسلم صَفِيَّةَ، فَأَعْتَقَهَا وَتَزَوَّجَهَا‏.‏ فَقَالَ ثَابِتٌ لأَنَسٍ مَا أَصْدَقَهَا قَالَ أَصْدَقَهَا نَفْسَهَا فَأَعْتَقَهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4211","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4211","x":"Narrated Anas bin Malik:\n\nWe arrived at Khaibar, and when Allah helped His Apostle to open the fort, the beauty of Safiya bint Huyai bin Akhtaq whose husband had been killed while she was a bride, was mentioned to Allah's Apostle. The Prophet (ﷺ) selected her for himself, and set out with her, and when we reached a place called Sidd-as-Sahba,' Safiya became clean from her menses then Allah's Messenger (ﷺ) married her. Hais (i.e. an 'Arabian dish) was prepared on a small leather mat. Then the Prophet (ﷺ) said to me, \"I invite the people around you.\" So that was the marriage banquet of the Prophet (ﷺ) and Safiya. Then we proceeded towards Medina, and I saw the Prophet, making for her a kind of cushion with his cloak behind him (on his camel). He then sat beside his camel and put his knee for Safiya to put her foot on, in order to ride (on the camel).","ar":"حَدَّثَنَا عَبْدُ الْغَفَّارِ بْنُ دَاوُدَ، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، ح وَحَدَّثَنِي أَحْمَدُ، حَدَّثَنَا ابْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ الزُّهْرِيُّ، عَنْ عَمْرٍو، مَوْلَى الْمُطَّلِبِ عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ قَدِمْنَا خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا النَّبِيُّ صلى الله عليه وسلم لِنَفْسِهِ، فَخَرَجَ بِهَا، حَتَّى بَلَغْنَا سَدَّ الصَّهْبَاءِ حَلَّتْ، فَبَنَى بِهَا رَسُولُ اللَّهِ صلى الله عليه وسلم، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ لِي ‏\n\n\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"\n\n‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَتَهُ عَلَى صَفِيَّةَ، ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ، فَرَأَيْتُ النَّبِيَّ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ، فَيَضَعُ رُكْبَتَهُ، وَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ حَتَّى تَرْكَبَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4212","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4212","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) stayed with Safiya bint Huyai for three days on the way of Khaibar where he consummated his marriage with her. Safiya was amongst those who were ordered to use a veil.","ar":"حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي أَخِي، عَنْ سُلَيْمَانَ، عَنْ يَحْيَى، عَنْ حُمَيْدٍ الطَّوِيلِ، سَمِعَ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه أَنَّ النَّبِيَّ صلى الله عليه وسلم أَقَامَ عَلَى صَفِيَّةَ بِنْتِ حُيَىٍّ، بِطَرِيقِ خَيْبَرَ ثَلاَثَةَ أَيَّامٍ، حَتَّى أَعْرَسَ بِهَا، وَكَانَتْ فِيمَنْ ضُرِبَ عَلَيْهَا الْحِجَابُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4213","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4213","x":"Narrated Anas:\n\nThe Prophet (ﷺ) stayed for three rights between Khaibar and Medina and was married to Safiya. I invited the Muslim to h s marriage banquet and there wa neither meat nor bread in that banquet but the Prophet ordered Bilal to spread the leather mats on which dates, dried yogurt and butter were put. The Muslims said amongst themselves, \"Will she (i.e. Safiya) be one of the mothers of the believers, (i.e. one of the wives of the Prophet (ﷺ) ) or just (a lady captive) of what his right-hand possesses\" Some of them said, \"If the Prophet (ﷺ) makes her observe the veil, then she will be one of the mothers of the believers (i.e. one of the Prophet's wives), and if he does not make her observe the veil, then she will be his lady slave.\" So when he departed, he made a place for her behind him (on his and made her observe the veil.","ar":"حَدَّثَنَا سَعِيدُ بْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرِ بْنِ أَبِي كَثِيرٍ، قَالَ أَخْبَرَنِي حُمَيْدٌ، أَنَّهُ سَمِعَ أَنَسًا ـ رضى الله عنه ـ يَقُولُ أَقَامَ النَّبِيُّ صلى الله عليه وسلم بَيْنَ خَيْبَرَ وَالْمَدِينَةِ ثَلاَثَ لَيَالٍ يُبْنَى عَلَيْهِ بِصَفِيَّةَ، فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ، وَمَا كَانَ فِيهَا مِنْ خُبْزٍ وَلاَ لَحْمٍ، وَمَا كَانَ فِيهَا إِلاَّ أَنْ أَمَرَ بِلاَلاً بِالأَنْطَاعِ فَبُسِطَتْ، فَأَلْقَى عَلَيْهَا التَّمْرَ وَالأَقِطَ وَالسَّمْنَ، فَقَالَ الْمُسْلِمُونَ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ، أَوْ مَا مَلَكَتْ يَمِينُهُ قَالُوا إِنْ حَجَبَهَا فَهْىَ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ، وَإِنْ لَمْ يَحْجُبْهَا فَهْىَ مِمَّا مَلَكَتْ يَمِينُهُ‏.‏ فَلَمَّا ارْتَحَلَ وَطَّأَ لَهَا خَلْفَهُ، وَمَدَّ الْحِجَابَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4531","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4531","x":"Narrated Mujahi:\n\n(regarding the Verse):-- \"Those of you who die and leave wives behind. They - (their wives) -- shall wait (as regards their marriage ) for four months and ten days).\" (2.234) The widow, according to this Verse, was to spend this period of waiting with her husband's family, so Allah revealed: \"Those of you who die and leave wives (i.e. widows) should bequeath for their wives, a year's maintenance and residences without turning them out, but if they leave (their residence), there is no blame on you for what they do with themselves provided it is honorable.' (i.e. lawful marriage) (2.240). So Allah entitled the widow to be bequeathed extra maintenance for seven months and twenty nights, and that is the completion of one year. If she wished she could stay (in her husband's home) according to the will, and she could leave it if she wished, as Allah says: \"..without turning them out, but if they leave (the residence), there is no blame on you.\" So the 'Idda (i.e. four months and ten days as it) is obligatory for her. 'Ata said: Ibn `Abbas said, \"This Verse, i.e. the Statement of Allah: \"..without turning them out..\" cancelled the obligation of staying for the waiting period in her dead husband's house, and she can complete this period wherever she likes.\" 'Ata's aid: If she wished, she could complete her 'Idda by staying in her dead husband's residence according to the will or leave it according to Allah's Statement:-- \"There is no blame on you for what they do with themselves.\" `Ata' added: Later the regulations of inheritance came and abrogated the order of the dwelling of the widow (in her dead husband's house), so she could complete the 'Idda wherever she likes. And it was no longer necessary to provide her with a residence. Ibn `Abbas said, \"This Verse abrogated her (i.e. widow's) dwelling in her dead husband's house and she could complete the 'Idda (i.e. four months and ten days) wherever she liked, as Allah's Statement says:--\"...without turning them out...\"","ar":"حَدَّثَنَا إِسْحَاقُ، حَدَّثَنَا رَوْحٌ، حَدَّثَنَا شِبْلٌ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، ‏{‏وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا‏}‏ قَالَ كَانَتْ هَذِهِ الْعِدَّةُ تَعْتَدُّ عِنْدَ أَهْلِ زَوْجِهَا وَاجِبٌ، فَأَنْزَلَ اللَّهُ ‏{‏وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا وَصِيَّةً لأَزْوَاجِهِمْ مَتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلاَ جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنْفُسِهِنَّ مِنْ مَعْرُوفٍ‏}‏ قَالَ جَعَلَ اللَّهُ لَهَا تَمَامَ السَّنَةِ سَبْعَةَ أَشْهُرٍ وَعِشْرِينَ لَيْلَةً وَصِيَّةً، إِنْ شَاءَتْ سَكَنَتْ فِي وَصِيَّتِهَا، وَإِنْ شَاءَتْ خَرَجَتْ، وَهْوَ قَوْلُ اللَّهِ تَعَالَى ‏{‏غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلاَ جُنَاحَ عَلَيْكُمْ‏}‏ فَالْعِدَّةُ كَمَا هِيَ وَاجِبٌ عَلَيْهَا‏.‏ زَعَمَ ذَلِكَ عَنْ مُجَاهِدٍ‏.‏ وَقَالَ عَطَاءٌ قَالَ ابْنُ عَبَّاسٍ نَسَخَتْ هَذِهِ الآيَةُ عِدَّتَهَا عِنْدَ أَهْلِهَا، فَتَعْتَدُّ حَيْثُ شَاءَتْ، وَهْوَ قَوْلُ اللَّهِ تَعَالَى ‏{‏غَيْرَ إِخْرَاجٍ‏}‏‏.‏ قَالَ عَطَاءٌ إِنْ شَاءَتِ اعْتَدَّتْ عِنْدَ أَهْلِهِ وَسَكَنَتْ فِي وَصِيَّتِهَا، وَإِنْ شَاءَتْ خَرَجَتْ لِقَوْلِ اللَّهِ تَعَالَى ‏{‏فَلاَ جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ‏}‏‏.‏ قَالَ عَطَاءٌ ثُمَّ جَاءَ الْمِيرَاثُ فَنَسَخَ السُّكْنَى فَتَعْتَدُّ حَيْثُ شَاءَتْ، وَلاَ سُكْنَى لَهَا‏.‏ وَعَنْ مُحَمَّدِ بْنِ يُوسُفَ حَدَّثَنَا وَرْقَاءُ عَنِ ابْنِ أَبِي نَجِيحٍ عَنْ مُجَاهِدٍ بِهَذَا‏.‏ وَعَنِ ابْنِ أَبِي نَجِيحٍ عَنْ عَطَاءٍ عَنِ ابْنِ عَبَّاسٍ قَالَ نَسَخَتْ هَذِهِ الآيَةُ عِدَّتَهَا فِي أَهْلِهَا، فَتَعْتَدُّ حَيْثُ شَاءَتْ لِقَوْلِ اللَّهِ ‏{‏غَيْرَ إِخْرَاجٍ‏}‏ نَحْوَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5085","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5085","x":"Narrated Anas:\n\nThe Prophet (ﷺ) stayed for three days between Khaibar and Medina, and there he consummated his marriage to Safiyya bint Huyai. I invited the Muslims to the wedding banquet in which neither meat nor bread was offered. He ordered for leather dining-sheets to be spread, and dates, dried yoghurt and butter were laid on it, and that was the Prophet's wedding banquet. The Muslims wondered, \"Is she (Saffiyya) considered as his wife or his slave girl?\" Then they said, \"If he orders her to veil herself, she will be one of the mothers of the Believers; but if he does not order her to veil herself, she will be a slave girl. So when the Prophet (ﷺ) proceeded from there, he spared her a space behind him (on his shecamel) and put a screening veil between her and the people.","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ حُمَيْدٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ أَقَامَ النَّبِيُّ صلى الله عليه وسلم بَيْنَ خَيْبَرَ وَالْمَدِينَةِ ثَلاَثًا يُبْنَى عَلَيْهِ بِصَفِيَّةَ بِنْتِ حُيَىٍّ فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ فَمَا كَانَ فِيهَا مِنْ خُبْزٍ وَلاَ لَحْمٍ، أُمِرَ بِالأَنْطَاعِ فَأَلْقَى فِيهَا مِنَ التَّمْرِ وَالأَقِطِ وَالسَّمْنِ فَكَانَتْ وَلِيمَتَهُ، فَقَالَ الْمُسْلِمُونَ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ أَوْ مِمَّا مَلَكَتْ يَمِينُهُ، فَقَالُوا إِنْ حَجَبَهَا فَهْىَ مِنْ أُمَّهَاتِ الْمُؤْمِنِينَ، وَإِنْ لَمْ يَحْجُبْهَا فَهْىَ مِمَّا مَلَكَتْ يَمِينُهُ، فَلَمَّا ارْتَحَلَ وَطَّى لَهَا خَلْفَهُ وَمَدَّ الْحِجَابَ بَيْنَهَا وَبَيْنَ النَّاسِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5169","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5169","x":"Narrated Anas:\n\nAllah's Messenger (ﷺ) manumitted Safiyya and then married her, and her Mahr was her manumission, and he gave a wedding banquet with Hais (a sort of sweet dish made from butter, cheese and dates).","ar":"حَدَّثَنَا مُسَدَّدٌ، عَنْ عَبْدِ الْوَارِثِ، عَنْ شُعَيْبٍ، عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَعْتَقَ صَفِيَّةَ، وَتَزَوَّجَهَا وَجَعَلَ عِتْقَهَا صَدَاقَهَا، وَأَوْلَمَ عَلَيْهَا بِحَيْسٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5387","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5387","x":"Narrated Anas:\n\nThe Prophet (ﷺ) halted to consummate his marriage with Safiyya. I invited the Muslims to his wedding banquet. He ordered that leather dining sheets be spread. Then dates, dried yoghurt and butter were put on those sheets. Anas added: The Prophet (ﷺ) consummated his marriage with Safiyya (during a journey) whereupon Hais (sweet dish) was served on a leather dining sheet.","ar":"حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، أَخْبَرَنِي حُمَيْدٌ، أَنَّهُ سَمِعَ أَنَسًا، يَقُولُ قَامَ النَّبِيُّ صلى الله عليه وسلم يَبْنِي بِصَفِيَّةَ فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ أَمَرَ بِالأَنْطَاعِ فَبُسِطَتْ فَأُلْقِيَ عَلَيْهَا التَّمْرُ وَالأَقِطُ وَالسَّمْنُ‏.‏ وَقَالَ عَمْرٌو عَنْ أَنَسٍ بَنَى بِهَا النَّبِيُّ صلى الله عليه وسلم ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5425","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5425","x":"Narrated Anas bin Malik:\n\nAllah's Messenger (ﷺ) said to Abu Talha, \"Seek one of your boys to serve me.\" Abu Talha mounted me behind him (on his riding animal) and took me (to the Prophet (ﷺ) ). So I used to serve Allah's Messenger (ﷺ) whenever he dismounted (to stay somewhere). I used to hear him saying very often, \"O Allah! I seek refuge with You from, having worries sadness, helplessness, laziness, miserliness, cowardice, from being heavily in debt and from being overpowered by other persons unjustly.\" I kept on serving till we -returned from the battle of Khaibar. The Prophet (ﷺ) then brought Safiyya bint Huyai whom he had won from the war booty. I saw him folding up a gown or a garment for her to sit on behind him (on his shecamel). When he reached As-Sahba', he prepared Hais and placed it on a dining sheet. Then he sent me to invite men, who (came and) ate; and that was his and Safiyya's wedding banquet. Then the Prophet proceeded, and when he saw (noticed) the mountain of Uhud, he said, \"This mountain loves us, and we love it.\" When we approached Medina, he said, \"O Allah! I make the area between its two mountains a sanctuary as Abraham has made Mecca a sanctuary. O Allah! Bless their Mudd and Sa (special kinds of measure).","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، مَوْلَى الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأَبِي طَلْحَةَ ‏\"‏ الْتَمِسْ غُلاَمًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي ‏\"‏‏.‏ فَخَرَجَ بِي أَبُو طَلْحَةَ، يُرْدِفُنِي وَرَاءَهُ، فَكُنْتُ أَخْدُمُ رَسُولَ اللَّهِ صلى الله عليه وسلم كُلَّمَا نَزَلَ، فَكُنْتُ أَسْمَعُهُ يُكْثِرُ أَنْ يَقُولَ ‏\"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ ‏\"‏‏.‏ فَلَمْ أَزَلْ أَخْدُمُهُ حَتَّى أَقْبَلْنَا مِنْ خَيْبَرَ، وَأَقْبَلَ بِصَفِيَّةَ بِنْتِ حُيَىٍّ قَدْ حَازَهَا، فَكُنْتُ أَرَاهُ يُحَوِّي وَرَاءَهُ بِعَبَاءَةٍ أَوْ بِكِسَاءٍ، ثُمَّ يُرْدِفُهَا وَرَاءَهُ، حَتَّى إِذَا كُنَّا بِالصَّهْبَاءِ صَنَعَ حَيْسًا فِي نِطَعٍ، ثُمَّ أَرْسَلَنِي فَدَعَوْتُ رِجَالاً فَأَكَلُوا، وَكَانَ ذَلِكَ بِنَاءَهُ بِهَا، ثُمَّ أَقْبَلَ حَتَّى إِذَا بَدَا لَهُ أُحُدٌ قَالَ ‏\"‏ هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ ‏\"‏‏.‏ فَلَمَّا أَشْرَفَ عَلَى الْمَدِينَةِ قَالَ ‏\"‏ اللَّهُمَّ إِنِّي أُحَرِّمُ مَا بَيْنَ جَبَلَيْهَا مِثْلَ مَا حَرَّمَ بِهِ إِبْرَاهِيمُ مَكَّةَ، اللَّهُمَّ بَارِكْ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6363","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6363","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) said to Abu Talha, \"Choose one of your boys to serve me.\" So Abu Talha took me (to serve the Prophet (ﷺ) ) by giving me a ride behind him (on his camel). So I used to serve Allah's Messenger (ﷺ) whenever he stayed somewhere. I used to hear him saying, \"O Allah! I seek refuge with you (Allah) from (worries) care and grief, from incapacity and laziness, from miserliness and cowardice, from being heavily in debt and from being overpowered by other men.\" I kept on serving him till he returned from (the battle of) Khaibar. He then brought Safiya, the daughter of Huyay whom he had got (from the booty). I saw him making a kind of cushion with a cloak or a garment for her. He then let her ride behind him. When we reached a place called As-Sahba', he prepared (a special meal called) Hais, and asked me to invite the men who (came and) ate, and that was the marriage banquet given on the consummation of his marriage to her. Then he proceeded till the mountain of Uhud appeared, whereupon he said, \"This mountain loves us and we love it.\" When he approached Medina, he said, \"O Allah! I make the land between its (i.e., Medina's) two mountains a sanctuary, as the prophet Abraham made Mecca a sanctuary. O Allah! Bless them (the people of Medina) in their Mudd and the Sa' (units of measuring).","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، مَوْلَى الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأَبِي طَلْحَةَ ‏\"‏ الْتَمِسْ لَنَا غُلاَمًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي ‏\"‏‏.‏ فَخَرَجَ بِي أَبُو طَلْحَةَ يُرْدِفُنِي وَرَاءَهُ، فَكُنْتُ أَخْدُمُ رَسُولَ اللَّهِ صلى الله عليه وسلم كُلَّمَا نَزَلَ، فَكُنْتُ أَسْمَعُهُ يُكْثِرُ أَنْ يَقُولَ ‏\"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ ‏\"‏‏.‏ فَلَمْ أَزَلْ أَخْدُمُهُ حَتَّى أَقْبَلْنَا مِنْ خَيْبَرَ، وَأَقْبَلَ بِصَفِيَّةَ بِنْتِ حُيَىٍّ قَدْ حَازَهَا، فَكُنْتُ أَرَاهُ يُحَوِّي وَرَاءَهُ بِعَبَاءَةٍ أَوْ كِسَاءٍ ثُمَّ يُرْدِفُهَا وَرَاءَهُ حَتَّى إِذَا كُنَّا بِالصَّهْبَاءِ صَنَعَ حَيْسًا فِي نِطَعٍ، ثُمَّ أَرْسَلَنِي فَدَعَوْتُ رِجَالاً فَأَكَلُوا، وَكَانَ ذَلِكَ بِنَاءَهُ بِهَا، ثُمَّ أَقْبَلَ حَتَّى بَدَا لَهُ أُحُدٌ قَالَ ‏\"‏ هَذَا جُبَيْلٌ يُحِبُّنَا وَنُحِبُّهُ ‏\"‏‏.‏ فَلَمَّا أَشْرَفَ عَلَى الْمَدِينَةِ قَالَ ‏\"‏ اللَّهُمَّ إِنِّي أُحَرِّمُ مَا بَيْنَ جَبَلَيْهَا مِثْلَ مَا حَرَّمَ بِهِ إِبْرَاهِيمُ مَكَّةَ، اللَّهُمَّ بَارِكْ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ ‏\"‏‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 3, Book 10, Hadith 2030","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-3/Book-10/Hadith-2030","x":"It was narrated that' Abdullah bin Mas'ud said:\n\n\"By Allah, for those who would like to go through the process of praying for Allah's curse to be upon the one who is wrong, the shorter Surah concerning women[l] was revealed after (the Verses[2] which speak of the waiting period of) four months and ten (days).\" [1] (65:40), [2] (2:234)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ وَاللَّهِ لَمَنْ شَاءَ لاَعَنَّاهُ لأُنْزِلَتْ سُورَةُ النِّسَاءِ الْقُصْرَى بَعْدَ أَرْبَعَةِ أَشْهُرٍ وَعَشْرًا ‏.‏","v":[]}],"235":[{"c":"Muwatta Malik","r":"Book 28, Hadith 1096","u":"https://quranx.com/Hadith/Malik/In-Book/Book-28/Hadith-1096","x":"Yahya related to me from Malik from Abd ar-Rahman ibn al-Qasim that his father said about the word of Allah, the Blessed, the Exalted, \"There is no fault in you about the proposal you offer to women, or hide in yourselves. Allah knows that you will be mindful of them; but do not make troth with them secretly without honourable words,\" (Sura 2 ayat 235) that it referred to a man saying to a woman while she was still in her idda after the death of her husband, \"You are dear to me, and I desire you, and Allah brings provision and blessing to you,\" and words such as these.","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ، عَنْ أَبِيهِ، أَنَّهُ كَانَ يَقُولُ فِي قَوْلِ اللَّهِ تَبَارَكَ وَتَعَالَى ‏{‏وَلاَ جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّسَاءِ أَوْ أَكْنَنْتُمْ فِي أَنْفُسِكُمْ عَلِمَ اللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَكِنْ لاَ تُوَاعِدُوهُنَّ سِرًّا إِلاَّ أَنْ تَقُولُوا قَوْلاً مَعْرُوفًا‏}‏ أَنْ يَقُولَ الرَّجُلُ لِلْمَرْأَةِ وَهِيَ فِي عِدَّتِهَا مِنْ وَفَاةِ زَوْجِهَا إِنَّكِ عَلَىَّ لَكَرِيمَةٌ وَإِنِّي فِيكِ لَرَاغِبٌ وَإِنَّ اللَّهَ لَسَائِقٌ إِلَيْكِ خَيْرًا وَرِزْقًا وَنَحْوَ هَذَا مِنَ الْقَوْلِ ‏.‏","v":[]}],"237":[{"c":"Muwatta Malik","r":"Book 28, Hadith 1104","u":"https://quranx.com/Hadith/Malik/In-Book/Book-28/Hadith-1104","x":"Yahya related to me from Malik that he had heard that Umar ibn Abd al-Aziz during his khalifate, wrote to one of his governors, \"Whatever a father, or guardian, who gives someone in marriage, makes a condition in the way of unreturnable gift or of favour, belongs to the woman if she wants it.\" Malik spoke about a woman whose father gave her in marriage and made an unreturnable gift a condition of the bride-price which was to be given. He said, \"Whatever is given as a condition by which marriage occurs belongs to the woman if she wants it. If the husband parts from her before the marriage is consummated, the husband has half of the unreturnable gift by which the marriage occurred.\" Malik said about a man who married off his young son and the son had no wealth at all, that the bride- price was obliged of the father if the young man had no property on the day of marriage. If the young man did have property the bride- price was taken from his property unless the father stipulated that he would pay the bride-price. The marriage was affirmed for the son if he was a minor only if he was under the guardianship of his father. Malik said that if a man divorced his wife before he had consummated the marriage and she was a virgin, her father returned half of the bride-price to him. That half was permitted to the husband from the father to compensate him for his expenses. Malik said that that was because Allah, the Blessed, the Exalted, said in His Book, \"Unless they (women with whom he had not consummated marriage) make remission or he makes remission to him in whose hand is the knot of marriage.\" (Sura 2 ayat 237). (He being the father of a virgin daughter or the master of a female slave.) Malik said, \"That is what I have heard about the matter, and that is how things are done among us.\" Malik said that a jewish or christian woman who was married to a jew or christian and then became muslim before the marriage had been consummated, did not keep anything from the bride-price. Malik said, \"I do not think that women should be married for less than a quarter of a dinar. That is the lowest amount for which cutting off the hand is obliged.\"","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ، كَتَبَ فِي خِلاَفَتِهِ إِلَى بَعْضِ عُمَّالِهِ أَنَّ كُلَّ مَا اشْتَرَطَ الْمُنْكِحُ - مَنْ كَانَ أَبًا أَوْ غَيْرَهُ - مِنْ حِبَاءٍ أَوْ كَرَامَةٍ فَهُوَ لِلْمَرْأَةِ إِنِ ابْتَغَتْهُ ‏.‏ قَالَ مَالِكٌ فِي الْمَرْأَةِ يُنْكِحُهَا أَبُوهَا وَيَشْتَرِطُ فِي صَدَاقِهَا الْحِبَاءَ يُحْبَى بِهِ إِنَّ مَا كَانَ مِنْ شَرْطٍ يَقَعُ بِهِ النِّكَاحُ فَهُوَ لاِبْنَتِهِ إِنِ ابْتَغَتْهُ وَإِنْ فَارَقَهَا زَوْجُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا فَلِزَوْجِهَا شَطْرُ الْحِبَاءِ الَّذِي وَقَعَ بِهِ النِّكَاحُ ‏.‏ قَالَ مَالِكٌ فِي الرَّجُلِ يُزَوِّجُ ابْنَهُ صَغِيرًا لاَ مَالَ لَهُ إِنَّ الصَّدَاقَ عَلَى أَبِيهِ إِذَا كَانَ الْغُلاَمُ يَوْمَ تَزَوَّجَ لاَ مَالَ لَهُ وَإِنْ كَانَ لِلْغُلاَمِ مَالٌ فَالصَّدَاقُ فِي مَالِ الْغُلاَمِ إِلاَّ أَنْ يُسَمِّيَ الأَبُ أَنَّ الصَّدَاقَ عَلَيْهِ وَذَلِكَ النِّكَاحُ ثَابِتٌ عَلَى الاِبْنِ إِذَا كَانَ صَغِيرًا وَكَانَ فِي وِلاَيَةِ أَبِيهِ ‏.‏ قَالَ مَالِكٌ فِي طَلاَقِ الرَّجُلِ امْرَأَتَهُ قَبْلَ أَنْ يَدْخُلَ بِهَا وَهِيَ بِكْرٌ فَيَعْفُوَ أَبُوهَا عَنْ نِصْفِ الصَّدَاقِ إِنَّ ذَلِكَ جَائِزٌ لِزَوْجِهَا مِنْ أَبِيهَا فِيمَا وَضَعَ عَنْهُ ‏.‏ قَالَ مَالِكٌ وَذَلِكَ أَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ فِي كِتَابِهِ ‏{‏إِلاَّ أَنْ يَعْفُونَ‏}‏ فَهُنَّ النِّسَاءُ اللاَّتِي قَدْ دُخِلَ بِهِنَّ ‏{‏أَوْ يَعْفُوَ الَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ‏}‏ فَهُوَ الأَبُ فِي ابْنَتِهِ الْبِكْرِ وَالسَّيِّدُ فِي أَمَتِهِ ‏.‏ قَالَ مَالِكٌ وَهَذَا الَّذِي سَمِعْتُ فِي ذَلِكَ وَالَّذِي عَلَيْهِ الأَمْرُ عِنْدَنَا ‏.‏ قَالَ مَالِكٌ فِي الْيَهُودِيَّةِ أَوِ النَّصْرَانِيَّةِ تَحْتَ الْيَهُودِيِّ أَوِ النَّصْرَانِيِّ فَتُسْلِمُ قَبْلَ أَنْ يَدْخُلَ بِهَا أَنَّهُ لاَ صَدَاقَ لَهَا ‏.‏ قَالَ مَالِكٌ لاَ أَرَى أَنْ تُنْكَحَ الْمَرْأَةُ بِأَقَلَّ مِنْ رُبْعِ دِينَارٍ وَذَلِكَ أَدْنَى مَا يَجِبُ فِيهِ الْقَطْعُ ‏.‏","v":[]}],"238":[{"c":"Sunan Abu Dawud","r":"Hadith 410","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-410","x":"Abu Yunus, the freed slave of 'Aishah said:\n\n'Aishah commanded me to write for her come passage from the Qur'an. She also added: When you reach the following verse, inform me: \"Be guardian of your prayers and of the midmost prayer\" (2:238). When I reached it, I informed her. She asked me to write: \"Be guardians of your prayers, and of the midmost prayer, and of the 'Asr prayer, and stand up with devotion of Allah\" (2:238). 'Aishah then said: I heard it from the Messenger of Allah (ﷺ).","ar":"حَدَّثَنَا الْقَعْنَبِيُّ، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنِ الْقَعْقَاعِ بْنِ حَكِيمٍ، عَنْ أَبِي يُونُسَ، مَوْلَى عَائِشَةَ - رَضِيَ اللَّهُ عَنْهَا - أَنَّهُ قَالَ أَمَرَتْنِي عَائِشَةُ أَنْ أَكْتُبَ لَهَا مُصْحَفًا وَقَالَتْ إِذَا بَلَغْتَ هَذِهِ الآيَةَ فَآذِنِّي ‏{‏ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاَةِ الْوُسْطَى ‏}‏ فَلَمَّا بَلَغْتُهَا آذَنْتُهَا فَأَمْلَتْ عَلَىَّ ‏{‏ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاَةِ الْوُسْطَى وَصَلاَةِ الْعَصْرِ وَقُومُوا لِلَّهِ قَانِتِينَ ‏}‏ ثُمَّ قَالَتْ عَائِشَةُ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 411","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-411","x":"Zaid b. Thabit said:\n\nThe Messenger of Allah (ﷺ) used to offer the Zuhr prayer in midday heat; and no prayer was harder on the Companions of the Messenger of Allah (ﷺ) that this one. Hence the revelation came down: \"Be guardians of your prayers, and of the midmost prayer\" (2:238). He (the narrator) said: There are two prayers before it and two prayers after it.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنِي مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، حَدَّثَنِي عَمْرُو بْنُ أَبِي حَكِيمٍ، قَالَ سَمِعْتُ الزِّبْرِقَانَ، يُحَدِّثُ عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، عَنْ زَيْدِ بْنِ ثَابِتٍ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي الظُّهْرَ بِالْهَاجِرَةِ وَلَمْ يَكُنْ يُصَلِّي صَلاَةً أَشَدَّ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْهَا فَنَزَلَتْ ‏{‏ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاَةِ الْوُسْطَى ‏}‏ وَقَالَ ‏\"‏ إِنَّ قَبْلَهَا صَلاَتَيْنِ وَبَعْدَهَا صَلاَتَيْنِ ‏\"‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 949","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-949","x":"Zaid b. Arqam said ; One of us used to speak to the man standing by his side during prayer. Then the Quranic verse \" And stand up with devotion to Allah\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عِيسَى، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ، عَنِ الْحَارِثِ بْنِ شُبَيْلٍ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، عَنْ زَيْدِ بْنِ أَرْقَمَ، قَالَ كَانَ أَحَدُنَا يُكَلِّمُ الرَّجُلَ إِلَى جَنْبِهِ فِي الصَّلاَةِ فَنَزَلَتْ ‏{‏ وَقُومُوا لِلَّهِ قَانِتِينَ ‏}‏ فَأُمِرْنَا بِالسُّكُوتِ وَنُهِينَا عَنِ الْكَلاَمِ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1200","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1200","x":"Narrated Zaid bin Arqam:\n\nIn the lifetime of the Prophet (ﷺ) we used to speak while praying, and one of us would tell his needs to his companions, till the verse, 'Guard strictly your prayers (2.238) was revealed. After that we were ordered to remain silent while praying.","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى، أَخْبَرَنَا عِيسَى ـ هُوَ ابْنُ يُونُسَ ـ عَنْ إِسْمَاعِيلَ، عَنِ الْحَارِثِ بْنِ شُبَيْلٍ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، قَالَ قَالَ لِي زَيْدُ بْنُ أَرْقَمَ إِنْ كُنَّا لَنَتَكَلَّمُ فِي الصَّلاَةِ عَلَى عَهْدِ النَّبِيِّ صلى الله عليه وسلم، يُكَلِّمُ أَحَدُنَا صَاحِبَهُ بِحَاجَتِهِ حَتَّى نَزَلَتْ ‏{‏حَافِظُوا عَلَى الصَّلَوَاتِ‏}‏ الآيَةَ، فَأُمِرْنَا بِالسُّكُوتِ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 539a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-539a","x":"Zaid b. Arqam reported:\n\nWe used to talk while engaged in prayer and a person talked with a companion on his side in prayer till (this verse) was revealed:\" And stand before Allah in devout obedience\" (ii, 238) and we were commanded to observe silence (in prayer) and were forbidden to speak.","ar":"حَدَّثَنَا يَحْيَى بْنُ يَحْيَى، أَخْبَرَنَا هُشَيْمٌ، عَنْ إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ، عَنِ الْحَارِثِ بْنِ شُبَيْلٍ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، عَنْ زَيْدِ بْنِ أَرْقَمَ، قَالَ كُنَّا نَتَكَلَّمُ فِي الصَّلاَةِ يُكَلِّمُ الرَّجُلُ صَاحِبَهُ وَهُوَ إِلَى جَنْبِهِ فِي الصَّلاَةِ حَتَّى نَزَلَتْ ‏{‏ وَقُومُوا لِلَّهِ قَانِتِينَ‏}‏ فَأُمِرْنَا بِالسُّكُوتِ وَنُهِينَا عَنِ الْكَلاَمِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 629","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-629","x":"Abu Yunus, the freed slave of 'A'isha said:\n\n'A'isha ordered me to transcribe a copy of the Qur'an for her and said: When you reach this verse:\" Guard the prayers and the middle prayer\" (ii. 238), inform me; so when I reached it, I informed her and she gave me dictation (like this): Guard the prayers and the middle prayer and the afternoon prayer, and stand up truly obedient to Allah. 'A'isha said: This is how I have heard from the Messenger of Allah (ﷺ).","ar":"وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ، قَالَ قَرَأْتُ عَلَى مَالِكٍ عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنِ الْقَعْقَاعِ بْنِ حَكِيمٍ، عَنْ أَبِي يُونُسَ، مَوْلَى عَائِشَةَ أَنَّهُ قَالَ أَمَرَتْنِي عَائِشَةُ أَنْ أَكْتُبَ لَهَا مُصْحَفًا وَقَالَتْ إِذَا بَلَغْتَ هَذِهِ الآيَةَ فَآذِنِّي ‏{‏ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاَةِ الْوُسْطَى‏}‏ فَلَمَّا بَلَغْتُهَا آذَنْتُهَا فَأَمْلَتْ عَلَىَّ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاَةِ الْوُسْطَى وَصَلاَةِ الْعَصْرِ ‏.‏ وَقُومُوا لِلَّهِ قَانِتِينَ ‏.‏ قَالَتْ عَائِشَةُ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 1, Book 2, Hadith 405","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-1/Book-2/Hadith-405","x":"Zaid bin Arqam narrated:\n\n\"We used to talk behind Allah's Messenger (S) during the Salat, a man among us would talk to his companions next to him until (the following) was revealed: And stand before Allah with obedience. (2:238) So we were ordered to be silent and prohibited from talking.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ، عَنِ الْحَارِثِ بْنِ شُبَيْلٍ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، عَنْ زَيْدِ بْنِ أَرْقَمَ، قَالَ كُنَّا نَتَكَلَّمُ خَلْفَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي الصَّلاَةِ يُكَلِّمُ الرَّجُلُ مِنَّا صَاحِبَهُ إِلَى جَنْبِهِ حَتَّى نَزَلَتْ ‏:‏ ‏(‏وَقُومُوا لِلَّهِ قَانِتِينَ ‏)‏ فَأُمِرْنَا بِالسُّكُوتِ وَنُهِينَا عَنِ الْكَلاَمِ ‏.‏ قَالَ وَفِي الْبَابِ عَنِ ابْنِ مَسْعُودٍ وَمُعَاوِيَةَ بْنِ الْحَكَمِ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ زَيْدِ بْنِ أَرْقَمَ حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَالْعَمَلُ عَلَيْهِ عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ ‏.‏ قَالُوا إِذَا تَكَلَّمَ الرَّجُلُ عَامِدًا فِي الصَّلاَةِ أَوْ نَاسِيًا أَعَادَ الصَّلاَةَ ‏.‏ وَهُوَ قَوْلُ سُفْيَانَ الثَّوْرِيِّ وَابْنِ الْمُبَارَكِ وَأَهْلِ الْكُوفَةِ ‏.‏ وَقَالَ بَعْضُهُمْ إِذَا تَكَلَّمَ عَامِدًا فِي الصَّلاَةِ أَعَادَ الصَّلاَةَ وَإِنْ كَانَ نَاسِيًا أَوْ جَاهِلاً أَجْزَأَهُ ‏.‏ وَبِهِ يَقُولُ الشَّافِعِيُّ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2982","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2982","x":"Narrated Abu Yunus, the freed slave of 'Aishah:\n\n\"'Aishah ordered me to write a Mushaf for her, and she said: 'When you get to this Ayah then tell me: Guard strictly (the five obligatory) prayers, and the middle Salat (2:238). So when I reached it, I told her and she dictated to me: 'Guard strictly (the five obligatory) prayers, and the middle Salat, and Salat Al-'Asr. And stand before Allah with obedience.' She said: 'I heard that from the Messenger of Allah (ﷺ).'","ar":"حَدَّثَنَا قُتَيْبَةُ، عَنْ مَالِكِ بْنِ أَنَسٍ، ح قَالَ وَحَدَّثَنَا الأَنْصَارِيُّ، حَدَّثَنَا مَعْنٌ، حَدَّثَنَا مَالِكٌ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنِ الْقَعْقَاعِ بْنِ حَكِيمٍ، عَنْ أَبِي يُونُسَ، مَوْلَى عَائِشَةَ قَالَ أَمَرَتْنِي عَائِشَةُ رضى الله عنها أَنْ أَكْتُبَ لَهَا مُصْحَفًا فَقَالَتْ إِذَا بَلَغْتَ هَذِهِ الآيَةَ فَآذِنِّي ‏:‏ ‏(‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاَةِ الْوُسْطَى ‏)‏ فَلَمَّا بَلَغْتُهَا آذَنْتُهَا فَأَمْلَتْ عَلَىَّ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاَةِ الْوُسْطَى وَصَلاَةِ الْعَصْرِ وَقُومُوا لِلَّهِ قَانِتِينَ وَقَالَتْ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ وَفِي الْبَابِ عَنْ حَفْصَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2986","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2986","x":"Narrated Zaid bin Arqam:\n\n\"During the time of the Messenger of Allah (ﷺ), we would talk during Salat, so 'And stand before Allah with obedience (2:238) was revealed, ordering us to be silent.\" (Another chain) with similar wordings, but he added: \"And we were forbidden from talking.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا مَرْوَانُ بْنُ مُعَاوِيَةَ، وَيَزِيدُ بْنُ هَارُونَ، وَمُحَمَّدُ بْنُ عُبَيْدٍ، عَنْ إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ، عَنِ الْحَارِثِ بْنِ شُبَيْلٍ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، عَنْ زَيْدِ بْنِ أَرْقَمَ، قَالَ كُنَّا نَتَكَلَّمُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي الصَّلاَةِ فَنَزَلَتْ ‏:‏ ‏(‏وَقُومُوا لِلَّهِ قَانِتِينَ ‏)‏ فَأُمِرْنَا بِالسُّكُوتِ ‏.‏ حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا هُشَيْمٌ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ، نَحْوَهُ وَزَادَ فِيهِ وَنُهِينَا عَنِ الْكَلاَمِ، ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَأَبُو عَمْرٍو الشَّيْبَانِيُّ اسْمُهُ سَعْدُ بْنُ إِيَاسٍ ‏.‏","v":[]}],"240":[{"c":"Sunan Abu Dawud","r":"Hadith 2305","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2305","x":"Umm Hakim, daughter of Usayd, reported on the authority of her mother that her husband died and she was suffering from sore eyes. She therefore applied collyrium (jala'). Ahmad said:\n\nThe correct version is \"glittering collyrium (kuhl al-jala'). She sent her slave-girl to Umm Salamah, and she asked her about the use of glittering collyrium (kuhl al-jala'). She said: Do not apply it except in the case of dire need which is troubling you. In that case you can use it at night, but you should remove it in the daytime. Then Umm Salamah said: The Messenger of Allah (ﷺ) came to visit me when AbuSalamah died, and I had put the juice of aloes in my eye. He asked : What is this, Umm Salamah? I replied: It is only the juice of aloes and contains no perfume. He said: It gives the face a glow, so apply it only at night and remove it in daytime, and do not comb yourself with scent or henna, for it is a dye. I asked: What should I use when I comb myself, Messenger of Allah? He said: Use lote-tree leaves and smear your head copiously with them.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي مَخْرَمَةُ، عَنْ أَبِيهِ، قَالَ سَمِعْتُ الْمُغِيرَةَ بْنَ الضَّحَّاكِ، يَقُولُ أَخْبَرَتْنِي أُمُّ حَكِيمٍ بِنْتُ أُسَيْدٍ، عَنْ أُمِّهَا، أَنَّ زَوْجَهَا، تُوُفِّيَ وَكَانَتْ تَشْتَكِي عَيْنَيْهَا فَتَكْتَحِلُ بِالْجَلاَءِ - قَالَ أَحْمَدُ الصَّوَابُ بِكُحْلِ الْجَلاَءِ - فَأَرْسَلَتْ مَوْلاَةً لَهَا إِلَى أُمِّ سَلَمَةَ فَسَأَلَتْهَا عَنْ كُحْلِ الْجَلاَءِ فَقَالَتْ لاَ تَكْتَحِلِي بِهِ إِلاَّ مِنْ أَمْرٍ لاَ بُدَّ مِنْهُ يَشْتَدُّ عَلَيْكِ فَتَكْتَحِلِينَ بِاللَّيْلِ وَتَمْسَحِينَهُ بِالنَّهَارِ ‏.‏ ثُمَّ قَالَتْ عِنْدَ ذَلِكَ أُمُّ سَلَمَةَ دَخَلَ عَلَىَّ رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَ تُوُفِّيَ أَبُو سَلَمَةَ وَقَدْ جَعَلْتُ عَلَى عَيْنِي صَبِرًا فَقَالَ ‏\"‏ مَا هَذَا يَا أُمَّ سَلَمَةَ ‏\"‏ ‏.‏ فَقُلْتُ إِنَّمَا هُوَ صَبِرٌ يَا رَسُولَ اللَّهِ لَيْسَ فِيهِ طِيبٌ ‏.‏ قَالَ ‏\"‏ إِنَّهُ يَشُبُّ الْوَجْهَ فَلاَ تَجْعَلِيهِ إِلاَّ بِاللَّيْلِ وَتَنْزِعِينَهُ بِالنَّهَارِ وَلاَ تَمْتَشِطِي بِالطِّيبِ وَلاَ بِالْحِنَّاءِ فَإِنَّهُ خِضَابٌ ‏\"‏ ‏.‏ قَالَتْ قُلْتُ بِأَىِّ شَىْءٍ أَمْتَشِطُ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ بِالسِّدْرِ تُغَلِّفِينَ بِهِ رَأْسَكِ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4530","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4530","x":"Narrated Ibn Az-Zubair:\n\nI said to `Uthman bin `Affan (while he was collecting the Qur'an) regarding the Verse:-- \"Those of you who die and leave wives...\" (2.240) \"This Verse was abrogated by an other Verse. So why should you write it? (Or leave it in the Qur'an)?\" `Uthman said. \"O son of my brother! I will not shift anything of it from its place.\"","ar":"حَدَّثَنِي أُمَيَّةُ بْنُ بِسْطَامٍ، حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، عَنْ حَبِيبٍ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، قَالَ ابْنُ الزُّبَيْرِ قُلْتُ لِعُثْمَانَ بْنِ عَفَّانَ ‏{‏وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا‏}‏ قَالَ قَدْ نَسَخَتْهَا الآيَةُ الأُخْرَى فَلِمَ تَكْتُبُهَا أَوْ تَدَعُهَا قَالَ يَا ابْنَ أَخِي، لاَ أُغَيِّرُ شَيْئًا مِنْهُ مِنْ مَكَانِهِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4531","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4531","x":"Narrated Mujahi:\n\n(regarding the Verse):-- \"Those of you who die and leave wives behind. They - (their wives) -- shall wait (as regards their marriage ) for four months and ten days).\" (2.234) The widow, according to this Verse, was to spend this period of waiting with her husband's family, so Allah revealed: \"Those of you who die and leave wives (i.e. widows) should bequeath for their wives, a year's maintenance and residences without turning them out, but if they leave (their residence), there is no blame on you for what they do with themselves provided it is honorable.' (i.e. lawful marriage) (2.240). So Allah entitled the widow to be bequeathed extra maintenance for seven months and twenty nights, and that is the completion of one year. If she wished she could stay (in her husband's home) according to the will, and she could leave it if she wished, as Allah says: \"..without turning them out, but if they leave (the residence), there is no blame on you.\" So the 'Idda (i.e. four months and ten days as it) is obligatory for her. 'Ata said: Ibn `Abbas said, \"This Verse, i.e. the Statement of Allah: \"..without turning them out..\" cancelled the obligation of staying for the waiting period in her dead husband's house, and she can complete this period wherever she likes.\" 'Ata's aid: If she wished, she could complete her 'Idda by staying in her dead husband's residence according to the will or leave it according to Allah's Statement:-- \"There is no blame on you for what they do with themselves.\" `Ata' added: Later the regulations of inheritance came and abrogated the order of the dwelling of the widow (in her dead husband's house), so she could complete the 'Idda wherever she likes. And it was no longer necessary to provide her with a residence. Ibn `Abbas said, \"This Verse abrogated her (i.e. widow's) dwelling in her dead husband's house and she could complete the 'Idda (i.e. four months and ten days) wherever she liked, as Allah's Statement says:--\"...without turning them out...\"","ar":"حَدَّثَنَا إِسْحَاقُ، حَدَّثَنَا رَوْحٌ، حَدَّثَنَا شِبْلٌ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، ‏{‏وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا‏}‏ قَالَ كَانَتْ هَذِهِ الْعِدَّةُ تَعْتَدُّ عِنْدَ أَهْلِ زَوْجِهَا وَاجِبٌ، فَأَنْزَلَ اللَّهُ ‏{‏وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا وَصِيَّةً لأَزْوَاجِهِمْ مَتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلاَ جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنْفُسِهِنَّ مِنْ مَعْرُوفٍ‏}‏ قَالَ جَعَلَ اللَّهُ لَهَا تَمَامَ السَّنَةِ سَبْعَةَ أَشْهُرٍ وَعِشْرِينَ لَيْلَةً وَصِيَّةً، إِنْ شَاءَتْ سَكَنَتْ فِي وَصِيَّتِهَا، وَإِنْ شَاءَتْ خَرَجَتْ، وَهْوَ قَوْلُ اللَّهِ تَعَالَى ‏{‏غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلاَ جُنَاحَ عَلَيْكُمْ‏}‏ فَالْعِدَّةُ كَمَا هِيَ وَاجِبٌ عَلَيْهَا‏.‏ زَعَمَ ذَلِكَ عَنْ مُجَاهِدٍ‏.‏ وَقَالَ عَطَاءٌ قَالَ ابْنُ عَبَّاسٍ نَسَخَتْ هَذِهِ الآيَةُ عِدَّتَهَا عِنْدَ أَهْلِهَا، فَتَعْتَدُّ حَيْثُ شَاءَتْ، وَهْوَ قَوْلُ اللَّهِ تَعَالَى ‏{‏غَيْرَ إِخْرَاجٍ‏}‏‏.‏ قَالَ عَطَاءٌ إِنْ شَاءَتِ اعْتَدَّتْ عِنْدَ أَهْلِهِ وَسَكَنَتْ فِي وَصِيَّتِهَا، وَإِنْ شَاءَتْ خَرَجَتْ لِقَوْلِ اللَّهِ تَعَالَى ‏{‏فَلاَ جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ‏}‏‏.‏ قَالَ عَطَاءٌ ثُمَّ جَاءَ الْمِيرَاثُ فَنَسَخَ السُّكْنَى فَتَعْتَدُّ حَيْثُ شَاءَتْ، وَلاَ سُكْنَى لَهَا‏.‏ وَعَنْ مُحَمَّدِ بْنِ يُوسُفَ حَدَّثَنَا وَرْقَاءُ عَنِ ابْنِ أَبِي نَجِيحٍ عَنْ مُجَاهِدٍ بِهَذَا‏.‏ وَعَنِ ابْنِ أَبِي نَجِيحٍ عَنْ عَطَاءٍ عَنِ ابْنِ عَبَّاسٍ قَالَ نَسَخَتْ هَذِهِ الآيَةُ عِدَّتَهَا فِي أَهْلِهَا، فَتَعْتَدُّ حَيْثُ شَاءَتْ لِقَوْلِ اللَّهِ ‏{‏غَيْرَ إِخْرَاجٍ‏}‏ نَحْوَهُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5344","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5344","x":"Narrated Mujahid:\n\n(regarding the Verse): 'If any of you dies and leaves wives behind,' That was the period of the 'Iddah which the widow was obliged to spend in the house of the late husband. Then Allah revealed: And those of you who die and leave wives should bequeath for their wives a year's maintenance and residence without turning them out, but if they leave, there is no blame on you for what they do of themselves, provided it is honorable (i.e. lawful marriage) (2.240) Mujahid said: Allah has ordered that a widow has the right to stay for seven months and twenty days with her husband's relatives through her husband's will and testament so that she will complete the period of one year (of 'Iddah). But the widow has the right to stay that extra period or go out of her husband's house as is indicated by the statement of Allah: 'But if they leave there is no blame on you,... ' (2.240) Ibn `Abbas said: The above Verse has cancelled the order of spending the period of the 'Iddah at her late husband's house, and so she could spend her period of the 'Iddah wherever she likes. And Allah says: 'Without turning them out.' 'Ata said: If she would, she could spend her period of the 'Iddah at her husband's house, and live there according to her (husband's) will and testament, and if she would, she could go out (of her husband's house) as Allah says: 'There is no blame on you for what they do of themselves.' (2.240) 'Ata added: Then the Verses of inheritance were revealed and the order of residence (for the widow) was cancelled, and she could spend her period of the 'Iddah wherever she would like, and she was no longer entitled to be accommodated by her husband's family.","ar":"حَدَّثَنِي إِسْحَاقُ بْنُ مَنْصُورٍ، أَخْبَرَنَا رَوْحُ بْنُ عُبَادَةَ، حَدَّثَنَا شِبْلٌ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، ‏{‏وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا‏}‏ قَالَ كَانَتْ هَذِهِ الْعِدَّةُ تَعْتَدُّ عِنْدَ أَهْلِ زَوْجِهَا وَاجِبًا، فَأَنْزَلَ اللَّهُ ‏{‏وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا وَصِيَّةً لأَزْوَاجِهِمْ مَتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلاَ جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنْفُسِهِنَّ مِنْ مَعْرُوفٍ‏}‏ قَالَ جَعَلَ اللَّهُ لَهَا تَمَامَ السَّنَةِ سَبْعَةَ أَشْهُرٍ وَعِشْرِينَ لَيْلَةً وَصِيَّةً إِنْ شَاءَتْ سَكَنَتْ فِي وَصِيَّتِهَا، وَإِنْ شَاءَتْ خَرَجَتْ، وَهْوَ قَوْلُ اللَّهِ تَعَالَى ‏{‏غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلاَ جُنَاحَ عَلَيْكُمْ‏}‏ فَالْعِدَّةُ كَمَا هِيَ، وَاجِبٌ عَلَيْهَا، زَعَمَ ذَلِكَ عَنْ مُجَاهِدٍ‏.‏ وَقَالَ عَطَاءٌ قَالَ ابْنُ عَبَّاسٍ نَسَخَتْ هَذِهِ الآيَةُ عِدَّتَهَا عِنْدَ أَهْلِهَا، فَتَعْتَدُّ حَيْثُ شَاءَتْ، وَقَوْلُ اللَّهِ تَعَالَى ‏{‏غَيْرَ إِخْرَاجٍ‏}‏‏.‏ وَقَالَ عَطَاءٌ إِنْ شَاءَتِ اعْتَدَّتْ عِنْدَ أَهْلِهَا، وَسَكَنَتْ فِي وَصِيَّتِهَا، وَإِنْ شَاءَتْ خَرَجَتْ لِقَوْلِ اللَّهِ ‏{‏فَلاَ جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ‏}‏‏.‏ قَالَ عَطَاءٌ ثُمَّ جَاءَ الْمِيرَاثُ فَنَسَخَ السُّكْنَى، فَتَعْتَدُّ حَيْثُ شَاءَتْ، وَلاَ سُكْنَى لَهَا‏.‏","v":[]}],"245":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2997","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2997","x":"Narrated Anas:\n\n\"When this Ayah was revealed: By no means shall you attain Al-Birr unless you spend of that which you love (3:92). Or, '...Who is he that will lend to Allah a goodly loan... (2:245)' Abu Talhah - who had a garden - said: 'O Messenger of Allah! My garden is for Allah, and if I was able to keep it secret I would not make it public.' So he said: 'Keep it for your relatives' or 'your close relatives.'\"","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ مَنْصُورٍ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ، حَدَّثَنَا حُمَيْدٌ، عَنْ أَنَسٍ، قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏ لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ ‏)‏ أَوْ ‏:‏ ‏(‏مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا ‏)‏ قَالَ أَبُو طَلْحَةَ وَكَانَ لَهُ حِائِطٌ فَقَالَ يَا رَسُولَ اللَّهِ حَائِطِي لِلَّهِ وَلَوِ اسْتَطَعْتُ أَنْ أُسِرَّهُ لَمْ أُعْلِنْهُ ‏.‏ فَقَالَ ‏\"‏ اجْعَلْهُ فِي قَرَابَتِكَ أَوْ أَقْرَبِيكَ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رَوَاهُ مَالِكُ بْنُ أَنَسٍ عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ عَنْ أَنَسِ بْنِ مَالِكٍ ‏.‏","v":[]}],"249":[{"c":"Sahih Bukhari","r":"Hadith 3957","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3957","x":"Narrated Al-Bara:\n\nThe companions of (the Prophet) Muhammad who took part in Badr, told me that their number was that of Saul's (i.e. Talut's) companions who crossed the river (of Jordan) with him and they were over three-hundred-and-ten men. By Allah, none crossed the river with him but a believer. (See Qur'an 2:249)","ar":"حَدَّثَنَا عَمْرُو بْنُ خَالِدٍ، حَدَّثَنَا زُهَيْرٌ، حَدَّثَنَا أَبُو إِسْحَاقَ، قَالَ سَمِعْتُ الْبَرَاءَ ـ رضى الله عنه ـ يَقُولُ حَدَّثَنِي أَصْحَابُ، مُحَمَّدٍ صلى الله عليه وسلم مِمَّنْ شَهِدَ بَدْرًا أَنَّهُمْ كَانُوا عِدَّةَ أَصْحَابِ طَالُوتَ الَّذِينَ جَازُوا مَعَهُ النَّهَرَ، بِضْعَةَ عَشَرَ وَثَلاَثَمِائَةٍ‏.‏ قَالَ الْبَرَاءُ لاَ وَاللَّهِ مَا جَاوَزَ مَعَهُ النَّهَرَ إِلاَّ مُؤْمِنٌ‏.‏","v":[]}],"255":[{"c":"Sunan Abu Dawud","r":"Hadith 1465","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1465","x":"Qatadah said:\n\nI asked Anas about the recitation of the Qur'an by the Prophet (ﷺ). He said: He used to express all the long accents clearly.","ar":"حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا جَرِيرٌ، عَنْ قَتَادَةَ، قَالَ سَأَلْتُ أَنَسًا عَنْ قِرَاءَةِ النَّبِيِّ، صلى الله عليه وسلم فَقَالَ كَانَ يَمُدُّ مَدًّا ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4014","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4014","x":"Narrated Jarhad:\n\nThe Messenger of Allah (ﷺ) sat with us and my thigh was uncovered. He said: Do you not know that thigh is a private part ?","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ أَبِي النَّضْرِ، عَنْ زُرْعَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ جَرْهَدٍ، عَنْ أَبِيهِ، - قَالَ كَانَ جَرْهَدٌ هَذَا مِنْ أَصْحَابِ الصُّفَّةِ - قَالَ جَلَسَ رَسُولُ اللَّهِ صلى الله عليه وسلم عِنْدَنَا وَفَخِذِي مُنْكَشِفَةٌ فَقَالَ ‏\n\n\"‏ أَمَا عَلِمْتَ أَنَّ الْفَخِذَ عَوْرَةٌ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3275","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3275","x":"Narrated Muhammad bin Sirin:\n\nAbu Huraira said, \"Allah's Messenger (ﷺ) put me in charge of the Zakat of Ramadan (i.e. Zakat-ul-Fitr). Someone came to me and started scooping some of the foodstuff of (Zakat) with both hands. I caught him and told him that I would take him to Allah's Messenger (ﷺ).\" Then Abu Huraira told the whole narration and added \"He (i.e. the thief) said, 'Whenever you go to your bed, recite the Verse of \"Al-Kursi\" (2.255) for then a guardian from Allah will be guarding you, and Satan will not approach you till dawn.' \"On that the Prophet (ﷺ) said, \"He told you the truth, though he is a liar, and he (the thief) himself was a satan.\"","ar":"وَقَالَ عُثْمَانُ بْنُ الْهَيْثَمِ حَدَّثَنَا عَوْفٌ، عَنْ مُحَمَّدِ بْنِ سِيرِينَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ وَكَّلَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم بِحِفْظِ زَكَاةِ رَمَضَانَ، فَأَتَانِي آتٍ، فَجَعَلَ يَحْثُو مِنَ الطَّعَامِ، فَأَخَذْتُهُ فَقُلْتُ لأَرْفَعَنَّكَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم‏.‏ فَذَكَرَ الْحَدِيثَ فَقَالَ إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ، وَلاَ يَقْرَبُكَ شَيْطَانٌ حَتَّى تُصْبِحَ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\n\n\"‏ صَدَقَكَ وَهْوَ كَذُوبٌ، ذَاكَ شَيْطَانٌ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5010","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5010","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) ordered me to guard the Zakat revenue of Ramadan. Then somebody came to me and started stealing from the foodstuff. I caught him and said, \"I will take you to Allah's Messenger (ﷺ)!\" Then Abu Huraira described the whole narration and said: That person said (to me), \"(Please don't take me to Allah's Messenger (ﷺ) and I will tell you a few words by which Allah will benefit you.) When you go to your bed, recite Ayat-al-Kursi, (2.255) for then there will be a guard from Allah who will protect you all night long, and no Satan will come near you until the morning..\" (When the Prophet (ﷺ) heard the story) he said (to me), \"He (who came to you at night) told you the truth although he is a liar; and it was a satan.\"","ar":"وَقَالَ عُثْمَانُ بْنُ الْهَيْثَمِ حَدَّثَنَا عَوْفٌ، عَنْ مُحَمَّدِ بْنِ سِيرِينَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ وَكَّلَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم بِحِفْظِ زَكَاةِ رَمَضَانَ فَأَتَانِي آتٍ فَجَعَلَ يَحْثُو مِنَ الطَّعَامِ فَأَخَذْتُهُ فَقُلْتُ لأَرْفَعَنَّكَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَصَّ الْحَدِيثَ فَقَالَ إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ لَنْ يَزَالَ مَعَكَ مِنَ اللَّهِ حَافِظٌ وَلاَ يَقْرَبُكَ شَيْطَانٌ حَتَّى تُصْبِحَ‏.‏ وَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\n\n\"‏ صَدَقَكَ وَهْوَ كَذُوبٌ ذَاكَ شَيْطَانٌ ‏\"\n\n‏‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 1020","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-1020","x":"Abu Hurairah (May Allah be pleased with him) reported:\n\nThe Messenger of Allah (ﷺ) put me in charge of charity of Ramadan (Sadaqat-ul- Fitr). Somebody came to me and began to take away some food-stuff. I caught him and said, \"I must take you to the Messenger of Allah (ﷺ).\" He said, \"I am a needy man with a large family, and so I have a pressing need.\" I let him go. When I saw the Messenger of Allah (ﷺ) next morning, he asked me, \"O Abu Hurairah! What did your captive do last night?\" I said, \"O Messenger of Allah! He complained of a pressing need and a big family. I felt pity for him so I let him go.\" He (ﷺ) said, \"He told you a lie and he will return.\" I was sure, according to the saying of the Messenger of Allah (ﷺ) that he would return. I waited for him. He sneaked up again and began to steal food-stuff from the Sadaqah. I caught him and said; \"I must take you to the Messenger of Allah (ﷺ).\" He said, \"Let go of me, I am a needy man. I have to bear the expenses of a big family. I will not come back.\" So I took pity on him and let him go. I went at dawn to the Messenger of Allah (ﷺ) who asked me, \"O Abu Hurairah! What did your captive do last night?\" I replied, \"O Messenger of Allah! He complained of a pressing want and the burden of a big family. I took pity on him and so I let him go.\" He (ﷺ) said, \"He told you a lie and he will return.\" (That man) came again to steal the food-stuff. I arrested him and said, \"I must take you to the Messenger of Allah (ﷺ), and this is the last of three times. You promised that you would not come again but you did.\" He said, \"Let go of me, I shall teach you some words with which Allah may benefit you.\" I asked, \"What are those words?\" He replied, \"When you go to bed, recite Ayat-ul- Kursi (2:255) for there will be a guardian appointed over you from Allah, and Satan will not be able to approach you till morning.\" So I let him go. Next morning the Messenger of Allah (ﷺ) asked me, \"What did your prisoner do last night.\" I answered, \"He promised to teach me some words which he claimed will benefit me before Allah. So I let him go.\" The Messenger of Allah (ﷺ) asked, \"What are those words that he taught you?\" I said, \"He told me: 'When you go to bed, recite Ayat- ul-Kursi from the beginning to the end i.e.,[ Allah! none has the right to be worshipped but He, the Ever Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them (His creatures) in this world, and what will happen to them in the Hereafter. And they will never compass anything of His Knowledge except that which He wills. His Kursi encompasses the heavens and the earth, and preserving them does not fatigue Him. And He is the Most High, the Most Great].' (2:255). He added: 'By reciting it, there will be a guardian appointed over you from Allah who will protect you during the night, and Satan will not be able to come near you until morning'.\" The Messenger of Allah (ﷺ) said, \"Verily, he has told you the truth though he is a liar. O Abu Hurairah! Do you know with whom you were speaking for the last three nights?\" I said, \"No.\" He (ﷺ) said, \"He was Shaitan (Satan).\"[Al-Bukhari].","ar":"وعن أبي هريرة رضي الله عنه قال‏:‏ وكلني رسول الله صلى الله عليه وسلم بحفظ زكاة رمضان، فأتاني آتٍ، فجعل يحثو من الطعام، فأخذته فقلت‏:‏ لأرفعنك إلى رسول الله صلى الله عليه وسلم قال‏:‏ إني محتاج، وعلي عيال، وبي حاجة شديدة، فخليت عنه، فأصبحت، فقال رسول الله صلى الله عليه وسلم ‏:‏‏\"‏ يا أبا هريرة، ما فعل أسيرك البارحة‏؟‏‏\"‏ قلت‏:‏ يا رسول الله شكا حاجة وعيالا، فرحمته، فخليت سبيله‏.‏ فقال‏:‏ ‏\"‏ أما إنه قد كذبك وسيعود‏\"‏ فعرفت أنه سيعود لقول رسول الله صلى الله عليه وسلم فرصدته، فجاء يحثو من الطعام، فقلت‏:‏ لأرفعنك إلى رسول الله صلى الله عليه وسلم، قال‏:‏ دعني فإني محتاج، وعلي عيال لا أعود، فرحمته فخليت سبيله، فأصبحت فقال لي رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏يا أبا هريرة، ما فعل أسيرك البارحة‏؟‏‏\"‏ قلت‏:‏ يا رسول الله شكا حاجة وعيالا فرحمته، فخليت سبيله، فقال‏:‏ ‏\"‏إنه قد كذبك وسيعود‏\"‏ فرصدته الثالثة‏.‏ فجاء يحثو من الطعام، فأخذته، فقلت‏:‏ لأرفعنك إلى رسول الله صلى الله عليه وسلم، وهذا آخر ثلاث أنك تزعم أنك لا تعود، ثم تعود‏!‏ فقال‏:‏ دعني فإني أعلمك كلمات ينفعك الله بها، قلت‏:‏ ما هن‏؟‏ قال‏:‏ إذا أويت إلى فراشك فاقرأ آية الكرسي، فإنه لن يزال عليك من الله حافظ، ولا يقربك شيطان حتى تصبح، فخليت سبيله فأصبحت، فقال لي رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏ما فعل أسيرك البارحة‏؟‏ ‏\"‏ قلت‏:‏ يا رسول الله زعم أنه يعلمني كلمات ينفعني الله بها، فخليت سبيله‏.‏ قال‏:‏ ‏\"‏ما هي‏؟‏‏\"‏ قلت‏:‏ قال لي‏:‏ إذا أويت إلى فراشك فاقرأ آية الكرسي من أولها حتى تختم الآية‏:‏ ‏{‏الله لا إله إلا هو الحي القيوم‏}‏ وقال لي‏:‏ لا يزال عليك من الله حافظ، ولن يقربك شيطان حتى تصبح، فقال النبي صلى الله عليه وسلم‏:‏ ‏\"‏أما إنه قد صدقك وهو كذوب، تعلم من تخاطب منذ ثلاث يا أبا هريرة ‏\"‏ ‏؟‏ قلت‏:‏ لا، قال‏:‏ ‏\"‏ذاك شيطان‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏","v":[]}],"256":[{"c":"Sahih Bukhari","r":"Hadith 1070","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1070","x":"Narrated `Abdullah bin Mas`ud:\n\nThe Prophet (ﷺ) recited Surat-an-Najm (53) and prostrated while reciting it and all the people prostrated and a man amongst the people took a handful of stones or earth and raised it to his face and said, \"This is sufficient for me. Later on I saw him killed as a non-believer.\"","ar":"حَدَّثَنَا حَفْصُ بْنُ عُمَرَ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الأَسْوَدِ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَرَأَ سُورَةَ النَّجْمِ فَسَجَدَ بِهَا، فَمَا بَقِيَ أَحَدٌ مِنَ الْقَوْمِ إِلاَّ سَجَدَ، فَأَخَذَ رَجُلٌ مِنَ الْقَوْمِ كَفًّا مِنْ حَصًى أَوْ تُرَابٍ، فَرَفَعَهُ إِلَى وَجْهِهِ وَقَالَ يَكْفِينِي هَذَا، فَلَقَدْ رَأَيْتُهُ بَعْدُ قُتِلَ كَافِرًا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2420","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2420","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"No doubt, I intended to order somebody to pronounce the Iqama of the (compulsory congregational) prayer and then I would go to the houses of those who do not attend the prayer and burn their houses over them.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ حَدَّثَنَا مُحَمَّدُ بْنُ أَبِي عَدِيٍّ، عَنْ شُعْبَةَ، عَنْ سَعْدِ بْنِ إِبْرَاهِيمَ، عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ لَقَدْ هَمَمْتُ أَنْ آمُرَ بِالصَّلاَةِ فَتُقَامَ ثُمَّ أُخَالِفَ إِلَى مَنَازِلِ قَوْمٍ لاَ يَشْهَدُونَ الصَّلاَةَ فَأُحَرِّقَ عَلَيْهِمْ ‏\"\n\n‏‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 1019","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-1019","x":"Ubayy bin Ka'b (May Allah be pleased with him) reported:\n\nThe Messenger of Allah (ﷺ) said: \"Abu Mundhir! Do you know which Ayah in Allah's Book is the greatest?\" I replied: \"It is 'Allah la ilaha illa Huwal-Haiyul-Qayum (Allah! none has the right to be worshipped but He, the Ever Living...)'.\" (2:256) Thereupon he (ﷺ) patted me in the chest and said, \"Rejoice by this knowledge, O Abu Mundhir!\"[Muslim].","ar":"وعن أبي بن كعب رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏\"‏ يا أبا المنذر أتدري أي آية من كتاب الله معك أعظم ‏؟‏ قلت‏:‏ الله لا إله إلا هو الحي القيوم، فضرب في صدري وقال ‏:‏‏\"‏ ليهنك العلم أبا المنذر‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم ‏)‏‏)‏‏.‏","v":[]}],"260":[{"c":"Sahih Bukhari","r":"Hadith 3372","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3372","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"We are more liable to be in doubt than Abraham when he said, 'My Lord! Show me how You give life to the dead.\". He (i.e. Allah) slid: 'Don't you believe then?' He (i.e. Abraham) said: \"Yes, but (I ask) in order to be stronger in Faith.\" (2.260) And may Allah send His Mercy on Lot! He wished to have a powerful support. If I were to stay in prison for such a long time as Joseph did I would have accepted the offer (of freedom without insisting on having my guiltless less declared).","ar":"حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا ابْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، وَسَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ نَحْنُ أَحَقُّ مِنْ إِبْرَاهِيمَ إِذْ قَالَ ‏{‏رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى قَالَ أَوَلَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي‏}‏ وَيَرْحَمُ اللَّهُ لُوطًا، لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ وَلَوْ لَبِثْتُ فِي السِّجْنِ طُولَ مَا لَبِثَ يُوسُفُ لأَجَبْتُ الدَّاعِيَ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4537","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4537","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"We have more right to be in doubt than Abraham when he said, 'My Lord! Show me how You give life to the dead.' He said, 'Do you not believe?' He said, 'Yes (I believe) but to be stronger in Faith.' \"(2.260)","ar":"حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي سَلَمَةَ، وَسَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ نَحْنُ أَحَقُّ بِالشَّكِّ مِنْ إِبْرَاهِيمَ إِذْ قَالَ ‏{‏رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى قَالَ أَوَلَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي‏}‏‏\"\n\n‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4694","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4694","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"May Allah bestow His Mercy on (Prophet) Lot. (When his nation troubled him) he wished if he could betake himself to some powerful support; and if I were to remain in prison for the period Joseph had remained, I would surely respond to the call; and we shall have more right (to be in doubt) than Abraham: When Allah said to him, \"Don't you believe?' Abraham said, 'Yes, (I do believe) but to be stronger in faith; (2.260)","ar":"حَدَّثَنَا سَعِيدُ بْنُ تَلِيدٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ، عَنْ بَكْرِ بْنِ مُضَرَ، عَنْ عَمْرِو بْنِ الْحَارِثِ، عَنْ يُونُسَ بْنِ يَزِيدَ، عَنِ ابْنِ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، وَأَبِي، سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ يَرْحَمُ اللَّهُ لُوطًا، لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ، وَلَوْ لَبِثْتُ فِي السِّجْنِ مَا لَبِثَ يُوسُفُ لأَجَبْتُ الدَّاعِيَ، وَنَحْنُ أَحَقُّ مِنْ إِبْرَاهِيمَ إِذْ قَالَ لَهُ ‏{‏أَوَلَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي‏}‏‏\"\n\n‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 36, Hadith 4026","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-36/Hadith-4026","x":"It was narrated from Abu Hurairah that the Messenger of Allah (ﷺ) said:\n\n\"We are more likely to express doubt than Ibrahim when he said: \"My Lord! Show me how You give life to the dead.’ He (Allah) said: ‘Do you not believe?’ He (Ibrahim) said: ‘Yes (I believe), but to be stronger in Faith.’[2:260] And may Allah have mercy on Lut. He wished to have a powerful support. And if i were to stay in prison as long as Yusuf stayed, I would have accepted the offer.’\"","ar":"حَدَّثَنَا حَرْمَلَةُ بْنُ يَحْيَى، وَيُونُسُ بْنُ عَبْدِ الأَعْلَى، قَالاَ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ بْنُ يَزِيدَ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، وَسَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\n\"‏ نَحْنُ أَحَقُّ بِالشَّكِّ مِنْ إِبْرَاهِيمَ إِذْ قَالَ ‏{رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى قَالَ أَوَ لَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي}‏ وَيَرْحَمُ اللَّهُ لُوطًا لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ وَلَوْ لَبِثْتُ فِي السِّجْنِ طُولَ مَا لَبِثَ يُوسُفُ لأَجَبْتُ الدَّاعِيَ ‏\"\n\n‏ ‏.‏","v":[]}],"261":[{"c":"Sunan Ibn Majah","r":"Volume 4, Book 24, Hadith 2761","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-24/Hadith-2761","x":"It was narrated from ‘Ali bin Abu Talib, Abu Darda’, Abu Hurairah, Abu Umamah Al-Bahili, ‘Abdullah bin ‘Umar, ‘Abdullah bin ‘Amr, Jabir bin ‘Abdullah and ‘Imran bin Husain, all of them narrating that the Messenger of Allah (ﷺ) said:\n\n\"Whoever sends financial support in the cause of Allah and stays at home, for every Dirham he will have (the reward of) seven hundred Dirham. Whoever fights himself in the cause of Allah, and spends on that, for every Dirham he will have (the reward of) seven hundred thousand Dirham.\" Then he recited the Verse: \"Allah gives manifold increase to whom He wills.\"[2:261]","ar":"حَدَّثَنَا هَارُونُ بْنُ عَبْدِ اللَّهِ الْحَمَّالُ، حَدَّثَنَا ابْنُ أَبِي فُدَيْكٍ، عَنِ الْخَلِيلِ بْنِ عَبْدِ اللَّهِ، عَنِ الْحَسَنِ، عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، وَأَبِي الدَّرْدَاءِ، وَأَبِي، هُرَيْرَةَ وَأَبِي أُمَامَةَ الْبَاهِلِيِّ وَعَبْدِ اللَّهِ بْنِ عُمَرَ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو وَجَابِرِ بْنِ عَبْدِ اللَّهِ وَعِمْرَانَ بْنِ الْحُصَيْنِ كُلُّهُمْ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ قَالَ ‏\"‏ مَنْ أَرْسَلَ بِنَفَقَةٍ فِي سَبِيلِ اللَّهِ وَأَقَامَ فِي بَيْتِهِ فَلَهُ بِكُلِّ دِرْهَمٍ سَبْعُمِائَةِ دِرْهَمٍ وَمَنْ غَزَا بِنَفْسِهِ فِي سَبِيلِ اللَّهِ وَأَنْفَقَ فِي وَجْهِ ذَلِكَ فَلَهُ بِكُلِّ دِرْهَمٍ سَبْعُمِائَةِ أَلْفِ دِرْهَمٍ ‏\"‏ ‏.‏ ثُمَّ تَلاَ هَذِهِ الآيَةَ ‏{وَاللَّهُ يُضَاعِفُ لِمَنْ يَشَاءُ}‏ ‏.‏","v":[]}],"267":[{"c":"Sunan Ibn Majah","r":"Volume 3, Book 8, Hadith 1822","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-3/Book-8/Hadith-1822","x":"It was narrated that:\n\nBara bin Azib said concerning the Verse: \"And of that which We have priduced from the earth for you, and don not aim at that which is bad to spend from it. \" [Al-Baqarah 2:267] \"This was revealed concerning the Ansar. At the time of the new date-palm harvest, they would take a bunch of dates that were beginning to ripen and hang it on a rope between two of the pillars in the mosque of the Messenger of Allah (ﷺ), and the poor emigrants would eat from it.\" One of them deliberately mixed a bunch containing rotten and shriveled dates, and thought this was permissible because of the large number of dates that had been put there. So the following was revealed about the one who did that: '… and do not aim at that which is bad to spend from it'. Meaning do not seek out the rotten and shriveled dates to give in charity: '…(thought) you would not accept it save if you close your eyes and tolerate therein.' Meaning, if you were given this as a gift you would only accept it because you felt embarrassed, and you would get angry that he had sent something of which you have no need. And know that Allah has no need of your charity.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ يَحْيَى بْنِ سَعِيدٍ الْقَطَّانُ، حَدَّثَنَا عَمْرُو بْنُ مُحَمَّدٍ الْعَنْقَزِيُّ، حَدَّثَنَا أَسْبَاطُ بْنُ نَصْرٍ، عَنِ السُّدِّيِّ، عَنْ عَدِيِّ بْنِ ثَابِتٍ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، فِي قَوْلِهِ سُبْحَانَهُ ‏{‏وَمِمَّا أَخْرَجْنَا لَكُمْ مِنَ الأَرْضِ وَلاَ تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ}‏ ‏.‏ قَالَ نَزَلَتْ فِي الأَنْصَارِ كَانَتِ الأَنْصَارُ تُخْرِجُ إِذَا كَانَ جِدَادُ النَّخْلِ مِنْ حِيطَانِهَا أَقْنَاءَ الْبُسْرِ فَيُعَلِّقُونَهُ عَلَى حَبْلٍ بَيْنَ أُسْطُوَانَتَيْنِ فِي مَسْجِدِ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فَيَأْكُلُ مِنْهُ فُقَرَاءُ الْمُهَاجِرِينَ فَيَعْمِدُ أَحَدُهُمْ فَيُدْخِلُ قِنْوَ الْحَشَفِ يَظُنُّ أَنَّهُ جَائِزٌ فِي كَثْرَةِ مَا يُوضَعُ مِنَ الأَقْنَاءِ فَنَزَلَ فِيمَنْ فَعَلَ ذَلِكَ ‏{وَلاَ تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ}‏ ‏.‏ يَقُولُ لاَ تَعْمِدُوا لِلْحَشَفِ مِنْهُ تُنْفِقُونَ ‏.‏ ‏{وَلَسْتُمْ بِآخِذِيهِ إِلاَّ أَنْ تُغْمِضُوا فِيهِ }‏ يَقُولُ لَوْ أُهْدِيَ لَكُمْ مَا قَبِلْتُمُوهُ إِلاَّ عَلَى اسْتِحْيَاءٍ مِنْ صَاحِبِهِ غَيْظًا أَنَّهُ بَعَثَ إِلَيْكُمْ مَا لَمْ يَكُنْ لَكُمْ فِيهِ حَاجَةٌ وَاعْلَمُوا أَنَّ اللَّهَ غَنِيٌّ عَنْ صَدَقَاتِكُمْ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2987","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2987","x":"Narrated Abu Malik:\n\nfrom Al-Bara (regarding): And do not aim at that which is bad to spend from it (2:267) - he said: \"It was revealed about us, the people of the Ansar who were date-palm owners. A man would bring the amount of dates that he would from his date-palms, either a lot or a little. A man would bring a cluster or two and hang it in the Masjid. The people of As-Suffah did not have food, so one of them would go up to the cluster and hit it with his stick, and unripe and ripe dates would fall, and he would eat. Some people did not hope for good, so a man would bring a cluster with pitless and hard dates, and a cluster with damaged dates, and hang it. So Allah, Blessed and Most High, revealed: O you who believe! Spend of the good things which you have earned, and of that which We have produced from the earth for you, and do not aim at that which is bad to spend from it (2:267). They said: 'If one of you were given similar to what he gave, he would take it except bashfully with your eyes closed.' So after that, one of us would bring the best that we had.\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ، أَخْبَرَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنِ السُّدِّيِّ، عَنْ أَبِي مَالِكٍ، عَنِ الْبَرَاءِ‏:‏ ‏(‏وَلاَ تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ ‏)‏ قَالَ نَزَلَتْ فِينَا مَعْشَرَ الأَنْصَارِ كُنَّا أَصْحَابَ نَخْلٍ فَكَانَ الرَّجُلُ يَأْتِي مِنْ نَخْلِهِ عَلَى قَدْرِ كَثْرَتِهِ وَقِلَّتِهِ وَكَانَ الرَّجُلُ يَأْتِي بِالْقِنْوِ وَالْقِنْوَيْنِ فَيُعَلِّقُهُ فِي الْمَسْجِدِ وَكَانَ أَهْلُ الصُّفَّةِ لَيْسَ لَهُمْ طَعَامٌ فَكَانَ أَحَدُهُمْ إِذَا جَاعَ أَتَى الْقِنْوَ فَضَرَبَهُ بِعَصَاهُ فَيَسْقُطُ مِنَ الْبُسْرِ وَالتَّمْرِ فَيَأْكُلُ وَكَانَ نَاسٌ مِمَّنْ لاَ يَرْغَبُ فِي الْخَيْرِ يَأْتِي الرَّجُلُ بِالْقِنْوِ فِيهِ الشِّيصُ وَالْحَشَفُ وَبِالْقِنْوِ قَدِ انْكَسَرَ فَيُعَلِّقُهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏يَا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ وَمِمَّا أَخْرَجْنَا لَكُمْ مِنَ الأَرْضِ وَلاَ تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ وَلَسْتُمْ بِآخِذِيهِ إِلاَّ أَنْ تُغْمِضُوا فِيهِ ‏)‏ قَالُوا لَوْ أَنَّ أَحَدَكُمْ أُهْدِيَ إِلَيْهِ مِثْلُ مَا أَعْطَى لَمْ يَأْخُذْهُ إِلاَّ عَلَى إِغْمَاضٍ وَحَيَاءٍ قَالَ فَكُنَّا بَعْدَ ذَلِكَ يَأْتِي أَحَدُنَا بِصَالِحِ مَا عِنْدَهُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ صَحِيحٌ وَأَبُو مَالِكٍ هُوَ الْغِفَارِيُّ وَيُقَالُ اسْمُهُ غَزْوَانُ وَقَدْ رَوَى سُفْيَانُ عَنِ السُّدِّيِّ شَيْئًا مِنْ هَذَا ‏.‏","v":[]}],"268":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2988","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2988","x":"Narrated 'Abdullah bin Mas'ud:\n\nthat the Messenger of Allah (ﷺ) said: \"Indeed the Shaitan has an effect on the son of Adam, and the angel also has en effect. As for the Shaitan, it is by threatening evil repercussions and rejecting the truth. As for the effect of the angel, it is by his promise of a good end and believing in the truth. Whoever finds that, let him know that it is from Allah, and let him praise Allah for it. Whoever finds the other then let him seek refuge with Allah from the Shaitan (the outcast) then recite: Shaitan threatens you with poverty and orders you to commit Fahisha (2:268).\"","ar":"حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ عَطَاءِ بْنِ السَّائِبِ، عَنْ مُرَّةَ الْهَمْدَانِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ لِلشَّيْطَانِ لَمَّةً بِابْنِ آدَمَ وَلِلْمَلَكِ لَمَّةً فَأَمَّا لَمَّةُ الشَّيْطَانِ فَإِيعَادٌ بِالشَّرِّ وَتَكْذِيبٌ بِالْحَقِّ وَأَمَّا لَمَّةُ الْمَلَكِ فَإِيعَادٌ بِالْخَيْرِ وَتَصْدِيقٌ بِالْحَقِّ فَمَنْ وَجَدَ ذَلِكَ فَلْيَعْلَمْ أَنَّهُ مِنَ اللَّهِ فَلْيَحْمَدِ اللَّهَ وَمَنْ وَجَدَ الأُخْرَى فَلْيَتَعَوَّذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ثُمَّ قَرَأ ‏:‏ ‏(‏الشََّيْطَانُ يَعِدُكُمُ الْفَقْرَ وَيَأْمُرُكُمْ بِالْفَحْشَاءِ ‏)‏ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ وَهُوَ حَدِيثُ أَبِي الأَحْوَصِ لاَ نَعْلَمُهُ مَرْفُوعًا إِلاَّ مِنْ حَدِيثِ أَبِي الأَحْوَصِ ‏.‏","v":[]}],"273":[{"c":"Sahih Bukhari","r":"Hadith 4539","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4539","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"The poor person is not the one for whom a date or two or a morsel or two (of food is sufficient but the poor person is he who does not (beg or) ask the people (for something) or show his poverty at all. Recite if you wish, (Allah's Statement): \"They do not beg of people at all.\" (2.273)","ar":"حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، قَالَ حَدَّثَنِي شَرِيكُ بْنُ أَبِي نَمِرٍ، أَنَّ عَطَاءَ بْنَ يَسَارٍ، وَعَبْدَ الرَّحْمَنِ بْنَ أَبِي عَمْرَةَ الأَنْصَارِيَّ، قَالاَ سَمِعْنَا أَبَا هُرَيْرَةَ ـ رضى الله عنه ـ يَقُولُ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ وَلاَ اللُّقْمَةُ وَلاَ اللُّقْمَتَانِ‏.‏ إِنَّمَا الْمِسْكِينُ الَّذِي يَتَعَفَّفُ وَاقْرَءُوا إِنْ شِئْتُمْ يَعْنِي قَوْلَهُ ‏{‏لاَ يَسْأَلُونَ النَّاسَ إِلْحَافًا‏}‏‏\"‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1039b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1039b","x":"Abu Huraira reported Allah's Messenger (ﷺ) as saying:\n\nMiskin is not he who is dismissed with one or two dates, and with one morsel or two morsels. (In fact) miskin is he who abstains (from begging). Read if you so desire (the verse):\" They beg not of men importunately)\" (ii. 273).","ar":"حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، قَالَ ابْنُ أَيُّوبَ حَدَّثَنَا إِسْمَاعِيلُ، - وَهُوَ ابْنُ جَعْفَرٍ - أَخْبَرَنِي شَرِيكٌ، عَنْ عَطَاءِ بْنِ يَسَارٍ، مَوْلَى مَيْمُونَةَ عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ لَيْسَ الْمِسْكِينُ بِالَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ وَلاَ اللُّقْمَةُ وَاللُّقْمَتَانِ إِنَّمَا الْمِسْكِينُ الْمُتَعَفِّفُ اقْرَءُوا إِنْ شِئْتُمْ ‏{‏ لاَ يَسْأَلُونَ النَّاسَ إِلْحَافًا‏}‏ ‏\"\n\n‏ ‏.‏","v":[]}],"275":[{"c":"Sahih Bukhari","r":"Hadith 459","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-459","x":"Narrated `Aisha:\n\nWhen the verses of Surat \"Al-Baqara\"' about the usury Riba were revealed, the Prophet (ﷺ) went to the mosque and recited them in front of the people and then banned the trade of alcohol.","ar":"حَدَّثَنَا عَبْدَانُ، عَنْ أَبِي حَمْزَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ، قَالَتْ لَمَّا أُنْزِلَ الآيَاتُ مِنْ سُورَةِ الْبَقَرَةِ فِي الرِّبَا، خَرَجَ النَّبِيُّ صلى الله عليه وسلم إِلَى الْمَسْجِدِ، فَقَرَأَهُنَّ عَلَى النَّاسِ، ثُمَّ حَرَّمَ تِجَارَةَ الْخَمْرِ‏.‏","v":[]}],"282":[{"c":"Sahih Bukhari","r":"Hadith 304","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-304","x":"Narrated Abu Sa`id Al-Khudri:\n\nOnce Allah's Messenger (ﷺ) went out to the Musalla (to offer the prayer) of `Id-al-Adha or Al-Fitr prayer. Then he passed by the women and said, \"O women! Give alms, as I have seen that the majority of the dwellers of Hell-fire were you (women).\" They asked, \"Why is it so, O Allah's Messenger (ﷺ) ?\" He replied, \"You curse frequently and are ungrateful to your husbands. I have not seen anyone more deficient in intelligence and religion than you. A cautious sensible man could be led astray by some of you.\" The women asked, \"O Allah's Messenger (ﷺ)! What is deficient in our intelligence and religion?\" He said, \"Is not the evidence of two women equal to the witness of one man?\" They replied in the affirmative. He said, \"This is the deficiency in her intelligence. Isn't it true that a woman can neither pray nor fast during her menses?\" The women replied in the affirmative. He said, \"This is the deficiency in her religion.\"","ar":"حَدَّثَنَا سَعِيدُ بْنُ أَبِي مَرْيَمَ، قَالَ أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، قَالَ أَخْبَرَنِي زَيْدٌ ـ هُوَ ابْنُ أَسْلَمَ ـ عَنْ عِيَاضِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ خَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي أَضْحًى ـ أَوْ فِطْرٍ ـ إِلَى الْمُصَلَّى، فَمَرَّ عَلَى النِّسَاءِ فَقَالَ ‏\"‏ يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، فَإِنِّي أُرِيتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ ‏\"‏‏.‏ فَقُلْنَ وَبِمَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ تُكْثِرْنَ اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ، مَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَذْهَبَ لِلُبِّ الرَّجُلِ الْحَازِمِ مِنْ إِحْدَاكُنَّ ‏\"‏‏.‏ قُلْنَ وَمَا نُقْصَانُ دِينِنَا وَعَقْلِنَا يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ أَلَيْسَ شَهَادَةُ الْمَرْأَةِ مِثْلَ نِصْفِ شَهَادَةِ الرَّجُلِ ‏\"‏‏.‏ قُلْنَ بَلَى‏.‏ قَالَ ‏\"‏ فَذَلِكَ مِنْ نُقْصَانِ عَقْلِهَا، أَلَيْسَ إِذَا حَاضَتْ لَمْ تُصَلِّ وَلَمْ تَصُمْ ‏\"‏‏.‏ قُلْنَ بَلَى‏.‏ قَالَ ‏\"‏ فَذَلِكَ مِنْ نُقْصَانِ دِينِهَا ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1462","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1462","x":"Narrated Abu Sa`id Al-Khudri:\n\nOn `Id ul Fitr or `Id ul Adha Allah's Messenger (ﷺ) (p.b.u.h) went out to the Musalla. After finishing the prayer, he delivered the sermon and ordered the people to give alms. He said, \"O people! Give alms.\" Then he went towards the women and said. \"O women! Give alms, for I have seen that the majority of the dwellers of Hell-Fire were you (women).\" The women asked, \"O Allah's Messenger (ﷺ)! What is the reason for it?\" He replied, \"O women! You curse frequently, and are ungrateful to your husbands. I have not seen anyone more deficient in intelligence and religion than you. O women, some of you can lead a cautious wise man astray.\" Then he left. And when he reached his house, Zainab, the wife of Ibn Mas`ud, came and asked permission to enter It was said, \"O Allah's Messenger (ﷺ)! It is Zainab.\" He asked, 'Which Zainab?\" The reply was that she was the wife of Ibn Mas'ub. He said, \"Yes, allow her to enter.\" And she was admitted. Then she said, \"O Prophet of Allah! Today you ordered people to give alms and I had an ornament and intended to give it as alms, but Ibn Mas`ud said that he and his children deserved it more than anybody else.\" The Prophet (ﷺ) replied, \"Ibn Mas`ud had spoken the truth. Your husband and your children had more right to it than anybody else.\"","ar":"حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، قَالَ أَخْبَرَنِي زَيْدٌ، عَنْ عِيَاضِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ ـ رضى الله عنه ـ خَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي أَضْحًى أَوْ فِطْرٍ إِلَى الْمُصَلَّى ثُمَّ انْصَرَفَ فَوَعَظَ النَّاسَ وَأَمَرَهُمْ بِالصَّدَقَةِ فَقَالَ ‏\"‏ أَيُّهَا النَّاسُ تَصَدَّقُوا ‏\"‏‏.‏ فَمَرَّ عَلَى النِّسَاءِ فَقَالَ ‏\"‏ يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ ‏\"‏‏.‏ فَقُلْنَ وَبِمَ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ تُكْثِرْنَ اللَّعْنَ وَتَكْفُرْنَ الْعَشِيرَ، مَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَذْهَبَ لِلُبِّ الرَّجُلِ الْحَازِمِ مِنْ إِحْدَاكُنَّ يَا مَعْشَرَ النِّسَاءِ ‏\"‏‏.‏ ثُمَّ انْصَرَفَ فَلَمَّا صَارَ إِلَى مَنْزِلِهِ جَاءَتْ زَيْنَبُ امْرَأَةُ ابْنِ مَسْعُودٍ تَسْتَأْذِنُ عَلَيْهِ فَقِيلَ يَا رَسُولَ اللَّهِ هَذِهِ زَيْنَبُ فَقَالَ ‏\"‏ أَىُّ الزَّيَانِبِ ‏\"‏‏.‏ فَقِيلَ امْرَأَةُ ابْنِ مَسْعُودٍ‏.‏ قَالَ ‏\"‏ نَعَمِ ائْذَنُوا لَهَا ‏\"‏‏.‏ فَأُذِنَ لَهَا قَالَتْ يَا نَبِيَّ اللَّهِ إِنَّكَ أَمَرْتَ الْيَوْمَ بِالصَّدَقَةِ، وَكَانَ عِنْدِي حُلِيٌّ لِي، فَأَرَدْتُ أَنْ أَتَصَدَّقَ بِهِ، فَزَعَمَ ابْنُ مَسْعُودٍ أَنَّهُ وَوَلَدَهُ أَحَقُّ مَنْ تَصَدَّقْتُ بِهِ عَلَيْهِمْ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ صَدَقَ ابْنُ مَسْعُودٍ، زَوْجُكِ وَوَلَدُكِ أَحَقُّ مَنْ تَصَدَّقْتِ بِهِ عَلَيْهِمْ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2658","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2658","x":"Narrated Abu Sa`id Al-Khudri:\n\nThe Prophet (ﷺ) said, \"Isn't the witness of a woman equal to half of that of a man?\" The women said, \"Yes.\" He said, \"This is because of the deficiency of a woman's mind.\"","ar":"حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، قَالَ أَخْبَرَنِي زَيْدٌ، عَنْ عِيَاضِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ أَلَيْسَ شَهَادَةُ الْمَرْأَةِ مِثْلَ نِصْفِ شَهَادَةِ الرَّجُلِ ‏\"‏‏.‏ قُلْنَا بَلَى‏.‏ قَالَ ‏\"‏ فَذَلِكَ مِنْ نُقْصَانِ عَقْلِهَا ‏\"‏‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 36, Hadith 1411","u":"https://quranx.com/Hadith/Malik/In-Book/Book-36/Hadith-1411","x":"Malik related to me that he heard that Abu Salama ibn Abd ar- Rahman and Sulayman ibn Yasar were both asked, \"Does one pronounce judgement on the basis of an oath with one witness?\" They both said, \"Yes.\" Malik said, \"The precedent of the sunna in judging by an oath with one witness is that if the plaintiff takes an oath with his witness, he is confirmed in his right. If he draws back and refuses to take an oath, the defendant is made to take an oath. If he takes an oath, the claim against him is dropped. If he refuses to take an oath, the claim is confirmed against him.\" Malik said, \"This procedure pertains to property cases in particular. It does not occur in any of the hadd-punishments, nor in marriage, divorce, freeing slaves, theft or slander. If some one says, 'Freeing slaves comes under property,' he has erred. It is not as he said. Had it been as he said, a slave could take an oath with one witness, if he could find one, that his master had freed him. \"However, when a slave lays claim to a piece of property, he can take an oath with one witness and demand his right as the freeman demands his right.\" Malik said, \"The sunna with us is that when a slave brings somebody who witnesses that he has been set free, his master is made to take an oath that he has not freed him, and the slave's claim is dropped.\" Malik said, \"The sunna about divorce is also like that with us. When a woman brings somebody who witnesses that her husband has divorced her, the husband is made to take an oath that he has not divorced her. If he takes the oath, the divorce does not proceed. \" Malik said, \"There is only one sunna of bringing a witness in cases of divorce and freeing a slave. The right to make an oath only belongs to the husband of the woman, and the master of the slave. Freeing is a hadd matter, and the testimony of women is not permitted in it because when a slave is freed, his inviolability is affirmed and the hadd punishments are applied for and against him. If he commits fornication and he is a muhsan, he is stoned. If he kills a slave, he is killed for it. Inheritance is established for him, between him and whoever inherits from him. If somebody disputes this, arguing that if a man frees his slave and then a man comes to demand from the master of the slave payment of a debt, and a man and two women testify to his right, that establishes the right against the master of the slave so that his freeing him is cancelled if he only has the slave as property, inferring by this case that the testimony of women is permitted in cases of setting free. The case is not as he suggests (i.e. it is a case of property not freeing). It is like a man who frees his slave, and then the claimant of a debt comes to the master and takes an oath with one witness, demanding his right. By that, the freeing of the slave would be cancelled. Or else a man comes who has frequent dealings and transactions with the master of the slave. He claims that he is owed money by the master of the slave. Someone says to the master of the slave, 'Take an oath that you don't owe what he claims'. If he draws back and refuses to take an oath, the one making the claim takes an oath and his right against the master of the slave is confirmed. That would cancel the freeing of the slave if it is confirmed that property is owed by the master.\" Malik said, \"It is the same case with a man who marries a slave-girl and then the master of the slave-girl comes to the man who has married her and claims, 'You and so-and-so have bought my slave-girl from me for such an amount of dinars. The husband of the slave-girl denies that. The master of the slave-girl brings a man and two women and they testify to what he has said. The sale is confirmed and his claim is considered true. So the slave-girl is haram for her husband and they have to separate, even though the testimony of women is not accepted in divorce.\" Malik said, \"It is also the same case with a man who accuses a free man, so the hadd falls on him. A man and two women come and testify that the one accused is a slave. That would remove the hadd from the accused after it had befallen him, even though the testimony of women is not accepted in accusations involving hadd punishments.\" Malik said, \"Another similar case in which judgement appears to go against the precedent of the sunna is that two women testify that a child is born alive and so it is necessary for him to inherit if a situation arises where he is entitled to inherit, and the child's property goes to those who inherit from him, if he dies, and it is not necessary that the two women witnesses should be accompanied by a man or an oath even though it may involve vast properties of gold, silver, live-stock, gardens and slaves and other properties. However, had two women testified to one dirham or more or less than that in a property case, their testimony would not affect anything and would not be permitted unless there was a witness or an oath with them.\" Malik said, \"There are people who say that an oath is not acceptable with only one witness and they argue by the word of Allah the Blessed, the Exalted, and His word is the Truth, 'And call in to witness two witnesses, men; or if the two be not men, then one man and two women, such witnesses as you approve of.' (Sura 2 ayat 282). Such people argue that if he does not bring one man and two women, he has no claim and he is not allowed to take an oath with one witness.\" Malik said, \"Part of the proof against those who argue this, is to reply to them, 'Do you think that if a man claimed property from a man, the one claimed from would not swear that the claim was false?' If he swears, the claim against him is dropped. If he refuses to take an oath, the claimant is made to take an oath that his claim is true, and his right against his companion is established. There is no dispute about this with any of the people nor in any country. By what does he take this? In what place in the Book of Allah does he find it? So if he confirms this, let him confirm the oath with one witness, even if it is not in the Book of Allah, the Mighty, the Majestic! It is enough that this is the precedent of the sunna. However, man wants to recognise the proper course of action and the location of the proof. In this there is a clarification for what is obscure about that, if Allah ta'ala wills.\"","ar":"وَحَدَّثَنِي مَالِكٌ، أَنَّهُ بَلَغَهُ أَنَّ أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ، وَسُلَيْمَانَ بْنَ يَسَارٍ، سُئِلاَ هَلْ يُقْضَى بِالْيَمِينِ مَعَ الشَّاهِدِ فَقَالاَ نَعَمْ ‏.‏ قَالَ مَالِكٌ مَضَتِ السُّنَّةُ فِي الْقَضَاءِ بِالْيَمِينِ مَعَ الشَّاهِدِ الْوَاحِدِ يَحْلِفُ صَاحِبُ الْحَقِّ مَعَ شَاهِدِهِ وَيَسْتَحِقُّ حَقَّهُ فَإِنْ نَكَلَ وَأَبَى أَنْ يَحْلِفَ أُحْلِفَ الْمَطْلُوبُ فَإِنْ حَلَفَ سَقَطَ عَنْهُ ذَلِكَ الْحَقُّ وَإِنْ أَبَى أَنْ يَحْلِفَ ثَبَتَ عَلَيْهِ الْحَقُّ لِصَاحِبِهِ ‏.‏ قَالَ مَالِكٌ وَإِنَّمَا يَكُونُ ذَلِكَ فِي الأَمْوَالِ خَاصَّةً وَلاَ يَقَعُ ذَلِكَ فِي شَىْءٍ مِنَ الْحُدُودِ وَلاَ فِي نِكَاحٍ وَلاَ فِي طَلاَقٍ وَلاَ فِي عَتَاقَةٍ وَلاَ فِي سَرِقَةٍ وَلاَ فِي فِرْيَةٍ فَإِنْ قَالَ قَائِلٌ فَإِنَّ الْعَتَاقَةَ مِنَ الأَمْوَالِ ‏.‏ فَقَدْ أَخْطَأَ لَيْسَ ذَلِكَ عَلَى مَا قَالَ وَلَوْ كَانَ ذَلِكَ عَلَى مَا قَالَ لَحَلَفَ الْعَبْدُ مَعَ شَاهِدِهِ إِذَا جَاءَ بِشَاهِدٍ أَنَّ سَيِّدَهُ أَعْتَقَهُ وَأَنَّ الْعَبْدَ إِذَا جَاءَ بِشَاهِدٍ عَلَى مَالٍ مِنَ الأَمْوَالِ ادَّعَاهُ حَلَفَ مَعَ شَاهِدِهِ وَاسْتَحَقَّ حَقَّهُ كَمَا يَحْلِفُ الْحُرُّ ‏.‏ قَالَ مَالِكٌ فَالسُّنَّةُ عِنْدَنَا أَنَّ الْعَبْدَ إِذَا جَاءَ بِشَاهِدٍ عَلَى عَتَاقَتِهِ اسْتُحْلِفَ سَيِّدُهُ مَا أَعْتَقَهُ وَبَطَلَ ذَلِكَ عَنْهُ ‏.‏ قَالَ مَالِكٌ وَكَذَلِكَ السُّنَّةُ عِنْدَنَا أَيْضًا فِي الطَّلاَقِ إِذَا جَاءَتِ الْمَرْأَةُ بِشَاهِدٍ أَنَّ زَوْجَهَا طَلَّقَهَا أُحْلِفَ زَوْجُهَا مَا طَلَّقَهَا فَإِذَا حَلَفَ لَمْ يَقَعْ عَلَيْهِ الطَّلاَقُ ‏.‏ قَالَ مَالِكٌ فَسُنَّةُ الطَّلاَقِ وَالْعَتَاقَةِ فِي الشَّاهِدِ الْوَاحِدِ وَاحِدَةٌ إِنَّمَا يَكُونُ الْيَمِينُ عَلَى زَوْجِ الْمَرْأَةِ وَعَلَى سَيِّدِ الْعَبْدِ وَإِنَّمَا الْعَتَاقَةُ حَدٌّ مِنَ الْحُدُودِ لاَ تَجُوزُ فِيهَا شَهَادَةُ النِّسَاءِ لأَنَّهُ إِذَا عَتَقَ الْعَبْدُ ثَبَتَتْ حُرْمَتُهُ وَوَقَعَتْ لَهُ الْحُدُودُ وَوَقَعَتْ عَلَيْهِ وَإِنْ زَنَى وَقَدْ أُحْصِنَ رُجِمَ وَإِنْ قَتَلَ الْعَبْدَ قُتِلَ بِهِ وَثَبَتَ لَهُ الْمِيرَاثُ بَيْنَهُ وَبَيْنَ مَنْ يُوَارِثُهُ فَإِنِ احْتَجَّ مُحْتَجٌّ فَقَالَ لَوْ أَنَّ رَجُلاً أَعْتَقَ عَبْدَهُ وَجَاءَ رَجُلٌ يَطْلُبُ سَيِّدَ الْعَبْدِ بِدَيْنٍ لَهُ عَلَيْهِ فَشَهِدَ لَهُ عَلَى حَقِّهِ ذَلِكَ رَجُلٌ وَامْرَأَتَانِ فَإِنَّ ذَلِكَ يُثْبِتُ الْحَقَّ عَلَى سَيِّدِ الْعَبْدِ حَتَّى تُرَدَّ بِهِ عَتَاقَتُهُ إِذَا لَمْ يَكُنْ لِسَيِّدِ الْعَبْدِ مَالٌ غَيْرُ الْعَبْدِ يُرِيدُ أَنْ يُجِيزَ بِذَلِكَ شَهَادَةَ النِّسَاءِ فِي الْعَتَاقَةِ فَإِنَّ ذَلِكَ لَيْسَ عَلَى مَا قَالَ وَإِنَّمَا مَثَلُ ذَلِكَ الرَّجُلُ يَعْتِقُ عَبْدَهُ ثُمَّ يَأْتِي طَالِبُ الْحَقِّ عَلَى سَيِّدِهِ بِشَاهِدٍ وَاحِدٍ فَيَحْلِفُ مَعَ شَاهِدِهِ ثُمَّ يَسْتَحِقُّ حَقَّهُ وَتُرَدُّ بِذَلِكَ عَتَاقَةُ الْعَبْدِ أَوْ يَأْتِي الرَّجُلُ قَدْ كَانَتْ بَيْنَهُ وَبَيْنَ سَيِّدِ الْعَبْدِ مُخَالَطَةٌ وَمُلاَبَسَةٌ فَيَزْعُمُ أَنَّ لَهُ عَلَى سَيِّدِ الْعَبْدِ مَالاً فَيُقَالُ لِسَيِّدِ الْعَبْدِ احْلِفْ مَا عَلَيْكَ مَا ادَّعَى فَإِنْ نَكَلَ وَأَبَى أَنْ يَحْلِفَ حُلِّفَ صَاحِبُ الْحَقِّ وَثَبَتَ حَقُّهُ عَلَى سَيِّدِ الْعَبْدِ فَيَكُونُ ذَلِكَ يَرُدُّ عَتَاقَةَ الْعَبْدِ إِذَا ثَبَتَ الْمَالُ عَلَى سَيِّدِهِ ‏.‏ قَالَ وَكَذَلِكَ أَيْضًا الرَّجُلُ يَنْكِحُ الأَمَةَ فَتَكُونُ امْرَأَتَهُ فَيَأْتِي سَيِّدُ الأَمَةِ إِلَى الرَّجُلِ الَّذِي تَزَوَّجَهَا فَيَقُولُ ابْتَعْتَ مِنِّي جَارِيَتِي فُلاَنَةَ أَنْتَ وَفُلاَنٌ بِكَذَا وَكَذَا دِينَارًا ‏.‏ فَيُنْكِرُ ذَلِكَ زَوْجُ الأَمَةِ فَيَأْتِي سَيِّدُ الأَمَةِ بِرَجُلٍ وَامْرَأَتَيْنِ فَيَشْهَدُونَ عَلَى مَا قَالَ فَيَثْبُتُ بَيْعُهُ وَيَحِقُّ حَقُّهُ وَتَحْرُمُ الأَمَةُ عَلَى زَوْجِهَا وَيَكُونُ ذَلِكَ فِرَاقًا بَيْنَهُمَا وَشَهَادَةُ النِّسَاءِ لاَ تَجُوزُ فِي الطَّلاَقِ ‏.‏ قَالَ مَالِكٌ وَمِنْ ذَلِكَ أَيْضًا الرَّجُلُ يَفْتَرِي عَلَى الرَّجُلِ الْحُرِّ فَيَقَعُ عَلَيْهِ الْحَدُّ فَيَأْتِي رَجُلٌ وَامْرَأَتَانِ فَيَشْهَدُونَ أَنَّ الَّذِي افْتُرِيَ عَلَيْهِ عَبْدٌ مَمْلُوكٌ فَيَضَعُ ذَلِكَ الْحَدَّ عَنِ الْمُفْتَرِي بَعْدَ أَنْ وَقَعَ عَلَيْهِ وَشَهَادَةُ النِّسَاءِ لاَ تَجُوزُ فِي الْفِرْيَةِ ‏.‏ قَالَ مَالِكٌ وَمِمَّا يُشْبِهُ ذَلِكَ أَيْضًا مِمَّا يَفْتَرِقُ فِيهِ الْقَضَاءُ وَمَا مَضَى مِنَ السُّنَّةِ أَنَّ الْمَرْأَتَيْنِ يَشْهَدَانِ عَلَى اسْتِهْلاَلِ الصَّبِيِّ فَيَجِبُ بِذَلِكَ مِيرَاثُهُ حَتَّى يَرِثَ وَيَكُونُ مَالُهُ لِمَنْ يَرِثُهُ إِنْ مَاتَ الصَّبِيُّ وَلَيْسَ مَعَ الْمَرْأَتَيْنِ اللَّتَيْنِ شَهِدَتَا رَجُلٌ وَلاَ يَمِينٌ وَقَدْ يَكُونُ ذَلِكَ فِي الأَمْوَالِ الْعِظَامِ مِنَ الذَّهَبِ وَالْوَرِقِ وَالرِّبَاعِ وَالْحَوَائِطِ وَالرَّقِيقِ وَمَا سِوَى ذَلِكَ مِنَ الأَمْوَالِ وَلَوْ شَهِدَتِ امْرَأَتَانِ عَلَى دِرْهَمٍ وَاحِدٍ أَوْ أَقَلَّ مِنْ ذَلِكَ أَوْ أَكْثَرَ لَمْ تَقْطَعْ شَهَادَتُهُمَا شَيْئًا وَلَمْ تَجُزْ إِلاَّ أَنْ يَكُونَ مَعَهُمَا شَاهِدٌ أَوْ يَمِينٌ ‏.‏ قَالَ مَالِكٌ وَمِنَ النَّاسِ مَنْ يَقُولُ لاَ تَكُونُ الْيَمِينُ مَعَ الشَّاهِدِ الْوَاحِدِ ‏.‏ وَيَحْتَجُّ بِقَوْلِ اللَّهِ تَبَارَكَ وَتَعَالَى وَقَوْلُهُ الْحَقُّ ‏{‏وَاسْتَشْهِدُوا شَهِيدَيْنِ مِنْ رِجَالِكُمْ فَإِنْ لَمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتَانِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَدَاءِ‏}‏ يَقُولُ فَإِنْ لَمْ يَأْتِ بِرَجُلٍ وَامْرَأَتَيْنِ فَلاَ شَىْءَ لَهُ وَلاَ يُحَلَّفُ مَعَ شَاهِدِهِ ‏.‏ قَالَ مَالِكٌ فَمِنَ الْحُجَّةِ عَلَى مَنْ قَالَ ذَلِكَ الْقَوْلَ أَنْ يُقَالَ لَهُ أَرَأَيْتَ لَوْ أَنَّ رَجُلاً ادَّعَى عَلَى رَجُلٍ مَالاً أَلَيْسَ يَحْلِفُ الْمَطْلُوبُ مَا ذَلِكَ الْحَقُّ عَلَيْهِ فَإِنْ حَلَفَ بَطَلَ ذَلِكَ عَنْهُ وَإِنْ نَكَلَ عَنِ الْيَمِينِ حُلِّفَ صَاحِبُ الْحَقِّ إِنَّ حَقَّهُ لَحَقٌّ ‏.‏ وَثَبَتَ حَقُّهُ عَلَى صَاحِبِهِ فَهَذَا مَا لاَ اخْتِلاَفَ فِيهِ عِنْدَ أَحَدٍ مِنَ النَّاسِ وَلاَ بِبَلَدٍ مِنَ الْبُلْدَانِ فَبِأَىِّ شَىْءٍ أَخَذَ هَذَا أَوْ فِي أَىِّ مَوْضِعٍ مِنْ كِتَابِ اللَّهِ وَجَدَهُ فَإِنْ أَقَرَّ بِهَذَا فَلْيُقْرِرْ بِالْيَمِينِ مَعَ الشَّاهِدِ وَإِنْ لَمْ يَكُنْ ذَلِكَ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ وَأَنَّهُ لَيَكْفِي مِنْ ذَلِكَ مَا مَضَى مِنَ السُّنَّةِ وَلَكِنِ الْمَرْءُ قَدْ يُحِبُّ أَنْ يَعْرِفَ وَجْهَ الصَّوَابِ وَمَوْقِعَ الْحُجَّةِ فَفِي هَذَا بَيَانُ مَا أَشْكَلَ مِنْ ذَلِكَ إِنْ شَاءَ اللَّهُ تَعَالَى ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 36, Hadith 7","u":"https://quranx.com/Hadith/Malik/USC-MSA/Book-36/Hadith-7","x":"Yahya said that Malik spoke about a man who died and had a debt owing to him and there was one witness, and some people had a debt against him and they had only one witness, and his heirs refused to take an oath on their rights with their witness. He said, \"The creditors take an oath and take their rights. If there is anything left over, the heirs do not take any of it. That is because the oaths were offered to them before and they abandoned them, unless they say, 'We did not know that our companion had extra,' and it is known that they only abandoned the oaths because of that. I think that they should take an oath and take what remains after his debt.\"","ar":"","v":[]}],"284":[{"c":"Sahih Bukhari","r":"Hadith 4545","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4545","x":"Narrated Ibn `Umar:\n\nThis Verse:--\"Whether you show what is in your minds or conceal it..\" (2.284) was abrogated.","ar":"حَدَّثَنَا مُحَمَّدٌ، حَدَّثَنَا النُّفَيْلِيُّ، حَدَّثَنَا مِسْكِينٌ، عَنْ شُعْبَةَ، عَنْ خَالِدٍ الْحَذَّاءِ، عَنْ مَرْوَانَ الأَصْفَرِ، عَنْ رَجُلٍ، مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَهْوَ ابْنُ عُمَرَ أَنَّهَا قَدْ نُسِخَتْ ‏{‏وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 125","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-125","x":"It is reported on the authority of Abu Huraira that when it was revealed to the Messenger of Allah (ﷺ):\n\nTo Allah belongs whatever is in the heavens and whatever is in the earth and whether you disclose that which is in your mind or conceal it, Allah will call you to account according to it. Then He forgives whom He pleases and chastises whom He Pleases; and Allah is over everything Potent\" (ii. 284). the Companions of the Messenger of Allah (ﷺ) felt it hard and severe and they came to the Messenger of Allah (ﷺ) and sat down on their knees and said: Messenger of Allah, we were assigned some duties which were within our power to perform, such as prayer, fasting, struggling (in the cause of Allah), charity. Then this (the above-mentioned) verse was revealed unto you and it is beyond our power to live up to it. The Messenger of Allah (ﷺ) said: Do you intend to say what the people of two books (Jews and Christians) said before you:\" We hear and disobey\"? You should rather say:\" We hear and we obey, (we seek) Thy forgiveness, our Lord! and unto Thee is the return.\" And they said:\" We hear and we obey, (we seek) Thy forgiveness, Our Lord! and unto Thee is the return.\" When the people recited it and it smoothly flowed on their tongues, then Allah revealed immediately afterwards:\" The Apostle believes in that which is sent down unto him from his Lord, and so do the believers. Each one believes in Allah and His Angels and His Books and His Apostles, saying: We differentiate not between any of His Apostles and they say: We hearken and we obey: (we seek) Thy forgiveness, our Lord! and unto Thee is the return\" (ii. 285). When they did that, Allah abrogated this (verse) and the Great, Majestic Allah revealed:\" Allah burdens not a soul beyond its capacity. It gets every good that it earns and it suffers every ill that it earns. Our Lord, punish us not if we forget or make a mistake.\" (The Prophet said: ) Yes, our Lord! do not lay on us a burden as Thou didst lay on those before us. (The Prophet said: ) Yes, our Lord, impose not on us (burdens) which we have not the strength to bear (The Prophet said: ) Yes, and pardon us and grant us protection! and have mercy on us. Thou art our Patron, so grant us victory over the disbelieving people\" (ii. 286). He (the Lord) said: Yes.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ مِنْهَالٍ الضَّرِيرُ، وَأُمَيَّةُ بْنُ بِسْطَامَ الْعَيْشِيُّ، - وَاللَّفْظُ لأُمَيَّةَ - قَالاَ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا رَوْحٌ، - وَهُوَ ابْنُ الْقَاسِمِ - عَنِ الْعَلاَءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا نَزَلَتْ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ‏{‏ لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَىْءٍ قَدِيرٌ‏}‏ قَالَ فَاشْتَدَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم ثُمَّ بَرَكُوا عَلَى الرُّكَبِ فَقَالُوا أَىْ رَسُولَ اللَّهِ كُلِّفْنَا مِنَ الأَعْمَالِ مَا نُطِيقُ الصَّلاَةُ وَالصِّيَامُ وَالْجِهَادُ وَالصَّدَقَةُ وَقَدْ أُنْزِلَتْ عَلَيْكَ هَذِهِ الآيَةُ وَلاَ نُطِيقُهَا ‏.‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الْكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا بَلْ قُولُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏\"‏ ‏.‏ قَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏.‏ فَلَمَّا اقْتَرَأَهَا الْقَوْمُ ذَلَّتْ بِهَا أَلْسِنَتُهُمْ فَأَنْزَلَ اللَّهُ فِي إِثْرِهَا ‏{‏ آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ‏}‏ فَلَمَّا فَعَلُوا ذَلِكَ نَسَخَهَا اللَّهُ تَعَالَى فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ لاَ يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا‏}‏ قَالَ نَعَمْ ‏{‏ رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا‏}‏ قَالَ نَعَمْ ‏{‏ رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ‏}‏ قَالَ نَعَمْ ‏{‏ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلاَنَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ‏}‏ قَالَ نَعَمْ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2990","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2990","x":"Narrated Isra'il:\n\nfrom As-Suddi who said: \"Someone who heard from 'Ali, narrated about him saying: 'When this Ayah was revealed: \"And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it. Then He forgives whom He wills and He punishes whom He wills (2:284).' - we were very distressed about it.' He said: 'We said: \"Something occurs in ourselves to one of us, and he will be taken to account for it, and we do not know what of it he will be pardoned for, and what of it he will not be pardoned for.\" So this Ayah was revealed: Allah does not burden a soul beyond what it can bear, for it, is what it has earned, and against it, is what it has wrought. (Its meaning is recorded by Muslim, while the chain for this version is weak)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنِ السُّدِّيِّ، قَالَ حَدَّثَنِي مَنْ، سَمِعَ عَلِيًّا، يَقُولُ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ ‏)‏ الآيَةَ أَحْزَنَتْنَا قَالَ قُلْنَا يُحَدِّثُ أَحَدُنَا نَفْسَهُ فَيُحَاسَبُ بِهِ لاَ نَدْرِي مَا يُغْفَرُ مِنْهُ وَلاَ مَا لاَ يُغْفَرُ فَنَزَلَتْ هَذِهِ الآيَةُ بَعْدَهَا فَنَسَخَتْهَا ‏(‏ لاَ يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ‏)‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2991","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2991","x":"Narrated Umayyah:\n\nthat she asked 'Aishah about the saying of Allah, blessed and Most High: And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it (2:284). And about His saying: And whoever does evil, he will be recompensed for it (4:123). She said: \"No one has asked me about it since I asked the Messenger of Allah (ﷺ), he said: 'This is Allah's admonition for His slave regarding whatever he is stricken with, of fever and problems, even the item that he has in the pocket of his shirt which he loses and worries about, until the slave's sins are removed, just as the red ore is removed from the bellows.'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا الْحَسَنُ بْنُ مُوسَى، وَرَوْحُ بْنُ عُبَادَةَ، عَنْ حَمَّادِ بْنِ سَلَمَةَ، عَنْ عَلِيِّ بْنِ زَيْدٍ، عَنْ أُمَيَّةَ، أَنَّهَا سَأَلَتْ عَائِشَةَ عَنْ قَوْلِ اللَّهِ تَعَالَى ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ‏)‏ وَعَنْ قَوْلِهِ ‏:‏ ‏(‏مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ ‏)‏ فَقَالَتْ مَا سَأَلَنِي عَنْهَا أَحَدٌ مُنْذُ سَأَلْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ هَذِهِ مُعَاتَبَةُ اللَّهِ الْعَبْدَ فِيمَا يُصِيبُهُ مِنَ الْحُمَّى وَالنَّكْبَةِ حَتَّى الْبِضَاعَةُ يَضَعُهَا فِي كُمِّ قَمِيصِهِ فَيَفْقِدُهَا فَيَفْزَعُ لَهَا حَتَّى إِنَّ الْعَبْدَ لَيَخْرُجُ مِنْ ذُنُوبِهِ كَمَا يَخْرُجُ التِّبْرُ الأَحْمَرُ مِنَ الْكِيرِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ مِنْ حَدِيثِ عَائِشَةَ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ حَمَّادِ بْنِ سَلَمَةَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2992","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2992","x":"Narrated Ibn 'Abbas:\n\n\"When this Ayah was revealed: And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it (2:284). Somethings entered their hearts that had not entered before. So they mentioned that to the Prophet (ﷺ) and he said: 'Say: \"We hear and we obey.\" So Allah put faith into their hearts and Allah Blessed and Most High revealed the Ayah: The Messenger believes in what has been sent down to him from his Lord, and (so do) the believers (and) Allah does not burden a soul beyond what it can bear, for it is what it has earned and against it is what it has wrought. \"Our Lord! Punish us not if we forget or fall into error (2:286).\" He said: 'I have done so (as requested).' Our Lord! Lay not upon us a burden like that which You did upon those before us. He said: ['I have done so (as requested).'] Our Lord! Put not a burden upon us greater than we have strength for. Pardon us and grant us forgiveness. Have mercy on us (2:286). He said: 'I have done so (as requested).'\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا سُفْيَانُ، عَنْ آدَمَ بْنِ سُلَيْمَانَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُْ ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏)‏ قَالَ دَخَلَ قُلُوبَهُمْ مِنْهُ شَيْءٌ لَمْ يَدْخُلْ مِنْ شَيْءٍ فَقَالُوا لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَ ‏\"‏ قُولُوا سَمِعْنَا وَأَطَعْنَا ‏\"‏ ‏.‏ فَأَلْقَى اللَّهُ الإِيمَانَ فِي قُلُوبِهِمْ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ‏)‏ الآيَةَ ‏:‏ ‏(‏ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏)‏ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏(‏رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏)‏ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏.‏ ‏(‏رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ‏)‏ الآيَةَ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ وَقَدْ رُوِيَ هَذَا مِنْ غَيْرِ هَذَا الْوَجْهِ عَنِ ابْنِ عَبَّاسٍ وَآدَمُ بْنُ سُلَيْمَانَ هُوَ وَالِدُ يَحْيَى بْنِ آدَمَ ‏.‏ وَفِي الْبَابِ عَنْ أَبِي هُرَيْرَةَ رضى الله عنه ‏.‏","v":[]}],"285":[{"c":"Sahih Muslim","r":"Hadith 125","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-125","x":"It is reported on the authority of Abu Huraira that when it was revealed to the Messenger of Allah (ﷺ):\n\nTo Allah belongs whatever is in the heavens and whatever is in the earth and whether you disclose that which is in your mind or conceal it, Allah will call you to account according to it. Then He forgives whom He pleases and chastises whom He Pleases; and Allah is over everything Potent\" (ii. 284). the Companions of the Messenger of Allah (ﷺ) felt it hard and severe and they came to the Messenger of Allah (ﷺ) and sat down on their knees and said: Messenger of Allah, we were assigned some duties which were within our power to perform, such as prayer, fasting, struggling (in the cause of Allah), charity. Then this (the above-mentioned) verse was revealed unto you and it is beyond our power to live up to it. The Messenger of Allah (ﷺ) said: Do you intend to say what the people of two books (Jews and Christians) said before you:\" We hear and disobey\"? You should rather say:\" We hear and we obey, (we seek) Thy forgiveness, our Lord! and unto Thee is the return.\" And they said:\" We hear and we obey, (we seek) Thy forgiveness, Our Lord! and unto Thee is the return.\" When the people recited it and it smoothly flowed on their tongues, then Allah revealed immediately afterwards:\" The Apostle believes in that which is sent down unto him from his Lord, and so do the believers. Each one believes in Allah and His Angels and His Books and His Apostles, saying: We differentiate not between any of His Apostles and they say: We hearken and we obey: (we seek) Thy forgiveness, our Lord! and unto Thee is the return\" (ii. 285). When they did that, Allah abrogated this (verse) and the Great, Majestic Allah revealed:\" Allah burdens not a soul beyond its capacity. It gets every good that it earns and it suffers every ill that it earns. Our Lord, punish us not if we forget or make a mistake.\" (The Prophet said: ) Yes, our Lord! do not lay on us a burden as Thou didst lay on those before us. (The Prophet said: ) Yes, our Lord, impose not on us (burdens) which we have not the strength to bear (The Prophet said: ) Yes, and pardon us and grant us protection! and have mercy on us. Thou art our Patron, so grant us victory over the disbelieving people\" (ii. 286). He (the Lord) said: Yes.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ مِنْهَالٍ الضَّرِيرُ، وَأُمَيَّةُ بْنُ بِسْطَامَ الْعَيْشِيُّ، - وَاللَّفْظُ لأُمَيَّةَ - قَالاَ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا رَوْحٌ، - وَهُوَ ابْنُ الْقَاسِمِ - عَنِ الْعَلاَءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا نَزَلَتْ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ‏{‏ لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَىْءٍ قَدِيرٌ‏}‏ قَالَ فَاشْتَدَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم ثُمَّ بَرَكُوا عَلَى الرُّكَبِ فَقَالُوا أَىْ رَسُولَ اللَّهِ كُلِّفْنَا مِنَ الأَعْمَالِ مَا نُطِيقُ الصَّلاَةُ وَالصِّيَامُ وَالْجِهَادُ وَالصَّدَقَةُ وَقَدْ أُنْزِلَتْ عَلَيْكَ هَذِهِ الآيَةُ وَلاَ نُطِيقُهَا ‏.‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الْكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا بَلْ قُولُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏\"‏ ‏.‏ قَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏.‏ فَلَمَّا اقْتَرَأَهَا الْقَوْمُ ذَلَّتْ بِهَا أَلْسِنَتُهُمْ فَأَنْزَلَ اللَّهُ فِي إِثْرِهَا ‏{‏ آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ‏}‏ فَلَمَّا فَعَلُوا ذَلِكَ نَسَخَهَا اللَّهُ تَعَالَى فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ لاَ يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا‏}‏ قَالَ نَعَمْ ‏{‏ رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا‏}‏ قَالَ نَعَمْ ‏{‏ رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ‏}‏ قَالَ نَعَمْ ‏{‏ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلاَنَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ‏}‏ قَالَ نَعَمْ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2990","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2990","x":"Narrated Isra'il:\n\nfrom As-Suddi who said: \"Someone who heard from 'Ali, narrated about him saying: 'When this Ayah was revealed: \"And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it. Then He forgives whom He wills and He punishes whom He wills (2:284).' - we were very distressed about it.' He said: 'We said: \"Something occurs in ourselves to one of us, and he will be taken to account for it, and we do not know what of it he will be pardoned for, and what of it he will not be pardoned for.\" So this Ayah was revealed: Allah does not burden a soul beyond what it can bear, for it, is what it has earned, and against it, is what it has wrought. (Its meaning is recorded by Muslim, while the chain for this version is weak)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنِ السُّدِّيِّ، قَالَ حَدَّثَنِي مَنْ، سَمِعَ عَلِيًّا، يَقُولُ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ ‏)‏ الآيَةَ أَحْزَنَتْنَا قَالَ قُلْنَا يُحَدِّثُ أَحَدُنَا نَفْسَهُ فَيُحَاسَبُ بِهِ لاَ نَدْرِي مَا يُغْفَرُ مِنْهُ وَلاَ مَا لاَ يُغْفَرُ فَنَزَلَتْ هَذِهِ الآيَةُ بَعْدَهَا فَنَسَخَتْهَا ‏(‏ لاَ يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ‏)‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2992","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2992","x":"Narrated Ibn 'Abbas:\n\n\"When this Ayah was revealed: And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it (2:284). Somethings entered their hearts that had not entered before. So they mentioned that to the Prophet (ﷺ) and he said: 'Say: \"We hear and we obey.\" So Allah put faith into their hearts and Allah Blessed and Most High revealed the Ayah: The Messenger believes in what has been sent down to him from his Lord, and (so do) the believers (and) Allah does not burden a soul beyond what it can bear, for it is what it has earned and against it is what it has wrought. \"Our Lord! Punish us not if we forget or fall into error (2:286).\" He said: 'I have done so (as requested).' Our Lord! Lay not upon us a burden like that which You did upon those before us. He said: ['I have done so (as requested).'] Our Lord! Put not a burden upon us greater than we have strength for. Pardon us and grant us forgiveness. Have mercy on us (2:286). He said: 'I have done so (as requested).'\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا سُفْيَانُ، عَنْ آدَمَ بْنِ سُلَيْمَانَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُْ ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏)‏ قَالَ دَخَلَ قُلُوبَهُمْ مِنْهُ شَيْءٌ لَمْ يَدْخُلْ مِنْ شَيْءٍ فَقَالُوا لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَ ‏\"‏ قُولُوا سَمِعْنَا وَأَطَعْنَا ‏\"‏ ‏.‏ فَأَلْقَى اللَّهُ الإِيمَانَ فِي قُلُوبِهِمْ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ‏)‏ الآيَةَ ‏:‏ ‏(‏ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏)‏ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏(‏رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏)‏ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏.‏ ‏(‏رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ‏)‏ الآيَةَ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ وَقَدْ رُوِيَ هَذَا مِنْ غَيْرِ هَذَا الْوَجْهِ عَنِ ابْنِ عَبَّاسٍ وَآدَمُ بْنُ سُلَيْمَانَ هُوَ وَالِدُ يَحْيَى بْنِ آدَمَ ‏.‏ وَفِي الْبَابِ عَنْ أَبِي هُرَيْرَةَ رضى الله عنه ‏.‏","v":[]}],"286":[{"c":"Sahih Muslim","r":"Hadith 125","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-125","x":"It is reported on the authority of Abu Huraira that when it was revealed to the Messenger of Allah (ﷺ):\n\nTo Allah belongs whatever is in the heavens and whatever is in the earth and whether you disclose that which is in your mind or conceal it, Allah will call you to account according to it. Then He forgives whom He pleases and chastises whom He Pleases; and Allah is over everything Potent\" (ii. 284). the Companions of the Messenger of Allah (ﷺ) felt it hard and severe and they came to the Messenger of Allah (ﷺ) and sat down on their knees and said: Messenger of Allah, we were assigned some duties which were within our power to perform, such as prayer, fasting, struggling (in the cause of Allah), charity. Then this (the above-mentioned) verse was revealed unto you and it is beyond our power to live up to it. The Messenger of Allah (ﷺ) said: Do you intend to say what the people of two books (Jews and Christians) said before you:\" We hear and disobey\"? You should rather say:\" We hear and we obey, (we seek) Thy forgiveness, our Lord! and unto Thee is the return.\" And they said:\" We hear and we obey, (we seek) Thy forgiveness, Our Lord! and unto Thee is the return.\" When the people recited it and it smoothly flowed on their tongues, then Allah revealed immediately afterwards:\" The Apostle believes in that which is sent down unto him from his Lord, and so do the believers. Each one believes in Allah and His Angels and His Books and His Apostles, saying: We differentiate not between any of His Apostles and they say: We hearken and we obey: (we seek) Thy forgiveness, our Lord! and unto Thee is the return\" (ii. 285). When they did that, Allah abrogated this (verse) and the Great, Majestic Allah revealed:\" Allah burdens not a soul beyond its capacity. It gets every good that it earns and it suffers every ill that it earns. Our Lord, punish us not if we forget or make a mistake.\" (The Prophet said: ) Yes, our Lord! do not lay on us a burden as Thou didst lay on those before us. (The Prophet said: ) Yes, our Lord, impose not on us (burdens) which we have not the strength to bear (The Prophet said: ) Yes, and pardon us and grant us protection! and have mercy on us. Thou art our Patron, so grant us victory over the disbelieving people\" (ii. 286). He (the Lord) said: Yes.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ مِنْهَالٍ الضَّرِيرُ، وَأُمَيَّةُ بْنُ بِسْطَامَ الْعَيْشِيُّ، - وَاللَّفْظُ لأُمَيَّةَ - قَالاَ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا رَوْحٌ، - وَهُوَ ابْنُ الْقَاسِمِ - عَنِ الْعَلاَءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا نَزَلَتْ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ‏{‏ لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَىْءٍ قَدِيرٌ‏}‏ قَالَ فَاشْتَدَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم ثُمَّ بَرَكُوا عَلَى الرُّكَبِ فَقَالُوا أَىْ رَسُولَ اللَّهِ كُلِّفْنَا مِنَ الأَعْمَالِ مَا نُطِيقُ الصَّلاَةُ وَالصِّيَامُ وَالْجِهَادُ وَالصَّدَقَةُ وَقَدْ أُنْزِلَتْ عَلَيْكَ هَذِهِ الآيَةُ وَلاَ نُطِيقُهَا ‏.‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الْكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا بَلْ قُولُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏\"‏ ‏.‏ قَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏.‏ فَلَمَّا اقْتَرَأَهَا الْقَوْمُ ذَلَّتْ بِهَا أَلْسِنَتُهُمْ فَأَنْزَلَ اللَّهُ فِي إِثْرِهَا ‏{‏ آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ‏}‏ فَلَمَّا فَعَلُوا ذَلِكَ نَسَخَهَا اللَّهُ تَعَالَى فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ لاَ يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا‏}‏ قَالَ نَعَمْ ‏{‏ رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا‏}‏ قَالَ نَعَمْ ‏{‏ رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ‏}‏ قَالَ نَعَمْ ‏{‏ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلاَنَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ‏}‏ قَالَ نَعَمْ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 126","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-126","x":"It is narrated on the authority of Ibn 'Abbas:\n\nWhen this verse:\" Whether you disclose that which is in your mind or conceal it, Allah will call you to account according to it\" (ii 284), there entered in their minds something (of that fear) such as had never entered their hearts (before). The Apostle (ﷺ) observed: Say: We have heard and obeyed and submitted ourselves. He (the reporter) said: Allah instilled faith in their hearts and He revealed this verse:\" Allah burdens not a soul beyond its capacity. It gets every good that it earns and it suffers every ill that it earns. Our Lord, call us not to account if we forget or make a mistake. He the (Lord) said: I indeed did it. Our Lord! do not lay on us a burden as Thou didst lay on those before us. He (our Lord) said: I indeed did it. And pardon us, have mercy on us. Thou art our Protector\" (ii. 286). He said: I indeed did it.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ - وَاللَّفْظُ لأَبِي بَكْرٍ قَالَ إِسْحَاقُ أَخْبَرَنَا وَقَالَ الآخَرَانِ، حَدَّثَنَا - وَكِيعٌ، عَنْ سُفْيَانَ، عَنْ آدَمَ بْنِ سُلَيْمَانَ، مَوْلَى خَالِدٍ قَالَ سَمِعْتُ سَعِيدَ بْنَ جُبَيْرٍ، يُحَدِّثُ عَنِ ابْنِ عَبَّاسٍ، قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏{‏ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ‏}‏ قَالَ دَخَلَ قُلُوبَهُمْ مِنْهَا شَىْءٌ لَمْ يَدْخُلْ قُلُوبَهُمْ مِنْ شَىْءٍ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ قُولُوا سَمِعْنَا وَأَطَعْنَا وَسَلَّمْنَا ‏\"‏ ‏.‏ قَالَ فَأَلْقَى اللَّهُ الإِيمَانَ فِي قُلُوبِهِمْ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏ لاَ يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا‏}‏ قَالَ قَدْ فَعَلْتُ ‏{‏ رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا‏}‏ - قَالَ قَدْ فَعَلْتُ ‏{‏ وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلاَنَا‏}‏ قَالَ قَدْ فَعَلْتُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2990","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2990","x":"Narrated Isra'il:\n\nfrom As-Suddi who said: \"Someone who heard from 'Ali, narrated about him saying: 'When this Ayah was revealed: \"And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it. Then He forgives whom He wills and He punishes whom He wills (2:284).' - we were very distressed about it.' He said: 'We said: \"Something occurs in ourselves to one of us, and he will be taken to account for it, and we do not know what of it he will be pardoned for, and what of it he will not be pardoned for.\" So this Ayah was revealed: Allah does not burden a soul beyond what it can bear, for it, is what it has earned, and against it, is what it has wrought. (Its meaning is recorded by Muslim, while the chain for this version is weak)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنِ السُّدِّيِّ، قَالَ حَدَّثَنِي مَنْ، سَمِعَ عَلِيًّا، يَقُولُ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ ‏)‏ الآيَةَ أَحْزَنَتْنَا قَالَ قُلْنَا يُحَدِّثُ أَحَدُنَا نَفْسَهُ فَيُحَاسَبُ بِهِ لاَ نَدْرِي مَا يُغْفَرُ مِنْهُ وَلاَ مَا لاَ يُغْفَرُ فَنَزَلَتْ هَذِهِ الآيَةُ بَعْدَهَا فَنَسَخَتْهَا ‏(‏ لاَ يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ‏)‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 2992","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-2992","x":"Narrated Ibn 'Abbas:\n\n\"When this Ayah was revealed: And whether you disclose what is in yourselves or conceal it, Allah will call you to account for it (2:284). Somethings entered their hearts that had not entered before. So they mentioned that to the Prophet (ﷺ) and he said: 'Say: \"We hear and we obey.\" So Allah put faith into their hearts and Allah Blessed and Most High revealed the Ayah: The Messenger believes in what has been sent down to him from his Lord, and (so do) the believers (and) Allah does not burden a soul beyond what it can bear, for it is what it has earned and against it is what it has wrought. \"Our Lord! Punish us not if we forget or fall into error (2:286).\" He said: 'I have done so (as requested).' Our Lord! Lay not upon us a burden like that which You did upon those before us. He said: ['I have done so (as requested).'] Our Lord! Put not a burden upon us greater than we have strength for. Pardon us and grant us forgiveness. Have mercy on us (2:286). He said: 'I have done so (as requested).'\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا سُفْيَانُ، عَنْ آدَمَ بْنِ سُلَيْمَانَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُْ ‏:‏ ‏(‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏)‏ قَالَ دَخَلَ قُلُوبَهُمْ مِنْهُ شَيْءٌ لَمْ يَدْخُلْ مِنْ شَيْءٍ فَقَالُوا لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَ ‏\"‏ قُولُوا سَمِعْنَا وَأَطَعْنَا ‏\"‏ ‏.‏ فَأَلْقَى اللَّهُ الإِيمَانَ فِي قُلُوبِهِمْ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ‏)‏ الآيَةَ ‏:‏ ‏(‏ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏)‏ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏(‏رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏)‏ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏.‏ ‏(‏رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ‏)‏ الآيَةَ قَالَ ‏\"‏ قَدْ فَعَلْتُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ وَقَدْ رُوِيَ هَذَا مِنْ غَيْرِ هَذَا الْوَجْهِ عَنِ ابْنِ عَبَّاسٍ وَآدَمُ بْنُ سُلَيْمَانَ هُوَ وَالِدُ يَحْيَى بْنِ آدَمَ ‏.‏ وَفِي الْبَابِ عَنْ أَبِي هُرَيْرَةَ رضى الله عنه ‏.‏","v":[]}]};